// =====================================================
// Internal Beta runtime path fix
//
// All native runtime files are resolved relative to the
// directory that actually contains rtx_backend.dll.
//
// This removes any dependency on the launcher/process
// working directory.
// =====================================================

extern "C" IMAGE_DOS_HEADER __ImageBase;


static std::string GetRTXBackendDirectory()
{
    static const std::string cachedDirectory = []() -> std::string
    {
        std::vector<char> buffer(
            32768,
            '\0'
        );


        const DWORD length =
            GetModuleFileNameA(
                reinterpret_cast<HMODULE>(
                    &__ImageBase
                ),
                buffer.data(),
                static_cast<DWORD>(
                    buffer.size()
                )
            );


        if(
            length == 0 ||
            length >= buffer.size()
        )
        {
            fprintf(
                stderr,
                "[RUNTIME PATH] GetModuleFileNameA failed error=%lu\n",
                GetLastError()
            );

            fflush(stderr);

            return {};
        }


        std::string modulePath(
            buffer.data(),
            length
        );


        const std::string::size_type slash =
            modulePath.find_last_of(
                "\\/"
            );


        if(slash == std::string::npos)
        {
            fprintf(
                stderr,
                "[RUNTIME PATH] invalid backend module path=%s\n",
                modulePath.c_str()
            );

            fflush(stderr);

            return {};
        }


        return modulePath.substr(
            0,
            slash
        );
    }();


    return cachedDirectory;
}


static bool IsAbsoluteWindowsPath(
    const char* path
)
{
    if(
        !path ||
        path[0] == '\0'
    )
    {
        return false;
    }


    // Drive path: C:\...
    if(
        path[0] != '\0' &&
        path[1] == ':' &&
        (
            path[2] == '\\' ||
            path[2] == '/'
        )
    )
    {
        return true;
    }


    // UNC / rooted path.
    return
        path[0] == '\\' ||
        path[0] == '/';
}


static std::string ResolveRTXRuntimePath(
    const char* path
)
{
    if(
        !path ||
        path[0] == '\0'
    )
    {
        return {};
    }


    if(IsAbsoluteWindowsPath(path))
    {
        return std::string(path);
    }


    const std::string baseDirectory =
        GetRTXBackendDirectory();


    if(baseDirectory.empty())
    {
        // Defensive fallback only.
        return std::string(path);
    }


    return
        baseDirectory +
        "\\" +
        path;
}


// =====================================================
// Optional MFG Ada unlock module (RTXMFG.dll)
// =====================================================
//
// Third-party module that makes 3x/4x/6x frame generation legal on Ada by
// detouring Streamline (slInit, slDLSSGSetOptions, slDLSSGGetState,
// slGetFeatureFunction) and the NGX DLSS-G provider entry points inside this
// process, and by correcting the provider's temporal program in mapped memory.
// It must be inside the process before slInit runs and before the DLSS-G
// pipeline is created, which is why the backend loads it rather than leaning on
// the game: the executable in a Fabric run is java.exe inside the JDK
// directory, so the mod's documented "rename it to a proxy DLL next to the exe"
// route would mean writing into the JDK.
//
// Entirely optional.  A missing file is not an error, nothing in this backend
// depends on it, and deleting RTXMFG.dll turns the unlock off again: the
// multiplier setting stays clamped to whatever the driver reports, and this
// module is what raises that ceiling.
static void LoadMfgUnlockModuleIfPresent()
{
    static bool attempted = false;


    if(attempted)
    {
        return;
    }

    attempted = true;


    const std::string modulePath =
        ResolveRTXRuntimePath(
            "RTXMFG.dll"
        );


    if(
        modulePath.empty() ||
        GetFileAttributesA(
            modulePath.c_str()
        ) == INVALID_FILE_ATTRIBUTES
    )
    {
        fprintf(
            stderr,
            "[MFG UNLOCK] RTXMFG.dll not present, unlock inactive\n"
        );

        fflush(stderr);

        return;
    }


    HMODULE unlockModule =
        LoadLibraryExA(
            modulePath.c_str(),
            nullptr,
            0
        );


    fprintf(
        stderr,
        "[MFG UNLOCK] path=%s handle=%p error=%lu\n",
        modulePath.c_str(),
        reinterpret_cast<void*>(
            unlockModule
        ),
        unlockModule
            ? 0ul
            : GetLastError()
    );

    fflush(stderr);
}


static std::ofstream rtLogFile(
    ResolveRTXRuntimePath("rt_debug.log"),
    std::ios::app
);


// Serialises the log stream.  Uploads arrive on worker threads while the render
// thread is logging, and an interleaved line is worse than a missing one.
static std::mutex g_rtLogMutex;


// Writes one timestamped line.  Flushing is opt-in: the buffered path exists so
// filesystem latency never lands on the render thread.
static void RTLogWrite(
    const std::string& msg,
    bool flush
)
{
    auto now =
        std::chrono::system_clock::now();


    auto t =
        std::chrono::system_clock::to_time_t(now);


    std::lock_guard<std::mutex> lock(g_rtLogMutex);

    rtLogFile
        << "[CPP] "
        << std::put_time(
            std::localtime(&t),
            "%H:%M:%S"
        )
        << " "
        << msg
        << "\n";

    if(flush)
    {
        rtLogFile.flush();
    }
}


static void RTLog(
    const std::string& msg
)
{
    RTLogWrite(msg, false);
}


// Flushed variant for the rare diagnostics whose loss would invalidate a whole
// capture: the host can die before the buffered stream ever reaches disk, and a
// report that was never written is indistinguishable from a stall that never
// happened.
static void RTLogFlushed(
    const std::string& msg
)
{
    RTLogWrite(msg, true);
}

// =====================================================================
// 2026-10-02 崩溃定位：把"无日志的硬崩"变成一行可读的日志。
//
// 现场证据：Windows 事件日志里五次崩溃全是 rtx_backend.dll + 0xC0000409
//（STATUS_STACK_BUFFER_OVERRUN，实际是 abort/__fastfail），偏移都落在同一小段
//（0x8ea65~0x8eb95）。既不是段错误，也不是 GPU device lost，而是**未捕获的 C++
// 异常 → std::terminate → abort**：check() 失败时只 throw、原先不打日志，一旦异常
// 在 noexcept 上下文 / 析构 / JNI 边界逃逸，进程直接消失，rt_debug.log 里一行都不
// 留 —— 这正是几次"日志突兀断掉"的成因。
//
// 注册 terminate handler：把当前异常的 what()（= 失败的 check 描述 + VkResult）
// 刷盘后再 abort。static 初始化即注册，不依赖任何 JNI 入口。
// =====================================================================
#include <exception>

static void RTXTerminateHandler()
{
    if(auto e = std::current_exception())
    {
        try
        {
            std::rethrow_exception(e);
        }
        catch(const std::exception& ex)
        {
            RTLogFlushed(std::string("[FATAL] uncaught C++ exception: ") + ex.what());
        }
        catch(...)
        {
            RTLogFlushed("[FATAL] uncaught non-std C++ exception");
        }
    }
    else
    {
        RTLogFlushed("[FATAL] std::terminate with no active exception");
    }
    std::abort();
}

