struct GPUSectionVertexAddress
{
    uint32_t addressLo = 0;
    uint32_t addressHi = 0;

    // =====================================================
    // 2026-10-09 运动矢量（DLSS-RR）—— 表项从 8B 扩到 16B。
    //
    // motionOffset：该 Section 顶点缓冲里"上一帧位移"段（**相机相对**；
    //   closest-hit 补 Δcam 后才是世界位移）的**字节偏移**
    //   （0 = 这个 Section 没有位移段）。shader 侧读法：
    //     motionAddr = vertexAddr + motionOffset;
    //     顶点 i 的位移 = *(float3*)(motionAddr + i*12);
    //   0 是安全哨兵：有尾段时偏移至少 3×48=144（顶点数 ≥ 3）。
    // vertexStride：该段 GPU 顶点步长 —— **32 = 地形 32B 打包，48 = 原布局**。
    //   shader 侧按它分派 loadSectionVertex()（见 material_common.glsl:89-135，
    //   以及四个自带 Vertex 的 TU）。写 48 与旧的 48B 路径逐位等价。
    //   2026-10-21 之前这个 lane 是"位移段 float 个数（= 顶点数 × 3），仅供调试"，
    //   shader 从未读过它 ⇒ 换语义不影响任何既有路径。
    //
    // 为什么扩表项而不是新开一张表：这张表本来就是"每个 Section 一份、随实例
    // 定制索引读"的 per-instance 元数据，位移地址与顶点地址同生命周期、同回收
    // 时机，放在一起就不会出现两张表不同步的半坏状态。
    // 代价：65536 槽 × 16B = 1MB host-visible（原 512KB），仍是一次性常驻。
    // =====================================================
    uint32_t motionOffset = 0;
    uint32_t vertexStride = 0;
};

static_assert(
    sizeof(GPUSectionVertexAddress) == 16,
    "GPUSectionVertexAddress must remain exactly 16 bytes (4 x uint32)"
);

static VkBuffer g_sectionVertexAddressBuffer =
    VK_NULL_HANDLE;

static VkDeviceMemory g_sectionVertexAddressMemory =
    VK_NULL_HANDLE;

static size_t g_sectionVertexAddressCapacity = 0;

// The table is allocated once at a fixed slot count and only ever appended to,
// so the buffer never has to be recreated - which also removes the descriptor
// rewrite that growing used to require.  Slot 0 is the placeholder entry bound
// before any Section exists, so real Sections start at 1.
//
// 2026-10-13：1<<16 → 1<<18。旧上限配的假设是"live Section count is bounded by
// render distance (85 in the last capture)"，而现实早已打破它：实测 [RT MEM] 的
// meshSec 常态 354~579、历史峰值 3114，加上世界高度 24~32 段都算 Section。
// 按 64×64 列 × 8 个非空段估，1<<16 在大视距下会被顶到 ⇒ 旧代码直接 **throw**
// "Section vertex address table slots exhausted"，整轮重建终止（见
// ensureSectionVertexAddressSlot；那里已同时改为"跳过 + 告警"）。
//
// 成本：表 262144 × 16B = 4MB，角色表 262144 × 4B = 1MB，合计 5MB host-visible
// （旧值 1MB + 256KB）。相对预算（实测 ~7GB）可忽略，换掉的是"高世界崩一轮"。
constexpr uint32_t SECTION_VERTEX_ADDRESS_SLOT_LIMIT = 1u << 18;

static uint32_t g_sectionVertexAddressNextSlot = 1u;
static std::vector<uint32_t> g_sectionVertexAddressFreeSlots;
static void* g_sectionVertexAddressMapped = nullptr;

// =====================================================
// Per-instance geometry role table (binding 19)
// =====================================================
//
// instanceCustomIndex carries a Section's stable vertexAddressSlot, and those
// slots come from a high-water / free-list allocator, so the slot numbers of
// the LOD pseudo-sections are NOT a contiguous run.  A Vista-style
// `instanceIndex in [lodInstanceOffset, +lodInstanceCount)` therefore cannot be
// expressed in this index space; this side table states the same fact
// explicitly instead: one role per slot, read by the hit shaders as
// `lodRoles.roles[gl_InstanceCustomIndexEXT]`.
//
// Before this table, "this is the DH far field" was a magic value baked into
// the vertex `pad1` lane (pad1 < -2.5) plus a TLAS instance mask special case
// (0xfe).  The role is the single source of truth now; pad1 keeps only its
// material meaning.  Voxy LOD is marked here too but not yet read -- the Voxy
// hit paths deliberately keep their existing pad1 test.
static constexpr uint32_t SECTION_ROLE_TERRAIN  = 0u;
static constexpr uint32_t SECTION_ROLE_VOXY_LOD = 1u;
static constexpr uint32_t SECTION_ROLE_DH_FAR   = 2u;

static VkBuffer g_sectionRoleBuffer = VK_NULL_HANDLE;
static VkDeviceMemory g_sectionRoleMemory = VK_NULL_HANDLE;
static void* g_sectionRoleMapped = nullptr;

// =====================================================
// Per-chunk-column near-field coverage bitmap (binding 20)
// =====================================================
//
// Mirror of the reference pack's VistaCoverage: 8 bits per chunk column,
// packed four columns to a word, LSB-first.
//   bit0 = near-field geometry for this column is loaded
//   bit1..7 reserved (the reference pack's fallback / border bits have no
//           consumer here: this engine never ignores near-field geometry, so
//           the shader mirrors bit0 only -- see cpp/shaders/lod_coverage.glsl)
// A far-field (DH) hit whose column is already covered by near-field geometry
// is the redundant second copy of that geometry and is dropped in the any-hit
// shaders.  Columns outside the published grid read back as 0.
struct LodCoverageHeader
{
    int32_t originChunkX = 0;
    int32_t originChunkZ = 0;
    int32_t sizeX = 0;
    int32_t sizeZ = 0;
};

// 256x256 columns = 64 KB of flags.  That is a 128-chunk radius, far above any
// reachable render distance, and small enough to clear in one memset per
// rebuild.  A larger near-field set is clamped: the columns that fall outside
// simply read back as "not covered", so their far field stays visible.
static constexpr int32_t LOD_COVERAGE_MAX_SIZE = 256;
static constexpr uint32_t LOD_COVERAGE_FLAG_NEAR_READY = 1u;

static VkBuffer g_lodCoverageBuffer = VK_NULL_HANDLE;
static VkDeviceMemory g_lodCoverageMemory = VK_NULL_HANDLE;
static void* g_lodCoverageMapped = nullptr;
static uint32_t g_lodCoverageWordCount = 0;

static VkDeviceMemory g_blasScratchMemory=VK_NULL_HANDLE;
static VkDeviceAddress g_blasScratchAddress=0;

static VkBuffer g_tlasBuffer=VK_NULL_HANDLE;
static VkDeviceMemory g_tlasMemory=VK_NULL_HANDLE;
static VkAccelerationStructureKHR g_tlas=VK_NULL_HANDLE;

// Handle currently stored in the TLAS descriptor (binding 0).  Kept so the
// rebuild can skip republishing an unchanged handle: the descriptor write is
// the only post-submit mutation that a frame in flight could race, so skipping
// it is what lets the steady-state rebuild run without draining the queue.
// Must be invalidated whenever the descriptor set is (re)created.
static VkAccelerationStructureKHR g_tlasDescriptorHandle=VK_NULL_HANDLE;
static VkDeviceAddress g_tlasDeviceAddress=0;
static VkBuffer g_tlasInstanceBuffer=VK_NULL_HANDLE;
static VkDeviceMemory g_tlasInstanceMemory=VK_NULL_HANDLE;
static VkDeviceAddress g_tlasInstanceDeviceAddress=0;
static VkBuffer g_tlasScratchBuffer=VK_NULL_HANDLE;
static VkDeviceMemory g_tlasScratchMemory=VK_NULL_HANDLE;
static VkDeviceAddress g_tlasScratchAddress=0;
static VkDeviceSize g_tlasScratchCapacity=0;
static VkDeviceSize g_tlasAsSize=0;
static VkDeviceSize g_tlasInstancesCapacity=0;
static size_t g_tlasInstanceCount=0;

// A Section rebuild is submitted ahead of the frame's RT command buffer on
// the same graphics queue.  Its staging and BLAS scratch allocations must
// remain alive until that queue reaches the submission, but the CPU does not
// need to wait for it in the submitting frame.  They are released at the
// beginning of the next rebuild, after the retirement fence is signaled.
struct DeferredSectionBuildResources
{
    VkCommandBuffer commandBuffer = VK_NULL_HANDLE;
    VkBuffer blasScratchBuffer = VK_NULL_HANDLE;
    VkDeviceMemory blasScratchMemory = VK_NULL_HANDLE;
    VkDeviceSize blasScratchSize = 0;
    VkBuffer vertexStagingBuffer = VK_NULL_HANDLE;
    VkDeviceMemory vertexStagingMemory = VK_NULL_HANDLE;
    VkDeviceSize vertexStagingSize = 0;
    struct OmmBuildInputs
    {
        VkBuffer dataBuffer = VK_NULL_HANDLE;
        OmmBufferBinding dataBinding;
        VkBuffer triangleBuffer = VK_NULL_HANDLE;
        OmmBufferBinding triangleBinding;
        VkBuffer scratchBuffer = VK_NULL_HANDLE;
        OmmBufferBinding scratchBinding;
    };
    std::vector<OmmBuildInputs> ommBuildInputs;
};


static DeferredSectionBuildResources
    g_deferredSectionBuild;

// =====================================================
// 2026-10-11 Section 重建缓冲池：单槽 → 多槽（治"周期性 20~45ms 顿挫"）
//
// 现场（2026-10-11 高压场景一局的 [PERF L10 ALLOC]，它只打 >=1ms 的分配）：
//   frame=778  ms=19.92 request=3508208 usage=0x1 host
//   frame=5022 ms=45.15 request=2212568 usage=0x1 host
//   frame=5547 ms=28.25 request=3106808 usage=0x1 host
// 三条的 usage=0x1 就是本池的顶点 staging（TRANSFER_SRC + 系统内存）；而同期
// 8~12MB 的分配只要 1.0~1.9ms —— 慢的不是大小，是这块内存**被反复申请/释放**
// 之后驱动主机分配器的状态。与之对应的是新的 [RT GEOMETRY SLOW] 分段日志里
// staging 段占 20.5/45.8/28.9ms（那几帧的 sections=1，几百 KB 的拷贝不可能是这个数）。
//
// 根因是单槽池：取用时把槽取空并置 VK_NULL_HANDLE，而一块缓冲要等退休 fence
// 才能归还；高压场景重建间隔（~30/s）远小于在飞寿命 ⇒ 每次重建都是"池空 →
// 新建"，每次归还又是"销毁上一个 + 停泊这个" ⇒ 稳态约 30 次/秒的 free+alloc
// （2~12MB）。这也是 [RT MEM] 里那条与玩法无关的固定速率私有提交增长的来源。
//
// 现在：每类一个 N 槽池，**只增不减**；取用挑"最小够用"的空闲槽；归还只清
// inFlight。只有"没有任何空闲槽够大"时才新建一块并登记进池 —— 且**绝不销毁
// 正在飞的那块**。稳态下（预热后）分配/释放次数降到 0。
struct RtxSectionBuildBufferSlot
{
    VkBuffer buffer = VK_NULL_HANDLE;
    VkDeviceMemory memory = VK_NULL_HANDLE;
    VkDeviceSize bytes = 0u;
    bool inFlight = false;
};

// 2026-10-14：新建池槽时的容量取整（见下方 adopt 的说明）。
//
// 目的：把"连续变化"的批次尺寸钉到少数几档，让池命中从"看运气"变成"几乎恒命中"。
// 实测（2026-10-14 那一局，流式加载那几秒）批次尺寸依次是 6.7 / 7.1 / 7.9 / 10.6 /
// 12.5 / 13.3 / 17.1 / 18.7 / 21 / 22.4MB —— 全部未命中、全部真分配，而单次分配
// 13.5~49.9ms **且与大小无关**（分配 0.2MB 也要 41ms ⇒ 是驱动在腾挪驻留）⇒ 那 4 秒
// 里 21 次分配合计 418ms，正好就是顿挫窗口。
// 取整到 2 的幂（1MB 起）后，一到两档就能覆盖上面整个范围；再配合 adopt 的"只顶掉
// 更小的空闲槽"，池会在两三批之内收敛到一个"够大的常驻槽"，此后命中率≈100%。
static VkDeviceSize sectionBuildPoolSlotBytes(VkDeviceSize requiredBytes)
{
    VkDeviceSize bytes = 1048576u; // 1MB

    while(bytes < requiredBytes)
    {
        bytes <<= 1u;
    }

    return bytes;
}

struct RtxSectionBuildBufferPool
{
    std::vector<RtxSectionBuildBufferSlot> slots;

    // 取一个空闲且 >= requiredBytes 的槽（best fit，避免小批占住大块），
    // 成功则标记在飞并返回其副本。
    bool tryAcquire(
        VkDeviceSize requiredBytes,
        RtxSectionBuildBufferSlot& out)
    {
        size_t best = slots.size();

        for(size_t index = 0u; index < slots.size(); ++index)
        {
            const RtxSectionBuildBufferSlot& slot = slots[index];

            if(slot.inFlight || slot.bytes < requiredBytes)
            {
                continue;
            }

            if(best == slots.size() || slot.bytes < slots[best].bytes)
            {
                best = index;
            }
        }

        if(best == slots.size())
        {
            return false;
        }

        slots[best].inFlight = true;
        out = slots[best];

        return true;
    }

    // 登记一块刚建好的缓冲（调用方已 createBuffer）。优先顶掉一个**空闲**槽
    // （顶掉的只是空闲缓冲，销毁它安全），否则追加。返回登记后的槽副本。
    RtxSectionBuildBufferSlot adopt(
        VkBuffer buffer,
        VkDeviceMemory memory,
        VkDeviceSize bytes)
    {
        RtxSectionBuildBufferSlot slot;
        slot.buffer = buffer;
        slot.memory = memory;
        slot.bytes = bytes;
        slot.inFlight = true;

        // 2026-10-14：只在"某个空闲槽比新块更小"时顶掉它 —— 被顶掉的必然是更小的
        // 容量，池的总容量单调不降。
        //
        // 改动前的写法是无条件顶掉**第一个**空闲槽。于是"池里有一个空闲的 40MB 槽 +
        // 来一个 22MB 的未命中请求"⇒ 销毁 40MB 换成 22MB，**池容量倒退**；下一批
        // 25MB 又未命中 ⇒ 又分配、又销毁…… 流式加载时批次尺寸连续变化（实测同一秒
        // 内 6.7/7.1/7.9/13.3/18.7/22.4MB 各来一次），于是退化成"每批一次
        // vkAllocateMemory + 一次销毁"，而实测单次分配 13.5~49.9ms 且与大小无关
        // （驱动腾挪驻留）⇒ 这正是"越是加载越卡"。
        //
        // 收敛性：miss 意味着**没有**空闲槽 ≥ 新块（tryAcquire 会命中），所以走到
        // 这里时空闲槽必然都比新块小 ⇒ 挑最大的一块顶掉，池**不长**；只有"全部在飞"
        // 时才追加。于是池收敛到"在飞深度个槽、尺寸跟上最近的最大批"。
        size_t victim = slots.size();

        for(size_t index = 0u; index < slots.size(); ++index)
        {
            if(slots[index].inFlight)
            {
                continue;
            }

            if(slots[index].bytes >= slot.bytes)
            {
                continue;
            }

            if(victim == slots.size() ||
               slots[index].bytes < slots[victim].bytes)
            {
                victim = index;
            }
        }

        if(victim != slots.size())
        {
            // 空闲且比新块小：销毁它（空闲 ⇒ 无在飞引用），换成更大的新块。
            if(slots[victim].buffer != VK_NULL_HANDLE)
            {
                vkDestroyBuffer(g_device, slots[victim].buffer, nullptr);
            }
            if(slots[victim].memory != VK_NULL_HANDLE)
            {
                vkFreeMemory(g_device, slots[victim].memory, nullptr);
            }

            slots[victim] = slot;

            return slot;
        }

        // 没有空闲槽（都在飞）：追加。这里**不做上限销毁** —— 在飞块数由 GPU
        // 流水线深度决定，本来就有界；宁可多留一块，也不能销毁在飞缓冲。
        slots.push_back(slot);

        return slot;
    }

    // 归还某个在飞槽（按缓冲句柄查找）。查不到说明它不属于本池，直接销毁以免泄漏。
    void release(VkBuffer buffer)
    {
        if(buffer == VK_NULL_HANDLE)
        {
            return;
        }

        for(RtxSectionBuildBufferSlot& slot : slots)
        {
            if(slot.buffer == buffer)
            {
                slot.inFlight = false;
                return;
            }
        }

        vkDestroyBuffer(g_device, buffer, nullptr);
    }

    void releaseAll()
    {
        for(RtxSectionBuildBufferSlot& slot : slots)
        {
            if(slot.buffer != VK_NULL_HANDLE)
            {
                vkDestroyBuffer(g_device, slot.buffer, nullptr);
            }
            if(slot.memory != VK_NULL_HANDLE)
            {
                vkFreeMemory(g_device, slot.memory, nullptr);
            }
        }

        slots.clear();
    }

    // =====================================================
    // 2026-10-13（乙-4）：越线时释放池里**空闲**槽的暂存块，只保留最大的一块。
    //
    // 现场：`[RT MEM]` 的 churnTop 里 `use=0x1`（纯 VK_BUFFER_USAGE_TRANSFER_SRC_BIT）
    // 长期挂着 `liveN=3 liveMB=820.5`，而 `vkLiveHostMB=828.7` 基本就等于它 ⇒ **本模组
    // 全部的主机可见内存都是这一类纯 TRANSFER_SRC 暂存**，其中量级对得上的只有本节顶点
    // 构建 staging 池（原注释自称"只增不减"）。它每块是一个重建批次的 totalStagingBytes，
    // 高视距下可到数百 MB；池会一直留着它们。
    //
    // 安全性（与 slab 池 trimSectionMemoryPool 的时序前提完全相同）：槽变成空闲**只**发生
    // 在 release()，而 release() 只从 releaseDeferredSectionBuildResources() 调用 ——
    // 那是退休环的 fence 已经信号之后（见 releaseRetirementSlot 的说明）⇒ 池里的空闲块
    // 不可能仍被在途提交引用，可以安全销毁。在飞槽一律不碰。
    //
    // 保留最大的一块，而不是全释放：下一批多半还能命中，否则立刻变成"每批新建"的 churn，
    // 反而把分配耗时打回改动前。
    // =====================================================
    VkDeviceSize trimIdleKeepingLargest()
    {
        size_t largestIdle = slots.size();

        for(size_t index = 0u; index < slots.size(); ++index)
        {
            if(slots[index].inFlight)
            {
                continue;
            }

            if(largestIdle == slots.size() ||
               slots[index].bytes > slots[largestIdle].bytes)
            {
                largestIdle = index;
            }
        }

        VkDeviceSize freed = 0u;

        for(size_t index = 0u; index < slots.size();)
        {
            if(index == largestIdle || slots[index].inFlight)
            {
                ++index;
                continue;
            }

            RtxSectionBuildBufferSlot& slot = slots[index];

            if(slot.buffer != VK_NULL_HANDLE)
            {
                vkDestroyBuffer(g_device, slot.buffer, nullptr);
            }
            if(slot.memory != VK_NULL_HANDLE)
            {
                vkFreeMemory(g_device, slot.memory, nullptr);
            }

            freed += slot.bytes;

            slots.erase(
                slots.begin() + static_cast<std::ptrdiff_t>(index)
            );
        }

        return freed;
    }

    // 2026-10-13（乙-4）：只读明细，进 [RT MEM]。
    void stats(
        size_t& outCount,
        VkDeviceSize& outTotalBytes,
        size_t& outInFlight) const
    {
        outCount = slots.size();
        outTotalBytes = 0u;
        outInFlight = 0u;

        for(const RtxSectionBuildBufferSlot& slot : slots)
        {
            outTotalBytes += slot.bytes;

            if(slot.inFlight)
            {
                outInFlight += 1u;
            }
        }
    }
};

static RtxSectionBuildBufferPool g_vertexStagingPool;
static RtxSectionBuildBufferPool g_blasScratchPool;

// 诊断：池的分配/命中计数（[RT GEOMETRY] counters 里打出，用来确认稳态零 churn）。
static uint64_t g_sectionBuildPoolAllocCount = 0u;
static uint64_t g_sectionBuildPoolReuseCount = 0u;

static void destroyPooledSectionBuildBuffers()
{
    g_vertexStagingPool.releaseAll();
    g_blasScratchPool.releaseAll();
}

static void releaseDeferredSectionBuildResources()
{
    if(
        g_deferredSectionBuild.commandBuffer != VK_NULL_HANDLE &&
        g_rtCommandPool != VK_NULL_HANDLE
    )
    {
        vkFreeCommandBuffers(
            g_device,
            g_rtCommandPool,
            1,
            &g_deferredSectionBuild.commandBuffer
        );
    }


    // 2026-10-11：归还而不是销毁（见 RtxSectionBuildBufferPool 的说明）。旧代码在这里
    // 销毁池里那一块、再停泊这一块，正是 30 次/秒 free+alloc 的来源。
    g_blasScratchPool.release(
        g_deferredSectionBuild.blasScratchBuffer
    );


    g_vertexStagingPool.release(
        g_deferredSectionBuild.vertexStagingBuffer
    );

    // After the queue-idle ownership barrier the micromap build inputs are
    // dead.  Keep only VkMicromapEXT and its storage backing with the BLAS.
    // 2026-10-10 池化：这三块内存同样是 Section slab 的 chunk，归还走 destroyPooledBuffer。
    for(auto& input : g_deferredSectionBuild.ommBuildInputs)
    {
        destroyPooledBuffer(input.scratchBuffer, input.scratchBinding);
        destroyPooledBuffer(input.triangleBuffer, input.triangleBinding);
        destroyPooledBuffer(input.dataBuffer, input.dataBinding);
    }


    g_deferredSectionBuild = {};
}

// =====================================================
// Perf-SR.1 - parked Section generation
// =====================================================
// A rebuild replaces the TLAS and rewrites Section BLAS objects, but the
// previous generation is still referenced by whatever the GPU is executing, so
// it cannot be destroyed during the rebuild.  The old code therefore drained
// the RT queue with vkQueueWaitIdle() before touching anything, which
// serialised the CPU-side rebuild behind the GPU.
//
// Instead the replaced generation is parked here while the CPU assembles its
// replacement, and the queue is drained only once that replacement is ready to
// be submitted, just before vkQueueSubmit().  The drain therefore overlaps the
// whole rebuild, which is where the saving comes from; the slot is emptied
// immediately after it.
struct SectionRetirementSlot
{
    bool occupied = false;
    std::vector<RTSectionAS> sections;
    VkAccelerationStructureKHR tlas = VK_NULL_HANDLE;
    VkBuffer tlasBuffer = VK_NULL_HANDLE;
    VkDeviceMemory tlasMemory = VK_NULL_HANDLE;
    VkBuffer tlasScratchBuffer = VK_NULL_HANDLE;
    VkDeviceMemory tlasScratchMemory = VK_NULL_HANDLE;
    VkBuffer tlasInstanceBuffer = VK_NULL_HANDLE;
    VkDeviceMemory tlasInstanceMemory = VK_NULL_HANDLE;
    VkBuffer tlasInstancesBuffer = VK_NULL_HANDLE;
    VkDeviceMemory tlasInstancesMemory = VK_NULL_HANDLE;
    DeferredSectionBuildResources deferredBuild;

    // Set while this slot's generation may still be read by work in flight, and
    // cleared once its fence has signaled.  A slot is only reusable after that.
    bool fencePending = false;
};


// Parked generations live in a small ring so the rebuild does not have to wait
// for the GPU before releasing the previous one: each generation is tagged with
// a fence on the build submit that came after it, and the queue being FIFO means
// a signaled fence proves every earlier submission - including the frames that
// still referenced that generation - has completed.  g_sectionRetirement always
// points at the slot the rebuild currently owns.
constexpr uint32_t SECTION_RETIREMENT_RING_SIZE = 3u;

static std::array<
    SectionRetirementSlot,
    SECTION_RETIREMENT_RING_SIZE
> g_sectionRetirementRing;

static std::array<
    VkFence,
    SECTION_RETIREMENT_RING_SIZE
> g_sectionRetirementFences{};

static bool g_sectionRetirementFencesReady = false;

static uint32_t g_currentRetirementSlot = 0u;

static SectionRetirementSlot*
    g_sectionRetirement =
        &g_sectionRetirementRing[0];

static VkDescriptorPool g_rayTracingDescriptorPool=VK_NULL_HANDLE;
static VkDescriptorSet g_rayTracingDescriptorSet=VK_NULL_HANDLE;
static VkDescriptorSetLayout g_rayTracingDescriptorSetLayout=VK_NULL_HANDLE;
static VkPipelineLayout g_rayTracingPipelineLayout=VK_NULL_HANDLE;
static VkPipeline g_rayTracingPipeline=VK_NULL_HANDLE;

// =====================================================
// NRD-1  NVIDIA Real-Time Denoisers (REBLUR_DIFFUSE)
//
// ★ 2026-09-30：ReSTIR DI 链（rt_restir_final.rgen / rt_restir_spatial.comp /
// rt_restir_reconstruct.comp 三个 pass 及其水库缓冲）已整链删除，本地光只剩
// rt_test.rgen 内的经典 RIS 路径。NRD 这一整套代码**保留但永久关停**：帧图里各
// 处 dispatch / composite 的判据统一为编译期常量 kNrdLocalDiEnabled = false。
// 保留而不删，是为了将来若要重新引入独立的本地光降噪器时不必重写集成层。
//
// 原设计背景（保留供参考）：本地光是全帧唯一的 1-spp、时域不相干信号，可见性项
// 是 DLSS-RR 平均不掉的噪声，NRD 正是为它设计的降噪器。
//
// NRD makes NO graphics API calls.  It hands back pool/SPIR-V/descriptor
// descriptions and this file turns them into real Vulkan objects.  The exact
// binding layout was read out of NRD's own SPIR-V and build flags, NOT guessed:
//   set 1 binding 0  = Sampler  NEAREST_CLAMP   (immutable)
//   set 1 binding 1  = Sampler  LINEAR_CLAMP    (immutable)
//   set 1 binding 2  = UniformBuffer (root CBV, push descriptor)
//   set 0 binding 20+ = SampledImage  inputs   (tRegShift 20)
//   set 0 binding 3+  = StorageImage  outputs  (uRegShift 3)
// Spaces/registers come from NRD's own defines; the shifts come from
// cpp/deps/NRD/CMakeLists.txt (SPIRV_SREG/BREG/UREG/TREG_OFFSET 0/2/3/20).
// =====================================================

// 2026-10-21：NRD 总开关。原先定义在 recordFrameCommand 里（原 58458 行），
// 但 createNRDResources 需要更早看到它来决定"要不要创建资源"，所以上提到这里。
// 语义不变：false = 整条链关停（不 dispatch / 不 composite / 也不创建资源）。
constexpr bool kNrdLocalDiEnabled = false;

// NRD 初始化成功时为 true。★ 2026-09-30 起 NRD 的 dispatch 由编译期常量 false
// 关停，本标志即使为 true 也不会导致任何 NRD pass 被录制（保留供将来重启）。
static bool g_nrdReady = false;

static nrd::Instance* g_nrdInstance = nullptr;
static uint32_t g_nrdWidth = 0u;
static uint32_t g_nrdHeight = 0u;
static uint32_t g_nrdIdentifier = 1u;

static nrd::LibraryDesc g_nrdLibraryDesc{};
static nrd::InstanceDesc g_nrdInstanceDesc{};

// NRD's own resources: the constant buffer, the two immutable samplers, the
// resource descriptor set (inputs + outputs + pool textures) and the shared
// pipeline layout / descriptor pool.
static VkBuffer g_nrdConstantBuffer = VK_NULL_HANDLE;
static VkDeviceMemory g_nrdConstantBufferMemory = VK_NULL_HANDLE;
static VkDeviceSize g_nrdConstantBufferStride = 0;

static VkSampler g_nrdSamplerNearest = VK_NULL_HANDLE;
static VkSampler g_nrdSamplerLinear = VK_NULL_HANDLE;

// NRD's SPIR-V declares TWO descriptor sets, not one.  Dumping the decorations
// out of the shipped blob (tools/nrd_spirv_sets.js on
// cpp/deps/NRD/_Shaders/REBLUR_ClassifyTiles.cs.spirv.h) reads back:
//
//   set 0 binding 3    gOut_Tiles                       (storage image)
//   set 0 binding 20   gIn_ViewZ                        (sampled image)
//   set 1 binding 2    REBLUR_ClassifyTilesConstants    (uniform block)
//
// which is exactly the split NRD reports at runtime (InstanceDesc
// .resourcesSpaceIndex = 0, .constantBufferAndSamplersSpaceIndex = 1, both
// printed in [NRD-1 INIT]).  The earlier single-set layout put the constant
// buffer and the immutable samplers into SET 0 while the shaders read them
// from SET 1, so every NRD pass executed with an unbound constant buffer and
// unbound samplers.  With gRectSize / gRectSizeMinusOne / gDenoisingRange all
// reading as zero every pass returns at its "outside the rect" early-out and
// OUT_DIFF_RADIANCE_HITDIST is never written -- the clean black the composite
// used to see.  NVIDIA's own integration keeps them apart the same way
// (cpp/deps/NRD/Integration/NRDIntegration.hpp: resources.registerSpace vs
// pipelineLayoutDesc.rootRegisterSpace).
static VkDescriptorSetLayout g_nrdDescriptorSetLayout = VK_NULL_HANDLE;
static VkDescriptorSetLayout g_nrdConstantSetLayout = VK_NULL_HANDLE;
static VkPipelineLayout g_nrdPipelineLayout = VK_NULL_HANDLE;
static VkDescriptorPool g_nrdDescriptorPool = VK_NULL_HANDLE;

// ONE SET PER DISPATCH, not one shared set.  vkUpdateDescriptorSets is a
// host-side call, so a single set reused across the frame's dispatches would
// have every dispatch observe the LAST update written before submission --
// the earlier passes would silently read the wrong textures.  Allocating one
// set per dispatch (NRD_MAX_DISPATCHES of them, from one pool) removes the
// hazard without touching the command stream.
static std::vector<VkDescriptorSet> g_nrdDescriptorSets;

// The same, one per dispatch, for the constant buffer + samplers set (SET 1).
static std::vector<VkDescriptorSet> g_nrdConstantSets;

// One entry per nrd::PipelineDesc.  NRD returns SPIR-V for every pass it may
// dispatch; each becomes one VkPipeline on the shared layout.
static std::vector<VkPipeline> g_nrdPipelines;

// The permanent pool holds NRD's history (must survive across frames), the
// transient pool is scratch that can be recycled the moment denoising ends.
static std::vector<VkImage> g_nrdPermanentImages;
static std::vector<VkDeviceMemory> g_nrdPermanentMemories;
static std::vector<VkImageView> g_nrdPermanentViews;
static std::vector<VkImageLayout> g_nrdPermanentLayouts;
static std::vector<nrd::TextureDesc> g_nrdPermanentDescs;

static std::vector<VkImage> g_nrdTransientImages;
static std::vector<VkDeviceMemory> g_nrdTransientMemories;
static std::vector<VkImageView> g_nrdTransientViews;
static std::vector<VkImageLayout> g_nrdTransientLayouts;
static std::vector<nrd::TextureDesc> g_nrdTransientDescs;

// App-provided inputs / output.  These are NOT NRD pool textures: the raygen
// writes the three inputs and reads the denoised result back out of the
// output, so they live in the RT descriptor set (bindings 50-53).
static VkImage g_nrdViewZImage = VK_NULL_HANDLE;
static VkDeviceMemory g_nrdViewZMemory = VK_NULL_HANDLE;
static VkImageView g_nrdViewZView = VK_NULL_HANDLE;
static VkImageLayout g_nrdViewZLayout = VK_IMAGE_LAYOUT_UNDEFINED;

static VkImage g_nrdNormalRoughnessImage = VK_NULL_HANDLE;
static VkDeviceMemory g_nrdNormalRoughnessMemory = VK_NULL_HANDLE;
static VkImageView g_nrdNormalRoughnessView = VK_NULL_HANDLE;
static VkImageLayout g_nrdNormalRoughnessLayout = VK_IMAGE_LAYOUT_UNDEFINED;

// IN_MV（binding 55）。★ 2026-09-30：写它的 rt_restir_final.rgen 已随 ReSTIR DI 链
// 删除，NRD 整条链也由 kNrdLocalDiEnabled=false 永久关停 ⇒ 本图现在**既无写者也无
// 读者**，只在创建时被清零一次（nrdTransitionImagesToGeneral）。保留是为将来重建链路。
static VkImage g_nrdMotionImage = VK_NULL_HANDLE;
static VkDeviceMemory g_nrdMotionMemory = VK_NULL_HANDLE;
static VkImageView g_nrdMotionView = VK_NULL_HANDLE;
static VkImageLayout g_nrdMotionLayout = VK_IMAGE_LAYOUT_UNDEFINED;

static VkImage g_nrdDiffRadianceHitDistImage = VK_NULL_HANDLE;
static VkDeviceMemory g_nrdDiffRadianceHitDistMemory = VK_NULL_HANDLE;
static VkImageView g_nrdDiffRadianceHitDistView = VK_NULL_HANDLE;
