// 2026-10-23：体积雾的动态光源绑定（体积云 render set 的 binding 12/13）。
// 与 rgen 的 binding 17/18 是**同一对 buffer**，只是另一个 descriptor set ——
// 于是"雾里亮的火把"与"rgen 里给表面打光的火把"结构上必然是同一盏灯。
// 只在句柄真的变了（本地光表扩容重建 / 云描述符集重建）时重写：描述符集可能
// 仍被在途帧使用，那时无条件改写是未定义行为。
static void updateCloudLocalLightDescriptors()
{
    if(g_volumetricCloudRenderSet == VK_NULL_HANDLE ||
       g_localLightGpuBuffer == VK_NULL_HANDLE ||
       g_localLightGridGpuBuffer == VK_NULL_HANDLE)
    {
        return;
    }
    if(g_cloudFogLightSetBound == g_volumetricCloudRenderSet &&
       g_cloudFogLightListBound == g_localLightGpuBuffer &&
       g_cloudFogLightGridBound == g_localLightGridGpuBuffer)
    {
        return;
    }

    VkDescriptorBufferInfo lightListInfo{};
    lightListInfo.buffer = g_localLightGpuBuffer;
    lightListInfo.offset = 0u;
    lightListInfo.range = VK_WHOLE_SIZE;
    VkDescriptorBufferInfo lightGridInfo{};
    lightGridInfo.buffer = g_localLightGridGpuBuffer;
    lightGridInfo.offset = 0u;
    lightGridInfo.range = VK_WHOLE_SIZE;

    VkWriteDescriptorSet writes[2]{};
    writes[0] = { VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, nullptr,
        g_volumetricCloudRenderSet, 12u, 0u, 1u,
        VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, nullptr, &lightListInfo, nullptr };
    writes[1] = { VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET, nullptr,
        g_volumetricCloudRenderSet, 13u, 0u, 1u,
        VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, nullptr, &lightGridInfo, nullptr };
    vkUpdateDescriptorSets(g_device, 2u, writes, 0u, nullptr);

    g_cloudFogLightSetBound = g_volumetricCloudRenderSet;
    g_cloudFogLightListBound = g_localLightGpuBuffer;
    g_cloudFogLightGridBound = g_localLightGridGpuBuffer;
    g_cloudFogLightDescriptorsReady.store(true);
}

// =====================================================
// 2026-10-11 SHaRC 资源：创建 / 销毁 / 描述符发布（bindings 65..68）
// =====================================================

static void destroySharcBuffers()
{
    if(g_sharcHashEntriesBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcHashEntriesBuffer, nullptr);
        g_sharcHashEntriesBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcHashEntriesMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcHashEntriesMemory, nullptr);
        g_sharcHashEntriesMemory = VK_NULL_HANDLE;
    }

    if(g_sharcAccumulationBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcAccumulationBuffer, nullptr);
        g_sharcAccumulationBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcAccumulationMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcAccumulationMemory, nullptr);
        g_sharcAccumulationMemory = VK_NULL_HANDLE;
    }

    if(g_sharcResolvedBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcResolvedBuffer, nullptr);
        g_sharcResolvedBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcResolvedMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcResolvedMemory, nullptr);
        g_sharcResolvedMemory = VK_NULL_HANDLE;
    }

    if(g_sharcLockBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcLockBuffer, nullptr);
        g_sharcLockBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcLockMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcLockMemory, nullptr);
        g_sharcLockMemory = VK_NULL_HANDLE;
    }

    g_sharcEntryCountResolved = 0u;
    g_sharcBuffersReady = false;
    g_sharcZeroed = false;

    // 地址一并归零：UBO 里那四个 lane 全 0 = 未启用/未就绪，着色器把模式闸门钉在 0。
    g_sharcHashEntriesAddress = 0u;
    g_sharcAccumulationAddress = 0u;
    g_sharcResolvedAddress = 0u;
    g_sharcLockAddress = 0u;

    // 5a 探针的 staging 与状态一起清掉：退出世界后重新进世界要能重做一次探针
    // （否则 g_sharcProbeStage 停在 2，重建缓冲后模式 lane 永远回不到 1）。
    if(g_sharcProbeStagingBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcProbeStagingBuffer, nullptr);
        g_sharcProbeStagingBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcProbeStagingMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcProbeStagingMemory, nullptr);
        g_sharcProbeStagingMemory = VK_NULL_HANDLE;
    }

    g_sharcProbeStage = 0u;
    g_sharcProbeTickCount = 0u;
    g_sharcProbeArmTick = 0u;
}

// 创建四块缓存缓冲（幂等）。失败时置 g_sharcCreateFailed 并让 g_sharcBuffersReady
// 保持 false ⇒ 此后不再重试，着色器的模式也永远进不到"用缓存"那一档，因而不会去
// 访问未写描述符的 65..68（未写描述符被访问是 UB）。
//
// 这里**不清零**：清零放在第一个启用帧（vkCmdFillBuffer 录进本帧 cmd），避免世界
// 初始化时插一次性 submit + wait。见文件上方 SHaRC 块里的说明。
static void ensureSharcBuffers()
{
    if(g_sharcBuffersReady || g_sharcCreateFailed)
    {
        return;
    }

    if(
        g_device == VK_NULL_HANDLE ||
        g_physicalDevice == VK_NULL_HANDLE ||
        !sharcEnabled()
    )
    {
        return;
    }

    const uint32_t entries =
        static_cast<uint32_t>(1u) << sharcEntryCount();

    // STORAGE_BUFFER：GPU 侧原子写 + 随机读。
    // TRANSFER_DST：首个启用帧要用 vkCmdFillBuffer 把它清零。
    // SHADER_DEVICE_ADDRESS：buffer_reference 按地址访问（见 CameraUBO 尾块）。
    //   createBuffer 已处理配套的 VK_MEMORY_ALLOCATE_DEVICE_ADDRESS_BIT（其内部按
    //   usage 位判断），所以这里只加标志即可。
    const VkBufferUsageFlags sharcUsage =
        VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
        VK_BUFFER_USAGE_TRANSFER_DST_BIT |
        VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT;

    // device-local：这是每像素随机读写 + 原子累加的热缓冲，不能放 host-visible。
    const VkMemoryPropertyFlags sharcProps =
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT;

    const VkDeviceSize hashBytes =
        static_cast<VkDeviceSize>(entries) * 8u;
    const VkDeviceSize accumulationBytes =
        static_cast<VkDeviceSize>(entries) * 16u;
    const VkDeviceSize resolvedBytes =
        static_cast<VkDeviceSize>(entries) * 16u;
    const VkDeviceSize lockBytes =
        static_cast<VkDeviceSize>(entries) * 4u;

    try
    {
        createBuffer(
            g_device, g_physicalDevice, hashBytes, sharcUsage, sharcProps,
            g_sharcHashEntriesBuffer, g_sharcHashEntriesMemory);

        createBuffer(
            g_device, g_physicalDevice, accumulationBytes, sharcUsage, sharcProps,
            g_sharcAccumulationBuffer, g_sharcAccumulationMemory);

        createBuffer(
            g_device, g_physicalDevice, resolvedBytes, sharcUsage, sharcProps,
            g_sharcResolvedBuffer, g_sharcResolvedMemory);

        createBuffer(
            g_device, g_physicalDevice, lockBytes, sharcUsage, sharcProps,
            g_sharcLockBuffer, g_sharcLockMemory);

        // 2026-10-11：取四块缓冲的设备地址（buffer_reference 按地址访问，见 CameraUBO
        // 尾块）。放在 try 里是有意的 —— 任一步失败都会走到下面的 catch，把资源收干净
        // 并让 g_sharcBuffersReady 留在 false（着色器的模式闸门因此恒为 0）。
        g_sharcHashEntriesAddress =
            getBufferDeviceAddress(g_device, g_sharcHashEntriesBuffer);
        g_sharcAccumulationAddress =
            getBufferDeviceAddress(g_device, g_sharcAccumulationBuffer);
        g_sharcResolvedAddress =
            getBufferDeviceAddress(g_device, g_sharcResolvedBuffer);
        g_sharcLockAddress =
            getBufferDeviceAddress(g_device, g_sharcLockBuffer);
    }
    catch(...)
    {
        // 新增的可选特性，不能因为它拿不到显存就把世界初始化整个抛出去。
        destroySharcBuffers();
        g_sharcCreateFailed = true;

        RTLog("[SHARC] 资源创建失败（显存不足？）⇒ 本次会话停用 SHaRC");
        return;
    }

    g_sharcEntryCountResolved = entries;
    g_sharcBuffersReady = true;

    {
        std::ostringstream log;
        log << "[SHARC] 缓存资源已创建"
            << " entries=" << entries
            << " hashMB=" << (static_cast<double>(hashBytes) / 1048576.0)
            << " accumMB=" << (static_cast<double>(accumulationBytes) / 1048576.0)
            << " resolvedMB=" << (static_cast<double>(resolvedBytes) / 1048576.0)
            << " lockMB=" << (static_cast<double>(lockBytes) / 1048576.0)
            << " totalMB=" << (static_cast<double>(hashBytes + accumulationBytes + resolvedBytes + lockBytes) / 1048576.0)
            << " scale=" << sharcSceneScale()
            << " 待首个启用帧清零";
        RTLog(log.str());
    }
}

// 把四块缓存写进 bindings 65..68。必须在 ensureSharcBuffers() 之后、且
// g_rayTracingDescriptorSet 有效时调用。
static void updateSharcDescriptors()
{
    if(
        g_rayTracingDescriptorSet == VK_NULL_HANDLE ||
        !g_sharcBuffersReady
    )
    {
        return;
    }

    const VkBuffer buffers[4] = {
        g_sharcHashEntriesBuffer,
        g_sharcAccumulationBuffer,
        g_sharcResolvedBuffer,
        g_sharcLockBuffer
    };

    const uint32_t bindings[4] = { 65u, 66u, 67u, 68u };

    VkDescriptorBufferInfo infos[4]{};
    VkWriteDescriptorSet writes[4]{};

    for(uint32_t index = 0u; index < 4u; ++index)
    {
        infos[index].buffer = buffers[index];
        infos[index].offset = 0u;
        infos[index].range = VK_WHOLE_SIZE;

        writes[index].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[index].dstSet = g_rayTracingDescriptorSet;
        writes[index].dstBinding = bindings[index];
        writes[index].descriptorCount = 1u;
        writes[index].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
        writes[index].pBufferInfo = &infos[index];
    }

    vkUpdateDescriptorSets(g_device, 4u, writes, 0u, nullptr);
}


// =====================================================
// 2026-10-11 SHaRC 5a —— 寻址探针（一次性，默认随 ORION_SHARC 打开）
//
// 为什么必须有这一步
// ------------------
// 到零号版本为止我们只证明了"能编译"。但三块缓存是按 GL_EXT_buffer_reference 的
// **64 位设备地址**访问的，一共有三种静默错法：
//   · 地址下发错（UBO lane 的 lo/hi 顺序，或 packUint2x32 的参数顺序）⇒ 读到别的显存；
//   · 元素下标错（capacity 与实际分配的元素数不一致）⇒ 读越界；
//   · 结构体字节偏移猜错（SharcPackedData 的 sampleData 到底在 +8 还是 +12）⇒ 读到
//     相邻字段的值。（2026-10-11 首跑探针时我就是猜错了这一项：期望写成 +12，实机
//     回读 0x46464646 ⇒ 报了假 FAIL。真实值 +8，由 SPIR-V 的 OpMemberDecorate 机械确认。）
// 三种都不报错、不崩溃，只会让之后所有调参建立在错误读数上。所以先用一组已知魔数把
// 四条寻址路径各走一遍。
//
// 时序（全部经 sharcProbeTick 在每帧的 Java_..._updateCamera 里推进）
// ----------------------------------------------------------------
//   stage 0（缓冲就绪的第一帧）
//       一次性提交：vkCmdUpdateBuffer 往四块缓冲的**第 0 个元素**写魔数，之后一道
//       显式屏障 + vkQueueWaitIdle 收尾。同帧起模式 lane（sharcCacheParams.w）= 1，
//       着色器随即在 (0,0) 这一个 invocation 里把读到的值回写进 lock[1..5]
//       （见 rt_test.rgen 的 sharcProbeWriteBack）。
//   stage 1（3 帧之后）
//       一次性提交：屏障（着色器写 → 传输读）+ vkCmdCopyBuffer 把 lock[0..5] 拷到
//       host-visible staging，vkQueueWaitIdle 后 map、逐项比对、打一行 [SHARC PROBE]，
//       并把模式 lane 复位为 0（探针只做一次）。
//
// 等待方式是照本工程既有的"一次性上传"惯例（纹理上传路径同样是 submit + 等待队列
// 空闲），不进入逐帧路径，也不改任何可见行为。
// =====================================================

// 默认跟随 ORION_SHARC（开了 SHaRC 就顺手做一次探针）。要跳过设
// ORION_SHARC_PROBE=0。
static bool sharcProbeEnabled()
{
    static const bool cached = []()
    {
        const char* raw = std::getenv("ORION_SHARC_PROBE");

        if(raw == nullptr || raw[0] == '\0')
        {
            return sharcEnabled();
        }

        return raw[0] != '0';
    }();

    return cached;
}

// 一次性提交的公共部分：分配 → begin → record() → end → submit → 等队列空闲 → 释放。
// 用函数指针而不是两个重复函数，是为了保证两处（写魔数 / 回读）的提交结构逐字一致。
static void sharcProbeOneShotSubmit(
    void (*record)(VkCommandBuffer),
    const char* label)
{
    VkCommandBufferAllocateInfo allocation{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO
    };
    allocation.commandPool = g_rtCommandPool;
    allocation.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
    allocation.commandBufferCount = 1u;

    VkCommandBuffer commandBuffer = VK_NULL_HANDLE;

    check(
        vkAllocateCommandBuffers(g_device, &allocation, &commandBuffer),
        label
    );

    VkCommandBufferBeginInfo beginInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO
    };
    beginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;

    check(vkBeginCommandBuffer(commandBuffer, &beginInfo), label);

    record(commandBuffer);

    check(vkEndCommandBuffer(commandBuffer), label);

    VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submit.commandBufferCount = 1u;
    submit.pCommandBuffers = &commandBuffer;

    check(vkQueueSubmit(g_queue, 1u, &submit, VK_NULL_HANDLE), label);
    check(vkQueueWaitIdle(g_queue), label);

    vkFreeCommandBuffers(g_device, g_rtCommandPool, 1u, &commandBuffer);
}

static void sharcProbeRecordMagic(VkCommandBuffer commandBuffer)
{
    const uint32_t hashWords[2] = {
        SHARC_PROBE_HASH_LO, SHARC_PROBE_HASH_HI
    };
    const uint32_t accumulationWords[4] = {
        SHARC_PROBE_ACCUM_X, 0x34343434u, 0x35353535u, 0x36363636u
    };
    const uint32_t resolvedWords[4] = {
        SHARC_PROBE_RESOLVED_W0,
        SHARC_PROBE_RESOLVED_W1,
        SHARC_PROBE_RESOLVED_SAMPLE,
        SHARC_PROBE_RESOLVED_SAMPLE_EXT
    };

    // vkCmdUpdateBuffer 在录制时就把数据拷进命令缓冲，所以这几个局部数组的生存期
    // 只需要覆盖本次录制。要求 offset/size 都是 4 的倍数，且缓冲带 TRANSFER_DST。
    vkCmdUpdateBuffer(
        commandBuffer, g_sharcHashEntriesBuffer, 0u, 8u, hashWords);
    vkCmdUpdateBuffer(
        commandBuffer, g_sharcAccumulationBuffer, 0u, 16u, accumulationWords);
    vkCmdUpdateBuffer(
        commandBuffer, g_sharcResolvedBuffer, 0u, 16u, resolvedWords);
    vkCmdUpdateBuffer(
        commandBuffer, g_sharcLockBuffer, 0u, 4u, &SHARC_PROBE_LOCK_MAGIC);

    // 传输写 → 着色器读/写。跨提交的可见性由随后的 vkQueueWaitIdle 收尾（本工程既有
    // 上传惯例），这道屏障把可用性/可见性显式写清楚。
    const VkBuffer probeBuffers[4] = {
        g_sharcHashEntriesBuffer,
        g_sharcAccumulationBuffer,
        g_sharcResolvedBuffer,
        g_sharcLockBuffer
    };

    VkBufferMemoryBarrier barriers[4]{};

    for(uint32_t index = 0u; index < 4u; ++index)
    {
        barriers[index].sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
        barriers[index].srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        barriers[index].dstAccessMask =
            VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        barriers[index].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].buffer = probeBuffers[index];
        barriers[index].offset = 0u;
        barriers[index].size = VK_WHOLE_SIZE;
    }

    vkCmdPipelineBarrier(
        commandBuffer,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        0u,
        0u, nullptr,
        4u, barriers,
        0u, nullptr);
}

static void sharcProbeRecordReadBack(VkCommandBuffer commandBuffer)
{
    VkBufferMemoryBarrier barrier{};
    barrier.sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
    barrier.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
    barrier.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
    barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.buffer = g_sharcLockBuffer;
    barrier.offset = 0u;
    barrier.size = 28u; // 7 个 uint32：回读槽 0..6（见 sharcProbeWriteBack）

    vkCmdPipelineBarrier(
        commandBuffer,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        0u,
        0u, nullptr,
        1u, &barrier,
        0u, nullptr);

    VkBufferCopy copy{};
    copy.srcOffset = 0u;
    copy.dstOffset = 0u;
    copy.size = 28u;

    vkCmdCopyBuffer(
        commandBuffer,
        g_sharcLockBuffer,
        g_sharcProbeStagingBuffer,
        1u,
        &copy);
}

// 回读 + 逐项比对 + 打一行结论。锁缓冲在 HASH_GRID_ENABLE_64_BIT_ATOMICS=1（SDK 默认，
// 本工程就用这个）时完全不被缓存逻辑使用，所以拿它当回读槽不会影响任何东西。
static void sharcProbeReadBackAndReport()
{
    sharcProbeOneShotSubmit(
        sharcProbeRecordReadBack,
        "SHaRC probe read-back submit failed");

    uint32_t words[7] = { 0u, 0u, 0u, 0u, 0u, 0u, 0u };

    void* mapped = nullptr;
    check(
        vkMapMemory(g_device, g_sharcProbeStagingMemory, 0u, 28u, 0u, &mapped),
        "map SHaRC probe staging failed");

    std::memcpy(words, mapped, 28u);
    vkUnmapMemory(g_device, g_sharcProbeStagingMemory);

    const uint32_t expected[7] = {
        SHARC_PROBE_LOCK_MAGIC,
        SHARC_PROBE_HASH_LO,
        SHARC_PROBE_HASH_HI,
        SHARC_PROBE_ACCUM_X,
        SHARC_PROBE_RESOLVED_SAMPLE,      // +8  （曾被我误写成 +12 ⇒ 假 FAIL）
        SHARC_PROBE_RESOLVED_SAMPLE_EXT,  // +12
        g_sharcEntryCountResolved
    };

    uint32_t mismatches = 0u;

    for(uint32_t index = 0u; index < 7u; ++index)
    {
        if(words[index] != expected[index])
        {
            ++mismatches;
        }
    }

    char line[460];
    _snprintf_s(
        line,
        sizeof(line),
        _TRUNCATE,
        "[SHARC PROBE] lock0=%08X hashLo=%08X hashHi=%08X accumX=%08X "
        "resolvedSample=%08X resolvedSampleExt=%08X capacity=%u "
        "| expected %08X %08X %08X %08X %08X %08X %u "
        "| verdict=%s mismatch=%u",
        words[0], words[1], words[2], words[3], words[4], words[5], words[6],
        expected[0], expected[1], expected[2], expected[3], expected[4],
        expected[5], expected[6],
        mismatches == 0u ? "PASS" : "FAIL",
        mismatches);

    // PASS / FAIL 都用 RTLogFlushed：这一行是 5a 唯一的产物，必须落盘。
    RTLogFlushed(line);

    if(mismatches != 0u)
    {
        RTLogFlushed(
            "[SHARC PROBE] FAIL 的含义：上面逐项与期望不符的那个字段就是错的寻址环节 "
            "—— lock0 不符 = lock 地址错；hashLo/hashHi 不符 = hashEntries 地址或 "
            "uint64 的 lo/hi 顺序错；accumX 不符 = accumulation 地址错；"
            "resolvedSample 不符 = resolved 地址或 SharcPackedData 的字节偏移错；"
            "capacity 不符 = UBO 标量 lane 与着色器读法不一致。");
    }
}

// 回读用的 host-visible staging（5a 探针与 5b 统计共用一份）。
// 2026-10-11：64 → 128 字节。5b-3 的逐环节诊断需要 lock[12..19] 八个槽，
// 64 字节只够到 lock[15]；128 字节给到 lock[31]，后面调参还有余量。
static void ensureSharcStaging()
{
    if(g_sharcProbeStagingBuffer != VK_NULL_HANDLE)
    {
        return;
    }

    createBuffer(
        g_device,
        g_physicalDevice,
        128u,
        VK_BUFFER_USAGE_TRANSFER_DST_BIT,
        VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
            VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
        g_sharcProbeStagingBuffer,
        g_sharcProbeStagingMemory,
        true);
}

static void sharcProbeTick()
{
    if(!sharcProbeEnabled() || g_sharcProbeStage >= 2u)
    {
        return;
    }

    if(!g_sharcBuffersReady)
    {
        // ensureSharcBuffers() 还没成功（未启用 / 创建失败）⇒ 什么都不做。
        return;
    }

    ++g_sharcProbeTickCount;

    if(g_sharcProbeStage == 0u)
    {
        ensureSharcStaging();

        sharcProbeOneShotSubmit(
            sharcProbeRecordMagic,
            "SHaRC probe magic submit failed");

        g_sharcProbeStage = 1u;
        g_sharcProbeArmTick = g_sharcProbeTickCount;

        RTLogFlushed(
            "[SHARC PROBE] armed: magic written into element 0 of "
            "hashEntries / accumulation / resolved / lock; mode lane = 1 "
            "for the next 3 frames");

        return;
    }

    // 让着色器至少跑 3 帧（探针写回的时机无所谓，多留几帧避免恰好落在没渲染的帧上）。
    if(g_sharcProbeTickCount - g_sharcProbeArmTick < 3u)
    {
        return;
    }

    sharcProbeReadBackAndReport();

    // 探针只做一次；模式 lane 随之复位为 0（见两处 UBO 填写）。
    g_sharcProbeStage = 2u;
}


// =====================================================
// 2026-10-11 5b-1：SHaRC 的 Resolve pass 与首次清零
//
// 三块缓存（+lock）之间的依赖只有三条，都靠 VkBufferMemoryBarrier 显式表达：
//   1) 首次清零（TRANSFER 写）→ 光追/计算阶段读写
//   2) update（光追阶段）写 → Resolve（计算阶段）读写
//   3) Resolve 写 → 下一帧的光追阶段读写
// =====================================================

// 四块缓存缓冲的「全缓冲」屏障，供上面三条依赖复用。
static void sharcCacheBarrier(
    VkCommandBuffer cmd,
    VkPipelineStageFlags srcStage,
    VkPipelineStageFlags dstStage)
{
    const VkBuffer sharcBuffers[4] = {
        g_sharcHashEntriesBuffer,
        g_sharcAccumulationBuffer,
        g_sharcResolvedBuffer,
        g_sharcLockBuffer
    };

    VkBufferMemoryBarrier barriers[4]{};

    for(uint32_t index = 0u; index < 4u; ++index)
    {
        barriers[index].sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
        barriers[index].srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
        barriers[index].dstAccessMask =
            VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        barriers[index].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].buffer = sharcBuffers[index];
        barriers[index].offset = 0u;
        barriers[index].size = VK_WHOLE_SIZE;
    }

    vkCmdPipelineBarrier(
        cmd, srcStage, dstStage, 0u, 0u, nullptr, 4u, barriers, 0u, nullptr);
}

// 首次清零。录进**本帧命令缓冲**而不是单独 submit + vkQueueWaitIdle：世界初始化
// 路径里插一次性 submit + wait 会阻塞渲染线程（本工程历史上那次 53.3ms 停顿就是
// 这么来的）。代价是那**一帧**多填充 176MB，之后就恒为 true。
//
// 必须在 RT pass 之前调用：本帧的 update 一进来就要往清零过的缓存里写。
static void recordSharcZeroFillIfNeeded(VkCommandBuffer cmd)
{
    if(g_sharcZeroed || !g_sharcBuffersReady)
    {
        return;
    }

    // ⚠ 探针没跑完就不清零。5a 探针往四块缓冲的第 0 个元素写魔数、3 帧后回读校验；
    // 若中间把缓存清了，探针会读到 0 并报 FAIL —— 那是"仪器自己把证据擦了"。
    // 探针关掉时（ORION_SHARC_PROBE=0）不受此限。
    if(sharcProbeEnabled() && g_sharcProbeStage < 2u)
    {
        return;
    }

    vkCmdFillBuffer(cmd, g_sharcHashEntriesBuffer, 0u, VK_WHOLE_SIZE, 0u);
    vkCmdFillBuffer(cmd, g_sharcAccumulationBuffer, 0u, VK_WHOLE_SIZE, 0u);
    vkCmdFillBuffer(cmd, g_sharcResolvedBuffer, 0u, VK_WHOLE_SIZE, 0u);
    // lock 缓冲不参与缓存逻辑（64 位原子档下不用），但 5a 探针拿它当回读槽，
    // 一并清掉免得留下上次的读数。
    vkCmdFillBuffer(cmd, g_sharcLockBuffer, 0u, VK_WHOLE_SIZE, 0u);

    // 传输写 → 光追/计算读写。ⓘ 这里 srcAccess 是 TRANSFER_WRITE（不是共享辅助函数
    // 里的 SHADER_WRITE），所以单独写一遍。
    const VkBuffer sharcBuffers[4] = {
        g_sharcHashEntriesBuffer,
        g_sharcAccumulationBuffer,
        g_sharcResolvedBuffer,
        g_sharcLockBuffer
    };

    VkBufferMemoryBarrier barriers[4]{};

    for(uint32_t index = 0u; index < 4u; ++index)
    {
        barriers[index].sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
        barriers[index].srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        barriers[index].dstAccessMask =
            VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        barriers[index].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[index].buffer = sharcBuffers[index];
        barriers[index].offset = 0u;
        barriers[index].size = VK_WHOLE_SIZE;
    }

    vkCmdPipelineBarrier(
        cmd,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        0u, 0u, nullptr, 4u, barriers, 0u, nullptr);

    g_sharcZeroed = true;

    RTLogFlushed(
        "[SHARC] 缓存首次清零已录进本帧命令缓冲（hash 32MB + accum 64MB + "
        "resolved 64MB + lock 16MB 一次性 vkCmdFillBuffer）；"
        "模式 lane 从本帧起 = 3（update+query）或 2（只 query）");
}

// Resolve 管线。复用 set 0 的**现有**描述符集布局（g_rayTracingDescriptorSetLayout）：
// 这个 pass 只读相机 UBO（binding 2），三块缓存是经 UBO 的设备地址以 buffer_reference
// 进来的 —— 所以不需要新的描述符集布局 / 池。
static void ensureSharcResolvePipeline()
{
    if(
        g_sharcResolvePipeline != VK_NULL_HANDLE ||
        g_sharcResolvePipelineFailed
    )
    {
        return;
    }

    if(
        g_device == VK_NULL_HANDLE ||
        g_rayTracingDescriptorSetLayout == VK_NULL_HANDLE ||
        !sharcEnabled()
    )
    {
        return;
    }

    VkPipelineLayoutCreateInfo pipelineLayoutInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO
    };
    pipelineLayoutInfo.setLayoutCount = 1u;
    pipelineLayoutInfo.pSetLayouts = &g_rayTracingDescriptorSetLayout;

    try
    {
        check(
            vkCreatePipelineLayout(
                g_device, &pipelineLayoutInfo, nullptr,
                &g_sharcResolvePipelineLayout),
            "SHaRC resolve pipeline layout failed");

        const std::vector<uint8_t> code =
            loadSpv("shaders/rt_sharc_resolve.comp.spv");
        VkShaderModule shader = createShaderModule(g_device, code);

        VkPipelineShaderStageCreateInfo stage{
            VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO
        };
        stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        stage.module = shader;
        stage.pName = "main";

        VkComputePipelineCreateInfo pipelineInfo{
            VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO
        };
        pipelineInfo.stage = stage;
        pipelineInfo.layout = g_sharcResolvePipelineLayout;

        const VkResult result = vkCreateComputePipelines(
            g_device, getSharedPipelineCache(), 1u, &pipelineInfo, nullptr,
            &g_sharcResolvePipeline);

        vkDestroyShaderModule(g_device, shader, nullptr);

        check(result, "SHaRC resolve pipeline failed");

        RTLogFlushed(
            "[SHARC] Resolve 管线已创建（rt_sharc_resolve.comp.spv，"
            "复用 set 0 布局，local_size=64）");
    }
    catch(...)
    {
        // 失败就停用（不要每帧重试）。缓存因此不再被维护 ⇒ 由模式 lane 的
        // g_sharcZeroed 逻辑兜住：update 仍会写，但没人读，画面不受影响。
        g_sharcResolvePipelineFailed = true;
        g_sharcResolvePipeline = VK_NULL_HANDLE;
        RTLogFlushed("[SHARC] Resolve 管线创建失败 ⇒ 本次会话不跑 Resolve pass");
    }
}

// 每帧的 Resolve 派发（在 RT pass 之后）。
// ============================================================================
// 2026-10-11 5b-4：SHaRC update pass 的第二条 RT 管线 + 它自己的 SBT。
//
// 参考：Samples/Pathtracer/PathtracerPipelines.cpp:84-88（同一份源码的两个
// permutation：SHARC_UPDATE=1 / SHARC_QUERY）与 Pathtracer.cpp:867-877（每帧
// **先 update 再 render**）。本仓库此前只有一条 RT 管线、一份 SBT，没有第二套的
// 先例 —— 这里照 createRayTracingSBT() 的布局（:36268-36447）另起一份：
//   · 管线布局与描述符**复用**主 RT 的（同一 set 0）；
//   · SBT 的 group 排列与主管线相同（raygen / opaque / miss / translucent / water），
//     但 handles 必须从**这条管线**重新取（:36341 的 get() 是按管线句柄查询的）；
//   · dispatch 用满分辨率 + shader 内按 5×5 块选像素（4%，与参考
//     sharcDownscaleFactor=5 同一密度）—— 不能照搬参考的降分辨率 dispatch，
//     因为本工程 rgen 的射线取自绑定图像（rt_test.rgen:17088 imageSize(image)），
//     降 dispatch 只会覆盖屏幕左上角。该适配已写进 rgen 的注释。
// 失败处理照 ensureSharcResolvePipeline() 的既有模式：latch 后不再重试，
// update pass 缺席时查询自然查不到缓存 ⇒ 渲染退回实追（安全的中性态）。
// ============================================================================
static VkPipeline g_sharcUpdatePipeline = VK_NULL_HANDLE;
static VkBuffer g_sharcUpdateSbtBuffer = VK_NULL_HANDLE;
static VkDeviceMemory g_sharcUpdateSbtMemory = VK_NULL_HANDLE;
static VkStridedDeviceAddressRegionKHR g_sharcUpdateRaygenRegion{};
static VkStridedDeviceAddressRegionKHR g_sharcUpdateMissRegion{};
static VkStridedDeviceAddressRegionKHR g_sharcUpdateHitRegion{};
static VkStridedDeviceAddressRegionKHR g_sharcUpdateCallableRegion{};
static bool g_sharcUpdatePipelineFailed = false;

static void destroySharcUpdatePipeline()
{
    if(g_sharcUpdateSbtBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_sharcUpdateSbtBuffer, nullptr);
        g_sharcUpdateSbtBuffer = VK_NULL_HANDLE;
    }
    if(g_sharcUpdateSbtMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_sharcUpdateSbtMemory, nullptr);
        g_sharcUpdateSbtMemory = VK_NULL_HANDLE;
    }
    if(g_sharcUpdatePipeline != VK_NULL_HANDLE)
    {
        vkDestroyPipeline(g_device, g_sharcUpdatePipeline, nullptr);
        g_sharcUpdatePipeline = VK_NULL_HANDLE;
    }
}

static void ensureSharcUpdatePipeline()
{
    if(g_sharcUpdatePipeline != VK_NULL_HANDLE || g_sharcUpdatePipelineFailed)
    {
        return;
    }

    // 2026-10-12：SHaRC 总开关关着时**连这条管线都不建**。
    // 它与缓存缓冲没有依赖，所以上一版把它放在 init 里无条件创建 —— 后果是
    // ORION_SHARC=0 时仍然要多等两分钟（驱动编译第二条 RT 管线实测 114 秒：
    // 12:44:21 开始 → 12:46:15 完成），用户感知就是"关了还是卡在加载页"。
    // 放在函数内部而不是调用点，是为了让将来任何惰性调用路径也一起受门控。
    if(!sharcEnabled())
    {
        return;
    }
    // 2026-10-12 卡加载页修复：创建只依赖 layout 与 SBT 的 handle 尺寸 —— 缓存缓冲
    // 与描述符集都**不需要**（管线编译不碰它们）。此前的守卫要求 g_sharcBuffersReady
    // 与 g_rayTracingDescriptorSet，而 init 顺序是 SBT → CameraUBO → 描述符集、缓存
    // 更是运行期才建 ⇒ init 时机永远不满足 ⇒ 创建被推迟到首帧录制路径里，而
    // vkCreateRayTracingPipelinesKHR 一次要数秒（本工程 :689 的注释）⇒ 首帧卡死。
    if(g_rayTracingPipelineLayout == VK_NULL_HANDLE || g_handleSizeAligned == 0u)
    {
        return;
    }

    RTLog("[SHARC] update pass：开始创建第二 RT 管线（驱动编译着色器，可能阻塞数秒）");

    try
    {
        auto updateRgen = loadSpv("shaders/rt_test_sharc_update.rgen.spv");
        auto chit = loadSpv("shaders/rt_test.rchit.spv");
        auto miss = loadSpv("shaders/rt_test.rmiss.spv");
        auto ahit = loadSpv("shaders/rt_test.rahit.spv");
        auto translucentChit = loadSpv("shaders/rt_test_translucent.rchit.spv");
        auto translucentAhit = loadSpv("shaders/rt_test_translucent.rahit.spv");

        VkShaderModule mods[6]{};
        const char* entry = "main";
        VkShaderModuleCreateInfo mci{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};
        auto makeModule = [&](const std::vector<uint8_t>& code, VkShaderModule& out)
        {
            mci.codeSize = code.size();
            mci.pCode = reinterpret_cast<const uint32_t*>(code.data());
            check(vkCreateShaderModule(g_device, &mci, nullptr, &out),
                  "Failed to create SHaRC update shader module");
        };
        makeModule(updateRgen, mods[0]);
        makeModule(chit, mods[1]);
        makeModule(miss, mods[2]);
        makeModule(ahit, mods[3]);
        makeModule(translucentChit, mods[4]);
        makeModule(translucentAhit, mods[5]);

        VkPipelineShaderStageCreateInfo stages[6]{};
        const VkShaderStageFlagBits stageKinds[6] = {
            VK_SHADER_STAGE_RAYGEN_BIT_KHR, VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR,
            VK_SHADER_STAGE_MISS_BIT_KHR, VK_SHADER_STAGE_ANY_HIT_BIT_KHR,
            VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR, VK_SHADER_STAGE_ANY_HIT_BIT_KHR };
        for(uint32_t i = 0u; i < 6u; ++i)
        {
            stages[i].sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
            stages[i].stage = stageKinds[i];
            stages[i].module = mods[i];
            stages[i].pName = entry;
        }

        // group 排列照主管线（:44004-44014）：0 raygen / 1 opaque / 2 miss /
        // 3 translucent / 4 water。
        VkRayTracingShaderGroupCreateInfoKHR groups[5]{};
        groups[0].sType = VK_STRUCTURE_TYPE_RAY_TRACING_SHADER_GROUP_CREATE_INFO_KHR;
        groups[0].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_GENERAL_KHR;
        groups[0].generalShader = 0u;
        groups[0].closestHitShader = VK_SHADER_UNUSED_KHR;
        groups[0].anyHitShader = VK_SHADER_UNUSED_KHR;
        groups[0].intersectionShader = VK_SHADER_UNUSED_KHR;
        groups[1] = groups[0];
        groups[1].type = VK_RAY_TRACING_SHADER_GROUP_TYPE_TRIANGLES_HIT_GROUP_KHR;
        groups[1].generalShader = VK_SHADER_UNUSED_KHR;
        groups[1].closestHitShader = 1u;
        groups[1].anyHitShader = 3u;
        groups[2] = groups[0];
        groups[2].generalShader = 2u;
        groups[3] = groups[1];
        groups[3].closestHitShader = 4u;
        groups[3].anyHitShader = 5u;
        groups[4] = groups[1];

        VkRayTracingPipelineCreateInfoKHR pci{
            VK_STRUCTURE_TYPE_RAY_TRACING_PIPELINE_CREATE_INFO_KHR};
        pci.stageCount = 6u;
        pci.pStages = stages;
        pci.groupCount = 5u;
        pci.pGroups = groups;
        pci.maxPipelineRayRecursionDepth = 1u;
        pci.layout = g_rayTracingPipelineLayout;
        if(g_ommNativeEnabled)
        {
            pci.flags |= VK_PIPELINE_CREATE_RAY_TRACING_OPACITY_MICROMAP_BIT_EXT;
        }

        auto createPipe =
            reinterpret_cast<PFN_vkCreateRayTracingPipelinesKHR>(
                vkGetDeviceProcAddr(g_device, "vkCreateRayTracingPipelinesKHR"));
        if(!createPipe)
        {
            throw std::runtime_error("vkCreateRayTracingPipelinesKHR unavailable");
        }
        check(createPipe(g_device, VK_NULL_HANDLE, getSharedPipelineCache(), 1u,
                         &pci, nullptr, &g_sharcUpdatePipeline),
              "Failed to create SHaRC update RT pipeline");

        for(uint32_t i = 0u; i < 6u; ++i)
        {
            vkDestroyShaderModule(g_device, mods[i], nullptr);
        }

        // ---- SBT（照 createRayTracingSBT 的布局，handles 从本管线取）----
        auto getHandles =
            reinterpret_cast<PFN_vkGetRayTracingShaderGroupHandlesKHR>(
                vkGetDeviceProcAddr(g_device,
                                    "vkGetRayTracingShaderGroupHandlesKHR"));
        if(!getHandles)
        {
            throw std::runtime_error(
                "vkGetRayTracingShaderGroupHandlesKHR unavailable");
        }

        VkPhysicalDeviceRayTracingPipelinePropertiesKHR rtProps{};
        rtProps.sType =
            VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_PIPELINE_PROPERTIES_KHR;
        VkPhysicalDeviceProperties2 props2{
            VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2};
        props2.pNext = &rtProps;
        vkGetPhysicalDeviceProperties2(g_physicalDevice, &props2);

        const uint32_t hs = rtProps.shaderGroupHandleSize;
        const uint32_t ha = rtProps.shaderGroupHandleAlignment;
        const uint32_t ba = rtProps.shaderGroupBaseAlignment;
        const uint32_t handleAligned = ((hs + ha - 1u) / ha) * ha;
        const uint32_t raygenOffset = 0u;
        const uint32_t missOffset =
            ((raygenOffset + handleAligned + ba - 1u) / ba) * ba;
        const uint32_t hitOffset =
            ((missOffset + handleAligned + ba - 1u) / ba) * ba;
        const uint32_t sbtSize =
            ((hitOffset + SBT_HIT_RECORD_COUNT * handleAligned + ba - 1u) / ba) *
            ba;

        // SBT group 下标照 createRayTracingSBT() 内的局部常量（RAYGEN=0 / OPAQUE=1 /
        // MISS=2 / ALPHA=3 / WATER=4）。那些常量是函数内的局部量，这里引用不到，
        // 只能复写同一套数值 —— 两处已互指，若日后改动要一起改。
        const uint32_t sharcRaygenGroup = 0u;
        const uint32_t sharcMissGroup = 2u;
        const uint32_t sharcOpaqueGroup = 1u;
        const uint32_t sharcAlphaGroup = 3u;
        const uint32_t sharcWaterGroup = 4u;
        const uint32_t sharcGroupCount = 5u;

        std::vector<uint8_t> handles((size_t)sharcGroupCount * hs, 0);
        check(getHandles(g_device, g_sharcUpdatePipeline, 0u,
                         sharcGroupCount, handles.size(), handles.data()),
              "Failed to get SHaRC update RT shader handles");

        std::vector<uint8_t> data((size_t)sbtSize, 0);
        std::memcpy(data.data() + raygenOffset,
                    handles.data() + sharcRaygenGroup * hs, hs);
        std::memcpy(data.data() + missOffset,
                    handles.data() + sharcMissGroup * hs, hs);
        const uint32_t recordGroups[SBT_HIT_RECORD_COUNT] = {
            sharcOpaqueGroup, sharcOpaqueGroup, sharcAlphaGroup,
            sharcWaterGroup, sharcOpaqueGroup };
        for(uint32_t record = 0u; record < SBT_HIT_RECORD_COUNT; ++record)
        {
            std::memcpy(data.data() + hitOffset + record * handleAligned,
                        handles.data() + recordGroups[record] * hs, hs);
        }

        createBuffer(g_device, g_physicalDevice, sbtSize,
                     VK_BUFFER_USAGE_SHADER_BINDING_TABLE_BIT_KHR |
                         VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT,
                     VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                         VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                     g_sharcUpdateSbtBuffer, g_sharcUpdateSbtMemory, true);

        void* sbtMapped = nullptr;
        check(vkMapMemory(g_device, g_sharcUpdateSbtMemory, 0u, sbtSize, 0u,
                          &sbtMapped),
              "map SHaRC update SBT failed");
        std::memcpy(sbtMapped, data.data(), sbtSize);
        vkUnmapMemory(g_device, g_sharcUpdateSbtMemory);

        const uint64_t sbtAddress =
            getBufferDeviceAddress(g_device, g_sharcUpdateSbtBuffer);
        g_sharcUpdateRaygenRegion.deviceAddress = sbtAddress + raygenOffset;
        g_sharcUpdateRaygenRegion.stride = handleAligned;
        g_sharcUpdateRaygenRegion.size = handleAligned;
        g_sharcUpdateMissRegion.deviceAddress = sbtAddress + missOffset;
        g_sharcUpdateMissRegion.stride = handleAligned;
        g_sharcUpdateMissRegion.size = handleAligned;
        g_sharcUpdateHitRegion.deviceAddress = sbtAddress + hitOffset;
        g_sharcUpdateHitRegion.stride = handleAligned;
        g_sharcUpdateHitRegion.size =
            SBT_HIT_RECORD_COUNT * handleAligned;
        g_sharcUpdateCallableRegion.deviceAddress = 0u;
        g_sharcUpdateCallableRegion.stride = 0u;
        g_sharcUpdateCallableRegion.size = 0u;

        RTLog("[SHARC] update pass 管线已创建（rt_test_sharc_update.rgen.spv，"
              "满分辨率 dispatch、shader 内 5×5 选块 = 4%）");
    }
    catch(const std::exception& error)
    {
        RTLog(std::string("[SHARC] update pass 管线创建失败（本会话不再重试，"
                          "查询将查不到缓存 ⇒ 渲染退回实追）：") + error.what());
        destroySharcUpdatePipeline();
        g_sharcUpdatePipelineFailed = true;
        g_sharcUpdatePipeline = VK_NULL_HANDLE;
    }
}

static void recordSharcUpdate(VkCommandBuffer cmd, uint32_t width, uint32_t height)
{
    if(!g_sharcZeroed || !g_sharcBuffersReady)
    {
        return;
    }
    if(g_rayTracingPipelineLayout == VK_NULL_HANDLE ||
       g_rayTracingDescriptorSet == VK_NULL_HANDLE)
    {
        return;
    }

    ensureSharcUpdatePipeline();
    if(g_sharcUpdatePipeline == VK_NULL_HANDLE)
    {
        return;
    }

    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_RAY_TRACING_KHR,
                      g_sharcUpdatePipeline);
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_RAY_TRACING_KHR,
                            g_rayTracingPipelineLayout, 0u, 1u,
                            &g_rayTracingDescriptorSet, 0u, nullptr);

    auto trace = getCmdTraceRays();
    if(!trace)
    {
        return;
    }

    // 满分辨率 dispatch；shader 内按 5×5 块选像素（4%，与参考
    // sharcDownscaleFactor=5 同一密度）。未选中像素在 shader 里直接退出。
    trace(cmd, &g_sharcUpdateRaygenRegion, &g_sharcUpdateMissRegion,
          &g_sharcUpdateHitRegion, &g_sharcUpdateCallableRegion,
          width, height, 1u);

    // update 写了 hashEntries / accumulation（也可能读了 resolved）⇒ 必须在渲染
    // pass 读缓存之前把写对读可见。四块一起，SHADER_WRITE → SHADER_READ|WRITE。
    sharcCacheBarrier(cmd, VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
                      VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR);
}

static void recordSharcResolve(VkCommandBuffer cmd)
{
    if(!g_sharcZeroed || !g_sharcBuffersReady)
    {
        return;
    }

    ensureSharcResolvePipeline();

    if(g_sharcResolvePipeline == VK_NULL_HANDLE)
    {
        return;
    }

    // 依赖 2：update 在本帧的光追阶段写了 accumulation / hashEntries，Resolve 要读它们。
    sharcCacheBarrier(
        cmd,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT);

    vkCmdBindPipeline(
        cmd, VK_PIPELINE_BIND_POINT_COMPUTE, g_sharcResolvePipeline);

    // 描述符集在 RT 与 COMPUTE 两个 bind point 上是分开绑的 —— set 0 里 binding 2
    // 是相机 UBO，这里再绑一次即可复用同一份内容。
    vkCmdBindDescriptorSets(
        cmd,
        VK_PIPELINE_BIND_POINT_COMPUTE,
        g_sharcResolvePipelineLayout,
        0u, 1u, &g_rayTracingDescriptorSet,
        0u, nullptr);

    const uint32_t sharcResolveGroups =
        (g_sharcEntryCountResolved + 63u) / 64u;

    vkCmdDispatch(cmd, sharcResolveGroups, 1u, 1u);

    // 依赖 3：Resolve 写了 hashEntries / accumulation / resolved，下一帧的光追阶段要用。
    sharcCacheBarrier(
        cmd,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT);
}


// =====================================================
// 2026-10-11 5b-1：更新速率读数（一次性）
//
// 为什么必须有：5b-1 不接 query ⇒ 缓存内容不影响任何像素。万一 update 因为某个门控
// 没生效而根本没跑，画面看不出来、成本也看起来"≈0"，于是"SHaRC 很便宜"就成了**假**
// 结论。所以让 rgen 每次成功更新往 lock[8] 原子加一，这里在缓存开始工作约 300 帧后
// 一次性回读，打一行 [SHARC STATS]：
//   · updates 的量级应与 屏幕像素数/25 × 帧数 同阶（1920×1080 ⇒ 每帧约 82k）；
//   · lock0 应为 0 —— 它是 5a 探针的魔数槽，被首次清零覆盖过 ⇒ 顺便证明清零生效。
// 用与探针相同的一次性提交 + 等待惯例（不进入逐帧路径）。只做一次（每进程一次）。
// =====================================================
static const uint32_t SHARC_STATS_FRAMES = 300u;

static uint32_t g_sharcStatsFrameTick = 0u;
static bool g_sharcStatsDone = false;

static void sharcStatsRecordReadBack(VkCommandBuffer commandBuffer)
{
    VkBufferMemoryBarrier barrier{};
    barrier.sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
    barrier.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
    barrier.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
    barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.buffer = g_sharcLockBuffer;
    barrier.offset = 0u;
    barrier.size = 128u; // lock[0..31]：0..6 探针槽 / 8 更新 / 10 失败 / 11 命中 / 12..19 诊断

    vkCmdPipelineBarrier(
        commandBuffer,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        0u, 0u, nullptr, 1u, &barrier, 0u, nullptr);

    VkBufferCopy copy{};
    copy.srcOffset = 0u;
    copy.dstOffset = 0u;
    copy.size = 128u;

    vkCmdCopyBuffer(
        commandBuffer,
        g_sharcLockBuffer,
        g_sharcProbeStagingBuffer,
        1u,
        &copy);
}

static void sharcStatsTick()
{
    // 只在"已经清零、缓存开始工作"之后才计数；否则计到的是准备期。
    if(
        g_sharcStatsDone ||
        !g_sharcZeroed ||
        !g_sharcBuffersReady
    )
    {
        return;
    }

    ++g_sharcStatsFrameTick;

    if(g_sharcStatsFrameTick < SHARC_STATS_FRAMES)
    {
        return;
    }

    ensureSharcStaging();

    if(g_sharcProbeStagingBuffer == VK_NULL_HANDLE)
    {
        g_sharcStatsDone = true;
        return;
    }

    sharcProbeOneShotSubmit(
        sharcStatsRecordReadBack,
        "SHaRC stats read-back submit failed");

    uint32_t words[32] = { 0u };

    void* mapped = nullptr;
    check(
        vkMapMemory(g_device, g_sharcProbeStagingMemory, 0u, 128u, 0u, &mapped),
        "map SHaRC stats staging failed");

    std::memcpy(words, mapped, 128u);
    vkUnmapMemory(g_device, g_sharcProbeStagingMemory);

    const double sharcUpdatesPerFrame =
        static_cast<double>(words[8]) /
        static_cast<double>(g_sharcStatsFrameTick);
    const double sharcFailsPerFrame =
        static_cast<double>(words[10]) /
        static_cast<double>(g_sharcStatsFrameTick);
    const double sharcHitsPerFrame =
        static_cast<double>(words[11]) /
        static_cast<double>(g_sharcStatsFrameTick);

    // 2026-10-11 5b-3 诊断：着色器里那四个计数是**1/256 抽样**累加的（见
    // rt_test.rgen 里 sharcDiagSampled 的说明 —— 全量打在单个全局地址上会串行化），
    // 所以这里 ×256 还原。lock[11] 是**全量精确**，不乘。
    // 这四个数的作用是把 "queryHits=0" 的三种成因分开：
    //   reached=0            ⇒ 代码根本没到（回路没进 / 前面 continue 掉了）
    //   reached>0 而三拒之和≈reached ⇒ 守卫拒光了（哪一条拒的多，看哪一个）
    //   reached>0 且守卫没拒光，但 hits=0 ⇒ 键不一致或样本数不够（缓存侧问题）
    const auto sharcSampledPerFrame =
        [](uint32_t value, uint32_t frames) -> double
        {
            return frames != 0u
                ? 256.0 * static_cast<double>(value) / static_cast<double>(frames)
                : 0.0;
        };

    char line[1200];
    _snprintf_s(
        line,
        sizeof(line),
        _TRUNCATE,
        "[SHARC STATS] frames=%u | GI跳数=%u | update=%.0f/frame fails=%.0f/frame | "
        "queryHits=%.0f/frame | query到达=%.0f/frame | lock0=%08X"
        " | 5b-4 口径：update = update pass 每帧成功写入缓存的**顶点数**（≈选中像素数"
        "×平均路径顶点数，选中像素 ≈ 渲染像素/25）；fails = SharcUpdateHit 返回 false，"
        "有两种原因——哈希插入失败 或 缓存重采样命中，缓存变热后后者占大头，"
        "fails 高不代表网格饱和；query到达 = 渲染 pass 走到查询点的次数（lock[12]，"
        "1/256 抽样 ×256 还原）；queryHits = 真正命中缓存并截断路径的次数"
        "（lock[11]，全量）。判读：queryHits>0 即 update→render→resolve 整条链通"
        "（前提 GI跳数≥2）；query到达>0 而 queryHits=0 ⇒ 守卫通过但查不到"
        "（缓存没被填充 或 存取键不一致）",
        g_sharcStatsFrameTick,
        g_perfGiBounces.load(),
        sharcUpdatesPerFrame,
        sharcFailsPerFrame,
        sharcHitsPerFrame,
        sharcSampledPerFrame(words[12], g_sharcStatsFrameTick),
        words[0]);

    RTLogFlushed(line);

    g_sharcStatsDone = true;
}


static void destroyVPTDirectHistoryBuffers()
{
    for(uint32_t i = 0u; i < 2u; ++i)
    {
        if(g_vptDirectHistoryBuffers[i] != VK_NULL_HANDLE)
        {
            vkDestroyBuffer(g_device, g_vptDirectHistoryBuffers[i], nullptr);
            g_vptDirectHistoryBuffers[i] = VK_NULL_HANDLE;
        }
        if(g_vptDirectHistoryMemories[i] != VK_NULL_HANDLE)
        {
            vkFreeMemory(g_device, g_vptDirectHistoryMemories[i], nullptr);
            g_vptDirectHistoryMemories[i] = VK_NULL_HANDLE;
        }
    }
    g_vptDirectHistoryWidth = 0u;
    g_vptDirectHistoryHeight = 0u;
    g_vptDirectHistoryBytes = 0;
    g_vptDirectHistoryNeedsClear = false;
}


static void updateVPTDirectHistoryDescriptors()
{
    if(
        g_rayTracingDescriptorSet == VK_NULL_HANDLE ||
        g_vptDirectHistoryBuffers[0] == VK_NULL_HANDLE ||
        g_vptDirectHistoryBuffers[1] == VK_NULL_HANDLE
    )
    {
        return;
    }

    VkDescriptorBufferInfo infos[2]{};
    VkWriteDescriptorSet writes[2]{};
    for(uint32_t i = 0u; i < 2u; ++i)
    {
        infos[i].buffer = g_vptDirectHistoryBuffers[i];
        infos[i].offset = 0;
        infos[i].range = VK_WHOLE_SIZE;

        writes[i].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[i].dstSet = g_rayTracingDescriptorSet;
        writes[i].dstBinding = 26u + i;
        writes[i].descriptorCount = 1;
        writes[i].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
        writes[i].pBufferInfo = &infos[i];
    }
    vkUpdateDescriptorSets(g_device, 2u, writes, 0u, nullptr);
}


static void createVPTDirectHistoryBuffers(uint32_t width, uint32_t height)
{
    if(width == 0u || height == 0u)
    {
        return;
    }
    if(
        g_vptDirectHistoryBuffers[0] != VK_NULL_HANDLE &&
        g_vptDirectHistoryBuffers[1] != VK_NULL_HANDLE &&
        g_vptDirectHistoryWidth == width &&
        g_vptDirectHistoryHeight == height
    )
    {
        return;
    }
    if(
        g_vptDirectHistoryBuffers[0] != VK_NULL_HANDLE ||
        g_vptDirectHistoryBuffers[1] != VK_NULL_HANDLE
    )
    {
        check(
            FGDeviceWaitIdle(g_device),
            "wait device before VPT direct-history recreate failed"
        );
    }

    destroyVPTDirectHistoryBuffers();

    const uint64_t pixelCount =
        static_cast<uint64_t>(width) * static_cast<uint64_t>(height);
    if(
        pixelCount > static_cast<uint64_t>(
            std::numeric_limits<VkDeviceSize>::max() / sizeof(VPTDirectHistoryGPU)
        )
    )
    {
        throw std::runtime_error("VPT direct-history size overflow");
    }

    // 2026-10-04 显存回收（无损）：缓冲从"两倍"收回**单倍** —— 后半已无写者。
    //
    // 核实依据（源码 + SPIR-V 双证，不是推测）：
    //   · cpp/shaders 下已无 rt_restir_final* 任何文件；全仓 localDITemporalAccumulate
    //     0 命中 ⇒ 后半唯一的写者（本地光 DI EMA）随该着色器一起被删掉了；
    //   · 活跃 rt_test.rgen 里 vptRead/WritePrimaryHistory 只用 entries[index]，
    //     而 index 恒 < pixelCount（没有任何 +pixelCount 偏移的访问）⇒ 后半无人读写。
    // 回收后每个缓冲 96 B/px → 48 B/px：
    //   超高性能档（640x350）省 21.5 MB，平衡档（1130x618）省 67 MB，
    //   DLAA（渲染=输出 1920x1051）省 194 MB。
    // 下方 2026-09-28 的历史说明原样保留：将来若恢复本地光 DI EMA，必须把后半加回来，
    // 并重新遵守"两个写者不得共用下标"的结论。
    //
    // 2026-09-28：每个缓冲扩成**两倍**，前后两半互不相干：
    //   前半 [0, pixelCount)              = rt_test.rgen 的 VPT 直射时域历史
    //                                      （evaluateVPTCandidateDirectTemporal /
    //                                       同族写者，count 上限 8）
    //   后半 [pixelCount, 2*pixelCount)   = rt_restir_final.rgen 的本地光 DI EMA
    //                                      （localDITemporalAccumulate，上限 64 帧）
    //
    // 为什么必须分开（这是实测结论，不是预防性设计）：把探针 RESTIR_DI_DEBUG_M
    // 打开后整屏读数显示，前半区**每个像素**都有活写者、计数已经积累到 8 以上。
    // 两个写者共用同一个下标时，后写的一方会按**自己的字段语义**覆盖对方的条目
    // （rt_test 写 normalAndPadding.w = 0，本地光 EMA 写 viewDepth），于是本地光
    // EMA 读回的自己的历史永远过不了深度判据，count 恒为 1、退化成原值直通——
    // 这正是"接上时域累积后画面丝毫没改善"的原因。
    const VkDeviceSize historyBytes =
        static_cast<VkDeviceSize>(pixelCount) *
        sizeof(VPTDirectHistoryGPU);
    for(uint32_t i = 0u; i < 2u; ++i)
    {
        createBuffer(
            g_device,
            g_physicalDevice,
            historyBytes,
            VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT,
            VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
            g_vptDirectHistoryBuffers[i],
            g_vptDirectHistoryMemories[i]
        );
    }

    g_vptDirectHistoryWidth = width;
    g_vptDirectHistoryHeight = height;
    g_vptDirectHistoryBytes = historyBytes;
    g_vptDirectHistoryNeedsClear = true;
    updateVPTDirectHistoryDescriptors();

    std::stringstream ss;
    ss << "[VPT-2.2] primary DDA history created size="
       << width << "x" << height
       << " bytesPerBuffer="
       << static_cast<unsigned long long>(historyBytes)
       << " (48 B/px 单半区；本地光 DI EMA 后半已随 rt_restir_final 删除而回收)"
       << " bindings=26,27";
    RTLog(ss.str());
}


static void prepareVPTDirectHistoryBuffers(VkCommandBuffer cmd)
{
    if(
        cmd == VK_NULL_HANDLE ||
        g_vptDirectHistoryBuffers[0] == VK_NULL_HANDLE ||
        g_vptDirectHistoryBuffers[1] == VK_NULL_HANDLE ||
        g_vptDirectHistoryBytes == 0
    )
    {
        return;
    }

    VkBufferMemoryBarrier barriers[2]{};
    for(uint32_t i = 0u; i < 2u; ++i)
    {
        // 只清**前半**（VPT 区）。后半是本地光 DI 的时域 EMA，VPT 数据更新并不
        // 使"接收面上的本地光辐照度"作废，清掉它等于每来一次 Section 更新就把
        // 累积到的 64 帧历史抹掉一次；它的几何/深度判据自己会拒绝过期条目。
        // 2026-10-04：缓冲已收回单半区，清屏长度改为整段。
        // （原先只清前半 [0, bytes/2)，因为后半是本地光 DI EMA、抹掉会丢 64 帧累积；
        //   后半现已随 rt_restir_final 一起删除，故这里清满。）
        if(g_vptDirectHistoryNeedsClear)
        {
            vkCmdFillBuffer(
                cmd,
                g_vptDirectHistoryBuffers[i],
                0,
                g_vptDirectHistoryBytes,
                0u
            );
        }

        barriers[i].sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER;
        barriers[i].srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[i].dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barriers[i].buffer = g_vptDirectHistoryBuffers[i];
        barriers[i].offset = 0;
        barriers[i].size = g_vptDirectHistoryBytes;
        barriers[i].srcAccessMask = g_vptDirectHistoryNeedsClear
            ? VK_ACCESS_TRANSFER_WRITE_BIT
            : VK_ACCESS_SHADER_WRITE_BIT;
        barriers[i].dstAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
    }

    vkCmdPipelineBarrier(
        cmd,
        g_vptDirectHistoryNeedsClear
            ? VK_PIPELINE_STAGE_TRANSFER_BIT
            : VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
                VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        0,
        0,
        nullptr,
        2,
        barriers,
        0,
        nullptr
    );
    g_vptDirectHistoryNeedsClear = false;
}


static void rebuildLocalLightGpuBuffer()
{
    if(
        g_device ==
            VK_NULL_HANDLE ||

        g_physicalDevice ==
            VK_NULL_HANDLE ||

        g_queue ==
            VK_NULL_HANDLE ||

        g_rayTracingDescriptorSet ==
            VK_NULL_HANDLE
    )
    {
        return;
    }


    const auto perfL10RebuildStart =
        std::chrono::steady_clock::now();

    double perfL10QueueIdleMilliseconds =
        0.0;

    // 触顶丢弃的光数（见 LOCAL_LIGHT_GPU_MAX_LIGHTS）。只在诊断行里报，不阻塞。
    size_t droppedLightCount =
        0u;


    // 2026-10-09：容量不再"按需增长"，而是**一次给足、永不改变**。
    // 这一改动的全部目的，就是让下面的 needsLocalLightGrow / needsGridGrow
    // 只在**首次创建**时为真 —— 之后无论内容怎么变都不会再走 `vkQueueWaitIdle`
    // （localLightQueueIdle 硬停的唯一来源）。原实现是 `totalBytes * 2` 的
    // 只增容量，内容每越过一次余量就再排空一次队列。依据见常量处注释。
    static VkDeviceSize
        g_localLightGpuCapacityBytes =
            LOCAL_LIGHT_GPU_FIXED_BYTES;

    static VkDeviceSize
        g_localLightGridCapacityBytes =
            LOCAL_LIGHT_GRID_FIXED_BYTES;


    std::vector<GPULocalLightRecord>
        gpuLights;


    std::unordered_map<
        LocalLightGridCellCoord,
        std::vector<uint32_t>,
        LocalLightGridCellCoordHash
    > gridCells;


    {
        std::lock_guard<std::mutex>
            lock(
                g_lightMutex
            );

        gpuLights.reserve(
            g_totalLocalLights
        );

        // unordered_map iteration order is intentionally unstable.  Light
        // indices are part of a ReSTIR reservoir, so aggregate Sections in a
        // stable order to avoid invalidating history for unchanged content.
        std::vector<uint64_t>
            orderedSectionKeys;

        orderedSectionKeys.reserve(
            g_lightSections.size()
        );

        for(const auto& sectionEntry : g_lightSections)
        {
            orderedSectionKeys.push_back(
                sectionEntry.first
            );
        }

        std::sort(
            orderedSectionKeys.begin(),
            orderedSectionKeys.end()
        );

        for(uint64_t sectionKey : orderedSectionKeys)
        {
            const auto sectionIt =
                g_lightSections.find(sectionKey);

            if(sectionIt == g_lightSections.end())
            {
                continue;
            }

            for(
                const LocalLightRecord& light :
                sectionIt->second
            )
            {
                // 触顶后丢弃尾部：**只记数、不阻塞**。关掉这一条就等于让容量
                // 重新变成运行时变量，也就把 localLightQueueIdle 硬停请回来 ——
                // 依据见 LOCAL_LIGHT_GPU_MAX_LIGHTS 的注释。
                // 注意 continue 必须同时跳过下面的 gridCells 登记与 gpuLights
                // 追加，否则网格索引会指向数组外的下标（着色器按
                // firstLightIndex/lightCount 在光照数组里直接寻址）。
                if(
                    gpuLights.size() >=
                    static_cast<size_t>(
                        LOCAL_LIGHT_GPU_MAX_LIGHTS
                    )
                )
                {
                    ++droppedLightCount;

                    continue;
                }

                GPULocalLightRecord
                    gpuLight{};

                gpuLight.worldX =
                    static_cast<float>(
                        light.worldX
                    );

                gpuLight.worldY =
                    static_cast<float>(
                        light.worldY
                    );

                gpuLight.worldZ =
                    static_cast<float>(
                        light.worldZ
                    );

                gpuLight.emissionLevel =
                    static_cast<float>(
                        light.emissionLevel
                    );

                gpuLight.typeCode =
                    static_cast<uint32_t>(
                        std::max(
                            light.typeCode,
                            0
                        )
                    );


                if(
                    gpuLights.size() >=
                    static_cast<size_t>(
                        std::numeric_limits<uint32_t>::max()
                    )
                )
                {
                    throw std::runtime_error(
                        "RT Local Lights exceed uint32 GPU index capacity"
                    );
                }


                const uint32_t lightIndex =
                    static_cast<uint32_t>(
                        gpuLights.size()
                    );


                const LocalLightGridCellCoord cellCoord{
                    localLightGridFloorDiv32(
                        light.worldX
                    ),
                    localLightGridFloorDiv32(
                        light.worldY
                    ),
                    localLightGridFloorDiv32(
                        light.worldZ
                    )
                };


                gridCells[cellCoord].push_back(
                    lightIndex
                );

                gpuLights.push_back(
                    gpuLight
                );
            }
        }
    }


    if(
        gridCells.size() >
        static_cast<size_t>(
            std::numeric_limits<uint32_t>::max()
        )
    )
    {
        throw std::runtime_error(
            "RT Local-Light grid exceeds uint32 cell capacity"
        );
    }


    const size_t requiredHashSlots =
        std::max<size_t>(
            1,
            gridCells.size() * 2
        );


    size_t hashCapacity =
        1;


    while(hashCapacity < requiredHashSlots)
    {
        if(
            hashCapacity >
            static_cast<size_t>(
                std::numeric_limits<uint32_t>::max()
            ) /
                2
        )
        {
            throw std::runtime_error(
                "RT Local-Light grid hash capacity overflow"
            );
        }


        hashCapacity *=
            2;
    }


    // Scratch reuse (2026-10-04 perf): the grid rebuild used to allocate a
    // fresh hash-table vector every rebuild.  thread_local keeps re-entrant or
    // multi-threaded callers independent.  The open-addressing fill below only
    // writes the slots it hashes into, so untouched slots must read as zero:
    // the explicit memset reproduces value-initialization exactly, while the
    // scratch only saves the heap allocation.
    thread_local std::vector<GPULocalLightGridSlot>
        gridSlotsScratch;
    gridSlotsScratch.resize(
        hashCapacity
    );
    std::memset(
        gridSlotsScratch.data(),
        0,
        gridSlotsScratch.size() * sizeof(GPULocalLightGridSlot)
    );
    std::vector<GPULocalLightGridSlot>& gridSlots = gridSlotsScratch;


    std::vector<uint32_t>
        gridLightIndices;

    gridLightIndices.reserve(
        gpuLights.size()
    );


    const size_t hashMask =
        hashCapacity - 1;

    // Use a stable insertion order.  Open addressing collision placement is
    // otherwise affected by unordered_map iteration and can produce a
    // different Binding-18 payload for the exact same light set.
    std::vector<LocalLightGridCellCoord>
        orderedGridCells;

    orderedGridCells.reserve(
        gridCells.size()
    );

    for(const auto& cellEntry : gridCells)
    {
        orderedGridCells.push_back(
            cellEntry.first
        );
    }

    std::sort(
        orderedGridCells.begin(),
        orderedGridCells.end(),
        [](
            const LocalLightGridCellCoord& a,
            const LocalLightGridCellCoord& b
        )
        {
            if(a.x != b.x)
            {
                return a.x < b.x;
            }

            if(a.y != b.y)
            {
                return a.y < b.y;
            }

            return a.z < b.z;
        }
    );

    // 每单元候选裁剪用的复用暂存（避免每单元一次堆分配）与被裁单元计数。
    // 语义与依据见 LOCAL_LIGHT_MAX_PER_CELL 的说明。
    std::vector<uint32_t>
        cellLightIndicesScratch;

    uint32_t
        cappedCellCount = 0u;


    for(const LocalLightGridCellCoord& gridCoord : orderedGridCells)
    {
        const auto cellIt =
            gridCells.find(gridCoord);

        if(cellIt == gridCells.end())
        {
            continue;
        }

        const LocalLightGridCellCoord& coord =
            cellIt->first;

        const std::vector<uint32_t>& cellLightIndices =
            cellIt->second;


        // 本单元真正要写进网格索引表的候选范围：默认原样，超过
        // LOCAL_LIGHT_MAX_PER_CELL 时按 emissionLevel 裁到前 K 个。
        // 只有这里被裁剪的光在这个单元里查不到；gpuLights 数组与它们的下标
        // 完全不变（下标是 ReSTIR reservoir 的一部分）。
        const uint32_t* packedCellFirst =
            cellLightIndices.data();

        size_t packedCellCount =
            cellLightIndices.size();

        if(
            LOCAL_LIGHT_MAX_PER_CELL > 0u &&
            packedCellCount >
                static_cast<size_t>(
                    LOCAL_LIGHT_MAX_PER_CELL
                )
        )
        {
            ++cappedCellCount;

            cellLightIndicesScratch.assign(
                cellLightIndices.begin(),
                cellLightIndices.end()
            );

            std::partial_sort(
                cellLightIndicesScratch.begin(),
                cellLightIndicesScratch.begin() +
                    static_cast<std::ptrdiff_t>(
                        LOCAL_LIGHT_MAX_PER_CELL
                    ),
                cellLightIndicesScratch.end(),
                [&gpuLights](
                    uint32_t left,
                    uint32_t right
                )
                {
                    const float leftEmission =
                        gpuLights[left].emissionLevel;

                    const float rightEmission =
                        gpuLights[right].emissionLevel;

                    if(leftEmission != rightEmission)
                    {
                        return leftEmission > rightEmission;
                    }

                    return left < right;
                }
            );

            packedCellFirst =
                cellLightIndicesScratch.data();

            packedCellCount =
                static_cast<size_t>(
                    LOCAL_LIGHT_MAX_PER_CELL
                );
        }


        const uint32_t firstLightIndex =
            static_cast<uint32_t>(
                gridLightIndices.size()
            );


        if(
            packedCellCount >
            static_cast<size_t>(
                std::numeric_limits<uint32_t>::max()
            )
        )
        {
            throw std::runtime_error(
                "RT Local-Light grid cell exceeds uint32 count capacity"
            );
        }


        gridLightIndices.insert(
            gridLightIndices.end(),
            packedCellFirst,
            packedCellFirst + packedCellCount
        );


        size_t slotIndex =
            static_cast<size_t>(
                localLightGridHash32(
                    coord.x,
                    coord.y,
                    coord.z
                )
            ) &
            hashMask;


        while(gridSlots[slotIndex].occupied != 0u)
        {
            slotIndex =
                (slotIndex + 1) &
                hashMask;
        }


        GPULocalLightGridSlot& slot =
            gridSlots[slotIndex];

        slot.cellX =
            coord.x;

        slot.cellY =
            coord.y;

        slot.cellZ =
            coord.z;

        slot.occupied =
            1u;

        slot.firstLightIndex =
            firstLightIndex;

        // 与上面 append 进 gridLightIndices 的条数必须一致：着色器就是按
        // (firstLightIndex, lightCount) 在这张表里扫的。
        slot.lightCount =
            static_cast<uint32_t>(
                packedCellCount
            );
    }


    ++g_localLightRevision;

    if(g_localLightRevision == 0u)
    {
        g_localLightRevision = 1u;
    }


    const GPULocalLightHeader
        header{
            static_cast<uint32_t>(
                gpuLights.size()
            ),
            g_localLightRevision,
            0u,
            0u
        };


    const VkDeviceSize
        totalBytes =
            static_cast<VkDeviceSize>(
                sizeof(GPULocalLightHeader) +
                gpuLights.size() *
                sizeof(GPULocalLightRecord)
            );


    const GPULocalLightGridHeader
        gridHeader{
            static_cast<uint32_t>(
                gridCells.size()
            ),
            static_cast<uint32_t>(
                gridLightIndices.size()
            ),
            static_cast<uint32_t>(
                hashCapacity
            ),
            LOCAL_LIGHT_GRID_SLOT_WORDS
        };


    const VkDeviceSize
        gridTotalBytes =
            static_cast<VkDeviceSize>(
                sizeof(GPULocalLightGridHeader) +
                gridSlots.size() *
                sizeof(GPULocalLightGridSlot) +
                gridLightIndices.size() *
                sizeof(uint32_t)
            );


    // Capacity-only increase.  A rebuild now runs whenever a Section's voxel
    // content changes (tile edit, chunk streaming), so recreating the buffers
    // and waiting on the queue every time would hitch the render thread and
    // break the project rule that vkQueueWaitIdle must never be unconditional.
    // Grow only when the new content no longer fits, request headroom so the
    // next edits reuse the allocation, and otherwise overwrite the mapped
    // memory below.
    const bool needsLocalLightGrow =
        g_localLightGpuBuffer ==
            VK_NULL_HANDLE ||
        totalBytes >
            g_localLightGpuCapacityBytes;

    const bool needsGridGrow =
        g_localLightGridGpuBuffer ==
            VK_NULL_HANDLE ||
        gridTotalBytes >
            g_localLightGridCapacityBytes;

    if(needsLocalLightGrow || needsGridGrow)
    {
        if(
            g_localLightGpuBuffer !=
                VK_NULL_HANDLE ||

            g_localLightGridGpuBuffer !=
                VK_NULL_HANDLE
        )
        {
            // Bindings 17 and 18 are read only by the RT graphics queue.  A
            // device-wide wait would also serialize unrelated RR/FG work.
            const auto perfL10QueueIdleStart =
                std::chrono::steady_clock::now();

            PERF_L10_TIME_STALL("localLightQueueIdle", check(
                vkQueueWaitIdle(
                    g_queue
                ),
                "wait RT queue before Local-Light buffer rebuild failed"
            ));

            perfL10QueueIdleMilliseconds =
                std::chrono::duration<double, std::milli>(
                    std::chrono::steady_clock::now() -
                    perfL10QueueIdleStart
                ).count();
        }


        if(needsLocalLightGrow)
        {
            destroyLocalLightGpuBuffer();

            g_localLightGpuCapacityBytes =
                LOCAL_LIGHT_GPU_FIXED_BYTES;

            createBuffer(
                g_device,
                g_physicalDevice,
                g_localLightGpuCapacityBytes,
                VK_BUFFER_USAGE_STORAGE_BUFFER_BIT,
                VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                g_localLightGpuBuffer,
                g_localLightGpuMemory
            );
        }


        if(needsGridGrow)
        {
            destroyLocalLightGridGpuBuffer();

            g_localLightGridCapacityBytes =
                LOCAL_LIGHT_GRID_FIXED_BYTES;

            createBuffer(
                g_device,
                g_physicalDevice,
                g_localLightGridCapacityBytes,
                VK_BUFFER_USAGE_STORAGE_BUFFER_BIT,
                VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                g_localLightGridGpuBuffer,
                g_localLightGridGpuMemory
            );
        }
    }


    void* mapped =
        nullptr;

    check(
        vkMapMemory(
            g_device,
            g_localLightGpuMemory,
            0,
            totalBytes,
            0,
            &mapped
        ),
        "RT Local Lights L3 map failed"
    );


    std::memcpy(
        mapped,
        &header,
        sizeof(GPULocalLightHeader)
    );


    if(
        !gpuLights.empty()
    )
    {
        std::memcpy(
            static_cast<uint8_t*>(
                mapped
            ) +
            sizeof(GPULocalLightHeader),
            gpuLights.data(),
            gpuLights.size() *
            sizeof(GPULocalLightRecord)
        );
    }


    vkUnmapMemory(
        g_device,
        g_localLightGpuMemory
    );


    void* gridMapped =
        nullptr;

    check(
        vkMapMemory(
            g_device,
            g_localLightGridGpuMemory,
            0,
            gridTotalBytes,
            0,
            &gridMapped
        ),
        "RT Local-Light Grid P2B-1 map failed"
    );


    std::memcpy(
        gridMapped,
        &gridHeader,
        sizeof(GPULocalLightGridHeader)
    );


    std::memcpy(
        static_cast<uint8_t*>(
            gridMapped
        ) +
            sizeof(GPULocalLightGridHeader),
        gridSlots.data(),
        gridSlots.size() *
        sizeof(GPULocalLightGridSlot)
    );


    if(!gridLightIndices.empty())
    {
        std::memcpy(
            static_cast<uint8_t*>(
                gridMapped
            ) +
                sizeof(GPULocalLightGridHeader) +
                gridSlots.size() *
                sizeof(GPULocalLightGridSlot),
            gridLightIndices.data(),
            gridLightIndices.size() *
            sizeof(uint32_t)
        );
    }


    vkUnmapMemory(
        g_device,
        g_localLightGridGpuMemory
    );


    updateLocalLightDescriptor();

    updateLocalLightGridDescriptor();

    // 2026-10-23：体积雾读的是同一对 buffer（另一份 descriptor set）。
    updateCloudLocalLightDescriptors();


    g_localLightGpuCount =
        gpuLights.size();

    g_localLightGridCellCount =
        gridCells.size();

    g_localLightGridIndexCount =
        gridLightIndices.size();

    g_localLightGridHashCapacity =
        hashCapacity;

    g_localLightsDirty =
        false;


    // 2026-10-06：这三条是热路径诊断 —— 流式加载期间 g_localLightsDirty 几乎每帧
    // 都被置位，于是每帧各构造一个 std::stringstream 并走 RTLog（内部还要取 mutex
    // 再写文件）。按调用次数节流到每 120 次一条（≈60fps 下每 2 秒），首次仍然输出。
    static uint32_t localLightLogThrottle = 0u;
    const bool localLightLogDue =
        (localLightLogThrottle++ % 120u) == 0u;

    if(localLightLogDue)
    {
        std::stringstream ss;

        ss
            << "[RT LOCAL LIGHTS L3 GPU]"
            << " lights="
            << g_localLightGpuCount
            << " bytes="
            << static_cast<unsigned long long>(
                totalBytes
            )
            << " cellCapped="
            << cappedCellCount
            << " droppedLights="
            << static_cast<unsigned long long>(
                droppedLightCount
            )
            << " capLights="
            << LOCAL_LIGHT_GPU_MAX_LIGHTS;

        RTLog(
            ss.str()
        );


        std::stringstream gridLog;

        gridLog
            << "[RT LOCAL GRID P2B-1]"
            << " cells="
            << g_localLightGridCellCount
            << " indices="
            << g_localLightGridIndexCount
            << " hashCapacity="
            << g_localLightGridHashCapacity
            << " cellSize="
            << LOCAL_LIGHT_GRID_CELL_SIZE
            << " maxPerCell="
            << LOCAL_LIGHT_MAX_PER_CELL
            << " bytes="
            << static_cast<unsigned long long>(
                gridTotalBytes
            )
            << " binding=18";

        RTLog(
            gridLog.str()
        );
    }


    const double perfL10TotalMilliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() -
            perfL10RebuildStart
        ).count();

    if(localLightLogDue)
    {
        std::stringstream perfL10Log;
        perfL10Log
            << "[PERF L10 LOCAL REBUILD]"
            << " frame=" << g_perfL10FrameSerial
            << " totalCpuMs=" << std::fixed << std::setprecision(3)
            << perfL10TotalMilliseconds
            << " queueIdleMs=" << perfL10QueueIdleMilliseconds
            << " lights=" << g_localLightGpuCount
            << " gridCells=" << g_localLightGridCellCount
            << " gridBytes="
            << static_cast<unsigned long long>(gridTotalBytes);

        RTLog(
            perfL10Log.str()
        );
    }
}


// ---------------------------------------------------------------------------
// 2026-10-04 帧率修复：图集 churn 发布的零等待描述符集环形。
//
// 背景：entity/粒子/雨/星图 binding 的句柄随 Java 侧槽位轮转持续变化
// （updateEntityTexture 已做句柄级去重，churn 是真实句柄变化），发布被
// PERF_L10_TEXTURE_PUBLISH_MIN_FRAME_INTERVAL=8 节流，但每次发布都要
// FGDeviceWaitIdle 等整机排空。rt_debug.log 多会话实测：atlasPublishDeviceIdle
// 共 26524 次、中位 4ms / p90 9.5ms / p99 21.6ms、合计 143.7s；TEXPUB churn
// 帧间隔 43216/43291 精确等于 8。这是 60 帧窗口 maxMs/avgMs 中位 1.31 帧率
// 锯齿的主因；FG 开着时在途管线更深、等待更长，输出端抖动被进一步放大。
//
// 方案（照搬 g_sectionRetirementFences 的"代纪 fence"模式）：
//   · 预分配 RT_DESCRIPTOR_RING_SIZE 个同 layout 描述符集，各配一枚 fence。
//   · churn 发布：取一枚 fence 已亮（无在飞引用）的槽 → 把 live 集整份 host
//     拷贝过去（VkCopyDescriptorSet；规范明确拷贝不构成对源集所引用资源的
//     使用，源集在途合法）→ 脏 binding 写到槽上 → live 指针换到该槽。全程
//     零等待；本帧 cmd 稍后绑定新槽，旧槽被在飞帧继续引用直到自然排空。
//   · 退休记账：换下的环内槽用**它自己的** fence 提交一个空 cmd 到 g_queue
//     —— 队列顺序保证该 fence 排在所有可能引用旧集的提交之后，亮起即旧集
//     不再被任何已提交工作引用，槽可复用。旧 live 是主池初始集时无需记账：
//     所有写入点都走 live 指针，它从此永远不会再被写，在飞帧读它直到排空。
//   · reload 类发布（PBR/albedo/动态绑定刷新，退役旧视图必须等）与环耗尽
//     回落，保持原 device-idle 契约不变。
//   · 其余低频写入点（TLAS/RR/Section/stats/水/云/DH）本就不等待、原地写
//     live 指针，语义不变：轮转后它们写到的集与旧方案内容一致（整份拷贝保证）。
//   · RTX_ATLAS_RING=0 关闭环形（回落 legacy device-idle），供 A/B 对照。
// ---------------------------------------------------------------------------
constexpr uint32_t RT_DESCRIPTOR_RING_SIZE = 4u;
static VkDescriptorPool g_rtDescriptorRingPool = VK_NULL_HANDLE;
static VkDescriptorSet g_rtDescriptorRingSets[RT_DESCRIPTOR_RING_SIZE] = {};
static VkFence g_rtDescriptorRingFences[RT_DESCRIPTOR_RING_SIZE] = {};
static bool g_rtDescriptorRingFencePending[RT_DESCRIPTOR_RING_SIZE] = {};
static uint32_t g_rtDescriptorRingNext = 0u;
static uint32_t g_rtDescriptorRingLiveIndex = UINT32_MAX;  // UINT32_MAX = live 仍是主池初始集
static VkCommandPool g_rtDescriptorRingCmdPool = VK_NULL_HANDLE;
static VkCommandBuffer g_rtDescriptorRingCmd = VK_NULL_HANDLE;
static bool g_rtDescriptorRingReady = false;
static bool g_rtDescriptorRingLastPublishUsedRing = false;
// 二分构建：本窗口内已轮转过的槽位掩码。无提交模式下槽位只在整机空闲后
// 重置复用（见发布块的 legacy 分支），窗口内每槽至多用一次 ⇒ 无在途引用风险。
static uint32_t g_rtDescriptorRingUsedMask = 0u;

static bool rtDescriptorRingEnabledByEnv()
{
    // 2026-10-04 深夜：环形轮转方案**已停用**（三轮二分证实"绑定拷贝出的
    // 集合"触发视角冻结，机制疑为驱动 per-set 状态）。churn 发布改为原地写
    // 不等待（见发布块注释）。环形代码保留，RTX_ATLAS_RING=1 可创建并复现
    // 实验（当前发布路径已不再调用轮转）。
    static int cached = -1;
    if(cached < 0)
    {
        const char* v = std::getenv("RTX_ATLAS_RING");
        cached = (v != nullptr && v[0] == '1') ? 1 : 0;
    }
    return cached != 0;
}

static void createRtDescriptorRing()
{
    g_rtDescriptorRingReady = false;

    // RTX_ATLAS_RING=0 必须在**任何驱动调用之前**生效：否则关不掉创建路径，
    // A/B 对照和事故回退都失去意义。
    if(!rtDescriptorRingEnabledByEnv())
    {
        RTLog("[RT DESCRIPTOR] ring disabled by RTX_ATLAS_RING=0 (legacy device-idle path stays)");
        return;
    }

    if(
        g_device == VK_NULL_HANDLE ||
        g_rayTracingDescriptorSetLayout == VK_NULL_HANDLE ||
        g_rayTracingDescriptorSet == VK_NULL_HANDLE ||
        g_queueFamily == UINT32_MAX
    )
    {
        return;
    }

    // 池容量与主池逐位相同的基础上**乘以槽数**：VkDescriptorPoolSize 计数是
    // 池级总量而非每集配额，不乘的话第 2 个 set 起就会 OUT_OF_POOL_MEMORY，
    // 环形会静默退化成单槽（2026-10-04 修复：此前只配了 1 份）。
    const VkDescriptorPoolSize ps[5] = {
        { VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR, 1 * RT_DESCRIPTOR_RING_SIZE },
        { VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 16 * RT_DESCRIPTOR_RING_SIZE },
        { VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1 * RT_DESCRIPTOR_RING_SIZE },
        // 40 → 72（2026-10-06）：binding 36 的 sampler2D 数组从 16 涨到 32，
        // 单集采样器数量随之 +16；沿用 40 会在第 2 个 set 起 OUT_OF_POOL_MEMORY。
        // 2026-10-09 实体 LabPBR：binding 63/64 再加 64 ⇒ 单集 118，池按 128 配。
        { VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 128 * RT_DESCRIPTOR_RING_SIZE },
        { VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 20 * RT_DESCRIPTOR_RING_SIZE }
    };
    VkDescriptorPoolCreateInfo pi{ VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO };
    pi.maxSets = RT_DESCRIPTOR_RING_SIZE;
    pi.poolSizeCount = 5;
    pi.pPoolSizes = ps;

    if(vkCreateDescriptorPool(g_device, &pi, nullptr, &g_rtDescriptorRingPool) != VK_SUCCESS)
    {
        RTLog("[RT DESCRIPTOR] ring pool create failed, keeping legacy idle path");
        return;
    }

    VkDescriptorSetAllocateInfo ai{ VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO };
    ai.descriptorPool = g_rtDescriptorRingPool;
    ai.descriptorSetCount = 1;
    ai.pSetLayouts = &g_rayTracingDescriptorSetLayout;

    // 初始即 signaled：槽从未被引用过，天然可复用。
    VkFenceCreateInfo fi{ VK_STRUCTURE_TYPE_FENCE_CREATE_INFO };
    fi.flags = VK_FENCE_CREATE_SIGNALED_BIT;

    bool ok = true;
    for(uint32_t i = 0u; i < RT_DESCRIPTOR_RING_SIZE && ok; ++i)
    {
        if(
            vkAllocateDescriptorSets(g_device, &ai, &g_rtDescriptorRingSets[i]) != VK_SUCCESS ||
            vkCreateFence(g_device, &fi, nullptr, &g_rtDescriptorRingFences[i]) != VK_SUCCESS
        )
        {
            ok = false;
        }
    }

    if(ok)
    {
        VkCommandPoolCreateInfo cpi{ VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO };
        cpi.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
        cpi.queueFamilyIndex = g_queueFamily;

        if(vkCreateCommandPool(g_device, &cpi, nullptr, &g_rtDescriptorRingCmdPool) != VK_SUCCESS)
        {
            ok = false;
        }
    }

    if(ok)
    {
        // 2026-10-04 修复启动崩溃（hs_err_pid8852，AV in nvoglv64@+0x3ec）：
        // 最初 cai.commandPool 在 vkCreateCommandPool **之前**就从
        // g_rtDescriptorRingCmdPool 取值 —— 拿到的是 VK_NULL_HANDLE，
        // vkAllocateCommandBuffers 直接在驱动里解引用空池对象。
        // 必须先建池、再以真实句柄填充 cai。
        VkCommandBufferAllocateInfo cai{ VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO };
        cai.commandPool = g_rtDescriptorRingCmdPool;
        cai.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        cai.commandBufferCount = 1u;

        if(vkAllocateCommandBuffers(g_device, &cai, &g_rtDescriptorRingCmd) != VK_SUCCESS)
        {
            ok = false;
        }
    }

    if(ok)
    {
        g_rtDescriptorRingReady = rtDescriptorRingEnabledByEnv();
    }

    RTLog(
        std::string("[RT DESCRIPTOR] ring ready=") +
        (g_rtDescriptorRingReady ? "1" : "0") +
        " slots=" + std::to_string(RT_DESCRIPTOR_RING_SIZE) +
        (g_rtDescriptorRingReady ? "" : " (legacy device-idle path stays)")
    );
}

// ---------------------------------------------------------------------------
// churn 发布的零等待路径。成功时 g_rayTracingDescriptorSet 已指向"整份拷贝自
// 旧 live"的新槽，调用方随后把脏 binding 写到它上面即可，无需任何等待；
// 返回 false = 未就绪/被 RTX_ATLAS_RING=0 关闭/环耗尽，调用方走 legacy
// device-idle 路径（行为与旧版逐位一致）。
// ---------------------------------------------------------------------------
static bool rtDescriptorRingPublish()
{
    g_rtDescriptorRingLastPublishUsedRing = false;

    if(!g_rtDescriptorRingReady)
    {
        return false;
    }

    // 非阻塞收割：fence 已亮的槽标记为可复用。vkGetFenceStatus 不排队、不等待。
    for(uint32_t i = 0u; i < RT_DESCRIPTOR_RING_SIZE; ++i)
    {
        if(
            g_rtDescriptorRingFencePending[i] &&
            vkGetFenceStatus(g_device, g_rtDescriptorRingFences[i]) == VK_SUCCESS
        )
        {
            g_rtDescriptorRingFencePending[i] = false;
        }
    }

    // 选槽（2026-10-04 二分构建）：跳过当前 live 槽和本窗口已用过的槽。
    // 不做任何队列提交 —— 若视角冻结元凶是空提交，本构建不应再冻结；
    // 若仍冻结，则元凶在拷贝/换指针。每 4 次发布环耗尽回落 legacy
    // device-idle（整机排空后重置掩码，槽位重新安全可用）。
    uint32_t slot = UINT32_MAX;
    for(uint32_t n = 0u; n < RT_DESCRIPTOR_RING_SIZE; ++n)
    {
        const uint32_t i = (g_rtDescriptorRingNext + n) % RT_DESCRIPTOR_RING_SIZE;
        if(i == g_rtDescriptorRingLiveIndex || (g_rtDescriptorRingUsedMask & (1u << i)) != 0u)
        {
            continue;
        }
        slot = i;
        break;
    }

    if(slot == UINT32_MAX)
    {
        static uint32_t s_ringExhaustedLogged = 0u;
        if(s_ringExhaustedLogged < 8u)
        {
            ++s_ringExhaustedLogged;
            RTLog("[RT DESCRIPTOR] ring exhausted (bisect: no-submit mode), legacy idle");
        }
        return false;
    }

    VkDescriptorSet newSet = g_rtDescriptorRingSets[slot];

    // 1) 整份拷贝 live → 新槽。源集可能仍被在飞命令缓冲读取，但 host 拷贝只读
    //    源、不改源（GPU 视角源负载不可变，规范允许），目的槽已确认无在飞引用。
    //    拷完新槽与 live 逐位一致，随后的脏 binding 写入只覆写变化项。
    VkCopyDescriptorSet copy{ VK_STRUCTURE_TYPE_COPY_DESCRIPTOR_SET };
    copy.srcSet = g_rayTracingDescriptorSet;
    copy.dstSet = newSet;
    vkUpdateDescriptorSets(g_device, 0u, nullptr, 1u, &copy);

    // 2)（2026-10-04 二分第三轮）只拷贝、**不换指针**：live 保持不变，本帧及
    //    后续帧照旧绑定主集/原槽；拷贝目标槽永不绑定，纯开销。
    //    返回 false 让调用方照旧走一次 device-idle 后原地写脏 binding ——
    //    与旧版行为完全一致，**唯一变量就是这次对在途源集的拷贝**：
    //    · 若仍视角冻结 ⇒ vkUpdateDescriptorSets 对在途源集的拷贝本身有害；
    //    · 若正常 ⇒ "换指针"（绑定拷贝出的集合）有害。
    g_rtDescriptorRingLastPublishUsedRing = false;
    return false;
}

static void createRayTracingDescriptorPoolAndSet()
{
    VkDescriptorPoolSize ps[5] = {
        { VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR, 1 },
        // 12 original storage images + 4 NRD-1 textures (bindings 50-53).
        { VK_DESCRIPTOR_TYPE_STORAGE_IMAGE, 16 },
        { VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1 },
        // 2026-10-09 实体 LabPBR：binding 63/64 各 32 个采样器 ⇒ 布局里的
        // sampler 总数从 54 涨到 118（36/37/63/64 四个数组 + 19 个单张），
        // 池按"布局总量"配 128（描述符池是主机侧记账，多配不占显存）。
        // 2026-10-13：槽数 32 → 64 ⇒ 布局总量 118 → 214
        // （36/63/64 各 64 = 192，37 = 3，单张 19），池同步配 256 留头寸。
        { VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER, 256 },
        // 18 + the two LOD tables at bindings 19/20.
        { VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 20 }
    };
    VkDescriptorPoolCreateInfo pi{ VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO };
    pi.maxSets = 1;
    pi.poolSizeCount = 5;
    pi.pPoolSizes = ps;

    check(vkCreateDescriptorPool(g_device, &pi, nullptr, &g_rayTracingDescriptorPool), "Failed to create RT descriptor pool");

    VkDescriptorSetAllocateInfo ai{ VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO };
    ai.descriptorPool = g_rayTracingDescriptorPool;
    ai.descriptorSetCount = 1;
    ai.pSetLayouts = &g_rayTracingDescriptorSetLayout;

    check(vkAllocateDescriptorSets(g_device, &ai, &g_rayTracingDescriptorSet), "Failed to allocate RT descriptor set");

    // 2026-10-04 帧率修复：主集就位后立刻准备零等待 churn 发布用的环形集。
    createRtDescriptorRing();

    // binding 0 : TLAS
    VkWriteDescriptorSetAccelerationStructureKHR asi{ VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET_ACCELERATION_STRUCTURE_KHR };
    asi.accelerationStructureCount = 1;
    asi.pAccelerationStructures = &g_tlas;

    VkWriteDescriptorSet tlasWrite{ VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET };
    tlasWrite.pNext = &asi;
    tlasWrite.dstSet = g_rayTracingDescriptorSet;
    tlasWrite.dstBinding = 0;
    tlasWrite.descriptorCount = 1;
    tlasWrite.descriptorType = VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR;

    // binding 1 : RT Output Storage Image
    VkDescriptorImageInfo imageInfo{};
    imageInfo.imageView = g_rtOutputView;
    imageInfo.imageLayout = VK_IMAGE_LAYOUT_GENERAL;

    VkWriteDescriptorSet imageWrite{ VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET };
    imageWrite.dstSet = g_rayTracingDescriptorSet;
    imageWrite.dstBinding = 1;
    imageWrite.descriptorCount = 1;
    imageWrite.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    imageWrite.pImageInfo = &imageInfo;

    // binding 2 : Camera UBO
    VkDescriptorBufferInfo uboInfo{};
    uboInfo.buffer = g_cameraUboBuffer;
    uboInfo.offset = 0;
    uboInfo.range = sizeof(CameraUBO);

    VkWriteDescriptorSet uboWrite{ VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET };
    uboWrite.dstSet = g_rayTracingDescriptorSet;
    uboWrite.dstBinding = 2;
    uboWrite.descriptorCount = 1;
    uboWrite.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
    uboWrite.pBufferInfo = &uboInfo;

    // 注意：Binding 3, 4, 5 (贴图数组) 在此处不写入，它们将作为空槽存在，
    // 后续在拦截到 Minecraft 纹理加载时，再通过 vkUpdateDescriptorSets 动态填入具体索引。

    VkWriteDescriptorSet writes[3] = { tlasWrite, imageWrite, uboWrite };
    vkUpdateDescriptorSets(g_device, 3, writes, 0, nullptr);

    // The freshly allocated set now holds this handle; keep the skip-guard in
    // the rebuild consistent with it so the next rebuild does not republish it.
    g_tlasDescriptorHandle = g_tlas;

    // Bind the full Section vertex address table.  Slot 0 is a placeholder
    // entry, so the initialization BLAS/TLAS always has a valid table to read;
    // the first Section rebuild starts writing real slots on top of it.
    createSectionVertexAddressTable();

    // =====================================================
    // RT Local Lights - L3 + P2B-1
    // Bind valid minimum buffers immediately so bindings 17 and 18
    // are never left dangling before the first section upload.
    // =====================================================
    rebuildLocalLightGpuBuffer();
    createVLILightResources();

    // 2026-10-07：动态光源（binding 61）。描述符必须无条件有效 —— 见该块说明
    //（着色器要先读头部才知道几条光源，未写描述符被访问是 UB）。内容留空 = 零光源。
    ensureDynamicLightBuffer();
    updateDynamicLightDescriptor();

    // 2026-10-11 SHaRC（bindings 65..68）。默认关闭 ⇒ 连那 176MB 都不分配，描述符
    // 65..68 保持未写；着色器的模式闸门在 g_sharcZeroed=false 时恒为 0，所以不会出现
    // "未写描述符被访问"。要启用：ORION_SHARC=1（见 sharcEnabled 的说明）。
    ensureSharcBuffers();
    updateSharcDescriptors();
}


// 2026-10-07: one formula for the eight capacity-sized pool buffers, shared by
// createVLIPoolBuffers() and the copy-based growth migration.  Index order must
// match both call sites: page, scratch, surface cache, work list, emitter
// index, emitter alias, candidates, source directory.
static VkDeviceSize poolByteSizeForCapacity(
    uint32_t capacity,
    uint32_t poolIndex
)
{
    const VkDeviceSize pages = static_cast<VkDeviceSize>(capacity);
    switch(poolIndex)
    {
        case 0u: return pages * VLI_PAGE_WORDS * sizeof(uint32_t);
        case 1u: return pages * VPT_DIRECTIONAL_CACHE_WORDS * sizeof(uint32_t);
        case 2u: return pages * VPT_SURFACE_FACES_PER_SECTION * sizeof(uint32_t);
        case 3u: return (pages + 1u) * sizeof(uint32_t);
        case 4u: return pages * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t);
        case 5u: return pages * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t);
        case 6u: return pages * VPT_RELATED_EMITTERS_PER_SECTION *
            sizeof(VPTRelatedEmitterGPU);
        case 7u: return pages * VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE *
            sizeof(VPTSourceDirectoryEntryGPU);
        default: return 0u;
    }
}


static void updateVLIDescriptors()
{
    if(
        g_rayTracingDescriptorSet == VK_NULL_HANDLE ||
        g_vliPageTableBuffer == VK_NULL_HANDLE ||
        g_vliPageBuffer == VK_NULL_HANDLE ||
        g_vliScratchBuffer == VK_NULL_HANDLE ||
        g_vliWorkListBuffer == VK_NULL_HANDLE ||
        g_vptEmitterIndexBuffer == VK_NULL_HANDLE ||
        g_vptEmitterAliasBuffer == VK_NULL_HANDLE ||
        g_vptCandidateBuffer == VK_NULL_HANDLE ||
        g_vptSourceDirectoryBuffer == VK_NULL_HANDLE ||
        g_vptSurfaceCacheBuffer == VK_NULL_HANDLE
    )
    {
        return;
    }

    VkDescriptorBufferInfo infos[9]{};
    infos[0] = { g_vliPageTableBuffer, 0, VK_WHOLE_SIZE };
    infos[1] = { g_vliPageBuffer, 0, VK_WHOLE_SIZE };
    infos[2] = { g_vliScratchBuffer, 0, VK_WHOLE_SIZE };
    infos[3] = { g_vliWorkListBuffer, 0, VK_WHOLE_SIZE };
    infos[4] = { g_vptEmitterIndexBuffer, 0, VK_WHOLE_SIZE };
    infos[5] = { g_vptCandidateBuffer, 0, VK_WHOLE_SIZE };
    infos[6] = { g_vptSurfaceCacheBuffer, 0, VK_WHOLE_SIZE };
    infos[7] = { g_vptSourceDirectoryBuffer, 0, VK_WHOLE_SIZE };
    infos[8] = { g_vptEmitterAliasBuffer, 0, VK_WHOLE_SIZE };

    VkWriteDescriptorSet writes[9]{};
    for(uint32_t i = 0; i < 9; ++i)
    {
        writes[i].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[i].dstSet = g_rayTracingDescriptorSet;
        writes[i].dstBinding =
            i < 4u ? 22u + i :
            (i == 4u ? 28u : (i == 5u ? 29u :
                (i == 6u ? 30u : (i == 7u ? 31u : 32u))));
        writes[i].descriptorCount = 1;
        writes[i].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
        writes[i].pBufferInfo = &infos[i];
    }

    vkUpdateDescriptorSets(g_device, 9, writes, 0, nullptr);
}


// Creates the pool buffers whose size is derived from g_vliPageCapacity.  The
// Section page table is fixed at VLI_PAGE_TABLE_CAPACITY entries and is created
// separately, because it addresses pages rather than bytes.
static void createVLIPoolBuffers()
{
    const VkBufferUsageFlags storageUsage =
        VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
        VK_BUFFER_USAGE_TRANSFER_DST_BIT |
        VK_BUFFER_USAGE_TRANSFER_SRC_BIT;

    const VkDeviceSize pageCapacity =
        static_cast<VkDeviceSize>(g_vliPageCapacity);

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VLI_PAGE_WORDS * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vliPageBuffer,
        g_vliPageMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_DIRECTIONAL_CACHE_WORDS * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vliScratchBuffer,
        g_vliScratchMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_SURFACE_FACES_PER_SECTION * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vptSurfaceCacheBuffer,
        g_vptSurfaceCacheMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        (1u + pageCapacity) * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vliWorkListBuffer,
        g_vliWorkListMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vptEmitterIndexBuffer,
        g_vptEmitterIndexMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vptEmitterAliasBuffer,
        g_vptEmitterAliasMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_RELATED_EMITTERS_PER_SECTION *
            sizeof(VPTRelatedEmitterGPU),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vptCandidateBuffer,
        g_vptCandidateMemory
    );

    createBuffer(
        g_device,
        g_physicalDevice,
        pageCapacity * VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE *
            sizeof(VPTSourceDirectoryEntryGPU),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vptSourceDirectoryBuffer,
        g_vptSourceDirectoryMemory
    );
}


// Destroys the capacity-sized pool buffers.  Only the device allocations are
// released; the CPU-side Section pages keep their payloads, which is what lets
// a growth re-upload them without any device-to-device copy.
static void destroyVLIPoolBuffers()
{
    const auto destroyBuffer = [](VkBuffer& buffer, VkDeviceMemory& memory)
    {
        if(buffer != VK_NULL_HANDLE) vkDestroyBuffer(g_device, buffer, nullptr);
        if(memory != VK_NULL_HANDLE) vkFreeMemory(g_device, memory, nullptr);
        buffer = VK_NULL_HANDLE;
        memory = VK_NULL_HANDLE;
    };

    destroyBuffer(g_vliWorkListBuffer, g_vliWorkListMemory);
    destroyBuffer(g_vptSourceDirectoryBuffer, g_vptSourceDirectoryMemory);
    destroyBuffer(g_vptCandidateBuffer, g_vptCandidateMemory);
    destroyBuffer(g_vptEmitterAliasBuffer, g_vptEmitterAliasMemory);
    destroyBuffer(g_vptEmitterIndexBuffer, g_vptEmitterIndexMemory);
    destroyBuffer(g_vptSurfaceCacheBuffer, g_vptSurfaceCacheMemory);
    destroyBuffer(g_vliScratchBuffer, g_vliScratchMemory);
    destroyBuffer(g_vliPageBuffer, g_vliPageMemory);
}


static void createVLILightResources()
{
    if(
        g_vliPageBuffer != VK_NULL_HANDLE ||
        g_device == VK_NULL_HANDLE ||
        g_physicalDevice == VK_NULL_HANDLE
    )
    {
        return;
    }

    const VkBufferUsageFlags storageUsage =
        VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
        VK_BUFFER_USAGE_TRANSFER_DST_BIT |
        VK_BUFFER_USAGE_TRANSFER_SRC_BIT;

    createBuffer(
        g_device,
        g_physicalDevice,
        static_cast<VkDeviceSize>(VLI_PAGE_TABLE_CAPACITY) * sizeof(VLITableSlot),
        storageUsage,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
        g_vliPageTableBuffer,
        g_vliPageTableMemory
    );

    createVLIPoolBuffers();

    g_vliNeedsInitialClear = true;
    updateVLIDescriptors();

    std::stringstream ss;
    ss << "[VPT-3.1] exact Section emitter index allocated bytes="
       << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t)
          )
       << " binding=28";
    RTLog(ss.str());
    std::stringstream candidateLog;
    candidateLog << "[VPT-3.2] bounded Section emitter candidates allocated bytes="
       << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_RELATED_EMITTERS_PER_SECTION *
            sizeof(VPTRelatedEmitterGPU)
          )
       << " binding=29";
    RTLog(candidateLog.str());
    std::stringstream sourceDirectoryLog;
    sourceDirectoryLog << "[VPT-3.3D.7] source-Section directory allocated bytes="
        << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE *
            sizeof(VPTSourceDirectoryEntryGPU)
        )
        << " maxSections=" << VPT_SOURCE_DIRECTORY_MAX_SECTIONS
        << " binding=31";
    RTLog(sourceDirectoryLog.str());
    std::stringstream directionalCacheLog;
    directionalCacheLog << "[VPT-3.2B] directional cache allocated bytes="
        << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_DIRECTIONAL_CACHE_WORDS * sizeof(uint32_t)
        )
        << " directions=" << VPT_DIRECTION_COUNT
        << " binding=23";
    RTLog(directionalCacheLog.str());
    std::stringstream secondaryCacheLog;
    secondaryCacheLog << "[VPT-3.3] secondary directional cache allocated bytes="
        << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_DIRECTIONAL_CACHE_WORDS * sizeof(uint32_t)
        )
        << " directions=" << VPT_DIRECTION_COUNT
        << " binding=24";
    RTLog(secondaryCacheLog.str());
    std::stringstream surfaceCacheLog;
    surfaceCacheLog << "[VPT-3.3B.1] face cache allocated bytes="
        << static_cast<unsigned long long>(
            static_cast<VkDeviceSize>(g_vliPageCapacity) *
            VPT_SURFACE_FACES_PER_SECTION * sizeof(uint32_t)
        )
        << " facesPerPage=" << VPT_SURFACE_FACES_PER_SECTION
        << " binding=30";
    RTLog(surfaceCacheLog.str());
    std::stringstream poolLog;
    poolLog << "[VLI-1.4] persistent Section voxel buffers allocated capacity="
        << g_vliPageCapacity
        << " limit=" << vliPageCapacityLimit()
        << " bytes="
        << static_cast<unsigned long long>(
            vliPoolBytesForCapacity(g_vliPageCapacity)
          );
    RTLog(poolLog.str());
}


// Grows the persistent VLI/VPT page pool.  This runs on the render thread only:
// it is called from recordVLIUpdates() before that command buffer records any
// VLI/VPT work, so the buffers destroyed here are no longer referenced by an
// in-flight submission once the queue has drained.  Caller must hold g_vliMutex.
static void growVLIPageCapacityLocked(uint32_t requiredPages)
{
    // 2026-10-13：上限不再是固定 4096，而是由预算反推（见 vliPageCapacityLimit）。
    // 它只影响"最多涨到多少页"；闸门不可用时恒为 VLI_MAX_SECTION_PAGES ⇒ 逐位回旧档。
    const uint32_t capacityLimit = vliPageCapacityLimit();

    if(g_vliPageCapacity >= capacityLimit)
    {
        return;
    }

    uint32_t newCapacity = g_vliPageCapacity;
    while(newCapacity < requiredPages && newCapacity < capacityLimit)
    {
        newCapacity *= 2u;
    }
    if(newCapacity > capacityLimit)
    {
        newCapacity = capacityLimit;
    }
    if(newCapacity <= g_vliPageCapacity)
    {
        return;
    }

    PerfL10StallTimer perfL10StallTimer("vliPageGrow");

    const uint32_t previousCapacity = g_vliPageCapacity;
    const size_t livePages = g_vliSections.size();

    // 2026-10-07 根治（"阵阵卡顿"的大停顿来源）：池扩容从"销毁重建 + 全部活页
    // 重传重解"改成"新缓冲 + 一次设备侧拷贝迁移"。旧实现每跨一个容量台阶都要
    // vkQueueWaitIdle 全排空，再把 livePages × ~185KB 逐页 vkCmdUpdateBuffer、
    // 把每个暴露面重新求解 —— rt_debug.log 里 46ms 到数秒的 vliPageGrow 停顿
    // 全在这一条路上。
    //
    // 迁移的合法性：池只通过 binding 22-25 / 28-32 访问，没有任何裸地址外泄
    // （vkGetBufferDeviceAddress 仅用于调试测试缓冲），页面索引在扩容时不变，
    // 所以"分配更大的新缓冲 -> 拷贝旧内容 -> 尾部补零 -> 重绑同一组 binding"
    // 对所有消费者透明。
    //
    // 时序：录制拷贝 -> 提交 -> vkQueueWaitIdle -> 销毁旧缓冲 -> 重绑描述符。
    // 同队列提交按序执行，拷贝必然晚于一切在途旧缓冲引用；idle 覆盖拷贝本身
    // 并让新内容对主机与后续提交可见。与旧实现一样只有一次排空，但省掉了
    // 重传与重解：stall 从秒级降到一次排空气泡。页面索引与 CPU 权威数据
    // （g_vliSections）都不动，脏集不动，g_vliNeedsInitialClear 不置位。

    // 1. 快照旧句柄与旧字节数，清空全局，让 createVLIPoolBuffers() 按新容量
    //    重建到全局句柄上。
    VkBuffer oldBuffers[8];
    VkDeviceMemory oldMemories[8];
    VkBuffer* const newBuffers[8] = {
        &g_vliPageBuffer,
        &g_vliScratchBuffer,
        &g_vptSurfaceCacheBuffer,
        &g_vliWorkListBuffer,
        &g_vptEmitterIndexBuffer,
        &g_vptEmitterAliasBuffer,
        &g_vptCandidateBuffer,
        &g_vptSourceDirectoryBuffer
    };
    VkDeviceMemory* const newMemories[8] = {
        &g_vliPageMemory,
        &g_vliScratchMemory,
        &g_vptSurfaceCacheMemory,
        &g_vliWorkListMemory,
        &g_vptEmitterIndexMemory,
        &g_vptEmitterAliasMemory,
        &g_vptCandidateMemory,
        &g_vptSourceDirectoryMemory
    };
    const VkDeviceSize oldPoolBytes[8] = {
        static_cast<VkDeviceSize>(previousCapacity) * VLI_PAGE_WORDS * sizeof(uint32_t),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_DIRECTIONAL_CACHE_WORDS * sizeof(uint32_t),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_SURFACE_FACES_PER_SECTION * sizeof(uint32_t),
        (static_cast<VkDeviceSize>(previousCapacity) + 1u) * sizeof(uint32_t),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_RELATED_EMITTERS_PER_SECTION *
            sizeof(VPTRelatedEmitterGPU),
        static_cast<VkDeviceSize>(previousCapacity) * VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE *
            sizeof(VPTSourceDirectoryEntryGPU)
    };
    for(size_t pool = 0; pool < 8u; ++pool)
    {
        oldBuffers[pool] = *newBuffers[pool];
        oldMemories[pool] = *newMemories[pool];
        *newBuffers[pool] = VK_NULL_HANDLE;
        *newMemories[pool] = VK_NULL_HANDLE;
    }

    g_vliPageCapacity = newCapacity;
    g_vliPageSectionKeys.resize(newCapacity, VLI_INVALID_SECTION_KEY);
    createVLIPoolBuffers();

    // 2. 一次性命令缓冲：逐池 old -> new 拷贝 + 尾部补零（保持"未分配页读出
    //    即零"的不变量，它原来由 initial clear 提供），最后把工作列表计数器
    //    （word 0）清零 —— 在途求解写入的条目属于旧一代池。
    VkCommandBufferAllocateInfo migrateAllocateInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO
    };
    migrateAllocateInfo.commandPool = g_rtCommandPool;
    migrateAllocateInfo.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
    migrateAllocateInfo.commandBufferCount = 1u;

    VkCommandBuffer migrateCmd = VK_NULL_HANDLE;
    check(
        vkAllocateCommandBuffers(g_device, &migrateAllocateInfo, &migrateCmd),
        "allocate VLI pool migration command buffer failed"
    );

    VkCommandBufferBeginInfo migrateBeginInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO
    };
    migrateBeginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;

    check(
        vkBeginCommandBuffer(migrateCmd, &migrateBeginInfo),
        "begin VLI pool migration command buffer failed"
    );

    for(size_t pool = 0; pool < 8u; ++pool)
    {
        VkBufferCopy region{};
        region.srcOffset = 0u;
        region.dstOffset = 0u;
        region.size = oldPoolBytes[pool];
        vkCmdCopyBuffer(
            migrateCmd,
            oldBuffers[pool],
            *newBuffers[pool],
            1u,
            &region
        );

        const VkDeviceSize newBytes = poolByteSizeForCapacity(
            newCapacity,
            static_cast<uint32_t>(pool)
        );
        if(newBytes > oldPoolBytes[pool])
        {
            vkCmdFillBuffer(
                migrateCmd,
                *newBuffers[pool],
                oldPoolBytes[pool],
                newBytes - oldPoolBytes[pool],
                0u
            );
        }
    }

    // 拷贝写与补零写都命中同缓冲的重叠/相邻区间，插入一道传输屏障把拷贝写
    // 定序到补零写之前；随后一道全局屏障把全部迁移写对新提交可见（之后紧跟
    // 的 queue idle 再兜一次底）。
    VkMemoryBarrier migrateWriteBarrier{
        VK_STRUCTURE_TYPE_MEMORY_BARRIER
    };
    migrateWriteBarrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
    migrateWriteBarrier.dstAccessMask =
        VK_ACCESS_TRANSFER_WRITE_BIT | VK_ACCESS_TRANSFER_READ_BIT;

    vkCmdPipelineBarrier(
        migrateCmd,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        0u,
        1u,
        &migrateWriteBarrier,
        0u,
        nullptr,
        0u,
        nullptr
    );

    vkCmdFillBuffer(migrateCmd, g_vliWorkListBuffer, 0u, sizeof(uint32_t), 0u);

    check(
        vkEndCommandBuffer(migrateCmd),
        "end VLI pool migration command buffer failed"
    );

    VkSubmitInfo migrateSubmitInfo{
        VK_STRUCTURE_TYPE_SUBMIT_INFO
    };
    migrateSubmitInfo.commandBufferCount = 1u;
    migrateSubmitInfo.pCommandBuffers = &migrateCmd;

    check(
        vkQueueSubmit(g_queue, 1u, &migrateSubmitInfo, VK_NULL_HANDLE),
        "submit VLI pool migration failed"
    );

    check(
        vkQueueWaitIdle(g_queue),
        "wait RT queue after VLI pool migration failed"
    );

    vkFreeCommandBuffers(
        g_device,
        g_rtCommandPool,
        1u,
        &migrateCmd
    );

    // 3. 排空已完成，旧的池缓冲可以安全退役。
    for(size_t pool = 0; pool < 8u; ++pool)
    {
        if(oldBuffers[pool] != VK_NULL_HANDLE)
        {
            vkDestroyBuffer(g_device, oldBuffers[pool], nullptr);
        }
        if(oldMemories[pool] != VK_NULL_HANDLE)
        {
            vkFreeMemory(g_device, oldMemories[pool], nullptr);
        }
    }

    updateVLIDescriptors();

    std::stringstream ss;
    ss << "[VLI-1.4 GROW] page capacity "
       << previousCapacity << " -> " << g_vliPageCapacity
       << " livePages=" << livePages
       << " limit=" << vliPageCapacityLimit()
       << " migratedBy=deviceCopy"
       << " poolBytes="
       << static_cast<unsigned long long>(
            vliPoolBytesForCapacity(g_vliPageCapacity)
          );
    RTLog(ss.str());
}


static uint32_t vliHashSectionCoord(
    int32_t x,
    int32_t y,
    int32_t z
)
{
    return localLightGridHash32(x, y, z);
}


static uint32_t vliFindTableSlot(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    bool& found
)
{
    const uint32_t mask = VLI_PAGE_TABLE_CAPACITY - 1u;
    uint32_t slot = vliHashSectionCoord(sectionX, sectionY, sectionZ) & mask;

    for(uint32_t probe = 0; probe < VLI_PAGE_TABLE_CAPACITY; ++probe)
    {
        const VLITableSlot& entry = g_vliTableCpu[slot];
        if(entry.pagePlusOne == 0u)
        {
            found = false;
            return slot;
        }

        if(
            entry.sectionX == sectionX &&
            entry.sectionY == sectionY &&
            entry.sectionZ == sectionZ
        )
        {
            found = true;
            return slot;
        }

        slot = (slot + 1u) & mask;
    }

    throw std::runtime_error("VLI Section page table is full");
}


static uint64_t packSectionKey(int x, int y, int z, int layerId);

// VPT-3.3B.2: every VPT neighbourhood query is the same fixed +/-2 Section
// window.  Resolve that window with direct Section lookups so one event costs
// O(125) instead of O(loadedSections) unordered_map traversals per queried
// receiver.  The visited Section set is exactly the one the previous full scan
// produced, so nothing about the solve changes; only the visit order differs,
// and the previous order was already unspecified map order.
template <typename Visit>
static void forEachVPTNeighborhoodSection(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    Visit&& visit
)
{
    constexpr int32_t radius = static_cast<int32_t>(VPT_SOURCE_DIRECTORY_RADIUS);

    for(int32_t offsetX = -radius; offsetX <= radius; ++offsetX)
    {
        for(int32_t offsetY = -radius; offsetY <= radius; ++offsetY)
        {
            for(int32_t offsetZ = -radius; offsetZ <= radius; ++offsetZ)
            {
                const auto it = g_vliSections.find(
                    packSectionKey(
                        sectionX + offsetX,
                        sectionY + offsetY,
                        sectionZ + offsetZ,
                        0
                    )
                );

                if(it != g_vliSections.end())
                {
                    visit(it->second);
                }
            }
        }
    }
}


static void markVLINeighborhoodDirty(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ
)
{
    forEachVPTNeighborhoodSection(
        sectionX,
        sectionY,
        sectionZ,
        [](VLISectionCpuPage& page)
        {
            g_vliDirtySolveTableSlots.insert(page.tableSlot);
        }
    );
}


static std::vector<uint32_t> buildVPTEmitterIndexWords(
    const std::vector<uint32_t>& sourceWords,
    uint32_t revision
)
{
    std::vector<uint32_t> emitterWords(VPT_EMITTER_PAGE_WORDS, 0u);
    emitterWords[1] = revision;

    uint32_t emitterCount = 0u;
    const uint32_t sourceCount = static_cast<uint32_t>(
        std::min<size_t>(sourceWords.size(), VLI_SOURCE_WORDS)
    );

    for(uint32_t sourceIndex = 0u; sourceIndex < sourceCount; ++sourceIndex)
    {
        const uint32_t source = sourceWords[sourceIndex];
        const uint32_t emission = (source >> 2u) & 15u;
        if(emission == 0u)
        {
            continue;
        }

        // Source layout is x + 16 * (z + 16 * y).
        const uint32_t localX = sourceIndex & 15u;
        const uint32_t localZ = (sourceIndex >> 4u) & 15u;
        const uint32_t localY = (sourceIndex >> 8u) & 15u;
        const uint32_t typeCode = (source >> 6u) & 7u;

        // Packed emitter record:
        // bits  0..3  local X
        // bits  4..7  local Y
        // bits  8..11 local Z
        // bits 12..15 emission level
        // bits 16..18 type code
        const uint32_t packedEmitter =
            localX |
            (localY << 4u) |
            (localZ << 8u) |
            (emission << 12u) |
            (typeCode << 16u);

        emitterWords[VPT_EMITTER_HEADER_WORDS + emitterCount] = packedEmitter;
        ++emitterCount;
    }

    emitterWords[0] = emitterCount;
    uint32_t totalEmissionPower = 0u;
    for(uint32_t emitterIndex = 0u; emitterIndex < emitterCount; ++emitterIndex)
    {
        totalEmissionPower += (emitterWords[VPT_EMITTER_HEADER_WORDS + emitterIndex] >> 12u) & 15u;
    }
    // Header word 2 was reserved.  It is the exact sum of the proposal
    // powers, allowing RayGen to reconstruct an emitter proposal PDF without
    // an extra per-emitter probability buffer.
    emitterWords[2] = totalEmissionPower;
    return emitterWords;
}

// VPT-3.3D.8: Binding 17's Section light records are the authoritative
// source of local emitters.  VLI sourceWords encode voxel occupancy/albedo
// for DDA and face exposure, but their emission bits are not populated by the
// current Java VLI upload.  Build the VPT exact emitter page from the same
// accepted records that already light ordinary opaque geometry.
static std::vector<uint32_t> buildVPTEmitterIndexWordsFromLocalLights(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    const std::vector<LocalLightRecord>& lights,
    uint32_t revision
)
{
    std::vector<uint32_t> emitterWords(VPT_EMITTER_PAGE_WORDS, 0u);
    emitterWords[1] = revision;

    uint32_t emitterCount = 0u;
    uint32_t totalEmissionPower = 0u;
    const int32_t baseX = sectionX * 16;
    const int32_t baseY = sectionY * 16;
    const int32_t baseZ = sectionZ * 16;

    for(const LocalLightRecord& light : lights)
    {
        if(
            light.emissionLevel <= 0 ||
            light.emissionLevel > 15 ||
            emitterCount >= VPT_MAX_EMITTERS_PER_SECTION
        )
        {
            continue;
        }

        const int32_t localX = light.worldX - baseX;
        const int32_t localY = light.worldY - baseY;
        const int32_t localZ = light.worldZ - baseZ;
        if(
            localX < 0 || localX >= 16 ||
            localY < 0 || localY >= 16 ||
            localZ < 0 || localZ >= 16
        )
        {
            continue;
        }

        const uint32_t emission = static_cast<uint32_t>(light.emissionLevel);
        const uint32_t typeCode = static_cast<uint32_t>(
            std::clamp(light.typeCode, 0, 7)
        );
        emitterWords[VPT_EMITTER_HEADER_WORDS + emitterCount] =
            static_cast<uint32_t>(localX) |
            (static_cast<uint32_t>(localY) << 4u) |
            (static_cast<uint32_t>(localZ) << 8u) |
            (emission << 12u) |
            (typeCode << 16u);
        ++emitterCount;
        totalEmissionPower += emission;
    }

    emitterWords[0] = emitterCount;
    emitterWords[2] = totalEmissionPower;
    return emitterWords;
}

static std::vector<uint32_t> buildVPTEmitterIndexWordsForSection(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    const std::vector<uint32_t>& sourceWords,
    const std::vector<LocalLightRecord>& localLights,
    uint32_t revision
)
{
    return localLights.empty()
        ? buildVPTEmitterIndexWords(sourceWords, revision)
        : buildVPTEmitterIndexWordsFromLocalLights(
            sectionX,
            sectionY,
            sectionZ,
            localLights,
            revision
        );
}

// One uint per compact emitter: low 16 bits are the Alias threshold and high
// 16 bits are the fallback emitter index.  The proposal probability itself is
// exactly emission / emitterWords[2], so it is never quantized.
static std::vector<uint32_t> buildVPTEmitterAliasWords(
    const std::vector<uint32_t>& emitterWords
)
{
    std::vector<uint32_t> aliasWords(VPT_EMITTER_PAGE_WORDS, 0u);
    if(emitterWords.size() != VPT_EMITTER_PAGE_WORDS) return aliasWords;

    const uint32_t count = std::min(emitterWords[0], VPT_MAX_EMITTERS_PER_SECTION);
    const uint32_t totalPower = emitterWords[2];
    aliasWords[0] = count;
    aliasWords[1] = totalPower;
    if(count == 0u || totalPower == 0u) return aliasWords;

    std::vector<double> scaled(count, 0.0);
    std::deque<uint32_t> small;
    std::deque<uint32_t> large;
    for(uint32_t i = 0u; i < count; ++i)
    {
        const uint32_t power = (emitterWords[VPT_EMITTER_HEADER_WORDS + i] >> 12u) & 15u;
        scaled[i] = static_cast<double>(power) * static_cast<double>(count) /
                    static_cast<double>(totalPower);
        (scaled[i] < 1.0 ? small : large).push_back(i);
    }

    while(!small.empty() && !large.empty())
    {
        const uint32_t s = small.front(); small.pop_front();
        const uint32_t l = large.front(); large.pop_front();
        const uint32_t threshold = static_cast<uint32_t>(std::clamp(
            std::lround(scaled[s] * 65535.0), 0l, 65535l));
        aliasWords[VPT_EMITTER_HEADER_WORDS + s] = threshold | (l << 16u);
        scaled[l] = (scaled[l] + scaled[s]) - 1.0;
        (scaled[l] < 1.0 ? small : large).push_back(l);
    }
    while(!small.empty())
    {
        const uint32_t i = small.front(); small.pop_front();
        aliasWords[VPT_EMITTER_HEADER_WORDS + i] = 65535u | (i << 16u);
    }
    while(!large.empty())
    {
        const uint32_t i = large.front(); large.pop_front();
        aliasWords[VPT_EMITTER_HEADER_WORDS + i] = 65535u | (i << 16u);
    }
    return aliasWords;
}


static float vptDistanceSquaredToSectionBounds(
    const VPTRelatedEmitterGPU& emitter,
    const VLISectionCpuPage& receiver
)
{
    const float minX = static_cast<float>(receiver.sectionX * 16);
    const float minY = static_cast<float>(receiver.sectionY * 16);
    const float minZ = static_cast<float>(receiver.sectionZ * 16);
    const float maxX = minX + 16.0f;
    const float maxY = minY + 16.0f;
    const float maxZ = minZ + 16.0f;

    const float x = static_cast<float>(emitter.worldX) + 0.5f;
    const float y = static_cast<float>(emitter.worldY) + 0.5f;
    const float z = static_cast<float>(emitter.worldZ) + 0.5f;

    const float dx = x < minX ? minX - x : (x > maxX ? x - maxX : 0.0f);
    const float dy = y < minY ? minY - y : (y > maxY ? y - maxY : 0.0f);
    const float dz = z < minZ ? minZ - z : (z > maxZ ? z - maxZ : 0.0f);
    return dx * dx + dy * dy + dz * dz;
}


static uint32_t packVPTSourceDirectoryMetadata(
    uint32_t emitterCount,
    int32_t offsetX,
    int32_t offsetY,
    int32_t offsetZ
)
{
    // bits 0..12 emitter count (0..4096), bits 13..15/16..18/19..21 are
    // offsets encoded as [-2,2] -> [0,4].  The remaining bits stay zero.
    return (std::min(emitterCount, VPT_MAX_EMITTERS_PER_SECTION) & 0x1fffu) |
        ((static_cast<uint32_t>(offsetX + 2) & 7u) << 13u) |
        ((static_cast<uint32_t>(offsetY + 2) & 7u) << 16u) |
        ((static_cast<uint32_t>(offsetZ + 2) & 7u) << 19u);
}


static void rebuildVPTSourceDirectoryPageLocked(VLISectionCpuPage& receiver)
{
    std::array<VPTSourceDirectoryEntryGPU,
        VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE> directory{};
    uint32_t directoryCount = 0u;
    std::array<double, VPT_SOURCE_DIRECTORY_MAX_SECTIONS> weights{};

    forEachVPTNeighborhoodSection(
        receiver.sectionX,
        receiver.sectionY,
        receiver.sectionZ,
        [&](VLISectionCpuPage& sourcePage)
        {
            if(sourcePage.emitterIndexWords.size() < VPT_EMITTER_HEADER_WORDS)
            {
                return;
            }

            const uint32_t emitterCount = std::min(
                sourcePage.emitterIndexWords[0],
                VPT_MAX_EMITTERS_PER_SECTION
            );
            if(emitterCount == 0u ||
               directoryCount >= VPT_SOURCE_DIRECTORY_MAX_SECTIONS)
            {
                return;
            }

            const int32_t offsetX = sourcePage.sectionX - receiver.sectionX;
            const int32_t offsetY = sourcePage.sectionY - receiver.sectionY;
            const int32_t offsetZ = sourcePage.sectionZ - receiver.sectionZ;

            VPTSourceDirectoryEntryGPU& destination =
                directory[1u + directoryCount++];
            destination.pageIndex = sourcePage.pageIndex;
            destination.emitterCountAndOffset = packVPTSourceDirectoryMetadata(
                emitterCount, offsetX, offsetY, offsetZ
            );
            // The source-level proposal is the exact sum of emitter powers
            // times the established Section-bound distance falloff.  The
            // per-emitter Alias table supplies the second, power-weighted
            // level.
            const uint32_t sectionPower = sourcePage.emitterIndexWords.size() > 2u
                ? sourcePage.emitterIndexWords[2] : 0u;
            const float dx = std::max(0, std::abs(offsetX) - 1) * 16.0f;
            const float dy = std::max(0, std::abs(offsetY) - 1) * 16.0f;
            const float dz = std::max(0, std::abs(offsetZ) - 1) * 16.0f;
            weights[directoryCount - 1u] = static_cast<double>(sectionPower) /
                static_cast<double>(1.0f + dx * dx + dy * dy + dz * dz);
        }
    );

    directory[0].pageIndex = directoryCount;

    // Header aliasThresholdQ16 is reserved as the ReSTIR DI directory revision.
    // rt_test.rgen rejects revision 0 and uses this token to invalidate temporal
    // reservoirs when the receiver's source-directory membership or weights
    // change.  Every integer through 0x00ffffff is represented exactly by
    // float32, which matters because the reservoir keeps it in a float field.
    const uint32_t directoryRevision = g_vptSourceDirectoryRevision++;
    if(g_vptSourceDirectoryRevision == 0u ||
       g_vptSourceDirectoryRevision > 0x00ffffffu)
    {
        g_vptSourceDirectoryRevision = 1u;
    }
    directory[0].aliasThresholdQ16 = directoryRevision;

    if(directoryCount > 0u)
    {
        double totalWeight = 0.0;
        for(uint32_t i = 0u; i < directoryCount; ++i) totalWeight += weights[i];
        if(totalWeight > 0.0)
        {
            std::array<double, VPT_SOURCE_DIRECTORY_MAX_SECTIONS> scaled{};
            std::deque<uint32_t> small;
            std::deque<uint32_t> large;
            for(uint32_t i = 0u; i < directoryCount; ++i)
            {
                directory[1u + i].selectionProbability =
                    static_cast<float>(weights[i] / totalWeight);
                scaled[i] = weights[i] * static_cast<double>(directoryCount) / totalWeight;
                (scaled[i] < 1.0 ? small : large).push_back(i);
            }
            while(!small.empty() && !large.empty())
            {
                const uint32_t s = small.front(); small.pop_front();
                const uint32_t l = large.front(); large.pop_front();
                directory[1u + s].aliasThresholdQ16 = static_cast<uint32_t>(std::clamp(
                    std::lround(scaled[s] * 65535.0), 0l, 65535l));
                directory[1u + s].aliasIndex = l;
                scaled[l] = (scaled[l] + scaled[s]) - 1.0;
                (scaled[l] < 1.0 ? small : large).push_back(l);
            }
            while(!small.empty())
            {
                const uint32_t i = small.front(); small.pop_front();
                directory[1u + i].aliasThresholdQ16 = 65535u;
                directory[1u + i].aliasIndex = i;
            }
            while(!large.empty())
            {
                const uint32_t i = large.front(); large.pop_front();
                directory[1u + i].aliasThresholdQ16 = 65535u;
                directory[1u + i].aliasIndex = i;
            }
        }
    }
    receiver.sourceDirectory = directory;
    g_vptDirtySourceDirectoryPages.insert(receiver.pageIndex);
}


static void rebuildVPTCandidatePageLocked(VLISectionCpuPage& receiver)
{
    std::array<VPTRelatedEmitterGPU, VPT_RELATED_EMITTERS_PER_SECTION>
        candidates{};
    std::array<float, VPT_RELATED_EMITTERS_PER_SECTION> scores{};
    scores.fill(-1.0f);

    forEachVPTNeighborhoodSection(
        receiver.sectionX,
        receiver.sectionY,
        receiver.sectionZ,
        [&](VLISectionCpuPage& sourcePage)
        {
            if(sourcePage.emitterIndexWords.size() < VPT_EMITTER_HEADER_WORDS)
            {
                return;
            }

            const uint32_t emitterCount = std::min(
                sourcePage.emitterIndexWords[0],
                VPT_MAX_EMITTERS_PER_SECTION
            );
            for(uint32_t emitterIndex = 0u;
                emitterIndex < emitterCount;
                ++emitterIndex)
            {
                const uint32_t packed = sourcePage.emitterIndexWords[
                    VPT_EMITTER_HEADER_WORDS + emitterIndex
                ];
                const uint32_t emission = (packed >> 12u) & 15u;
                if(emission == 0u)
                {
                    continue;
                }

                VPTRelatedEmitterGPU candidate{};
                candidate.worldX = sourcePage.sectionX * 16 +
                    static_cast<int32_t>(packed & 15u);
                candidate.worldY = sourcePage.sectionY * 16 +
                    static_cast<int32_t>((packed >> 4u) & 15u);
                candidate.worldZ = sourcePage.sectionZ * 16 +
                    static_cast<int32_t>((packed >> 8u) & 15u);
                candidate.emissionAndType = emission |
                    (((packed >> 16u) & 7u) << 4u);

                const float score = static_cast<float>(emission) /
                    (1.0f + vptDistanceSquaredToSectionBounds(candidate, receiver));
                if(score <= scores[VPT_RELATED_EMITTERS_PER_SECTION - 1u])
                {
                    continue;
                }

                uint32_t insertAt = VPT_RELATED_EMITTERS_PER_SECTION - 1u;
                while(insertAt > 0u && score > scores[insertAt - 1u])
                {
                    scores[insertAt] = scores[insertAt - 1u];
                    candidates[insertAt] = candidates[insertAt - 1u];
                    --insertAt;
                }
                scores[insertAt] = score;
                candidates[insertAt] = candidate;
            }
        }
    );

    receiver.relatedEmitters = candidates;
    g_vptDirtyCandidatePages.insert(receiver.pageIndex);
    // Candidate selection is part of the solved lighting state.  Recompute
    // this receiver page in the same event epoch even when its own source
    // voxels did not change.
    g_vliDirtySolveTableSlots.insert(receiver.tableSlot);
}


static void rebuildVPTCandidateNeighborhoodLocked(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ
)
{
    forEachVPTNeighborhoodSection(
        sectionX,
        sectionY,
        sectionZ,
        [](VLISectionCpuPage& receiver)
        {
            rebuildVPTCandidatePageLocked(receiver);
            rebuildVPTSourceDirectoryPageLocked(receiver);
        }
    );
}


// 2026-10-13：VLI 页淘汰（甲·二级动作）。定义在 eraseVLITableSlot 之后（它要用
// 那一条页移除序列），所以这里先声明。详见其定义处。
static bool evictFarthestVLIPageLocked(uint32_t& outPageIndex);

// Registers or refreshes one VLI Section page and marks the affected
// neighborhood dirty.  Caller must hold g_vliMutex and must already have built
// the emitter payloads.  Returns false when a new page is required while the
// pool is at its current capacity: the payloads are then untouched and the
// caller has to park the Section until the render thread has grown the pool.
static bool applyVLISectionVoxelsLocked(
    uint64_t sectionKey,
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    std::vector<uint32_t>& incoming,
    std::vector<uint32_t>& emitterIndexWords,
    std::vector<uint32_t>& emitterAliasWords
)
{
    uint32_t pageIndex = 0u;
    const auto pageIt = g_vliSections.find(sectionKey);

    if(pageIt != g_vliSections.end())
    {
        pageIt->second.sourceWords = std::move(incoming);
        pageIt->second.emitterIndexWords = std::move(emitterIndexWords);
        pageIt->second.emitterAliasWords = std::move(emitterAliasWords);
        pageIndex = pageIt->second.pageIndex;

        // 2026-10-13：刷新即视为"用过一次"，推进 LRU 序数（见 lastUseTick 的说明）。
        pageIt->second.lastUseTick = ++g_vliPageUseTick;
    }
    else
    {
        if(!g_vliFreePages.empty())
        {
            pageIndex = g_vliFreePages.back();
            g_vliFreePages.pop_back();
        }
        else
        {
            if(g_vliNextPage >= g_vliPageCapacity)
            {
                // 2026-10-13：池已满。旧行为是无条件 return false（调用点打
                // "page capacity exhausted; Section ignored"）—— 后果是**永久保留
                // 最先注册的那批页**（通常离玩家最远），而近处的光进不来。
                //
                // 闸门判定超预算时改为：淘汰**离玩家最远**的那一页，把这个页号让给
                // 新 Section。闸门关闭或驱动不支持该扩展时走旧行为 ⇒ 关断即逐位回旧档。
                uint32_t evictedPageIndex = 0u;

                if(!g_vramGovernor.over ||
                   !evictFarthestVLIPageLocked(evictedPageIndex))
                {
                    ++g_vliGovernorIgnoredSections;
                    return false;
                }

                ++g_vliGovernorEvictedPages;
                pageIndex = evictedPageIndex;
            }
            else
            {
                pageIndex = g_vliNextPage++;
            }
        }

        bool found = false;
        const uint32_t tableSlot = vliFindTableSlot(sectionX, sectionY, sectionZ, found);
        if(found)
        {
            // JNI entry points must never allow a native exception to
            // cross into Java. The table/map mismatch is recoverable on
            // the next full VLI reset; keep the render thread alive and
            // report the invariant violation instead.
            RTLog("[VLI-1.4 SOURCE] table/map mismatch; Section ignored");
            return true;
        }

        VLITableSlot& slot = g_vliTableCpu[tableSlot];
        slot.sectionX = sectionX;
        slot.sectionY = sectionY;
        slot.sectionZ = sectionZ;
        slot.pagePlusOne = pageIndex + 1u;
        g_vliDirtyTableSlots.insert(tableSlot);

        VLISectionCpuPage page{};
        page.sectionX = sectionX;
        page.sectionY = sectionY;
        page.sectionZ = sectionZ;
        page.pageIndex = pageIndex;
        page.tableSlot = tableSlot;
        // 2026-10-13：新建页也推进 LRU 序数（否则新页序数恒 0，会被当成最旧的一页）。
        page.lastUseTick = ++g_vliPageUseTick;
        page.sourceWords = std::move(incoming);
        page.emitterIndexWords = std::move(emitterIndexWords);
        page.emitterAliasWords = std::move(emitterAliasWords);
        g_vliSections.emplace(sectionKey, std::move(page));
        g_vliPageSectionKeys[pageIndex] = sectionKey;
    }

    g_vliDirtySourcePages.insert(pageIndex);
    g_vptDirtyEmitterPages.insert(pageIndex);
    g_vptDirtyEmitterAliasPages.insert(pageIndex);
    markVLINeighborhoodDirty(sectionX, sectionY, sectionZ);
    rebuildVPTCandidateNeighborhoodLocked(sectionX, sectionY, sectionZ);

    return true;
}

// Defined with the native Section upload functions below.  This declaration is
// required here because the VPT bridge is intentionally kept beside the VPT
// page-management code.
static uint64_t packSectionKey(int x, int y, int z, int layerId);

// Local-light and voxel uploads are independent Java callbacks.  Refresh the
// VPT emitter representation when a light Section changes, but only after
// the light-cache mutex has been released; this keeps the global lock order
// one-way and lets either callback arrive first.
static void refreshVPTEmitterSectionFromLocalLights(
    int32_t sectionX,
    int32_t sectionY,
    int32_t sectionZ,
    const std::vector<LocalLightRecord>& localLights
)
{
    const uint64_t sectionKey = packSectionKey(sectionX, sectionY, sectionZ, 0);
    uint32_t pageIndex = 0u;
    uint32_t emitterCount = 0u;
    bool hasVoxelPage = false;

    {
        std::lock_guard<std::mutex> lock(g_vliMutex);
        auto pageIt = g_vliSections.find(sectionKey);
        if(pageIt == g_vliSections.end())
        {
            return;
        }

        uint32_t emitterRevision = g_vptEmitterRevision++;
        if(g_vptEmitterRevision == 0u)
        {
            g_vptEmitterRevision = 1u;
        }

        std::vector<uint32_t> emitterIndexWords =
            buildVPTEmitterIndexWordsForSection(
                sectionX,
                sectionY,
                sectionZ,
                pageIt->second.sourceWords,
                localLights,
                emitterRevision
            );

        emitterCount = emitterIndexWords[0];
        pageIt->second.emitterIndexWords = std::move(emitterIndexWords);
        pageIt->second.emitterAliasWords =
            buildVPTEmitterAliasWords(pageIt->second.emitterIndexWords);
        pageIndex = pageIt->second.pageIndex;
        hasVoxelPage = true;

        g_vptDirtyEmitterPages.insert(pageIndex);
        g_vptDirtyEmitterAliasPages.insert(pageIndex);
        markVLINeighborhoodDirty(sectionX, sectionY, sectionZ);
        rebuildVPTCandidateNeighborhoodLocked(sectionX, sectionY, sectionZ);
    }

    if(hasVoxelPage)
    {
        if constexpr(PERF_L10_ENABLE_LIGHT_REFRESH_LOGS)
        {
            std::stringstream ss;
            ss << "[VPT-3.3D.8 EMITTER BRIDGE] section=("
               << sectionX << "," << sectionY << "," << sectionZ << ")"
               << " local=" << localLights.size()
               << " vpt=" << emitterCount
               << " page=" << pageIndex;
            RTLog(ss.str());
        }
    }
}


// 2026-10-22：VLI（体素光注入）分帧预算。
//
// 现场（2026-10-22 21:51~21:54 那局，3.5 分钟）：[RT VLI SLOW]（阈值 8ms）
// 触发 **105 次**，平均 16.93ms、中位 12.54ms、最大 57.84ms，其中 >=20ms 有 25 次。
// 同一局 GPU 只有 7.87ms/帧、几何单段构建只有 0.1ms ⇒ 卡顿几乎全部来自这一条。
//
// 根因：recordVLIUpdates 一次把 g_vliPendingSections 里**全部**待处理 Section
// 做完（每段还要 buildVPTEmitterIndexWordsForSection + buildVPTEmitterAliasWords
// + applyVLISectionVoxelsLocked）。新区块流入时它们挤在同一帧，直接顶穿帧时间。
//
// 做法：加"至少做 1 段，之后按时间/段数收手"的闸门 —— 与 SectionMemoryPool、
// 几何预算同一套思路（**延后，不丢弃**）。剩下的留在 pending 队列里下一帧继续；
// 它本来就是队列，跨帧天然安全（容量在 growVLIPageCapacityLocked 里已按全部
// pending 预留）。
//
//   ORION_VLI_BUDGET_MS=<ms>          默认 4；0 = 不分帧（逐位回到旧行为）
//   ORION_VLI_SECTIONS_PER_FRAME=<n>  默认 2；0 = 不限段数（只按时间闸）
static double vliPendingSectionBudgetMs()
{
    static const double cached = []()
    {
        const char* raw = std::getenv("ORION_VLI_BUDGET_MS");

        if(raw == nullptr || raw[0] == '\0')
        {
            return 4.0;
        }

        const double parsed = std::atof(raw);

        if(parsed <= 0.0)
        {
            return 0.0;
        }

        return parsed > 50.0 ? 50.0 : parsed;
    }();

    return cached;
}

static uint32_t vliPendingSectionLimit()
{
    static const uint32_t cached = []() -> uint32_t
    {
        const char* raw = std::getenv("ORION_VLI_SECTIONS_PER_FRAME");

        if(raw == nullptr || raw[0] == '\0')
        {
            return 2u;
        }

        const long parsed = std::atol(raw);

        if(parsed <= 0)
        {
            return 0u;
        }

        return static_cast<uint32_t>(parsed > 64 ? 64 : parsed);
    }();

    return cached;
}

// 给 [RT VLI SLOW] 用的积压读数（只在渲染线程写/读）。
static size_t g_vliPendingBacklogForLog = 0u;

// 2026-10-22：VLI 单段内部分项计时（[RT VLI BREAKDOWN]）。只在渲染线程写/读，
// 每次 recordVLIUpdates 入口清零，出口处由调用方的 [RT VLI SLOW] 打出。
static double g_vliMsIndex = 0.0;   // buildVPTEmitterIndexWordsForSection
static double g_vliMsAlias = 0.0;   // buildVPTEmitterAliasWords
static double g_vliMsApply = 0.0;   // applyVLISectionVoxelsLocked
static double g_vliMsGather = 0.0;  // 锁内收集上传集（含整页 vector 拷贝）
static double g_vliMsUpload = 0.0;  // Fill + 全部 vkCmdUpdateBuffer
static double g_vliMsLockWait = 0.0;    // 取 g_vliMutex 的等待
static double g_vliMsSolve = 0.0;       // sort/unique/workList/dispatch/屏障
static size_t g_vliGatherPages = 0u;    // 本轮 gather 实际拷了多少条目

// 2026-10-22：gather 的扁平暂存。
//
// 原来每页 emplace_back(pageIndex, std::vector) 会为 sourceWords /
// emitterIndexWords / emitterAliasWords 各分配一次 16KB —— 254 页就是 760 次
// 16KB 堆分配，而工作线程在同一时刻做同样的事，堆锁互相拖 ⇒ 实测持锁侧
// 6~10ms、另一侧 lockWait 16~24ms。
//
// 现在改成：一个跨帧复用的 arena（clear 保留容量 ⇒ 稳态零分配）+ 每条目一个
// (pageIndex, wordOffset, wordCount) 描述符。数据仍是渲染线程私有快照，
// 不引用解锁后可能被淘汰的页指针。
struct VliUploadRef
{
    uint32_t pageIndex = 0u;
    uint32_t wordOffset = 0u;
    uint32_t wordCount = 0u;
};

static std::vector<uint32_t> g_vliUploadArena;
static std::vector<VliUploadRef> g_vliSourceUploads;
static std::vector<VliUploadRef> g_vliEmitterUploads;
static std::vector<VliUploadRef> g_vliEmitterAliasUploads;

static void beginVliUploadArena()
{
    g_vliUploadArena.clear();
    g_vliSourceUploads.clear();
    g_vliEmitterUploads.clear();
    g_vliEmitterAliasUploads.clear();
}

static void appendVliUpload(
    std::vector<VliUploadRef>& refs,
    uint32_t pageIndex,
    const std::vector<uint32_t>& words)
{
    VliUploadRef ref;
    ref.pageIndex = pageIndex;
    ref.wordOffset = static_cast<uint32_t>(g_vliUploadArena.size());
    ref.wordCount = static_cast<uint32_t>(words.size());

    g_vliUploadArena.insert(
        g_vliUploadArena.end(),
        words.begin(),
        words.end()
    );

    refs.push_back(ref);
}

static void recordVLIUpdates(VkCommandBuffer cmd)
{
    if(
        cmd == VK_NULL_HANDLE ||
        g_vliPageTableBuffer == VK_NULL_HANDLE ||
        g_vliPageBuffer == VK_NULL_HANDLE ||
        g_vliScratchBuffer == VK_NULL_HANDLE ||
        g_vptEmitterIndexBuffer == VK_NULL_HANDLE ||
        g_vptEmitterAliasBuffer == VK_NULL_HANDLE ||
        g_vptCandidateBuffer == VK_NULL_HANDLE ||
        g_vptSourceDirectoryBuffer == VK_NULL_HANDLE ||
        g_vptSurfaceCacheBuffer == VK_NULL_HANDLE ||
        g_vliComputePipeline == VK_NULL_HANDLE ||
        g_vliComputePipelineLayout == VK_NULL_HANDLE
    )
    {
        return;
    }

    g_vliMsIndex = 0.0;
    g_vliMsAlias = 0.0;
    g_vliMsApply = 0.0;
    g_vliMsGather = 0.0;
    g_vliMsUpload = 0.0;

    // The page pool is allocated lazily.  Sections parked by SectionCompiler
    // worker threads while the pool was full are registered here, on the render
    // thread, because this is the one place where the pool can be replaced: the
    // queue drain inside growVLIPageCapacityLocked() retires every reference to
    // the old buffers, and this command buffer has not recorded any VLI/VPT
    // work yet.
    if(g_vliGrowthRequested || !g_vliPendingSections.empty())
    {
        std::lock_guard<std::mutex> lock(g_vliMutex);

        if(g_vliGrowthRequested)
        {
            g_vliGrowthRequested = false;
            growVLIPageCapacityLocked(
                g_vliNextPage +
                static_cast<uint32_t>(g_vliPendingSections.size())
            );
        }

        // 2026-10-22：分帧（实测依据见 vliPendingSectionBudgetMs 处）。
        // index 0 永远做，保证一定有进展；之后一旦超预算或超段数就收手，
        // 剩下的留在队列里下一帧继续。
        const double vliPendingBudgetMs = vliPendingSectionBudgetMs();
        const uint32_t vliPendingLimit = vliPendingSectionLimit();
        const auto vliPendingBegin = std::chrono::steady_clock::now();

        size_t vliPendingProcessed = 0u;

        for(;
            vliPendingProcessed < g_vliPendingSections.size();
            ++vliPendingProcessed)
        {
            if(vliPendingProcessed > 0u)
            {
                if(vliPendingLimit != 0u &&
                   vliPendingProcessed >= vliPendingLimit)
                {
                    break;
                }

                if(vliPendingBudgetMs > 0.0)
                {
                    const double vliPendingElapsedMs =
                        std::chrono::duration<double, std::milli>(
                            std::chrono::steady_clock::now() -
                            vliPendingBegin
                        ).count();

                    if(vliPendingElapsedMs >= vliPendingBudgetMs)
                    {
                        break;
                    }
                }
            }

            VLIPendingSection& pending =
                g_vliPendingSections[vliPendingProcessed];

            std::vector<uint32_t> incoming = std::move(pending.sourceWords);
            std::vector<LocalLightRecord> pendingLights = std::move(pending.lights);

            const uint32_t emitterRevision = g_vptEmitterRevision++;
            if(g_vptEmitterRevision == 0u)
            {
                g_vptEmitterRevision = 1u;
            }
            const auto vliIdxBegin = std::chrono::steady_clock::now();

            std::vector<uint32_t> emitterIndexWords =
                buildVPTEmitterIndexWordsForSection(
                    pending.sectionX,
                    pending.sectionY,
                    pending.sectionZ,
                    incoming,
                    pendingLights,
                    emitterRevision
                );

            const auto vliAliasBegin = std::chrono::steady_clock::now();

            g_vliMsIndex +=
                std::chrono::duration<double, std::milli>(
                    vliAliasBegin - vliIdxBegin
                ).count();

            std::vector<uint32_t> emitterAliasWords =
                buildVPTEmitterAliasWords(emitterIndexWords);

            const auto vliApplyBegin = std::chrono::steady_clock::now();

            g_vliMsAlias +=
                std::chrono::duration<double, std::milli>(
                    vliApplyBegin - vliAliasBegin
                ).count();

            if(!applyVLISectionVoxelsLocked(
                   pending.sectionKey,
                   pending.sectionX,
                   pending.sectionY,
                   pending.sectionZ,
                   incoming,
                   emitterIndexWords,
                   emitterAliasWords
               ))
            {
                // Reachable only once the pool is at VLI_MAX_SECTION_PAGES.
                RTLog("[VLI-1.4 SOURCE] page capacity exhausted; Section ignored");
            }

            g_vliMsApply +=
                std::chrono::duration<double, std::milli>(
                    std::chrono::steady_clock::now() - vliApplyBegin
                ).count();
        }

        if(vliPendingProcessed > 0u)
        {
            // 只摘掉已处理的前缀；剩下的保留到下一帧。
            g_vliPendingSections.erase(
                g_vliPendingSections.begin(),
                g_vliPendingSections.begin() + vliPendingProcessed
            );
        }

        g_vliPendingBacklogForLog = g_vliPendingSections.size();
    }

    const auto vliBreakdownGatherBegin =
        std::chrono::steady_clock::now();

    // 2026-10-22：这三个改指向跨帧复用的扁平 arena（见 appendVliUpload）。
    beginVliUploadArena();

    std::vector<VliUploadRef>& sourceUploads = g_vliSourceUploads;
    std::vector<VliUploadRef>& emitterUploads = g_vliEmitterUploads;
    std::vector<VliUploadRef>& emitterAliasUploads = g_vliEmitterAliasUploads;
    std::vector<std::pair<uint32_t,
        std::array<VPTRelatedEmitterGPU, VPT_RELATED_EMITTERS_PER_SECTION>>>
        candidateUploads;
    std::vector<std::pair<uint32_t, std::array<VPTSourceDirectoryEntryGPU,
        VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE>>> sourceDirectoryUploads;
    std::vector<uint32_t> tableUpdates;
    std::vector<std::pair<uint32_t, VLITableSlot>> tablePayloads;
    std::vector<std::pair<uint32_t, uint32_t>> solvePages;

    {
        std::lock_guard<std::mutex> lock(g_vliMutex);

        // 2026-10-22：gather 窗口 = 取锁等待 + 拷贝。工作线程在 apply 期间一直
        // 持有这把锁，所以先把等待单独量出来。
        g_vliMsLockWait =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() -
                vliBreakdownGatherBegin
            ).count();

        // Per-frame fast path: most frames have no VLI/VPT updates.  All
        // post-lock work (vkCmdUpdateBuffer, barriers, sort) derives from
        // these sets plus the initial clear, so returning here is identical
        // to running the empty path below.
        if(
            !g_vliNeedsInitialClear &&
            g_vliDirtySourcePages.empty() &&
            g_vliDirtyTableSlots.empty() &&
            g_vliDirtySolveTableSlots.empty() &&
            g_vptDirtyEmitterPages.empty() &&
            g_vptDirtyEmitterAliasPages.empty() &&
            g_vptDirtyCandidatePages.empty() &&
            g_vptDirtySourceDirectoryPages.empty()
        )
        {
            return;
        }

        sourceUploads.reserve(g_vliDirtySourcePages.size());
        for(uint32_t pageIndex : g_vliDirtySourcePages)
        {
            const VLISectionCpuPage* const page =
                findVLISectionPageByIndexLocked(pageIndex);
            if(page != nullptr)
            {
                appendVliUpload(
                    sourceUploads,
                    pageIndex,
                    page->sourceWords
                );
            }
        }

        emitterUploads.reserve(g_vptDirtyEmitterPages.size());
        for(uint32_t pageIndex : g_vptDirtyEmitterPages)
        {
            const VLISectionCpuPage* const page =
                findVLISectionPageByIndexLocked(pageIndex);
            if(page != nullptr)
            {
                appendVliUpload(
                    emitterUploads,
                    pageIndex,
                    page->emitterIndexWords
                );
            }
        }

        emitterAliasUploads.reserve(g_vptDirtyEmitterAliasPages.size());
        for(uint32_t pageIndex : g_vptDirtyEmitterAliasPages)
        {
            const VLISectionCpuPage* const page =
                findVLISectionPageByIndexLocked(pageIndex);
            if(page != nullptr)
            {
                appendVliUpload(
                    emitterAliasUploads,
                    pageIndex,
                    page->emitterAliasWords
                );
            }
        }

        candidateUploads.reserve(g_vptDirtyCandidatePages.size());
        for(uint32_t pageIndex : g_vptDirtyCandidatePages)
        {
            const VLISectionCpuPage* const page =
                findVLISectionPageByIndexLocked(pageIndex);
            if(page != nullptr)
            {
                candidateUploads.emplace_back(
                    pageIndex,
                    page->relatedEmitters
                );
            }
        }

        sourceDirectoryUploads.reserve(g_vptDirtySourceDirectoryPages.size());
        for(uint32_t pageIndex : g_vptDirtySourceDirectoryPages)
        {
            const VLISectionCpuPage* const page =
                findVLISectionPageByIndexLocked(pageIndex);
            if(page != nullptr)
            {
                sourceDirectoryUploads.emplace_back(
                    pageIndex,
                    page->sourceDirectory
                );
            }
        }

        tableUpdates.assign(
            g_vliDirtyTableSlots.begin(),
            g_vliDirtyTableSlots.end()
        );

        tablePayloads.reserve(tableUpdates.size());
        for(uint32_t tableSlot : tableUpdates)
        {
            tablePayloads.emplace_back(tableSlot, g_vliTableCpu[tableSlot]);
        }

        // VPT-3.2B never continuously re-solves loaded pages.  A Section
        // content/candidate change explicitly marks the bounded affected
        // neighborhood; all of its 729 probes are then solved atomically.
        solvePages.reserve(g_vliDirtySolveTableSlots.size());
        for(uint32_t tableSlot : g_vliDirtySolveTableSlots)
        {
            const uint32_t pagePlusOne = g_vliTableCpu[tableSlot].pagePlusOne;
            if(pagePlusOne != 0u)
            {
                solvePages.emplace_back(tableSlot, pagePlusOne - 1u);
            }
        }

        g_vliDirtySourcePages.clear();
        g_vliDirtyTableSlots.clear();
        g_vliDirtySolveTableSlots.clear();
        g_vptDirtyEmitterPages.clear();
        g_vptDirtyEmitterAliasPages.clear();
        g_vptDirtyCandidatePages.clear();
        g_vptDirtySourceDirectoryPages.clear();
    }

    g_vliGatherPages =
        tableUpdates.size() +
        sourceUploads.size() +
        emitterUploads.size() +
        emitterAliasUploads.size() +
        candidateUploads.size() +
        sourceDirectoryUploads.size();

    g_vliMsGather =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() -
            vliBreakdownGatherBegin
        ).count() -
        g_vliMsLockWait;

    const auto vliBreakdownUploadBegin =
        std::chrono::steady_clock::now();

    const bool didInitialClear = g_vliNeedsInitialClear;
    if(didInitialClear)
    {
        vkCmdFillBuffer(cmd, g_vliPageTableBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vliPageBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vliScratchBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vptSurfaceCacheBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vliWorkListBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vptEmitterIndexBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vptEmitterAliasBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vptCandidateBuffer, 0, VK_WHOLE_SIZE, 0u);
        vkCmdFillBuffer(cmd, g_vptSourceDirectoryBuffer, 0, VK_WHOLE_SIZE, 0u);
        g_vliNeedsInitialClear = false;
    }

    for(const auto& update : tablePayloads)
    {
        vkCmdUpdateBuffer(
            cmd,
            g_vliPageTableBuffer,
            static_cast<VkDeviceSize>(update.first) * sizeof(VLITableSlot),
            sizeof(VLITableSlot),
            &update.second
        );
    }

    for(const VliUploadRef& upload : sourceUploads)
    {
        vkCmdUpdateBuffer(
            cmd,
            g_vliPageBuffer,
            static_cast<VkDeviceSize>(upload.pageIndex) *
                VLI_PAGE_WORDS * sizeof(uint32_t),
            static_cast<VkDeviceSize>(upload.wordCount) * sizeof(uint32_t),
            g_vliUploadArena.data() + upload.wordOffset
        );
    }

    uint64_t uploadedEmitterCount = 0u;
    for(const VliUploadRef& upload : emitterUploads)
    {
        if(upload.wordCount != VPT_EMITTER_PAGE_WORDS)
        {
            continue;
        }

        uploadedEmitterCount += g_vliUploadArena[upload.wordOffset];
        vkCmdUpdateBuffer(
            cmd,
            g_vptEmitterIndexBuffer,
            static_cast<VkDeviceSize>(upload.pageIndex) *
                VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
            static_cast<VkDeviceSize>(VPT_EMITTER_PAGE_WORDS) * sizeof(uint32_t),
            g_vliUploadArena.data() + upload.wordOffset
        );
    }

    // 2026-10-06：VPT 页诊断日志按调用次数节流。流式加载期间这三个上传集合几乎
    // 每帧都非空，原来每帧三次 std::stringstream + RTLog（含 mutex 与文件写）。
    // 节流到每 120 次一条（≈60fps 下每 2 秒），首次仍然输出。
    static uint32_t vptPageLogThrottle = 0u;
    const bool vptLogDue = (vptPageLogThrottle++ % 120u) == 0u;

    if(!emitterUploads.empty() && vptLogDue)
    {
        std::stringstream ss;
        ss << "[VPT-3.1 INDEX] pages=" << emitterUploads.size()
           << " emitters=" << uploadedEmitterCount
           << " bytes="
           << static_cast<unsigned long long>(
                emitterUploads.size() *
                static_cast<size_t>(VPT_EMITTER_PAGE_WORDS) *
                sizeof(uint32_t)
              )
           << " binding=28";
        RTLog(ss.str());
    }

    for(const VliUploadRef& upload : emitterAliasUploads)
    {
        if(upload.wordCount != VPT_EMITTER_PAGE_WORDS) continue;
        vkCmdUpdateBuffer(
            cmd,
            g_vptEmitterAliasBuffer,
            static_cast<VkDeviceSize>(upload.pageIndex) *
                VPT_EMITTER_PAGE_WORDS * sizeof(uint32_t),
            static_cast<VkDeviceSize>(VPT_EMITTER_PAGE_WORDS) * sizeof(uint32_t),
            g_vliUploadArena.data() + upload.wordOffset
        );
    }

    uint64_t uploadedCandidateCount = 0u;
    for(const auto& upload : candidateUploads)
    {
        for(const VPTRelatedEmitterGPU& candidate : upload.second)
        {
            if((candidate.emissionAndType & 15u) != 0u)
            {
                ++uploadedCandidateCount;
            }
        }

        vkCmdUpdateBuffer(
            cmd,
            g_vptCandidateBuffer,
            static_cast<VkDeviceSize>(upload.first) *
                VPT_RELATED_EMITTERS_PER_SECTION *
                sizeof(VPTRelatedEmitterGPU),
            sizeof(upload.second),
            upload.second.data()
        );
    }

    if(!candidateUploads.empty() && vptLogDue)
    {
        std::stringstream ss;
        ss << "[VPT-3.2 CANDIDATES] pages=" << candidateUploads.size()
           << " entries=" << uploadedCandidateCount
           << " maxPerPage=" << VPT_RELATED_EMITTERS_PER_SECTION
           << " binding=29";
        RTLog(ss.str());
    }

    uint64_t uploadedDirectorySources = 0u;
    for(const auto& upload : sourceDirectoryUploads)
    {
        uploadedDirectorySources += upload.second[0].pageIndex;
        vkCmdUpdateBuffer(
            cmd,
            g_vptSourceDirectoryBuffer,
            static_cast<VkDeviceSize>(upload.first) *
                VPT_SOURCE_DIRECTORY_ENTRIES_PER_PAGE *
                sizeof(VPTSourceDirectoryEntryGPU),
            sizeof(upload.second),
            upload.second.data()
        );
    }

    if(!sourceDirectoryUploads.empty() && vptLogDue)
    {
        std::stringstream ss;
        ss << "[VPT-3.3D.7 DIRECTORY] pages="
           << sourceDirectoryUploads.size()
           << " sourceSections=" << uploadedDirectorySources
           << " maxPerPage=" << VPT_SOURCE_DIRECTORY_MAX_SECTIONS
           << " binding=31";
        RTLog(ss.str());
    }

    // VPT-3.3C.4: any Section payload, emitter list, or receiver candidate
    // update invalidates temporal local-light visibility immediately.
    if(!tableUpdates.empty() || !sourceUploads.empty() ||
       !emitterUploads.empty() || !emitterAliasUploads.empty() || !candidateUploads.empty() ||
       !sourceDirectoryUploads.empty())
    {
        g_vptDirectHistoryNeedsClear = true;
    }

    g_vliMsUpload =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() -
            vliBreakdownUploadBegin
        ).count();

    const auto vliBreakdownSolveBegin =
        std::chrono::steady_clock::now();

    std::sort(
        solvePages.begin(),
        solvePages.end(),
        [](const auto& a, const auto& b) { return a.first < b.first; }
    );
    solvePages.erase(
        std::unique(solvePages.begin(), solvePages.end()),
        solvePages.end()
    );

    if(solvePages.empty())
    {
        if(
            !tableUpdates.empty() ||
            !sourceUploads.empty() ||
            !emitterUploads.empty() ||
            !candidateUploads.empty() ||
            !sourceDirectoryUploads.empty() ||
            didInitialClear
        )
        {
            VkMemoryBarrier rayReadBarrier{ VK_STRUCTURE_TYPE_MEMORY_BARRIER };
            rayReadBarrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
            rayReadBarrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
            vkCmdPipelineBarrier(
                cmd,
                VK_PIPELINE_STAGE_TRANSFER_BIT,
                VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
                0,
                1,
                &rayReadBarrier,
                0,
                nullptr,
                0,
                nullptr
            );
        }
        return;
    }

    std::vector<uint32_t> workList(1u + solvePages.size());
    workList[0] = static_cast<uint32_t>(solvePages.size());
    for(size_t i = 0; i < solvePages.size(); ++i)
    {
        workList[1u + i] = solvePages[i].first;
    }

    vkCmdUpdateBuffer(
        cmd,
        g_vliWorkListBuffer,
        0,
        static_cast<VkDeviceSize>(workList.size()) * sizeof(uint32_t),
        workList.data()
    );

    VkMemoryBarrier workBarrier{ VK_STRUCTURE_TYPE_MEMORY_BARRIER };
    workBarrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
    workBarrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
    vkCmdPipelineBarrier(
        cmd,
        VK_PIPELINE_STAGE_TRANSFER_BIT,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        0,
        1,
        &workBarrier,
        0,
        nullptr,
        0,
        nullptr
    );

    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, g_vliComputePipeline);
    vkCmdBindDescriptorSets(
        cmd,
        VK_PIPELINE_BIND_POINT_COMPUTE,
        g_vliComputePipelineLayout,
        0,
        1,
        &g_rayTracingDescriptorSet,
        0,
        nullptr
    );

    const uint64_t totalSurfaceFaces =
        static_cast<uint64_t>(solvePages.size()) * VPT_SURFACE_FACES_PER_SECTION;
    const uint32_t surfaceDispatchX =
        static_cast<uint32_t>((totalSurfaceFaces + 63u) / 64u);

    // VPT-3.3B.1 has exactly one event-driven solve pass: emitter -> exact
    // block face.  The former 9^3 direct/secondary probe passes are not
    // dispatched and therefore cannot contribute interpolated light to the
    // primary image.
    VPTPushConstants pushConstants{};
    pushConstants.eventSerial = g_vptTemporalFrame++;
    pushConstants.passIndex = 1u;
    vkCmdPushConstants(cmd, g_vliComputePipelineLayout, VK_SHADER_STAGE_COMPUTE_BIT,
        0, sizeof(VPTPushConstants), &pushConstants);
    vkCmdDispatch(cmd, surfaceDispatchX, 1, 1);

    VkMemoryBarrier computeToRayBarrier{ VK_STRUCTURE_TYPE_MEMORY_BARRIER };
    // D.7's source directory is uploaded by transfer and read directly by
    // RayGen; it is not consumed by the intervening Compute solve.  Include
    // both producers so a frame with a surface-cache solve cannot race that
    // direct RayGen read.
    computeToRayBarrier.srcAccessMask =
        VK_ACCESS_SHADER_WRITE_BIT | VK_ACCESS_TRANSFER_WRITE_BIT;
    computeToRayBarrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
    vkCmdPipelineBarrier(
        cmd,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_TRANSFER_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
        0,
        1,
        &computeToRayBarrier,
        0,
        nullptr,
        0,
        nullptr
    );

    g_vliMsSolve =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() -
            vliBreakdownSolveBegin
        ).count();
}

// =====================================================================================
// NRD-1  NVIDIA Real-Time Denoisers - implementation
//
// Everything below is derived from NRD's own headers, its CMake flags or the
// SPIR-V it ships.  Where NRD's API and its binaries disagree, the comment says
// which one wins and how that was checked.
// =====================================================================================

// NRD's `InstanceDesc::shaderEntryPoint` reports the *unexpanded* macro token
// "NRD_CS_MAIN", but the SPIR-V NRD ships declares
//     OpEntryPoint GLCompute %main "main"
// (checked with spirv-dis on cpp/deps/NRD/_Shaders/*.spirv).  Vulkan resolves
// the entry point by name, so the pipeline must ask for "main".  NRD's reported
// name is kept only as a fallback in case a future build renames it.
static const char* const NRD_SPIRV_ENTRY_POINT = "main";

// Defined further down; createNRDResources / destroyNRDResources call them.
static void createNRDCompositePipeline();
static void destroyNRDCompositePipeline();

// Upper bound on the dispatches NRD may return for a single frame.  The
// The REBLUR_DIFFUSE chain used eight passes; RELAX_DIFFUSE runs a dozen-ish
// (ClassifyTiles / PreBlur / Atrous xN / HistoryClamping / HistoryFix /
// AntiFirefly / HitDistReconstruction).  Overflowing the bound below skips NRD
// for that frame instead of overrunning the constant-buffer ring.
static constexpr uint32_t NRD_MAX_DISPATCHES = 64u;

// Constant-buffer ring.  NRD hands back one small block per dispatch and each
// dispatch needs its own slot, because all the slots are filled by one
// vkCmdUpdateBuffer sweep before the dispatches are recorded.
static std::vector<uint32_t> g_nrdConstantBufferOffsets;

struct NRDCompositePushConstants
{
    uint32_t width;
    uint32_t height;
};

static VkFormat nrdFormatToVkFormat(nrd::Format format)
{
    switch(format)
    {
        case nrd::Format::R8_UNORM:              return VK_FORMAT_R8_UNORM;
        case nrd::Format::R8_SNORM:              return VK_FORMAT_R8_SNORM;
        case nrd::Format::R8_UINT:               return VK_FORMAT_R8_UINT;
        case nrd::Format::R8_SINT:               return VK_FORMAT_R8_SINT;
        case nrd::Format::RG8_UNORM:             return VK_FORMAT_R8G8_UNORM;
        case nrd::Format::RG8_SNORM:             return VK_FORMAT_R8G8_SNORM;
        case nrd::Format::RG8_UINT:              return VK_FORMAT_R8G8_UINT;
        case nrd::Format::RG8_SINT:              return VK_FORMAT_R8G8_SINT;
        case nrd::Format::RGBA8_UNORM:           return VK_FORMAT_R8G8B8A8_UNORM;
        case nrd::Format::RGBA8_SNORM:           return VK_FORMAT_R8G8B8A8_SNORM;
        case nrd::Format::RGBA8_UINT:            return VK_FORMAT_R8G8B8A8_UINT;
        case nrd::Format::RGBA8_SINT:            return VK_FORMAT_R8G8B8A8_SINT;
        case nrd::Format::RGBA8_SRGB:            return VK_FORMAT_R8G8B8A8_SRGB;
        case nrd::Format::R16_UNORM:             return VK_FORMAT_R16_UNORM;
        case nrd::Format::R16_SNORM:             return VK_FORMAT_R16_SNORM;
        case nrd::Format::R16_UINT:              return VK_FORMAT_R16_UINT;
        case nrd::Format::R16_SINT:              return VK_FORMAT_R16_SINT;
        case nrd::Format::R16_SFLOAT:            return VK_FORMAT_R16_SFLOAT;
        case nrd::Format::RG16_UNORM:            return VK_FORMAT_R16G16_UNORM;
        case nrd::Format::RG16_SNORM:            return VK_FORMAT_R16G16_SNORM;
        case nrd::Format::RG16_UINT:             return VK_FORMAT_R16G16_UINT;
        case nrd::Format::RG16_SINT:             return VK_FORMAT_R16G16_SINT;
        case nrd::Format::RG16_SFLOAT:           return VK_FORMAT_R16G16_SFLOAT;
        case nrd::Format::RGBA16_UNORM:          return VK_FORMAT_R16G16B16A16_UNORM;
        case nrd::Format::RGBA16_SNORM:          return VK_FORMAT_R16G16B16A16_SNORM;
        case nrd::Format::RGBA16_UINT:           return VK_FORMAT_R16G16B16A16_UINT;
        case nrd::Format::RGBA16_SINT:           return VK_FORMAT_R16G16B16A16_SINT;
        case nrd::Format::RGBA16_SFLOAT:         return VK_FORMAT_R16G16B16A16_SFLOAT;
        case nrd::Format::R32_UINT:              return VK_FORMAT_R32_UINT;
        case nrd::Format::R32_SINT:              return VK_FORMAT_R32_SINT;
        case nrd::Format::R32_SFLOAT:            return VK_FORMAT_R32_SFLOAT;
        case nrd::Format::RG32_UINT:             return VK_FORMAT_R32G32_UINT;
        case nrd::Format::RG32_SINT:             return VK_FORMAT_R32G32_SINT;
        case nrd::Format::RG32_SFLOAT:           return VK_FORMAT_R32G32_SFLOAT;
        // Vulkan has no 3-channel 32-bit format.  NRD only uses these for
        // scratch, and a wider texture is always safe.
        case nrd::Format::RGB32_UINT:            return VK_FORMAT_R32G32B32A32_UINT;
        case nrd::Format::RGB32_SINT:            return VK_FORMAT_R32G32B32A32_SINT;
        case nrd::Format::RGB32_SFLOAT:          return VK_FORMAT_R32G32B32A32_SFLOAT;
        case nrd::Format::RGBA32_UINT:           return VK_FORMAT_R32G32B32A32_UINT;
        case nrd::Format::RGBA32_SINT:           return VK_FORMAT_R32G32B32A32_SINT;
        case nrd::Format::RGBA32_SFLOAT:         return VK_FORMAT_R32G32B32A32_SFLOAT;
        // D3D "R10G10B10A2_UNORM" and Vulkan "A2B10G10R10_UNORM_PACK32" are the
        // same logical layout (10-bit RGB + 2-bit A).  NRD only ever reads this
        // through imageLoad, which returns normalised floats, so the bit order
        // of the packed words is irrelevant.
        case nrd::Format::R10_G10_B10_A2_UNORM:  return VK_FORMAT_A2B10G10R10_UNORM_PACK32;
        case nrd::Format::R10_G10_B10_A2_UINT:   return VK_FORMAT_A2B10G10R10_UINT_PACK32;
        case nrd::Format::R11_G11_B10_UFLOAT:    return VK_FORMAT_B10G11R11_UFLOAT_PACK32;
        case nrd::Format::R9_G9_B9_E5_UFLOAT:    return VK_FORMAT_E5B9G9R9_UFLOAT_PACK32;
        default:                                 break;
    }

    return VK_FORMAT_UNDEFINED;
}

static void nrdDestroyImage(
    VkImage& image,
    VkDeviceMemory& memory,
    VkImageView& view,
    VkImageLayout& layout)
{
    if(view != VK_NULL_HANDLE)
    {
        vkDestroyImageView(g_device, view, nullptr);
        view = VK_NULL_HANDLE;
    }

    if(image != VK_NULL_HANDLE)
    {
        vkDestroyImage(g_device, image, nullptr);
        image = VK_NULL_HANDLE;
    }

    if(memory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, memory, nullptr);
        memory = VK_NULL_HANDLE;
    }

    layout = VK_IMAGE_LAYOUT_UNDEFINED;
}

// NRD pool textures and the app-side inputs/outputs are all read and written as
// untyped storage images, so every one of them is created with STORAGE +
// SAMPLED and lives in GENERAL for its whole life.  That also matches how the
// rest of this backend handles long-lived images (see g_rtOutputImage), so no
// new layout-tracking rules are introduced.
static bool nrdCreateImage2D(
    uint32_t width,
    uint32_t height,
    VkFormat format,
    VkImage& image,
    VkDeviceMemory& memory,
    VkImageView& view,
    VkImageLayout& layout,
    const char* what)
{
    if(width == 0u || height == 0u)
    {
        RTLog(std::string("[NRD-1 CREATE] refused zero-size image for ") + what);
        return false;
    }

    if(format == VK_FORMAT_UNDEFINED)
    {
        RTLog(std::string("[NRD-1 CREATE] no Vulkan format for ") + what);
        return false;
    }

    VkFormatProperties formatProps{};
    vkGetPhysicalDeviceFormatProperties(g_physicalDevice, format, &formatProps);

    if((formatProps.optimalTilingFeatures & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT) == 0u)
    {
        RTLog(
            std::string("[NRD-1 CREATE] format lacks STORAGE_IMAGE support for ") +
            what + " vkFormat=" + std::to_string(static_cast<int>(format))
        );
        return false;
    }

    VkImageCreateInfo ci{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};
    ci.imageType = VK_IMAGE_TYPE_2D;
    ci.format = format;
    ci.extent = {width, height, 1u};
    ci.mipLevels = 1u;
    ci.arrayLayers = 1u;
    ci.samples = VK_SAMPLE_COUNT_1_BIT;
    ci.tiling = VK_IMAGE_TILING_OPTIMAL;
    ci.usage =
        VK_IMAGE_USAGE_STORAGE_BIT |
        VK_IMAGE_USAGE_SAMPLED_BIT |
        VK_IMAGE_USAGE_TRANSFER_SRC_BIT |
        VK_IMAGE_USAGE_TRANSFER_DST_BIT;
    ci.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    ci.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;

    if(vkCreateImage(g_device, &ci, nullptr, &image) != VK_SUCCESS)
    {
        image = VK_NULL_HANDLE;
        RTLog(std::string("[NRD-1 CREATE] vkCreateImage failed for ") + what);
        return false;
    }

    VkMemoryRequirements requirements{};
    vkGetImageMemoryRequirements(g_device, image, &requirements);

    VkMemoryAllocateInfo allocation{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex = findMemoryType(
        g_physicalDevice,
        requirements.memoryTypeBits,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT
    );

    if(vkAllocateMemory(g_device, &allocation, nullptr, &memory) != VK_SUCCESS)
    {
        memory = VK_NULL_HANDLE;
        nrdDestroyImage(image, memory, view, layout);
        RTLog(std::string("[NRD-1 CREATE] vkAllocateMemory failed for ") + what);
        return false;
    }

    if(vkBindImageMemory(g_device, image, memory, 0) != VK_SUCCESS)
    {
        nrdDestroyImage(image, memory, view, layout);
        RTLog(std::string("[NRD-1 CREATE] vkBindImageMemory failed for ") + what);
        return false;
    }

    VkImageViewCreateInfo viewInfo{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
    viewInfo.image = image;
    viewInfo.viewType = VK_IMAGE_VIEW_TYPE_2D;
    viewInfo.format = format;
    viewInfo.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
    viewInfo.subresourceRange.baseMipLevel = 0u;
    viewInfo.subresourceRange.levelCount = 1u;
    viewInfo.subresourceRange.baseArrayLayer = 0u;
    viewInfo.subresourceRange.layerCount = 1u;

    if(vkCreateImageView(g_device, &viewInfo, nullptr, &view) != VK_SUCCESS)
    {
        view = VK_NULL_HANDLE;
        nrdDestroyImage(image, memory, view, layout);
        RTLog(std::string("[NRD-1 CREATE] vkCreateImageView failed for ") + what);
        return false;
    }

    layout = VK_IMAGE_LAYOUT_UNDEFINED;
    return true;
}

// The two immutable samplers NRD asks for (Sampler::NEAREST_CLAMP and
// Sampler::LINEAR_CLAMP).  Address mode is CLAMP_TO_EDGE and mip 0 is the only
// level, exactly as NRD's own integration layer sets them up.
static VkSampler nrdCreateImmutableSampler(bool linear, const char* what)
{
    VkSamplerCreateInfo ci{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};
    ci.magFilter = linear ? VK_FILTER_LINEAR : VK_FILTER_NEAREST;
    ci.minFilter = linear ? VK_FILTER_LINEAR : VK_FILTER_NEAREST;
    ci.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
    ci.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    ci.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    ci.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    ci.minLod = 0.0f;
    ci.maxLod = 0.0f;
    ci.maxAnisotropy = 1.0f;
    ci.compareOp = VK_COMPARE_OP_NEVER;
    ci.borderColor = VK_BORDER_COLOR_FLOAT_TRANSPARENT_BLACK;

    VkSampler sampler = VK_NULL_HANDLE;

    if(vkCreateSampler(g_device, &ci, nullptr, &sampler) != VK_SUCCESS)
    {
        RTLog(std::string("[NRD-1 CREATE] sampler creation failed for ") + what);
        return VK_NULL_HANDLE;
    }

    return sampler;
}

// Every image NRD touches is used as a GENERAL storage/sampled image, but
// nrdCreateImage2D leaves each one at VK_IMAGE_LAYOUT_UNDEFINED and nothing
// transitions them afterwards (the tracked layouts are only read at destroy).
// Describing an image as GENERAL while it was never transitioned into it makes
// the very first access undefined -- and that first access is the RayGen's
// store into IN_VIEWZ / IN_NORMAL_ROUGHNESS / IN_DIFF, i.e. the only writer the
// whole denoiser depends on.  The water-sim and caustic images in this file do
// the UNDEFINED -> GENERAL step explicitly for the same reason, so do it here
// once per NRD (re)creation.
static void nrdTransitionImagesToGeneral()
{
    std::vector<VkImage> images;

    const VkImage appImages[7] =
    {
        g_nrdViewZImage,
        g_nrdNormalRoughnessImage,
        g_nrdMotionImage,
        g_nrdDiffRadianceHitDistImage,
        g_nrdOutDiffRadianceHitDistImage,
        g_nrdValidationImage,
        g_nrdMvProbeImage
    };

    for(VkImage image : appImages)
    {
        if(image != VK_NULL_HANDLE)
        {
            images.push_back(image);
        }
    }

    for(VkImage image : g_nrdPermanentImages)
    {
        if(image != VK_NULL_HANDLE)
        {
            images.push_back(image);
        }
    }

    for(VkImage image : g_nrdTransientImages)
    {
        if(image != VK_NULL_HANDLE)
        {
            images.push_back(image);
        }
    }

    if(images.empty() || g_rtCommandPool == VK_NULL_HANDLE)
    {
        return;
    }

    std::vector<VkImageMemoryBarrier> barriers(images.size());

    for(size_t i = 0u; i < images.size(); ++i)
    {
        VkImageMemoryBarrier& barrier = barriers[i];
        barrier = VkImageMemoryBarrier{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};
        barrier.srcAccessMask = 0u;
        barrier.dstAccessMask =
            VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        barrier.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED;
        barrier.newLayout = VK_IMAGE_LAYOUT_GENERAL;
        barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        barrier.image = images[i];
        barrier.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        barrier.subresourceRange.baseMipLevel = 0u;
        barrier.subresourceRange.levelCount = 1u;
        barrier.subresourceRange.baseArrayLayer = 0u;
        barrier.subresourceRange.layerCount = 1u;
    }

    VkCommandBufferAllocateInfo allocation{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO
    };
    allocation.commandPool = g_rtCommandPool;
    allocation.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
    allocation.commandBufferCount = 1u;

    VkCommandBuffer commandBuffer = VK_NULL_HANDLE;

    if(vkAllocateCommandBuffers(g_device, &allocation, &commandBuffer) != VK_SUCCESS)
    {
        RTLog("[NRD-1 CREATE] layout transition command buffer failed");
        return;
    }

    VkCommandBufferBeginInfo beginInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO
    };
    beginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;

    check(
        vkBeginCommandBuffer(commandBuffer, &beginInfo),
        "NRD layout transition begin failed"
    );

    vkCmdPipelineBarrier(
        commandBuffer,
        VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,
        VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
        0u,
        0u, nullptr,
        0u, nullptr,
        static_cast<uint32_t>(barriers.size()),
        barriers.data()
    );

    // IN_MV 现在**没有生产者**：写它的 rt_restir_final.rgen 已随 ReSTIR DI 链删除，
    // NRD 整条链也被 kNrdLocalDiEnabled=false 关停（settings 里配的是
    // motionVectorScale={1,1,1}，但那份 settings 只在关停的 recordNRDLocalDenoiser 里构建）。
    // 清零保留的两个理由：(1) NRD 的 TemporalStabilization pass 会把它自己跟踪的运动
    // **写回同一张图**（Reblur_Diffuse.hpp PushOutput(ResourceType::IN_MV)），下一帧读到的
    // 就是它 —— 首帧若留驱动分配内容会污染第一份历史；(2) 将来重建链路时这张图必须从
    // 一个确定状态出发。
    if(g_nrdMotionImage != VK_NULL_HANDLE)
    {
        VkClearColorValue motionClear{};
        motionClear.float32[0] = 0.0f;
        motionClear.float32[1] = 0.0f;
        motionClear.float32[2] = 0.0f;
        motionClear.float32[3] = 0.0f;

        VkImageSubresourceRange motionRange{};
        motionRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
        motionRange.baseMipLevel = 0u;
        motionRange.levelCount = 1u;
        motionRange.baseArrayLayer = 0u;
        motionRange.layerCount = 1u;

        vkCmdClearColorImage(
            commandBuffer,
            g_nrdMotionImage,
            VK_IMAGE_LAYOUT_GENERAL,
            &motionClear,
            1u,
            &motionRange
        );

        VkImageMemoryBarrier motionReady{
            VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER
        };
        motionReady.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
        motionReady.dstAccessMask =
            VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT;
        motionReady.oldLayout = VK_IMAGE_LAYOUT_GENERAL;
        motionReady.newLayout = VK_IMAGE_LAYOUT_GENERAL;
        motionReady.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        motionReady.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
        motionReady.image = g_nrdMotionImage;
        motionReady.subresourceRange = motionRange;

        vkCmdPipelineBarrier(
            commandBuffer,
            VK_PIPELINE_STAGE_TRANSFER_BIT,
            VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR |
                VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
            0u,
            0u, nullptr,
            0u, nullptr,
            1u, &motionReady
        );
    }

    check(
        vkEndCommandBuffer(commandBuffer),
        "NRD layout transition end failed"
    );

    VkSubmitInfo submit{VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submit.commandBufferCount = 1u;
    submit.pCommandBuffers = &commandBuffer;

    check(vkQueueSubmit(g_queue, 1u, &submit, VK_NULL_HANDLE), "NRD layout transition submit failed");
    check(vkQueueWaitIdle(g_queue), "NRD layout transition wait failed");

    vkFreeCommandBuffers(g_device, g_rtCommandPool, 1u, &commandBuffer);

    // Keep the trackers honest for the destroy path.
    g_nrdViewZLayout = VK_IMAGE_LAYOUT_GENERAL;
    g_nrdNormalRoughnessLayout = VK_IMAGE_LAYOUT_GENERAL;
    g_nrdMotionLayout = VK_IMAGE_LAYOUT_GENERAL;
    g_nrdDiffRadianceHitDistLayout = VK_IMAGE_LAYOUT_GENERAL;
    g_nrdOutDiffRadianceHitDistLayout = VK_IMAGE_LAYOUT_GENERAL;
    g_nrdMvProbeLayout = VK_IMAGE_LAYOUT_GENERAL;

    for(VkImageLayout& layout : g_nrdPermanentLayouts)
    {
        layout = VK_IMAGE_LAYOUT_GENERAL;
    }

    for(VkImageLayout& layout : g_nrdTransientLayouts)
    {
        layout = VK_IMAGE_LAYOUT_GENERAL;
    }

    RTLog(
        std::string("[NRD-1 CREATE] transitioned ") +
        std::to_string(images.size()) +
        " NRD images UNDEFINED -> GENERAL"
    );
}

// Builds the one shared descriptor set layout NRD's pipelines were compiled
// against.  Binding numbers come from NRD's SPIRV_*REG_OFFSET build flags:
//   set 0 : sampled images from textureOffset (20), storage images from
//           storageTextureAndBufferOffset (3)
//   set 1 : samplers from samplerOffset (0), constant buffer at
//           constantBufferOffset (2) + constantBufferRegisterIndex (0)
static bool createNRDDescriptorSetLayout()
{
    if(g_nrdDescriptorSetLayout != VK_NULL_HANDLE)
    {
        return true;
    }

    const uint32_t textureBase =
        g_nrdLibraryDesc.spirvBindingOffsets.textureOffset +
        g_nrdInstanceDesc.resourcesBaseRegisterIndex;

    const uint32_t storageBase =
        g_nrdLibraryDesc.spirvBindingOffsets.storageTextureAndBufferOffset +
        g_nrdInstanceDesc.resourcesBaseRegisterIndex;

    const uint32_t samplerBase =
        g_nrdLibraryDesc.spirvBindingOffsets.samplerOffset +
        g_nrdInstanceDesc.samplersBaseRegisterIndex;

    const uint32_t constantBufferBinding =
        g_nrdLibraryDesc.spirvBindingOffsets.constantBufferOffset +
        g_nrdInstanceDesc.constantBufferRegisterIndex;

    const uint32_t textureCount =
        std::max(1u, g_nrdInstanceDesc.descriptorPoolDesc.perSetTexturesMaxNum);

    const uint32_t storageCount =
        std::max(1u, g_nrdInstanceDesc.descriptorPoolDesc.perSetStorageTexturesMaxNum);

    // NRD's own offsets put storage images at binding 3 and sampled images at
    // binding 20, which leaves room for 17 storage images before the two
    // ranges would collide.  Overlapping bindings make
    // vkCreateDescriptorSetLayout fail, so fail early with a clear message.
    if(storageBase + storageCount > textureBase)
    {
        RTLog(
            std::string("[NRD-1 CREATE] NRD descriptor ranges overlap: storage ") +
            std::to_string(storageBase) + "+" + std::to_string(storageCount) +
            " vs textures from " + std::to_string(textureBase)
        );
        return false;
    }

    std::vector<VkDescriptorSetLayoutBinding> bindings;
    bindings.reserve(
        textureCount + storageCount + 3u
    );

    for(uint32_t i = 0u; i < textureCount; ++i)
    {
        VkDescriptorSetLayoutBinding binding{};
        binding.binding = textureBase + i;
        binding.descriptorType = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
        binding.descriptorCount = 1u;
        binding.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        bindings.push_back(binding);
    }

    for(uint32_t i = 0u; i < storageCount; ++i)
    {
        VkDescriptorSetLayoutBinding binding{};
        binding.binding = storageBase + i;
        binding.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
        binding.descriptorCount = 1u;
        binding.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        bindings.push_back(binding);
    }

    // Samplers are immutable: the shader never changes filtering, so the
    // sampler objects are baked into the layout.  This is what NRD's own
    // integration layer means by "root/immutable samplers recommended".
    //
    // They belong to SET 1 together with the constant buffer, NOT to the
    // resource set: NRD's SPIR-V declares them in "space 1"
    // (NRD_CONSTANT_BUFFER_AND_SAMPLERS_SPACE_INDEX) and DXC turns a register
    // space into a SPIR-V DescriptorSet.  See the note next to the layout
    // globals above for the dump this was read out of.
    VkSampler immutableSamplers[static_cast<size_t>(nrd::Sampler::MAX_NUM)] =
    {
        g_nrdSamplerNearest,
        g_nrdSamplerLinear
    };

    std::vector<VkDescriptorSetLayoutBinding> constantBindings;
    constantBindings.reserve(g_nrdInstanceDesc.samplersNum + 1u);

    for(uint32_t i = 0u; i < g_nrdInstanceDesc.samplersNum; ++i)
    {
        VkDescriptorSetLayoutBinding binding{};
        binding.binding = samplerBase + i;
        binding.descriptorType = VK_DESCRIPTOR_TYPE_SAMPLER;
        binding.descriptorCount = 1u;
        binding.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        binding.pImmutableSamplers = &immutableSamplers[i];
        constantBindings.push_back(binding);
    }

    // One dynamic uniform buffer: every dispatch gets its own slot in a ring so
    // a single descriptor set serves the whole frame.
    VkDescriptorSetLayoutBinding constantBufferBindingInfo{};
    constantBufferBindingInfo.binding = constantBufferBinding;
    constantBufferBindingInfo.descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC;
    constantBufferBindingInfo.descriptorCount = 1u;
    constantBufferBindingInfo.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
    constantBindings.push_back(constantBufferBindingInfo);

    VkDescriptorSetLayoutCreateInfo layoutInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO
    };
    layoutInfo.bindingCount = static_cast<uint32_t>(bindings.size());
    layoutInfo.pBindings = bindings.data();

    if(vkCreateDescriptorSetLayout(g_device, &layoutInfo, nullptr, &g_nrdDescriptorSetLayout) != VK_SUCCESS)
    {
        g_nrdDescriptorSetLayout = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD descriptor set layout failed");
        return false;
    }

    VkDescriptorSetLayoutCreateInfo constantLayoutInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO
    };
    constantLayoutInfo.bindingCount = static_cast<uint32_t>(constantBindings.size());
    constantLayoutInfo.pBindings = constantBindings.data();

    if(vkCreateDescriptorSetLayout(g_device, &constantLayoutInfo, nullptr, &g_nrdConstantSetLayout) != VK_SUCCESS)
    {
        g_nrdConstantSetLayout = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD constant/sampler set layout failed");
        return false;
    }

    // Set 0 = resources (space 0), set 1 = constant buffer + samplers (space 1).
    const VkDescriptorSetLayout setLayouts[2] =
    {
        g_nrdDescriptorSetLayout,
        g_nrdConstantSetLayout
    };

    VkPipelineLayoutCreateInfo pipelineLayoutInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO
    };
    pipelineLayoutInfo.setLayoutCount = 2u;
    pipelineLayoutInfo.pSetLayouts = setLayouts;

    if(vkCreatePipelineLayout(g_device, &pipelineLayoutInfo, nullptr, &g_nrdPipelineLayout) != VK_SUCCESS)
    {
        g_nrdPipelineLayout = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD pipeline layout failed");
        return false;
    }

    RTLog(
        std::string("[NRD-1 CREATE] layouts ready: set0 resources textures=") +
        std::to_string(textureCount) + "@" + std::to_string(textureBase) +
        " storages=" + std::to_string(storageCount) + "@" + std::to_string(storageBase) +
        " set1 samplers@" + std::to_string(samplerBase) +
        " cb@" + std::to_string(constantBufferBinding)
    );

    return true;
}

static bool createNRDPoolTextures()
{
    const uint32_t permanentCount = g_nrdInstanceDesc.permanentPoolSize;
    const uint32_t transientCount = g_nrdInstanceDesc.transientPoolSize;

    g_nrdPermanentImages.assign(permanentCount, VK_NULL_HANDLE);
    g_nrdPermanentMemories.assign(permanentCount, VK_NULL_HANDLE);
    g_nrdPermanentViews.assign(permanentCount, VK_NULL_HANDLE);
    g_nrdPermanentLayouts.assign(permanentCount, VK_IMAGE_LAYOUT_UNDEFINED);
    g_nrdPermanentDescs.resize(permanentCount);

    g_nrdTransientImages.assign(transientCount, VK_NULL_HANDLE);
    g_nrdTransientMemories.assign(transientCount, VK_NULL_HANDLE);
    g_nrdTransientViews.assign(transientCount, VK_NULL_HANDLE);
    g_nrdTransientLayouts.assign(transientCount, VK_IMAGE_LAYOUT_UNDEFINED);
    g_nrdTransientDescs.resize(transientCount);

    // NRD's own rule for pool texture size: ceil(resourceSize / downsampleFactor).
    for(uint32_t i = 0u; i < permanentCount + transientCount; ++i)
    {
        const bool isPermanent = i < permanentCount;
        const nrd::TextureDesc& desc = isPermanent
            ? g_nrdInstanceDesc.permanentPool[i]
            : g_nrdInstanceDesc.transientPool[i - permanentCount];

        const uint32_t downsample = std::max<uint32_t>(1u, desc.downsampleFactor);
        const uint32_t poolWidth = (g_nrdWidth + downsample - 1u) / downsample;
        const uint32_t poolHeight = (g_nrdHeight + downsample - 1u) / downsample;
        const VkFormat format = nrdFormatToVkFormat(desc.format);

        const std::string what =
            std::string(isPermanent ? "permanent pool " : "transient pool ") +
            std::to_string(isPermanent ? i : (i - permanentCount));

        if(isPermanent)
        {
            g_nrdPermanentDescs[i] = desc;

            if(!nrdCreateImage2D(
                   poolWidth,
                   poolHeight,
                   format,
                   g_nrdPermanentImages[i],
                   g_nrdPermanentMemories[i],
                   g_nrdPermanentViews[i],
                   g_nrdPermanentLayouts[i],
                   what.c_str()))
            {
                return false;
            }
        }
        else
        {
            const uint32_t slot = i - permanentCount;
            g_nrdTransientDescs[slot] = desc;

            if(!nrdCreateImage2D(
                   poolWidth,
                   poolHeight,
                   format,
                   g_nrdTransientImages[slot],
                   g_nrdTransientMemories[slot],
                   g_nrdTransientViews[slot],
                   g_nrdTransientLayouts[slot],
                   what.c_str()))
            {
                return false;
            }
        }
    }

    return true;
}

static bool createNRDPipelines()
{
    const uint32_t pipelineCount = g_nrdInstanceDesc.pipelinesNum;
    g_nrdPipelines.assign(pipelineCount, VK_NULL_HANDLE);

    for(uint32_t i = 0u; i < pipelineCount; ++i)
    {
        const nrd::PipelineDesc& desc = g_nrdInstanceDesc.pipelines[i];

        if(desc.computeShaderSPIRV.bytecode == nullptr || desc.computeShaderSPIRV.size == 0u)
        {
            RTLog(
                std::string("[NRD-1 CREATE] pipeline ") + std::to_string(i) +
                " has no SPIR-V"
            );
            return false;
        }

        VkShaderModuleCreateInfo moduleInfo{
            VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO
        };
        moduleInfo.codeSize = static_cast<size_t>(desc.computeShaderSPIRV.size);
        moduleInfo.pCode = static_cast<const uint32_t*>(desc.computeShaderSPIRV.bytecode);

        VkShaderModule module = VK_NULL_HANDLE;

        if(vkCreateShaderModule(g_device, &moduleInfo, nullptr, &module) != VK_SUCCESS)
        {
            module = VK_NULL_HANDLE;
            RTLog(
                std::string("[NRD-1 CREATE] shader module failed for pipeline ") +
                std::to_string(i)
            );
            return false;
        }

        VkPipelineShaderStageCreateInfo stage{
            VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO
        };
        stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        stage.module = module;
        stage.pName = NRD_SPIRV_ENTRY_POINT;

        VkComputePipelineCreateInfo pipelineInfo{
            VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO
        };
        pipelineInfo.stage = stage;
        pipelineInfo.layout = g_nrdPipelineLayout;

        VkResult result = vkCreateComputePipelines(
            g_device,
            getSharedPipelineCache(),
            1u,
            &pipelineInfo,
            nullptr,
            &g_nrdPipelines[i]
        );

        if(result != VK_SUCCESS && g_nrdInstanceDesc.shaderEntryPoint != nullptr)
        {
            // Defensive fallback: if a future NRD build really does emit the
            // entry point under NRD's reported name, this still works.
            stage.pName = g_nrdInstanceDesc.shaderEntryPoint;

            result = vkCreateComputePipelines(
                g_device,
                getSharedPipelineCache(),
                1u,
                &pipelineInfo,
                nullptr,
                &g_nrdPipelines[i]
            );
        }

        vkDestroyShaderModule(g_device, module, nullptr);

        if(result != VK_SUCCESS)
        {
            g_nrdPipelines[i] = VK_NULL_HANDLE;
            RTLog(
                std::string("[NRD-1 CREATE] vkCreateComputePipelines failed for pipeline ") +
                std::to_string(i) + " result=" + std::to_string(static_cast<int>(result)) +
                " name=" + std::string(desc.shaderIdentifier)
            );
            return false;
        }
    }

    return true;
}

static bool createNRDAppTextures()
{
    // IN_VIEWZ is linear view-space Z at the primary hit.
    //
    // ★ 2026-09-28：由 R16f 改为 R32f。
    //
    // 为什么改：NRD 用 IN_VIEWZ 做重投影校验（平面距离 / 视差），阈值是
    // CommonSettings::disocclusionThreshold = 0.01（相对、斜率缩放）。而半精度
    // 的 ULP 在 30 格处约 0.016 —— **量化误差已经大于判定阈值**，于是远处像素
    // 的重投影校验必然失败、历史被丢弃；移动时误差再叠加，全屏都会失败。
    //
    // 这与实测完全吻合：静止时近处历史 16+ 帧（精度足够），静止时远处黑红
    // （精度不足），移动时全屏黑红（误差叠加运动）。
    //
    // NRD 的契约允许 R16f+（NRDDescs.h: "Linear view depth for primary rays (R16f+)"），
    // 所以 R32f 是合法且更精确的选择。
    //
    // 注意：shader 侧 binding 50 的格式限定符必须同步改成 r32f。天空/超范围标记
    // 65504.0 在 float32 里仍然是有限值，仍高于 denoisingRange(60000)，所以标记
    // 机制不变。
    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R32_SFLOAT,
           g_nrdViewZImage,
           g_nrdViewZMemory,
           g_nrdViewZView,
           g_nrdViewZLayout,
           "IN_VIEWZ"))
    {
        return false;
    }

    // IN_NORMAL_ROUGHNESS.  The format is fixed by NRD_NORMAL_ENCODING=2, which
    // is compiled into NRD's SPIR-V (cpp/deps/NRD/Shaders/NRDConfig.hlsli), so
    // an RGBA8 or RGBA16F texture here would be decoded with the wrong packing.
    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_A2B10G10R10_UNORM_PACK32,
           g_nrdNormalRoughnessImage,
           g_nrdNormalRoughnessMemory,
           g_nrdNormalRoughnessView,
           g_nrdNormalRoughnessLayout,
           "IN_NORMAL_ROUGHNESS"))
    {
        return false;
    }

    // IN_MV.  这张图现在没有生产者（rt_restir_final.rgen 已删、NRD 已关停），但仍必须
    // 存在并绑定：ResourceType::IN_MV 是 NRD 的固定输入之一。
    // （原文记的是早先"scale 置 0、让 NRD 自跟踪"那一档 —— 该档已被 2026-09-29 实测
    //   否决，它等价于零重投影，见 HANDOFF-2026-09-29-RT-DI-NRD.md §11。）
    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R16G16_SFLOAT,
           g_nrdMotionImage,
           g_nrdMotionMemory,
           g_nrdMotionView,
           g_nrdMotionLayout,
           "IN_MV"))
    {
        return false;
    }

    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R16G16B16A16_SFLOAT,
           g_nrdDiffRadianceHitDistImage,
           g_nrdDiffRadianceHitDistMemory,
           g_nrdDiffRadianceHitDistView,
           g_nrdDiffRadianceHitDistLayout,
           "IN_DIFF_RADIANCE_HITDIST"))
    {
        return false;
    }

    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R16G16B16A16_SFLOAT,
           g_nrdOutDiffRadianceHitDistImage,
           g_nrdOutDiffRadianceHitDistMemory,
           g_nrdOutDiffRadianceHitDistView,
           g_nrdOutDiffRadianceHitDistLayout,
           "OUT_DIFF_RADIANCE_HITDIST"))
    {
        return false;
    }

// OUT_VALIDATION。格式下限是 RGBA8（NRDDescs.h），这里用 RGBA8_UNORM。
    // 注意 NRD 不会清这张图（InstanceImpl.cpp 显式跳过），且 mini 视口靠帧间
    // 累积才有意义，所以它必须是常驻图像、不能被当成瞬时池复用。
    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R8G8B8A8_UNORM,
           g_nrdValidationImage,
           g_nrdValidationMemory,
           g_nrdValidationView,
           g_nrdValidationLayout,
           "OUT_VALIDATION"))
    {
        return false;
    }

    // MV 读回探针（binding 57，见 g_nrdMvProbeImage 的说明）。渲染分辨率，RGBA16F：
    // R/G = MV.xy（像素），B = MV.z，A = "本帧是否真的算了 MV"。它是**我们自己**的
    // 图 —— NRD 的 set 里没有它，所以它的内容不可能被 NRD 覆写。
    if(!nrdCreateImage2D(
           g_nrdWidth,
           g_nrdHeight,
           VK_FORMAT_R16G16B16A16_SFLOAT,
           g_nrdMvProbeImage,
           g_nrdMvProbeMemory,
           g_nrdMvProbeView,
           g_nrdMvProbeLayout,
           "MV_PROBE"))
    {
        return false;
    }

    return true;
}

// Publishes the four NRD textures into the shared RT descriptor set.  It runs
// after the textures exist, which is why it is not part of
// createRayTracingDescriptorPoolAndSet: NRD resources are created (and
// re-created on a render-resolution change) later than that set is allocated.
static bool updateNRDDescriptors()
{
    if(g_rayTracingDescriptorSet == VK_NULL_HANDLE)
    {
        RTLog("[NRD-1] RT descriptor set missing, cannot publish NRD textures");
        return false;
    }

    // 显式的 (binding, view) 表，替换掉原来那套 "前 4 个顺排、第 5 个落 55" 的
    // 位置推导：加了 binding 56 之后位置推导会很容易写错，而这里写错的表现是
    // 描述符错位、画面直接坏掉，不值得省这几行。
    struct NrdPublishEntry
    {
        uint32_t binding;
        VkImageView view;
    };

    NrdPublishEntry entries[7] =
    {
        { 50u, g_nrdViewZView },
        { 51u, g_nrdNormalRoughnessView },
        { 52u, g_nrdDiffRadianceHitDistView },
        { 53u, g_nrdOutDiffRadianceHitDistView },
        { 55u, g_nrdMotionView },
        { 56u, g_nrdValidationView },
        { 57u, g_nrdMvProbeView }
    };

    // IN_MV（55）只在真实运动矢量打开时发布；关闭时保持旧行为，binding 55 不
    // 绑定且 shader 也不声明它。OUT_VALIDATION（56）与 MV 读回探针（57）总是发布，
    // 因为两个 shader 侧都是无条件声明的（探针是纯自己的图，NRD 不参与）。
    // ⚠️ 2026-09-30：这段发布逻辑随 NRD 链一起关停（recordNRDLocalDenoiser 被
    //    kNrdLocalDiEnabled=false 门控），发布出去的 IN_MV 也没有生产者再写它。
    uint32_t selected[7]{};
    uint32_t selectedNum = 0u;

    for(uint32_t i = 0u; i < 4u; ++i)
    {
        selected[selectedNum++] = i;
    }

#if NRD_USE_REAL_MOTION_VECTORS
    selected[selectedNum++] = 4u;
#endif

    selected[selectedNum++] = 5u;
    selected[selectedNum++] = 6u;

    VkDescriptorImageInfo infos[7]{};

    for(uint32_t s = 0u; s < selectedNum; ++s)
    {
        const NrdPublishEntry& entry = entries[selected[s]];

        if(entry.view == VK_NULL_HANDLE)
        {
            RTLog(
                std::string("[NRD-1] missing NRD texture view for binding ") +
                std::to_string(entry.binding)
            );
            return false;
        }

        infos[s].imageView = entry.view;
        infos[s].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
    }

    VkWriteDescriptorSet writes[7]{};

    for(uint32_t s = 0u; s < selectedNum; ++s)
    {
        writes[s].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[s].dstSet = g_rayTracingDescriptorSet;
        writes[s].dstBinding = entries[selected[s]].binding;
        writes[s].dstArrayElement = 0u;
        writes[s].descriptorCount = 1u;
        writes[s].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
        writes[s].pImageInfo = &infos[s];
    }

    vkUpdateDescriptorSets(g_device, selectedNum, writes, 0u, nullptr);

    return true;
}

static bool createNRDConstantBuffer()
{
    VkPhysicalDeviceProperties properties{};
    vkGetPhysicalDeviceProperties(g_physicalDevice, &properties);

    const VkDeviceSize alignment = std::max<VkDeviceSize>(
        1u,
        properties.limits.minUniformBufferOffsetAlignment
    );

    const VkDeviceSize rawSize = static_cast<VkDeviceSize>(
        std::max(1u, g_nrdInstanceDesc.constantBufferMaxDataSize)
    );

    g_nrdConstantBufferStride =
        ((rawSize + alignment - 1u) / alignment) * alignment;

    const VkDeviceSize totalSize = g_nrdConstantBufferStride * NRD_MAX_DISPATCHES;

    VkBufferCreateInfo bufferInfo{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
    bufferInfo.size = totalSize;
    bufferInfo.usage = VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT;
    bufferInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;

    if(vkCreateBuffer(g_device, &bufferInfo, nullptr, &g_nrdConstantBuffer) != VK_SUCCESS)
    {
        g_nrdConstantBuffer = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD constant buffer failed");
        return false;
    }

    VkMemoryRequirements requirements{};
    vkGetBufferMemoryRequirements(g_device, g_nrdConstantBuffer, &requirements);

    VkMemoryAllocateInfo allocation{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex = findMemoryType(
        g_physicalDevice,
        requirements.memoryTypeBits,
        VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT
    );

    if(vkAllocateMemory(g_device, &allocation, nullptr, &g_nrdConstantBufferMemory) != VK_SUCCESS)
    {
        g_nrdConstantBufferMemory = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD constant buffer memory failed");
        return false;
    }

    if(vkBindBufferMemory(g_device, g_nrdConstantBuffer, g_nrdConstantBufferMemory, 0) != VK_SUCCESS)
    {
        RTLog("[NRD-1 CREATE] NRD constant buffer bind failed");
        return false;
    }

    return true;
}

static bool createNRDDescriptorSet()
{
    const uint32_t perSetTextures =
        std::max(1u, g_nrdInstanceDesc.descriptorPoolDesc.perSetTexturesMaxNum);

    const uint32_t perSetStorages =
        std::max(1u, g_nrdInstanceDesc.descriptorPoolDesc.perSetStorageTexturesMaxNum);

    const uint32_t samplersNum = std::max(1u, g_nrdInstanceDesc.samplersNum);

    VkDescriptorPoolSize poolSizes[4]{};

    poolSizes[0].type = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
    poolSizes[0].descriptorCount = perSetTextures * NRD_MAX_DISPATCHES;

    poolSizes[1].type = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    poolSizes[1].descriptorCount = perSetStorages * NRD_MAX_DISPATCHES;

    poolSizes[2].type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC;
    poolSizes[2].descriptorCount = NRD_MAX_DISPATCHES;

    poolSizes[3].type = VK_DESCRIPTOR_TYPE_SAMPLER;
    poolSizes[3].descriptorCount = samplersNum * NRD_MAX_DISPATCHES;

    VkDescriptorPoolCreateInfo poolInfo{VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};
    // Two sets per dispatch: set 0 (resources) + set 1 (constant buffer and
    // samplers).  The per-type counts below already cover both sets, because
    // the descriptors simply moved from one set into the other.
    poolInfo.maxSets = 2u * NRD_MAX_DISPATCHES;
    poolInfo.poolSizeCount = 4u;
    poolInfo.pPoolSizes = poolSizes;

    if(vkCreateDescriptorPool(g_device, &poolInfo, nullptr, &g_nrdDescriptorPool) != VK_SUCCESS)
    {
        g_nrdDescriptorPool = VK_NULL_HANDLE;
        RTLog("[NRD-1 CREATE] NRD descriptor pool failed");
        return false;
    }

    // Allocated once and kept for the lifetime of the instance.  Nothing is
    // reset per frame, so a frame still in flight can never have its sets
    // rewritten underneath it.
    std::vector<VkDescriptorSetLayout> layouts(
        NRD_MAX_DISPATCHES,
        g_nrdDescriptorSetLayout
    );

    g_nrdDescriptorSets.assign(NRD_MAX_DISPATCHES, VK_NULL_HANDLE);

    VkDescriptorSetAllocateInfo allocateInfo{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};
    allocateInfo.descriptorPool = g_nrdDescriptorPool;
    allocateInfo.descriptorSetCount = NRD_MAX_DISPATCHES;
    allocateInfo.pSetLayouts = layouts.data();

    if(vkAllocateDescriptorSets(g_device, &allocateInfo, g_nrdDescriptorSets.data()) != VK_SUCCESS)
    {
        g_nrdDescriptorSets.clear();
        RTLog("[NRD-1 CREATE] NRD descriptor set allocation failed");
        return false;
    }

    // SET 1: the constant buffer and the immutable samplers, one set per
    // dispatch so each dispatch can carry its own constant-buffer ring slot.
    std::vector<VkDescriptorSetLayout> constantLayouts(
        NRD_MAX_DISPATCHES,
        g_nrdConstantSetLayout
    );

    g_nrdConstantSets.assign(NRD_MAX_DISPATCHES, VK_NULL_HANDLE);

    VkDescriptorSetAllocateInfo constantAllocateInfo{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};
    constantAllocateInfo.descriptorPool = g_nrdDescriptorPool;
    constantAllocateInfo.descriptorSetCount = NRD_MAX_DISPATCHES;
    constantAllocateInfo.pSetLayouts = constantLayouts.data();

    if(vkAllocateDescriptorSets(g_device, &constantAllocateInfo, g_nrdConstantSets.data()) != VK_SUCCESS)
    {
        g_nrdConstantSets.clear();
        RTLog("[NRD-1 CREATE] NRD constant set allocation failed");
        return false;
    }

    // The constant buffer keeps the same binding in every set and only its
    // dynamic offset varies, so all of them can be written once here.
    VkDescriptorBufferInfo bufferInfo{};
    bufferInfo.buffer = g_nrdConstantBuffer;
    bufferInfo.offset = 0u;
    bufferInfo.range = g_nrdInstanceDesc.constantBufferMaxDataSize;

    std::vector<VkWriteDescriptorSet> writes(NRD_MAX_DISPATCHES);

    for(uint32_t i = 0u; i < NRD_MAX_DISPATCHES; ++i)
    {
        writes[i].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
        writes[i].dstSet = g_nrdConstantSets[i];
        writes[i].dstBinding =
            g_nrdLibraryDesc.spirvBindingOffsets.constantBufferOffset +
            g_nrdInstanceDesc.constantBufferRegisterIndex;
        writes[i].dstArrayElement = 0u;
        writes[i].descriptorCount = 1u;
        writes[i].descriptorType = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC;
        writes[i].pBufferInfo = &bufferInfo;
    }

    vkUpdateDescriptorSets(
        g_device,
        NRD_MAX_DISPATCHES,
        writes.data(),
        0u,
        nullptr
    );

    return true;
}

static void destroyNRDResources()
{
    g_nrdReady = false;

    if(g_device == VK_NULL_HANDLE)
    {
        g_nrdInstance = nullptr;
        return;
    }

    destroyNRDCompositePipeline();

    for(VkPipeline& pipeline : g_nrdPipelines)
    {
        if(pipeline != VK_NULL_HANDLE)
        {
            vkDestroyPipeline(g_device, pipeline, nullptr);
            pipeline = VK_NULL_HANDLE;
        }
    }

    g_nrdPipelines.clear();

    if(g_nrdDescriptorPool != VK_NULL_HANDLE)
    {
        // The pool owns the sets, so no vkFreeDescriptorSets is needed.
        vkDestroyDescriptorPool(g_device, g_nrdDescriptorPool, nullptr);
        g_nrdDescriptorPool = VK_NULL_HANDLE;
    }

    g_nrdDescriptorSets.clear();
    g_nrdConstantSets.clear();

    if(g_nrdPipelineLayout != VK_NULL_HANDLE)
    {
        vkDestroyPipelineLayout(g_device, g_nrdPipelineLayout, nullptr);
        g_nrdPipelineLayout = VK_NULL_HANDLE;
    }

    if(g_nrdDescriptorSetLayout != VK_NULL_HANDLE)
    {
        vkDestroyDescriptorSetLayout(g_device, g_nrdDescriptorSetLayout, nullptr);
        g_nrdDescriptorSetLayout = VK_NULL_HANDLE;
    }

    if(g_nrdConstantSetLayout != VK_NULL_HANDLE)
    {
        vkDestroyDescriptorSetLayout(g_device, g_nrdConstantSetLayout, nullptr);
        g_nrdConstantSetLayout = VK_NULL_HANDLE;
    }

    if(g_nrdConstantBuffer != VK_NULL_HANDLE)
    {
        vkDestroyBuffer(g_device, g_nrdConstantBuffer, nullptr);
        g_nrdConstantBuffer = VK_NULL_HANDLE;
    }

    if(g_nrdConstantBufferMemory != VK_NULL_HANDLE)
    {
        vkFreeMemory(g_device, g_nrdConstantBufferMemory, nullptr);
        g_nrdConstantBufferMemory = VK_NULL_HANDLE;
    }

    g_nrdConstantBufferStride = 0u;
    g_nrdConstantBufferOffsets.clear();

    for(size_t i = 0u; i < g_nrdPermanentImages.size(); ++i)
    {
        nrdDestroyImage(
            g_nrdPermanentImages[i],
            g_nrdPermanentMemories[i],
            g_nrdPermanentViews[i],
            g_nrdPermanentLayouts[i]
        );
    }

    for(size_t i = 0u; i < g_nrdTransientImages.size(); ++i)
    {
        nrdDestroyImage(
            g_nrdTransientImages[i],
            g_nrdTransientMemories[i],
            g_nrdTransientViews[i],
            g_nrdTransientLayouts[i]
        );
    }

    g_nrdPermanentImages.clear();
    g_nrdPermanentMemories.clear();
    g_nrdPermanentViews.clear();
    g_nrdPermanentLayouts.clear();
    g_nrdPermanentDescs.clear();

    g_nrdTransientImages.clear();
    g_nrdTransientMemories.clear();
    g_nrdTransientViews.clear();
    g_nrdTransientLayouts.clear();
    g_nrdTransientDescs.clear();

    nrdDestroyImage(
        g_nrdViewZImage,
        g_nrdViewZMemory,
        g_nrdViewZView,
        g_nrdViewZLayout
    );

    nrdDestroyImage(
        g_nrdNormalRoughnessImage,
        g_nrdNormalRoughnessMemory,
        g_nrdNormalRoughnessView,
        g_nrdNormalRoughnessLayout
    );

    nrdDestroyImage(
        g_nrdMotionImage,
        g_nrdMotionMemory,
        g_nrdMotionView,
        g_nrdMotionLayout
    );

    nrdDestroyImage(
        g_nrdDiffRadianceHitDistImage,
        g_nrdDiffRadianceHitDistMemory,
        g_nrdDiffRadianceHitDistView,
        g_nrdDiffRadianceHitDistLayout
    );

    nrdDestroyImage(
        g_nrdOutDiffRadianceHitDistImage,
        g_nrdOutDiffRadianceHitDistMemory,
        g_nrdOutDiffRadianceHitDistView,
        g_nrdOutDiffRadianceHitDistLayout
    );

    nrdDestroyImage(
        g_nrdValidationImage,
        g_nrdValidationMemory,
        g_nrdValidationView,
        g_nrdValidationLayout
    );

    nrdDestroyImage(
        g_nrdMvProbeImage,
        g_nrdMvProbeMemory,
        g_nrdMvProbeView,
        g_nrdMvProbeLayout
    );

    if(g_nrdSamplerNearest != VK_NULL_HANDLE)
    {
        vkDestroySampler(g_device, g_nrdSamplerNearest, nullptr);
        g_nrdSamplerNearest = VK_NULL_HANDLE;
    }

    if(g_nrdSamplerLinear != VK_NULL_HANDLE)
    {
        vkDestroySampler(g_device, g_nrdSamplerLinear, nullptr);
        g_nrdSamplerLinear = VK_NULL_HANDLE;
    }

    if(g_nrdInstance != nullptr)
    {
        nrd::DestroyInstance(*g_nrdInstance);
        g_nrdInstance = nullptr;
    }

    g_nrdWidth = 0u;
    g_nrdHeight = 0u;
    g_nrdFrameIndex = 0u;
    g_nrdNeedsHistoryReset = true;
    g_nrdSettingsLogged = false;
}

// Full (re)creation.  NRD has no resize support at all (NRD README, "API"), so
// a render-resolution change - which this backend really does have, because the
// RR preset changes the render size - must destroy and rebuild the instance.
static bool createNRDResources(uint32_t width, uint32_t height)
{
    // =====================================================================
    // 2026-10-21 收口：NRD 链路已是死代码，这里直接不创建任何资源。
    //
    // 依据（全部来自本仓库，不是推测）：
    //   · 链路本身被编译期常量 kNrdLocalDiEnabled = false 永久关停
    //     （dispatch / composite 的判据统一用它，见 5611 行的说明）；
    //   · 唯一的输入写者 rt_restir_final.rgen 已随 ReSTIR DI 链删除
    //     （git 2e3015c），本文件 5718 行的原文是"既无写者也无读者"；
    //   · 但初始化此前是**无条件**的：同一份日志里既能读到
    //     "[NRD-1 CREATE] transitioned 19 NRD images"、"[NRD-1 INIT] REBLUR_DIFFUSE ready"，
    //     又能读到 tag 里的 "+nrd-chain-disabled" —— 自相矛盾，说明纯粹白花。
    //
    // 代价：19 张渲染分辨率图像的显存（含历史缓冲）与一段启动时间；
    // 收益：帧内零收益（该 pass 从不 dispatch）。
    //
    // 安全性：NRD 的图像只挂在 NRD 自己的两个 descriptor set（set0 资源 / set1 采样器），
    // 不进我们的 RT set；g_nrdReady 保持 false，所有按 g_nrdReady / kNrdLocalDiEnabled
    // 门控的帧内代码自然不执行。若将来要复活 NRD，把 kNrdLocalDiEnabled 改 true 即可，
    // 这里是唯一入口，不需要再改这段。
    // =====================================================================
    if(!kNrdLocalDiEnabled)
    {
        return true;
    }

    if(g_device == VK_NULL_HANDLE || width == 0u || height == 0u)
    {
        return false;
    }

    g_nrdReady = false;
    g_nrdWidth = width;
    g_nrdHeight = height;

    const nrd::LibraryDesc* libraryDesc = nrd::GetLibraryDesc();

    if(libraryDesc == nullptr)
    {
        RTLog("[NRD-1 INIT] GetLibraryDesc returned null");
        return false;
    }

    g_nrdLibraryDesc = *libraryDesc;

    // =====================================================
    // 2026-09-29 第三步：DI 降噪器 REBLUR / RELAX 可切换。
    //
    // 依据（NRD README）：
    //   * "RELAX - A-trous based denoiser, has been designed for RTXDI"；
    //     "[RELAX] The Sweet Home of RELAX is RTXDI sample."
    //   * 两者输入输出槽相同（NRDDescs.h: REBLUR_DIFFUSE / RELAX_DIFFUSE 都是
    //     IN_DIFF_RADIANCE_HITDIST → OUT_DIFF_RADIANCE_HITDIST），所以合成端不用换，
    //     但**打包口径不同**（REBLUR = YCoCg + 归一化 hit dist；RELAX = 线性 + 原始
    //     hit dist），因此必须与 rt_restir_final.rgen / rt_nrd_composite.comp 的
    //     LOCAL_DI_DENOISER_RELAX 同步改，三者不能只改一处。
    //   * confidence 在两者里用法不同（REBLUR 乘进反馈环、RELAX 只用在 temporal
    //     accumulation，且 RELAX 期望更小的取值）⇒ 切换后 confidence 参数要重调。
    // 默认 0 = REBLUR（今天的线上行为）。
    // =====================================================
// ★★ 2026-09-29 第 3 项（方案 C）：RELAX_DIFFUSE 实验 —— 已回退，回到 REBLUR。★★
//
// 09-29 曾翻 0 -> 1 启用 RELAX（依据 NRD README:932：RELAX 适合 RTXDI 或
// 部署后实测结论：ReSTIR DI 这条链的噪点没有改善。原因读码即可确认，且与
// 下方 18565-18566 记录的 09-27 结论一致：
//   * 换降噪器只改"时域累积行为"，不改 1spp 估计量的方差；
//   * 本链的时域累积整条甩给 NRD 一层（线上口径 RESTIR_DI_LOCAL_EMA=0，
//     见 rt_restir_final.rgen:1450-1465），NRD 一旦逐帧拒史就掉回接近 1spp；
//   * RELAX 对 IN_DIFF_CONFIDENCE 的用法是历史帧数的**硬上限**
//     （min(historyLength, maxAccumulatedFrameNum * c)，NRD README:802），
//     不像 REBLUR 那样被 lerp(c,1,1/(1+A)) 稀释 —— confidence 一旦被低估，
//     噪点直接暴露。所以在"1spp + 自家算的 MV"这套输入下 RELAX 更脆。
//
// 用户裁定：退回 REBLUR。三处 shader 同名宏必须同步改回 0（否则打包口径错位）：
//   cpp/shaders/rt_restir_final.rgen   LOCAL_DI_DENOISER_RELAX
//   cpp/shaders/rt_nrd_composite.comp  LOCAL_DI_DENOISER_RELAX
//   cpp/shaders/rt_di_confidence.comp  LOCAL_DI_DENOISER_RELAX（亮度取样口径）
// 重新启用：本行改回 1，三个 shader 同名宏一并改回 1，重编三个 spv 与 DLL。
#ifndef NRD_LOCAL_DI_USE_RELAX
#define NRD_LOCAL_DI_USE_RELAX 0
#endif

#if NRD_LOCAL_DI_USE_RELAX
    constexpr nrd::Denoiser NRD_LOCAL_DI_DENOISER = nrd::Denoiser::RELAX_DIFFUSE;
    constexpr const char* NRD_LOCAL_DI_DENOISER_NAME = "RELAX_DIFFUSE";
#else
    constexpr nrd::Denoiser NRD_LOCAL_DI_DENOISER = nrd::Denoiser::REBLUR_DIFFUSE;
    constexpr const char* NRD_LOCAL_DI_DENOISER_NAME = "REBLUR_DIFFUSE";
#endif

    bool supportsDiffuse = false;

    for(uint32_t i = 0u; i < g_nrdLibraryDesc.supportedDenoisersNum; ++i)
    {
        if(g_nrdLibraryDesc.supportedDenoisers[i] == NRD_LOCAL_DI_DENOISER)
        {
            supportsDiffuse = true;
            break;
        }
    }

    if(!supportsDiffuse)
    {
        RTLog(
            std::string("[NRD-1 INIT] this NRD build has no ") +
            NRD_LOCAL_DI_DENOISER_NAME
        );
        return false;
    }

    const nrd::DenoiserDesc denoiserDescs[] =
    {
        {g_nrdIdentifier, NRD_LOCAL_DI_DENOISER}
    };

    nrd::InstanceCreationDesc creationDesc{};
    creationDesc.denoisers = denoiserDescs;
    creationDesc.denoisersNum = 1u;

    if(nrd::CreateInstance(creationDesc, g_nrdInstance) != nrd::Result::SUCCESS)
    {
        g_nrdInstance = nullptr;
        RTLog("[NRD-1 INIT] nrd::CreateInstance failed");
        return false;
    }

    const nrd::InstanceDesc* instanceDesc = nrd::GetInstanceDesc(*g_nrdInstance);

    if(instanceDesc == nullptr)
    {
        RTLog("[NRD-1 INIT] GetInstanceDesc returned null");
        destroyNRDResources();
        return false;
    }

    g_nrdInstanceDesc = *instanceDesc;

    RTLog(
        std::string("[NRD-1 INIT] version=") +
        std::to_string(g_nrdLibraryDesc.versionMajor) + "." +
        std::to_string(g_nrdLibraryDesc.versionMinor) + "." +
        std::to_string(g_nrdLibraryDesc.versionBuild) +
        " normalEncoding=" + std::to_string(static_cast<int>(g_nrdLibraryDesc.normalEncoding)) +
        " roughnessEncoding=" + std::to_string(static_cast<int>(g_nrdLibraryDesc.roughnessEncoding)) +
        " cbSpace=" + std::to_string(g_nrdInstanceDesc.constantBufferAndSamplersSpaceIndex) +
        " resSpace=" + std::to_string(g_nrdInstanceDesc.resourcesSpaceIndex) +
        " texOffset=" + std::to_string(g_nrdLibraryDesc.spirvBindingOffsets.textureOffset) +
        " storageOffset=" + std::to_string(g_nrdLibraryDesc.spirvBindingOffsets.storageTextureAndBufferOffset) +
        " samplerOffset=" + std::to_string(g_nrdLibraryDesc.spirvBindingOffsets.samplerOffset) +
        " cbOffset=" + std::to_string(g_nrdLibraryDesc.spirvBindingOffsets.constantBufferOffset) +
        " pipelines=" + std::to_string(g_nrdInstanceDesc.pipelinesNum) +
        " permanent=" + std::to_string(g_nrdInstanceDesc.permanentPoolSize) +
        " transient=" + std::to_string(g_nrdInstanceDesc.transientPoolSize) +
        " cbSize=" + std::to_string(g_nrdInstanceDesc.constantBufferMaxDataSize) +
        " perSetTextures=" + std::to_string(g_nrdInstanceDesc.descriptorPoolDesc.perSetTexturesMaxNum) +
        " perSetStorages=" + std::to_string(g_nrdInstanceDesc.descriptorPoolDesc.perSetStorageTexturesMaxNum) +
        " size=" + std::to_string(width) + "x" + std::to_string(height)
    );

    // The space indices are part of the compiled-in layout; if a future NRD
    // build moved them, everything below would be wrong, so fail loudly.
    if(g_nrdInstanceDesc.constantBufferAndSamplersSpaceIndex != 1u ||
       g_nrdInstanceDesc.resourcesSpaceIndex != 0u)
    {
        RTLog("[NRD-1 INIT] unexpected register spaces, refusing to build a mismatched layout");
        destroyNRDResources();
        return false;
    }

    if(g_nrdInstanceDesc.descriptorPoolDesc.perSetStorageTexturesMaxNum == 0u ||
       g_nrdInstanceDesc.descriptorPoolDesc.perSetTexturesMaxNum == 0u)
    {
        RTLog("[NRD-1 INIT] empty descriptor pool description");
        destroyNRDResources();
        return false;
    }

    g_nrdSamplerNearest = nrdCreateImmutableSampler(false, "NEAREST_CLAMP");
    g_nrdSamplerLinear = nrdCreateImmutableSampler(true, "LINEAR_CLAMP");

    if(g_nrdSamplerNearest == VK_NULL_HANDLE || g_nrdSamplerLinear == VK_NULL_HANDLE)
    {
        destroyNRDResources();
        return false;
    }

    if(!createNRDDescriptorSetLayout() ||
       !createNRDConstantBuffer() ||
       !createNRDDescriptorSet() ||
       !createNRDPoolTextures() ||
       !createNRDPipelines() ||
       !createNRDAppTextures() ||
       !updateNRDDescriptors())
    {
        destroyNRDResources();
        return false;
    }

    // Every image above now exists; move them out of UNDEFINED before the first
    // frame can describe them as GENERAL.
    nrdTransitionImagesToGeneral();

    // createNRDCompositePipeline reports failure by throwing, so it cannot join
    // the boolean chain above.
    try
    {
        createNRDCompositePipeline();
    }
    catch(...)
    {
        RTLog("[NRD-1 INIT] composite pipeline creation threw");
        destroyNRDResources();
        return false;
    }

    g_nrdFrameIndex = 0u;
    g_nrdNeedsHistoryReset = true;
    g_nrdReady = true;

    RTLog("[NRD-1 INIT] REBLUR_DIFFUSE ready");

    return true;
}

// Called once per frame before the RT pass, so a render-resolution change is
// picked up in the same place the DLSS/RR guide images are resized.
static void ensureNRDResources(uint32_t width, uint32_t height)
{
    // =====================================================
    // 2026-09-26 本地光全灭修复（总开关，改回 true 即恢复 NRD 实验）。
    //
    // 证据链（rt_nrd_composite.comp 里的三分屏探针，2026-09-26）：
    //   M >= 16（reservoir 样本在）、RayGen 交下来的原始本地光项非零，
    //   但 composite 加进画面的项恒等于 0。
    // 反照率打包/传递/解包约定在 rgen -> spatial -> final -> composite 四处
    // 与老的 rt_restir_reconstruct.comp 完全一致（老链路能亮），所以清零
    // 乘数锁定为 NRD REBLUR_DIFFUSE 的输出：NRD-1 这套集成喂给 REBLUR 的
    // 引导输入（viewZ 口径今晚还从径向距离改成 clip.w、motion/reprojection
    // 缺失）没对齐，REBLUR 输出 0，composite 原样信任它。
    //
    // 在 NRD 的输入接口修好之前，整体旁路：g_nrdReady 保持 false，
    //   * rt_restir_final.rgen 的三个 NRD 输入照常写（无害）；
    //   * 34304 行的 !g_nrdReady 门控让老的 rt_restir_reconstruct.comp
    //     5/9/13-tap 时域滤波重新接管本地光降噪（09-25 收尾之十三
    //     验证过的已知良好状态）；
    //   * composite pass 不再 dispatch。
    // =====================================================
    // 2026-09-26 深夜：REBLUR -> RELAX_DIFFUSE 切换（NVIDIA 官方为 RTXDI 直射
    // 光设计的家族），打包约定同步改（原始 hitDist、无 YCoCg、radiance clamp
    // 250），NRD 链重新启用。旁路回退：改回 false 即退回 reconstruct 时域链。
    // 2026-09-27 20:2x 终裁：本地光链
    // 没有降噪器——确定性辐射不进 denoiser。实测 RELAX 把 0.16-0.32 的健康
    // 输入衰减到 ~0.06（本地光不亮的直接根因），shader 侧已停消费/停喂 NRD
    // （RESTIR_DI_CONSUME_RELAX / RESTIR_DI_FEED_NRD，均可用 -D 逐字节回滚）。
    // C++ 侧同步旁路：g_nrdReady=false，reconstruct 5/9/13-tap 时域滤波接管，
    // composite 停发。NRD 集成代码原地保留，改回 true 可整体恢复。
    // 2026-09-27 晚：恢复 NRD（REBLUR_DIFFUSE）。上一版把整个 NRD 从本地光链上
    // 摘掉，理由是"本地光链没有降噪器"。那句只对链条本身成立——降噪器
    // 其实在下游（indirect.rgen.slang:16 "temporal convergence is the
    // denoiser's job"，guides.slang:277 "consumed by the denoiser/DLSS-RR"），
    // 它的 RIS 之所以是单帧不复用 reservoir，正是因为 DLSS-RR 在最后做时域收敛。
    // 而在本项目里 DLSS-RR 已被实测证明去噪不了这个 1spp 时间不相干信号
    // （rrMode 四档全试过无变化）——那正是引入 NRD 的原因。摘掉 NRD 的结果就是
    // 1spp 原始项直接上屏，即"很强烈的噪点"。
    // 同时 RELAX -> REBLUR：RELAX 实测把 0.16-0.32 的健康输入衰减到 ~0.06，
    // 且 NRD 官方对它的定位是"极干净的高 RPP 信号 / RTXDI"，不是我们的 1spp。
    // 回滚：改回 false 即整体退回 reconstruct 5/9/13-tap 时域链。
    // =====================================================================
    // ★★ 实验已结束（2026-09-27 22:11 那次运行）：关掉后画面「明显更噪」，
    // 所以 NRD 确实在做实事，问题不在"降噪器没生效"，而在"降噪强度不够"。
 // 已改回 true，并按实验预注册的分支执行 D，
    // 见下方 nrdBuildReblurSettings。下面这段判读说明保留作为记录。 ★★
    //
    // 设为 false 的后果（已逐处核对门控）：
    //   * ensureNRDResources 立刻返回 -> NRD 实例从不创建 -> g_nrdReady 恒为 false
    //   * 34355 行的 `executeReSTIRDIReconstruct && !g_nrdReady` 让**老的
    //     rt_restir_reconstruct.comp（5/9/13-tap 时域滤波）**重新接管本地光降噪
    //   * 34476 行的 `if(g_nrdReady)` 让 NRD composite 不再 dispatch
    //
    // 所以这是一次 NRD 与老手写滤波的对照：两者都降噪，看哪一个真的在起作用。
    //
    // 判读方法（一次启动即可）：
    //   关掉后明显更噪   -> NRD 确实在做实事 -> 问题在降噪器不足 -> 下一步走 D
    //                        （开 anti-firefly、开 5x5 hit-distance 重建、
    //                          把累积窗口从 23 帧提到 ~60）
    //   关掉前后几乎一样 -> NRD 没起作用 -> 问题在估计量方差本身 ->
    //                        下一步走 C（候选数 4 -> 32）
    //
    // 回滚：把本行改回 true 即完整恢复（NRD 集成代码原地保留，未删任何东西）。
    // =====================================================================
    constexpr bool NRD_LOCAL_DI_ENABLED = true;
    if(!NRD_LOCAL_DI_ENABLED)
    {
        return;
    }

    if(width == 0u || height == 0u)
    {
        return;
    }

    if(g_nrdReady && width == g_nrdWidth && height == g_nrdHeight)
    {
        return;
    }

    if(g_nrdReady || g_nrdInstance != nullptr)
    {
        RTLog(
            std::string("[NRD-1 RESIZE] ") + std::to_string(g_nrdWidth) + "x" +
            std::to_string(g_nrdHeight) + " -> " + std::to_string(width) + "x" +
            std::to_string(height)
        );

        check(
            FGDeviceWaitIdle(g_device),
            "wait device before NRD resize failed"
        );

        destroyNRDResources();
    }

    createNRDResources(width, height);
}

static void createNRDCompositePipeline()
{
    if(g_nrdCompositePipeline != VK_NULL_HANDLE)
    {
        return;
    }

    const std::vector<uint8_t> code =
        loadSpv("shaders/rt_nrd_composite.comp.spv");

    VkShaderModule shaderModule = createShaderModule(g_device, code);

    try
    {
        VkPushConstantRange pushRange{};
        pushRange.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        pushRange.offset = 0u;
        pushRange.size = sizeof(NRDCompositePushConstants);

        VkPipelineLayoutCreateInfo layoutInfo{
            VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO
        };
        layoutInfo.setLayoutCount = 1u;
        layoutInfo.pSetLayouts = &g_rayTracingDescriptorSetLayout;
        layoutInfo.pushConstantRangeCount = 1u;
        layoutInfo.pPushConstantRanges = &pushRange;

        check(
            vkCreatePipelineLayout(
                g_device,
                &layoutInfo,
                nullptr,
                &g_nrdCompositePipelineLayout
            ),
            "NRD composite pipeline layout failed"
        );

        VkPipelineShaderStageCreateInfo stage{
            VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO
        };
        stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
        stage.module = shaderModule;
        stage.pName = "main";

        VkComputePipelineCreateInfo pipelineInfo{
            VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO
        };
        pipelineInfo.stage = stage;
        pipelineInfo.layout = g_nrdCompositePipelineLayout;

        check(
            vkCreateComputePipelines(
                g_device,
                getSharedPipelineCache(),
                1u,
                &pipelineInfo,
                nullptr,
                &g_nrdCompositePipeline
            ),
            "NRD composite compute pipeline failed"
        );
    }
    catch(...)
    {
        if(g_nrdCompositePipelineLayout != VK_NULL_HANDLE)
        {
            vkDestroyPipelineLayout(
                g_device,
                g_nrdCompositePipelineLayout,
                nullptr
            );
            g_nrdCompositePipelineLayout = VK_NULL_HANDLE;
        }

        vkDestroyShaderModule(g_device, shaderModule, nullptr);
        throw;
    }

    vkDestroyShaderModule(g_device, shaderModule, nullptr);
    RTLog("[NRD-1] local DI composite pipeline created");
}

static void destroyNRDCompositePipeline()
{
    if(g_nrdCompositePipeline != VK_NULL_HANDLE)
    {
        vkDestroyPipeline(g_device, g_nrdCompositePipeline, nullptr);
        g_nrdCompositePipeline = VK_NULL_HANDLE;
    }

    if(g_nrdCompositePipelineLayout != VK_NULL_HANDLE)
    {
        vkDestroyPipelineLayout(
            g_device,
            g_nrdCompositePipelineLayout,
            nullptr
        );
        g_nrdCompositePipelineLayout = VK_NULL_HANDLE;
    }
}

// Camera-space matrices for NRD.  NRD requires NON-jittered matrices and takes
// the jitter separately (NRD README, "OTHER"), which is exactly how this
// backend already treats them: CameraUBO::viewInverse / projInverse come from
// JOML un-jittered, and the DLSS jitter is a separate Halton offset in
// [-0.5; 0.5] produced by GetDLSSFrameJitter.
//
// Streamline's float4x4 stores rows in memory ("m[row][col]"), while NRD wants
// "vector is a column, layout is column-major", so the matrices are transposed
// on the way out.
static void nrdFillColumnMajor(const sl::float4x4& m, float out[16])
{
    // sl::float4 has no operator[], so the four components are taken by name.
    for(uint32_t row = 0u; row < 4u; ++row)
    {
        const sl::float4 r = m[row];

        out[0u * 4u + row] = r.x;
        out[1u * 4u + row] = r.y;
        out[2u * 4u + row] = r.z;
        out[3u * 4u + row] = r.w;
    }
}

static void nrdBuildCommonSettings(
    nrd::CommonSettings& settings,
    uint32_t width,
    uint32_t height)
{
    settings = {};

    float currentJitterX = 0.0f;
    float currentJitterY = 0.0f;
    float previousJitterX = 0.0f;
    float previousJitterY = 0.0f;

    uint32_t jitterFrame = g_nrdFrameIndex;

    if(g_cameraUboMapped != nullptr)
    {
        const CameraUBO* cameraUbo =
            static_cast<const CameraUBO*>(g_cameraUboMapped);

        sl::float4x4 currentViewToWorld =
            JOMLColumnMajorToSLRowMajor(cameraUbo->viewInverse);

        sl::float4x4 previousViewToWorld =
            JOMLColumnMajorToSLRowMajor(cameraUbo->prevViewInverse);

        sl::float4x4 currentClipToView =
            JOMLColumnMajorToSLRowMajor(cameraUbo->projInverse);

        sl::float4x4 previousClipToView =
            JOMLColumnMajorToSLRowMajor(cameraUbo->prevProjInverse);

        sl::float4x4 currentViewToClip{};
        sl::float4x4 previousViewToClip{};
        sl::float4x4 currentWorldToView{};

        sl::matrixFullInvert(currentViewToClip, currentClipToView);
        sl::matrixFullInvert(previousViewToClip, previousClipToView);
        sl::matrixFullInvert(currentWorldToView, currentViewToWorld);

        nrdFillColumnMajor(currentViewToClip, settings.viewToClipMatrix);
        nrdFillColumnMajor(previousViewToClip, settings.viewToClipMatrixPrev);
        nrdFillColumnMajor(currentWorldToView, settings.worldToViewMatrix);

        sl::float4x4 previousWorldToView{};
        sl::matrixFullInvert(previousWorldToView, previousViewToWorld);
        nrdFillColumnMajor(previousWorldToView, settings.worldToViewMatrixPrev);

        previousJitterX = cameraUbo->historyPrevJitterX;
        previousJitterY = cameraUbo->historyPrevJitterY;
        jitterFrame = cameraUbo->frameCount;
    }

    GetDLSSFrameJitter(jitterFrame, currentJitterX, currentJitterY);

    settings.cameraJitter[0] = currentJitterX;
    settings.cameraJitter[1] = currentJitterY;
    settings.cameraJitterPrev[0] = previousJitterX;
    settings.cameraJitterPrev[1] = previousJitterY;

#if NRD_USE_REAL_MOTION_VECTORS
    // 真实屏幕空间 MV：mv.xy = prevUv − curUv，单位为 UV。
    // ⚠️ 2026-09-30：写 IN_MV 的 rt_restir_final.rgen 已删除，且本函数只在被
    //    kNrdLocalDiEnabled=false 关停的 recordNRDLocalDenoiser 里调用 ⇒ **本段现在
    //    对画面没有任何影响**，保留只为将来重建链路时有现成口径。
    // NRD 契约（NRDSettings.h）：isMotionVectorInWorldSpace=false 且 motionVectorScale[2]==0。
    settings.motionVectorScale[0] = 1.0f;
    settings.motionVectorScale[1] = 1.0f;
    // 2D（0.0）vs 2.5D。
    // mv.xy 是 UV 单位，所以 xy 的 scale 保持 1.0；z 是「线性视深差」，同样是 1.0 直接用。
    // ⚠️ 2026-09-30：2D/2.5D 现在不可分辨 —— mv.z 的唯一写入者（rt_restir_final.rgen）
    //    已删除，IN_MV 的 z 恒为 0，两档给出同样的结果。
    settings.motionVectorScale[2] =
        NRD_USE_25D_MOTION_VECTORS ? 1.0f : 0.0f;
    // ★★★ 2026-09-29 一度判为根因：motionVectorBias 必须补偿相机抖动，不能是 0。
    //
    // ⚠️ 该判断**已被推翻**，不要据它重开开关。同段末尾（"2026-09-29 实测结论"起）
    //    与 HANDOFF-2026-09-29-RT-DI-NRD.md §3 第 5 条都记着结论：raw mv 本身已经
    //    是"非抖动"的（README:435 的要求就是 "must be non-jittered after scaling and
    //    bias"），再加 bias 等于把抖动量重新加回去；实测加与不加画面无变化。
    //    下面这一大段推导保留为历史记录。
    //
    // 此前写的是「两个 UV 都取自不含 jitter 的投影矩阵，MV 本身已经非抖动，所以 bias = 0」。
    // 那句话对 **mv 的差值**成立，但对 **smbPixelUv 的落点**不成立，二者是两件事：
    //
    //   rgen 侧：mv = prevUv(P) − curUv(P)，其中 curUv(P) 是**抖动后**像素中心 P 的投影
    //            （P 由抖动后的主射线命中点反解，见 rt_restir_final.rgen 的
    //             nrdGeometryViewPos / primaryPixelCenter）。
    //   NRD 侧：smbPixelUv = pixelUv + mv + bias，pixelUv 是**未抖动**像素中心。
    //
    // 于是（把上面两式相减）：
    //   smbPixelUv = prevUv(P) − jitter_cur + bias
    // 而「上一帧存在像素 u 处的 IN_VIEWZ」的物理含义是：
    //   非抖动 uv 为 u + jitter_prev 的那个点的深度。
    // 要让 NRD 采到 **P 自己** 的上一帧深度，必须内层对齐：
    //   smbPixelUv + jitter_prev = pixelUv + jitter_cur
    //   ⇒ bias = jitter_cur − jitter_prev        （像素换算成 UV：/ renderSize）
    //
    // 为什么这个 0.25~0.5px 的残差是致命的：
    //   NRD 的拒史深度门是 |prevViewZ_tap − Xvprev.z| ≤ 0.01 * frustumSize
    //   （REBLUR_TemporalAccumulation.cs.hlsl:259-267 / Common.hlsli:585），
    //   3 格处约 0.04 格。而方块世界里每个方块边界都是一次深度跳变，复投影落点偏
    //   半个像素就足以让它落到另一个方块面上 ⇒ 四个 tap 全判遮挡 ⇒
    //   smbFootprintQuality = 0 ⇒ c = min(smbFootprintQuality, IN_DIFF_CONFIDENCE) = 0
    //   ⇒ 历史上据此推得"累积停在 (1+√5)/2 ≈ 1.618 帧不动点"。
    //      ⚠️ **该模型已被证伪**：四 tap 全拒时 A 不是"小"而是**恰好 0**
    //      （ApplyBilinearCustomWeights 的 dot(w,1)<1e-4 硬分支返回 0），
    //      对应的是 **0 帧**。见 HANDOFF-2026-09-29-RT-DI-NRD.md §11.3 / §11.9。
    //
    // 静止时为什么看不出来：主机位不动 ⇒ mv = 0，且 jitter 逐帧仍在变，但
    //   prevViewZ_tap 与 viewZ 在同一像素上自洽 ⇒ 门恒过 ⇒ 累积到 63 帧（白）。
    //   而一旦移动，smbPixelUv 才真正离开本位，残差才暴露。
    //
    // 为什么以前每一刀都「有反应、没治好」：
    //   * confidence 钉成 1（FORCE_ONE=1）无效 —— min() 的另一支 smbFootprintQuality 才是 0
    //   * disocclusionThreshold 放到 0.5 无效 —— 那次是在 mv.z 符号仍错的构建上做的，
    //     误差是「整格量级」，任何阈值都吸不掉，所以那一轮证据无效
    //   * 几何口径（IN_VIEWZ/法线/MV 的来源）改动无效 —— 残差在落点上，不在来源上
    //
    // 单位口径（已核对 NRD 源码）：mv 与 gMvBias 是 **UV**；cameraJitter 是 **像素**
    //   （REBLUR_Validation.cs.hlsl:151 先 * gRectSize 再与 gJitter 比较）。
    //   宿主传入的 currentJitterX/Y 正是像素单位、且与主射线/本 pass 用的是同一个
    //   GetDLSSFrameJitter(cam.frameCount)，所以这里只需 / renderSize。
    //
    // ★★ 2026-09-29 实测结论：这个 bias **是错的，已置 0**。
    //
    // 加它的推导是「smbPixelUv 差了一个 (jitter_cur − jitter_prev)」，但按 NRD README:564-567
    // 对视口 3 的定义重新推一遍就发现前提错了：
    //   视口 3 的期望 MV = 「假定场景静止、对该像素按**未抖动**重建算出的 MV」
    //   desired = prevUv(Q) − pixelUv        （Q = 该像素中心射线上的点）
    //   我们写的 raw mv = prevUv(P) − project_cur(P) = prevUv(P) − pixelUv − jitter_cur
    //   而 prevUv(Q) ≈ prevUv(P) − jitter_cur（一阶：屏幕位移在小量下近似不变）
    //   ⇒ desired = raw mv                         ← 两者相等
    // 也就是说 **raw mv 本身已经是「非抖动」的**（README:435 的原文要求就是
    // "must be non-jittered after scaling and bias"），再加 bias 等于把抖动量重新加回去。
    // 实测也印证：加上去之后转视角仍 1-2 帧，没有任何变化。
    //
    // 保留这段代码只为可复现：需要复现时可加 -DNRD_MV_JITTER_BIAS=1。
#ifndef NRD_MV_JITTER_BIAS
#define NRD_MV_JITTER_BIAS 0
#endif
#if NRD_MV_JITTER_BIAS
    settings.motionVectorBias[0] =
        (currentJitterX - previousJitterX) /
        std::max(1.0f, static_cast<float>(width));
    settings.motionVectorBias[1] =
        (currentJitterY - previousJitterY) /
        std::max(1.0f, static_cast<float>(height));
#else
    settings.motionVectorBias[0] = 0.0f;
    settings.motionVectorBias[1] = 0.0f;
#endif
    settings.motionVectorBias[2] = 0.0f;
    settings.isMotionVectorInWorldSpace = false;
#else
    // 退役（2026-09-30）：自跟踪档（scale={0,0,0} + worldSpace=true）**已被 2026-09-29
    // 实测否决** —— gMvScale.xy ≡ 0 ⇒ REBLUR_TemporalAccumulation 的 smbPixelUv ≡ pixelUv
    // ⇒ 零重投影（NRD README:874 亦自述该档是"首次集成用的简化档"）；且它依赖的
    // IN_MV 写入者已随 ReSTIR 链删除。
    // 外层套 #if 0：-DNRD_USE_REAL_MOTION_VECTORS=0 **也打不开**它（该档下 settings 保持
    // NRD 默认 motionVectorScale={1,1,0}），原文完整保留在下面以备将来复现论证。
#if 0
    // 旧行为：全零 MV，让 NRD 内部跟踪相机运动（NRD README, "OTHER"）。
    settings.motionVectorScale[0] = 0.0f;
    settings.motionVectorScale[1] = 0.0f;
    settings.motionVectorScale[2] = 0.0f;
    settings.motionVectorBias[0] = 0.0f;
    settings.motionVectorBias[1] = 0.0f;
    settings.motionVectorBias[2] = 0.0f;
    settings.isMotionVectorInWorldSpace = true;
#endif
#endif

    // 一次性日志：把实际生效的 MV 参数和「上一帧矩阵来源」打出来，便于回读验证。
    // 上一帧矩阵来源是 CameraUBO.prevViewInverse / prevProjInverse（见本函数开头），
    // shader 侧用同一对矩阵把 hitPos 重投影成上一帧 UV。
    // ★★★ 2026-09-29：原来这条日志在**首帧**就打，而首帧的 historyValid 天然为 0
    //     （frameCount 也是 0），读不出运行态 —— 这也是本轮之前一直没能从日志里
    //     发现「MV 从未被写出」的原因。改为跑到第 ~120 帧后再打一次，此时打印的
    //     historyValid / frameCount 才是稳态值，可直接验证 MV 是否真的在写。
    static bool mvSettingsLogged = false;

    const CameraUBO* mvLogProbe = g_cameraUboMapped != nullptr
        ? static_cast<const CameraUBO*>(g_cameraUboMapped)
        : nullptr;

    const bool mvLogReady =
        mvLogProbe != nullptr && mvLogProbe->frameCount >= 120u;

    if(!mvSettingsLogged && mvLogReady)
    {
        mvSettingsLogged = true;

        const CameraUBO* mvUbo = g_cameraUboMapped != nullptr
            ? static_cast<const CameraUBO*>(g_cameraUboMapped)
            : nullptr;

        RTLog(
            std::string("[NRD-1 MV] motionVectorScale=(") +
            std::to_string(settings.motionVectorScale[0]) + "," +
            std::to_string(settings.motionVectorScale[1]) + "," +
            std::to_string(settings.motionVectorScale[2]) + ")" +
            " isMotionVectorInWorldSpace=" +
            (settings.isMotionVectorInWorldSpace ? "1" : "0") +
            " jitter=(" + std::to_string(currentJitterX) + "," +
            std::to_string(currentJitterY) + ")" +
            " jitterPrev=(" + std::to_string(previousJitterX) + "," +
            std::to_string(previousJitterY) + ")" +
            " mvBias=(" + std::to_string(settings.motionVectorBias[0]) + "," +
            std::to_string(settings.motionVectorBias[1]) + ")" +
            " prevMatrix=CameraUBO.prevViewInverse/prevProjInverse(historyValid=" +
            std::to_string(mvUbo != nullptr ? mvUbo->historyValid : 0u) +
            ",frameCount=" +
            std::to_string(mvUbo != nullptr ? mvUbo->frameCount : 0u) + ")"
        );
    }

    // ★ 2026-09-29 第二步：history confidence（NRD 的"外部提示"，官方标注
    // optional but highly recommended）。
    //
    // 依据：NRD README 说明该类时空降噪器"对光照突变反应迟钝"，confidence 用来告诉
    // 它"哪里变了、历史该重置"，REBLUR 的用法是
    //   historyLength *= lerp( confidence, 1, 1 / ( 1 + historyLength ) )；
    // 有了它才敢把累积窗口提到 60 帧（README 原文）。
    //
    // 开关条件写在"本帧 confidence 视图是否可用"上：shader 缺失/管线失败时自动退回
    // 无 confidence 的旧行为，而不是让 NRD 因资源未解析整帧不跑。
    // 关闭：编译期 -DNRD_LOCAL_DI_CONFIDENCE=0。
#if NRD_LOCAL_DI_CONFIDENCE
    settings.isHistoryConfidenceAvailable =
        g_nrdConfidenceViewThisFrame != VK_NULL_HANDLE;
#else
    settings.isHistoryConfidenceAvailable = false;
#endif

    settings.resourceSize[0] = static_cast<uint16_t>(width);
    settings.resourceSize[1] = static_cast<uint16_t>(height);
    settings.resourceSizePrev[0] = static_cast<uint16_t>(width);
    settings.resourceSizePrev[1] = static_cast<uint16_t>(height);
    settings.rectSize[0] = static_cast<uint16_t>(width);
    settings.rectSize[1] = static_cast<uint16_t>(height);
    settings.rectSizePrev[0] = static_cast<uint16_t>(width);
    settings.rectSizePrev[1] = static_cast<uint16_t>(height);

    settings.viewZScale = 1.0f;
    settings.frameIndex = g_nrdFrameIndex;

    settings.accumulationMode = g_nrdNeedsHistoryReset
        ? nrd::AccumulationMode::CLEAR_AND_RESTART
        : nrd::AccumulationMode::CONTINUE;

    // Nothing inside the render distance should be skipped: local lights only
    // reach ~30 blocks, so 60000 is far beyond anything that can be lit.  Sky
    // and invalid receivers are marked by writing a viewZ of 65504 (the largest
    // finite half float, see rt_restir_final.rgen) in IN_VIEWZ, which is above
    // this range and therefore skipped by NRD automatically.  The two numbers
    // are a pair: the marker has to survive the R16f store, so it cannot simply
    // be "some huge number".
    settings.denoisingRange = 60000.0f;

    // ★ 2026-09-28 实测结论：**这道闸门与此故障无关，已改回生产值 0.01。**
    //
    // 做过的事：把阈值从 0.01 放到 0.5（50 倍）后重跑，日志确认生效
    // （`[NRD-1 DISOC] threshold=0.500000`），用户报告"大幅度移动视角时橙色棋盘照旧"。
    // 而且这是**过强的一次**测试，不只是放大 50 倍：GetDisocclusionThreshold
    // （Common.hlsli:585）= `frustumSize * saturate( threshold / max(0.05, NoV) )`，
    // 里层有 saturate()，阈值 0.5 时只要 NoV < 0.5（绝大多数斜视墙面/地面）比值就 ≥ 1，
    // 被夹到上限 frustumSize —— 等于直接测了天花板都没有变化。
    //
    // 同时排掉的还有法线闸门：REBLUR_ALMOST_ZERO_ANGLE = cos(89°) ≈ 0.017
    // （REBLUR_Config.hlsli:101），要两根法线几乎垂直才会失败，不可能成为瓶颈。
    //
    // 真正常开的开关在这里：antilag（REBLUR_TemporalStabilization.cs.hlsl:157-160）
    //   diffAntilag = ComputeAntilag(historyLuma, currentLuma, sigma, ...)
    //   data1.x = lerp( min(data1.x, gHistoryFixFrameNum), data1.x, diffAntilag )
    // REBLUR_USE_ANTILAG_NOT_INVOKING_HISTORY_FIX = 1（REBLUR_Config.hlsli:39），
    // 所以那个 min() **只会封顶、永远不会加分**：一旦 antilag 在第 N 帧落到 0，
    // 累积计数就停在重置后的低值上再也长不起来 —— 这既解释了"全屏橙"，
    // 也解释了棋盘（data1.x 一直在 1 以下）。我上一轮说"棋盘出现即证明不是
    // antilag"是错的，已修正。
    // ★★★ 2026-09-29 15:0x：恢复环境变量覆盖（注释里早就写着"可由环境变量覆盖"，但代码里
    // 只剩常量，覆盖其实已经没了）。
    //
    // 为什么现在要它：转动录像 + validation 宫格定案——**视口 3（我们的 MV vs NRD 期望 MV）
    // 在纯转动段几乎全黑（99.3% / 96.3% / 99.8%）= MV 没错**，但视口 8（图例标定后）显示历史
    // 随转动从 60 帧一路掉到 10~30 帧。读 REBLUR_TemporalAccumulation.cs.hlsl:238-267 后，
    // 运动时只剩一处会收紧：`NoVstrict = lerp(NoV, 1.0, saturate(parallax/30))` 让
    //   smbDisocclusionThreshold = disocclusionThreshold * frustumSize * saturate(1/NoVstrict)
    // 从静止斜视时的最多 20 倍宽容（NoV<0.05 → saturate(0.01/0.05)=0.2）**退回基准 0.01×frustumSize**
    // （3 格处≈0.04 格）。平面距离判据 `|prevViewZ_tap − (worldToViewPrev*Xprev).z| < 阈值` 里，
    // 两者的差就是"上一帧存储视深 vs 我们预期视深"，容差越紧越容易被亚像素落点/位置量化吃掉。
    //
    // 用法（**免重编**，改完重启即可）：
    //   set RTX_NRD_DISOCCLUSION_THRESHOLD=0.05   （官方的 alternate 量级；0.1 更激进）
    // 判读：顶部历史色带在**转动时**是否保持青/白；画面噪点是否随之下降。
    // 注意 NRD 内部还有一层 `saturate(threshold/max(0.05,NoV))`，所以 >0.25 之后基本饱和，
    // 09-28 那次"放到 0.5 无变化"就是测到了天花板——**有效的对比区间是 0.01 → 0.05 → 0.1**。
    float disocclusionThresholdValue = 0.01f;

    {
        const char* envThreshold = std::getenv("RTX_NRD_DISOCCLUSION_THRESHOLD");

        if(envThreshold != nullptr && envThreshold[0] != '\0')
        {
            const float parsed = static_cast<float>(std::atof(envThreshold));

            if(parsed > 0.0f)
            {
                disocclusionThresholdValue = parsed;
            }
        }
    }

    settings.disocclusionThreshold = disocclusionThresholdValue;
    // ★ 2026-09-29 第 2 项：alternate 倍数 5x -> 2x。
    //
    // Radiance 取 disocclusionThreshold = 0.01f / alternate = 0.02f（即 2x）。
    // 注意本项**当前是惰性**的：alternate 只在与 IN_DISOCCLUSION_THRESHOLD_MIX 混合时
    // 才被用到（REBLUR_TemporalAccumulation.cs.hlsl:234），而
    //   * isDisocclusionThresholdMixAvailable 仍是 false，且
    //   * strandMaterialID 走的是默认值 999，永远撞不上（materialID 由 R10G10B10A2 的
    //     alpha 给出，只可能是 {0,85,170,255}）
    // ⇒ `disocclusionThreshold ≡ gDisocclusionThreshold`。改倍数只为口径一致。
    settings.disocclusionThresholdAlternate = disocclusionThresholdValue * 2.0f;

    if(!g_nrdDisocclusionLogged)
    {
        g_nrdDisocclusionLogged = true;

        RTLog(
            std::string("[NRD-1 DISOC] threshold=") +
            std::to_string(settings.disocclusionThreshold) +
            " alternate=" + std::to_string(settings.disocclusionThresholdAlternate)
        );
    }

    // Both optional inputs are left off for the first integration; NRD's
    // internal tracking covers them, and inventing a confidence signal would
    // add a second untested input to the bring-up.
    //
    // ★★ 2026-09-29 14:5x：这里原本还有一句无条件的
    //      settings.isHistoryConfidenceAvailable = false;
    //    它把本函数**前面**按"本帧 confidence 视图是否可用"算出来的值覆盖掉了
    //    ⇒ confidence 一路带过来却从未被 NRD 消费（与当年 enableValidation 被后面
    //    一句覆盖是同一个坑——同一个函数里 `settings = {}` 之后的赋值必须查重）。
    //    证据链：validation 视口 8（DIFF FRAMES）图例标定后实测**历史只停 6~16 帧**
    //    （满量程 63，官方口径要求停在"紫区"），而宿主日志一直打印 confidence 链
    //    "resources created/pipeline created"，两边只有这条覆盖能解释。
    settings.isDisocclusionThresholdMixAvailable = false;

    // 2026-09-28：打开 NRD 自带的调试层，让 NRD 自己说明"历史为什么被拒"，而不是
    // 继续在外面猜。写进 OUT_VALIDATION（视口布局与判读方法见 g_nrdValidationImage
    // 的注释）。OUT_VALIDATION 纹理和 NRD 侧的 OUT_VALIDATION 描述符都已就位，
    // 所以这里置 true 是唯一需要做的事。
    //
    // ★ 这里原本是一句无条件的 `settings.enableValidation = false;`。第一次接线的
    // 时候我把 true 写在了函数中段，被这一句在后面覆盖掉，结果 OUT_VALIDATION 全是
    // 0、屏幕整片全黑——"调试层没生效"和"NRD 什么都没画"在画面上长得一模一样。
    // 教训：这个函数里任何 `settings = {}` 之后的赋值都要检查有没有重复赋值。
    //
    // 代价：多一个全分辨率 RGBA8 写 + 一个 dispatch；只在定位期间打开，定位结束
    // 后把 NRD_LOCAL_DI_VALIDATION 设为 0 重编即可（Validation pass 就不执行了）。
#if NRD_LOCAL_DI_VALIDATION
    settings.enableValidation = true;
#else
    settings.enableValidation = false;
#endif
}

// NRD-1 lag tuning (2026-09-24, second pass).  The first integration removed the
// local-light noise but left a visible after-image under motion.  The cause is
// temporal lag, and the two dials below are the ones NRD provides for it.  Both
// push the same way, so this build is a single yes/no test: if the after-image
// drops, lag was the cause and these get fine-tuned; if it does not move at all,
// the cause is reprojection instead and no amount of window tuning will help.
//
//   maxAccumulatedFrameNum - the slow "main" history.  NRD's default period is
//     0.5 s, which at 60 FPS is ~30 frames.  The pass this replaced used ~50
//     frames when static but only ~8 when the camera moved, so 30 is already
//     shorter statically; the problem is that nothing shortened it under motion.
//     0.35 s (~21 frames at 60 FPS) trims the worst of it while staying
//     FPS-independent, which is the whole point of expressing it in seconds.
//
//   fastHistoryClampingSigmaScale - the actual lag control, and the CHEAP one.
//     REBLUR clamps the spatially processed slow history to a colour box built
//     from the responsive 6-frame fast history; a smaller sigma is a tighter
//     box, so the result tracks the fast history (less lag) instead of the slow
//     one.  NRD's default is 2.0, valid range [1; 3].
//
//     Why this knob and not the window: the two are NOT symmetric in cost.
//     Lowering maxAccumulatedFrameNum removes lag and averaging together, so it
//     buys lag with noise.  Lowering the sigma only limits how far the output
//     may deviate from the fast history; when the scene is static the slow
//     history is still free to accumulate, so the averaging is kept.  It is the
//     free lever, so the second tuning step pushes ONLY this one.
//
// Second step (2026-09-24, after the user confirmed the after-image was
// "clearly reduced" at 1.5/0.35 s and that the noise had NOT come back): sigma
// 1.5 -> 1.1 with the window left alone.  1.1 is the bottom of NRD's documented
// useful range ("1.5 works well even for dirty signals, 1.1 is a safe value for
// occlusion denoising"), so this step deliberately aims at the noise wall: if
// noise returns here, the answer is a sigma between 1.1 and 1.5 and it is found
// by bisection; if it does not, the after-image is gone for free.
// NRD-1 lag tuning (carried over from the REBLUR bring-up).  RELAX exposes the
// same two families of dials, under diffuse*/specular* names (RELAX_DIFFUSE
// only reads the diffuse ones):
//
//   diffuseMaxAccumulatedFrameNum - the slow "main" history.  NRD's default is
//     30.  The pass this replaces used ~50 frames when static but only ~8 under
//     motion, so the FPS-invariant seconds-based formula is kept:
//     maxAccumulatedFrameNum = accumulationPeriodInSeconds * FPS, clamped to
//     RELAX_MAX_HISTORY_FRAME_NUM (255 -- five times REBLUR's 63, so the same
//     0.35 s period is now never the binding constraint).
//
//   fastHistoryClampingSigmaScale - the lag control.  RELAX clamps the slow
//     history to a colour box built from the responsive fast history; a smaller
//     sigma is a tighter box, so the output tracks the fast history (less lag).
//     NRD's default is 2.0, and the REBLUR-era bisection landed on 1.1.
// =====================================================
// D：对齐 NRD 参数（2026-09-27，在 NRD 旁路实验证明"NRD 确实在做实事、
// 只是强度不够"之后执行）。
//
// 事实核对（避免误称"我开了什么"）：
//   * enableAntiFirefly —— REBLUR 的结构体默认值就是 **true**（NRDSettings.h:339，
//     RELAX 才是 false）。我们 `settings = {}` 已经吃到该默认值，所以这次**没有**、
//     也无法"打开"它：它本来就是开的。RELAX 阶段才短暂变成关闭状态。
//   * diffusePrepassBlurRadius / minHitDistanceWeight —— REBLUR 默认 30.0 / 0.1，
// nrd.yaml 也是 30.0 / 0.1，本来就一致。
// 所以真正有差异、也是本次要改的只有下面三项。
//
// 1) 累积窗口 0.35 s (~23 帧) -> 1.0 s (~63 帧，被 REBLUR_MAX_HISTORY_FRAME_NUM 钳住)。
// nrd.yaml 是 max_accumulated_frame_num 60。这是本次的主要杠杆：
//    降噪强度直接由累积帧数决定，噪声随 1/sqrt(N) 下降。
//
// 2) fastHistoryClampingSigmaScale 1.1 -> 1.5。
//    ★ 这一项暴露了我自己的问题：1.1 是我为了压残影特意调紧的（低滞后取向），
//    但紧钳制会**削弱累积效果** —— 输出被拉向 6 帧的快历史，慢历史的平均量吃不到。
//    也就是说"残留噪声"里有相当一部分是我当初压残影时付出的代价。
//    ★ 代价要说清：1.5 会让残影回到你此前验收过的"明显减轻"那一档，而不是
//    1.1 那一档更好的残影表现。这次选择用一点残影换降噪。
//
// 3) hitDistanceReconstructionMode OFF -> AREA_5X5。
//    注意 NRD README 说它是"主命中做漫反/镜面概率拆分时"的必需项；我们没有做拆分，
// =====================================================
static constexpr float NRD_LOCAL_DI_ACCUMULATION_SECONDS = 1.0f;
static constexpr float NRD_LOCAL_DI_FAST_HISTORY_CLAMP_SIGMA = 1.5f;
static constexpr bool NRD_LOCAL_DI_HIT_DIST_RECONSTRUCTION_5X5 = true;

static void nrdBuildReblurSettings(nrd::ReblurSettings& settings)
{
    settings = {};

    // ★ 2026-09-29 第 2 项：materialID 比较阈值 4.0 -> 0.0。
    //
    // Radiance 在 REBLUR 与 RELAX 两处都显式写 0.0f（NRD 结构体默认是 4.0f）。
    // 语义（Shaders/Common.hlsli:248）：CompareMaterials(m0,m,minm) = (max(m0,minm)==max(m,minm))，
    // minm 越大越宽容。我们的 materialID 恒为 0（rt_restir_final.rgen 把
    // IN_NORMAL_ROUGHNESS 的 alpha 写成 0.0），所以 minm=4 与 minm=0 对我们的输入
    // 回退：改回 4.0f，或直接删掉这两行（恢复 NRD 默认）。
    settings.minMaterialForDiffuse = 0.0f;
    settings.minMaterialForSpecular = 0.0f;

    // NRD recommends an FPS-dependent accumulation window:
    //   maxAccumulatedFrameNum = accumulationPeriodInSeconds * FPS
    // clamped to REBLUR_MAX_HISTORY_FRAME_NUM, with the frame time low-pass
    // filtered so a stutter does not throw the history away.
    const float smoothedFps = 1000.0f / std::max(1.0f, g_nrdSmoothedFrameTimeMs);

    settings.maxAccumulatedFrameNum = std::min<uint32_t>(
        nrd::REBLUR_MAX_HISTORY_FRAME_NUM,
        nrd::GetMaxAccumulatedFrameNum(NRD_LOCAL_DI_ACCUMULATION_SECONDS, smoothedFps)
    );

    // Keep NRD's constraint maxAccumulatedFrameNum > maxFastAccumulatedFrameNum >
    // historyFixFrameNum intact for low FPS, where the window collapses.
    settings.maxFastAccumulatedFrameNum = std::min<uint32_t>(
        settings.maxFastAccumulatedFrameNum,
        settings.maxAccumulatedFrameNum
    );

    settings.historyFixFrameNum = std::min<uint32_t>(
        settings.historyFixFrameNum,
        settings.maxFastAccumulatedFrameNum
    );

    // ★ 2026-09-29：fastHistoryClampingSigmaScale 回归 NRD 默认。
    // 官方 README：「If you are unsure of which denoiser settings to use - use defaults
    // via {} construction」，且第 2 步接入 history confidence 后，"历史该不该收紧"
    // 这件事由 confidence 承担，不再需要靠这个 sigma 去迁就 1spp 的亮度抖动。
 // 回退：取消下一行注释即恢复对齐值（1.5）。
    // settings.fastHistoryClampingSigmaScale = NRD_LOCAL_DI_FAST_HISTORY_CLAMP_SIGMA;

 // D：对齐（nrd.yaml hit_distance_reconstruction_mode = 5x5）。
    settings.hitDistanceReconstructionMode = NRD_LOCAL_DI_HIT_DIST_RECONSTRUCTION_5X5
        ? nrd::HitDistanceReconstructionMode::AREA_5X5
        : nrd::HitDistanceReconstructionMode::OFF;

 // ★ 2026-09-27 第二次应用 D：antilag 对齐。
    //
    // 触发证据：把累积窗口从 0.35s(23 帧) 提到 1.0s(63 帧) 之后，用户报告噪声
    // "几乎不变"。2.7 倍的累积窗口若不产生任何可见改善，只说明一件事——
    // **历史实际上没有在累积，一直被重置**。NRD 里唯一会持续重置历史的机制
    // 就是 antilag：它按亮度变化量决定是否收紧/丢弃历史，而我们的输入是 1spp
    // 的二值可见性，逐帧在「0」与「被照亮」之间摆动，会被它当成光照突变。
    //
    // 4.0（NRD 默认 2.0，合法范围 1.0-5.0），sensitivity 维持默认 3.0。
    // 语义（NRDSettings.h）：luminanceSigmaScale 越大，"亮度梯度被局部方差
    // 削减"的力度越大 -> antilag 对变化越不敏感 -> 越倾向于保住历史。
    // 这正是我们需要的方向。
    //
    // 代价：antilag 更不敏感意味着真正的光照突变（开关灯）反应会变慢一点。
    // ★★★ 2026-09-28 诊断：把 antilag **近似关闭**（生产值是 4.0 / 3.0，本行起为诊断态）。
    //
    // 依据（全部来自 NRD 源码，不是猜的）：
    //   REBLUR_ANTILAG_MODE = 2（REBLUR_Config.hlsli:111）时
    //     hc = Color::Clamp( a, s, h );                 // s = sigma * luminanceSigmaScale
    //     d  = abs( h - hc ) / ( max( h, hc ) + eps );   // 超出方差带的相对亮度差
    //     antilag = 1.0 / ( 1.0 + d * accumSpeed / magic );
    //     magic   = luminanceSensitivity * ( 2 * frameRateScale )^2
    //   （REBLUR_Common.hlsli:237-265）
    // 两个旋钮都朝"更宽容"方向：
    //   * luminanceSigmaScale 越大 -> 方差带 s 越宽 -> hc 越常等于 h -> d 越接近 0
    //   * luminanceSensitivity 越大 -> magic 越大 -> d*accum/magic 越小 -> antilag 越接近 1
    // 取 sigmaScale=8、sensitivity=1e4：magic 约 4e4，而 accumSpeed 最大 63，
    // 于是 d*accum/magic ≤ 63/4e4 ≈ 1.6e-3，antilag ≈ 0.998，等于关掉。
    //
    // 为什么这是决定性的：因为 REBLUR_USE_ANTILAG_NOT_INVOKING_HISTORY_FIX = 1，
    // `data1.x = lerp( min(data1.x, 3), data1.x, antilag )` 里的 min() 只会封顶、
    // 不会加分。antilag 一旦落到 0，累积计数就永远停在重置后的低值上 —— 既产生
    // "全屏橙"，也产生棋盘。所以：
    //   关掉 antilag 后视口 8 在移动时变绿/青 => antilag 就是根因，确诊
    //   仍然全橙                            => 累积计数不是被"压住"的，而是从来没
    //                                          长起来，矛头转向写回路径
    // 代价：若确诊，画面会开始出现拖影（历史真的活了）。这是预期，不是新 bug。
    // 回滚：恢复 4.0f / 3.0f。
    // 2026-09-28 实测结论：**antilag 不是根因，已改回生产值 4.0 / 3.0。**
    //
    // 做过的事：按下面这段推导把 antilag 近似关闭（sigmaScale=8、sensitivity=1e4，
    // 使 magic≈4e4 而 accumSpeed≤63，于是 d*accum/magic ≤1.6e-3、antilag≈0.998），
    // 用户报告"还是橙色棋盘格" —— 累积计数依然长不起来。
    //
    // 这一步的意义比它本身大：到目前为止被排除的机制有
    //   * 平面距离闸门（阈值放到 saturate 天花板都无效）
    //   * 法线闸门（cos(89°) 根本不会触发）
    //   * antilag（近似关闭也无效）
    // 也就是说累积计数**不是被任何"拒绝机制"压住的**，它压根没有被加上去。
    // 结论：继续拧 NRD 的参数没有意义，方向应转向"每帧 +1 的写回/混合路径"
    // （smbAccumSpeed 的加权混合、gPrev_InternalData 的读回）而不是闸门。
 // ★ 2026-09-29：antilag 回归 NRD 默认。
    // 依据：官方 README 对新集成的要求是「Antilag parameters need to be carefully tuned.
    // Initial integration should be done with disabled antilag.」——而我们现在的
    // 1spp 二值可见性信号对 antilag 的"亮度突变"判定本就不友好；history confidence
    // （第二步）才是官方指定的"哪里变了就重置哪里"的机制，它接上后再谈 antilag 调参。
    // 回退：取消下面两行注释即恢复 4.0 / 3.0。
    // settings.antilagSettings.luminanceSigmaScale = 4.0f;
    // settings.antilagSettings.luminanceSensitivity = 3.0f;
    //
    // ★★★ 2026-09-29 14:5x 复测（用户："噪点还在"，要求按官方文档深挖）：
    //   上一轮"antilag 近似关闭无效"的结论**是在 IN_MV 仍混着相机抖动（NRD validation
    //   视口 3 整帧洋红）的状态下得到的**——那时复投影落点系统性偏 0.25~0.5px，历史被
    //   `smbFootprintQuality` 压住，antilag 是不是根因根本测不出来。现在 MV 已修，
    //   必须复测这一格。
    //   **本轮证据**：validation 视口 8 用其自带图例标定后实测，历史只停
    //   **6~16 帧 / 满量程 63**（官方口径要求"停在紫区"），且短的地方正是被本地光
    //   照亮、1spp 二值可见性让逐帧亮度大幅摆动的墙面（用户截图的噪点位置一致）；
    //   而太阳照亮、信号平滑的区域能达到 46~54 帧 ⇒ 恰好是 antilag 的触发特征
    //   （它与"局部方差带"比较，方差小的平滑区域不触发）。
    //   取值沿用 09-28 的诊断态（sigmaScale=8、sensitivity=1e4 ⇒ antilag≈0.998，等于关掉），
    //   与 confidence 修复一起上，避免连续两次重启。
    //   判读（重启后看顶部色带 + 画面）：色带转青/白 ⇒ 历史活了、噪点应明显下降；
    //   色带仍黄/红 ⇒ 累积计数不是被 antilag 压住的，矛头转向 smbFootprintQuality /
    //   写回路径（此时 antilag 这一格已被彻底排除）。
    // ★ 2026-09-29 第 2 项：回到 4.0 / 3.0，撤销"近似关闭"的诊断态。
    //
    // Radiance 的 REBLUR 实例显式设
    //   antilagSettings.luminanceSigmaScale = 4.0f;  antilagSettings.luminanceSensitivity = 3.0f;
    // （其 RELAX 实例用的是另一组旋钮 accelerationAmount / resetAmount，与此无关）。
    // 我们自 09-28 起留的是诊断态 8.0 / 1e4（magic≈4e4、accumSpeed≤63 ⇒
    // d*accum/magic ≤ 1.6e-3 ⇒ antilag≈0.998，等价关闭），而 09-28 的实测结论已经写明
    // "antilag 不是根因"。既然不是根因，就没有理由继续留在非生产值上。
    // 回退：改回 8.0f / 10000.0f 即恢复诊断态。
    settings.antilagSettings.luminanceSigmaScale = 4.0f;
    settings.antilagSettings.luminanceSensitivity = 3.0f;

    // ★ 2026-09-28：把 OUT_DIFF_RADIANCE_HITDIST 的 .w 从「归一化命中距离（AO）」
    // 换成「历史长度（帧）」。
    //
    // 依据（NRDSettings.h 原文）：returnHistoryLengthInsteadOfOcclusion = true 时，
    // "History length is measured in frames, it can be in [0; maxAccumulatedFrameNum] range"。
    //
    // 为什么安全：本链**没有任何消费者**读 .w（rt_nrd_composite.comp 里明确写着
    // ".w 在 REBLUR 里是归一化命中距离（AO），本链没有消费者"），所以打开它不改画面。
    //
    // 为什么需要：这是唯一能直接测量「NRD 到底有没有在累积历史」的手段。配合
    // rt_nrd_composite.comp 的 NRD_COMPOSITE_DEBUG=4 把它伪彩上屏即可读出。
    // 若整屏是黑/暗红，说明历史每帧都在被丢弃，输出≈1spp——那滤波再调也没用。
// 2026-09-28：**默认已置 0（回到生产语义）**。诊断期曾置 1，用来把 .w 读成历史
// 长度做读数；本链没有 .w 消费者，所以两种取值都不影响画面，只是诊断脚手架。
// ★ 2026-09-29 14:0x 诊断态：置 1，配合合成端 NRD_COMPOSITE_DEBUG=4 把 NRD 的
// 历史长度（帧）伪彩上屏。问题："单降噪器 + 默认参数 + confidence" 下静止仍有高频噪点，
// 需要先确认 NRD 到底有没有在累积历史（唯一能直接回答的仪器）。
// 诊断结束后改回 0。
#ifndef NRD_LOCAL_DI_RETURN_HISTORY_LENGTH
#define NRD_LOCAL_DI_RETURN_HISTORY_LENGTH 1
#endif
#if NRD_LOCAL_DI_RETURN_HISTORY_LENGTH
    settings.returnHistoryLengthInsteadOfOcclusion = true;
#endif

    // ★ 2026-09-27 第三次应用 D：关掉 diffuse prepass blur（这是 11 轮里从未碰过的参数）
    //
    // 依据（来自用户截图 + Advisor 的方向性分析）：
    //   截图里地面的条纹**基本水平**：沿屏幕 X 拉长、垂直方向只有几个像素，
    //   而且平行于屏幕坐标轴。这是**屏幕空间的方向性相关**，采样方差不会长这样
    //   （方差是随机颗粒）。方向性相关最常见的来源就是**可分离滤波**——而 REBLUR
    //   的 prepass 正是一个大半径空间预滤波。
    //
    // 关键：diffusePrepassBlurRadius 的 REBLUR 默认值是 30.0，我们 `settings = {}`
    // 一直吃到这个默认值，**从本次会话开始到现在从未被修改过**。这就解释了为什么
    // 条纹的"形状"对所有改动都不变——我一直改的都是别的参数（降噪器模型、累积窗口、
    // sigma、antilag、候选数、种子、donor 信任、渲染分辨率），而真正产生条纹的
    // 这个参数**一次都没被碰过**。
    //
    // 30 像素的半径在 707x376 的渲染分辨率上相当于屏幕宽度的 4%，对 1spp 输入来说
    // 是极重的空间滤波。
    //
    // 回滚：把两行改回 30.0f / 50.0f 即恢复 REBLUR 默认行为。
    // 若本条无效（条纹不变），则说明条纹在滤波上游，下一步改用
    // RESTIR_FINAL_DEBUG_RAW 直接转储 pre-NRD 原始估计值来定位。
    // ★ 2026-09-29：**恢复官方默认的 pre-pass**（30 / 50），撤销此前置 0 的改动。
    // 依据：NRD README 的命中距离要求里明确写着
    //   "Pre-pass must be enabled (i.e. diffusePrepassBlurRadius and
    //    specularPrepassBlurRadius must be non-0)"
    // 且 "Input signal quality can be improved by enabling pre-pass"。
    // 我们的输入是 1spp 二值可见性，属于"脏信号"，正是 pre-pass 的适用场景；
    // 13:46 录屏的满幅高频噪点也需要这道空间预滤波。
    // 旧结论（"prepass 产生水平条纹"）来自三层叠加时期，单降噪器下需重新评估；
    // 若条纹复现，回退两行为 0.0f（并记录）。
    // ★ 2026-09-29 第 2 项：diffuse 置 0，撤销 30 / 50 的"官方默认值"。
    //
    // 依据一（Radiance）：REBLUR 实例（diffuse=0.0f, specular=20.0f）与
    //   RELAX 实例（diffuse=0.0f, specular=0.0f）的 diffusePrepassBlurRadius **都是 0**。
    // 依据二（NRD README:905-910）："Pre-pass must be enabled" 这条约束只适用于
    //   "In case of probabilistic diffuse / specular split at the primary hit"——
    //   我们不做主命中的概率性 lobe 拆分（见本函数上方 19162 行的说明），前提不成立。
    // 依据三（NRD 源码 Reblur.cpp:119）：
    //   skipPrePass = (diffRadius==0 || !hasDiffuse) && (specRadius==0 || !hasSpecular)
    //   本实例只有 diffuse ⇒ 置 0 会**整条跳过 pre-pass**。AREA_5X5 的命中距离重建不受影响，仍然在跑
    //   （Reblur.cpp:135-142 会把 passIndex 切到 +2 变体）。
    // 回退：改回 30.0f / 50.0f。
    settings.diffusePrepassBlurRadius = 0.0f;
    // 我们没有镜面分量（REBLUR_DIFFUSE），这一项对 skipPrePass 无影响，
    // 置 0 只是避免它继续扮演一个实际不生效的 20。
    settings.specularPrepassBlurRadius = 0.0f;

    // hitDistanceParameters is deliberately left at NRD's defaults
    // (A = 3.0, B = 0.1, C = 20.0).  rt_restir_final.rgen normalises the hit
    // distance with the SAME constants in NRD_HIT_DISTANCE_PARAMS, and REBLUR
    // denormalises with these, so the two must not drift apart.
    settings.hitDistanceParameters = nrd::ReblurHitDistanceParameters{};

    // Logged once per (re)creation so the numbers that are actually in force can
    // be read back out of run/rt_debug.log instead of being taken on trust.
    if(!g_nrdSettingsLogged)
    {
        g_nrdSettingsLogged = true;

        RTLog(
            std::string("[NRD-1 TUNING] reblur accumulationSeconds=") +
            std::to_string(NRD_LOCAL_DI_ACCUMULATION_SECONDS) +
            " maxAccumulatedFrameNum=" + std::to_string(settings.maxAccumulatedFrameNum) +
            " maxFastAccumulatedFrameNum=" + std::to_string(settings.maxFastAccumulatedFrameNum) +
            " historyFixFrameNum=" + std::to_string(settings.historyFixFrameNum) +
            " fastHistoryClampingSigmaScale=" + std::to_string(settings.fastHistoryClampingSigmaScale) +
            " hitDistA=" + std::to_string(settings.hitDistanceParameters.A) +
            " hitDistB=" + std::to_string(settings.hitDistanceParameters.B) +
            " hitDistC=" + std::to_string(settings.hitDistanceParameters.C) +
            " diffPrepassBlurRadius=" + std::to_string(settings.diffusePrepassBlurRadius) +
            " specPrepassBlurRadius=" + std::to_string(settings.specularPrepassBlurRadius) +
            " antilagSigmaScale=" + std::to_string(settings.antilagSettings.luminanceSigmaScale) +
            " antilagSensitivity=" + std::to_string(settings.antilagSettings.luminanceSensitivity) +
            " minMaterialForDiffuse=" + std::to_string(settings.minMaterialForDiffuse) +
            " minMaterialForSpecular=" + std::to_string(settings.minMaterialForSpecular) +
            " smoothedFps=" + std::to_string(smoothedFps)
        );
    }
}

// =============================================================================
// RELAX_DIFFUSE 的全部设置；只在 RELAX 分支被引用，宏为 0 时整段编掉（避免 /WX 下的 C4505）。
#if NRD_LOCAL_DI_USE_RELAX
//
// 两个"帧数"字段按官方 FPS 公式换算（NRD README:911-914）：
//   maxAccumulatedFrameNum = accumulationPeriodInSeconds * FPS。
// 用 scaleFrameCount 换算，等价于 accumulationSeconds = configured / 60，本函数照抄
// 该换算，所以 60fps 下结果就是 30 / 12。
//
// 注意：这与上面 REBLUR 分支的 NRD_LOCAL_DI_ACCUMULATION_SECONDS = 1.0 **不同**，
// 是刻意的：RELAX 这组按"60fps 基准帧数"换算，REBLUR 那边（HANDOFF §12.3）
// 按 NRD README 的推荐公式保留 1.0s，两件事各自的依据不同。
//
// specular* 几项在本实例（RELAX_DIFFUSE，无镜面通道）里是惰性的，但仍要填：
// historyFixFrameNum 的推导用的是 min(diffuseMaxFast, specularMaxFast) - 1，
// 那一项不是可有可无的装饰。
//
// 回退：把宿主 NRD_LOCAL_DI_USE_RELAX 改回 0（并同步两个 shader 的同名宏）。
// =============================================================================
static void nrdBuildRelaxSettings(nrd::RelaxSettings& settings)
{
    settings = {};

    const float smoothedFps = 1000.0f / std::max(1.0f, g_nrdSmoothedFrameTimeMs);

    const auto framesFromReference60 = [smoothedFps](uint32_t referenceFrames)
    {
        return std::min<uint32_t>(
            nrd::RELAX_MAX_HISTORY_FRAME_NUM,
            nrd::GetMaxAccumulatedFrameNum(
                static_cast<float>(referenceFrames) / 60.0f, smoothedFps
            )
        );
    };

    // --- 与 makeDefaultRelaxSettings() 逐项对应 ---
    settings.antilagSettings.accelerationAmount = 0.3f;
    settings.antilagSettings.resetAmount = 0.5f;
    settings.diffuseMaxAccumulatedFrameNum = framesFromReference60(30u);
    settings.specularMaxAccumulatedFrameNum = framesFromReference60(12u);
    settings.diffuseMaxFastAccumulatedFrameNum = 6u;
    settings.specularMaxFastAccumulatedFrameNum = 4u;
    settings.historyFixFrameNum = 3u;
    settings.fastHistoryClampingSigmaScale = 1.35f;
    settings.diffusePrepassBlurRadius = 0.0f;
    settings.specularPrepassBlurRadius = 0.0f;
    settings.minHitDistanceWeight = 0.05f;
    settings.diffusePhiLuminance = 2.5f;
    settings.specularPhiLuminance = 1.5f;
    settings.diffuseMinLuminanceWeight = 0.05f;
    settings.specularMinLuminanceWeight = 0.02f;
    settings.lobeAngleFraction = 0.35f;
    settings.roughnessFraction = 0.2f;
    settings.specularVarianceBoost = 0.15f;
    settings.atrousIterationNum = 3u;
    settings.depthThreshold = 0.003f;
    settings.minMaterialForDiffuse = 0.0f;
    settings.minMaterialForSpecular = 0.0f;
    settings.enableAntiFirefly = true;
    settings.hitDistanceReconstructionMode = nrd::HitDistanceReconstructionMode::AREA_3X3;

    // --- 低帧率保护：保证 fast <= max（同向缩放），否则在低 FPS 下窗口收缩会违反 NRD 的
    // maxAccumulatedFrameNum > maxFastAccumulatedFrameNum > historyFixFrameNum。
    settings.diffuseMaxFastAccumulatedFrameNum = std::min<uint32_t>(
        settings.diffuseMaxFastAccumulatedFrameNum,
        settings.diffuseMaxAccumulatedFrameNum
    );
    settings.specularMaxFastAccumulatedFrameNum = std::min<uint32_t>(
        settings.specularMaxFastAccumulatedFrameNum,
        settings.specularMaxAccumulatedFrameNum
    );

    const uint32_t minimumFastHistory = std::min<uint32_t>(
        settings.diffuseMaxFastAccumulatedFrameNum,
        settings.specularMaxFastAccumulatedFrameNum
    );
    settings.historyFixFrameNum = minimumFastHistory == 0u
        ? 0u
        : std::min<uint32_t>(settings.historyFixFrameNum, minimumFastHistory - 1u);

    if(!g_nrdSettingsLogged)
    {
        g_nrdSettingsLogged = true;

        RTLog(
            std::string("[NRD-1 TUNING] relax (reference-aligned)")
            + " diffMaxFrames=" + std::to_string(settings.diffuseMaxAccumulatedFrameNum)
            + " specMaxFrames=" + std::to_string(settings.specularMaxAccumulatedFrameNum)
            + " diffFastFrames=" + std::to_string(settings.diffuseMaxFastAccumulatedFrameNum)
            + " specFastFrames=" + std::to_string(settings.specularMaxFastAccumulatedFrameNum)
            + " historyFixFrameNum=" + std::to_string(settings.historyFixFrameNum)
            + " fastHistoryClampingSigmaScale=" + std::to_string(settings.fastHistoryClampingSigmaScale)
            + " atrousIterationNum=" + std::to_string(settings.atrousIterationNum)
            + " accelerationAmount=" + std::to_string(settings.antilagSettings.accelerationAmount)
            + " resetAmount=" + std::to_string(settings.antilagSettings.resetAmount)
            + " minMaterialForDiffuse=" + std::to_string(settings.minMaterialForDiffuse)
            + " minMaterialForSpecular=" + std::to_string(settings.minMaterialForSpecular)
            + " smoothedFps=" + std::to_string(smoothedFps)
        );
    }
}
#endif // NRD_LOCAL_DI_USE_RELAX

// =============================================================================
// 2026-09-29 第二步：NRD history confidence（IN_DIFF_CONFIDENCE）产线
//
// 官方依据见 cpp/shaders/rt_di_confidence.comp 头部注释与 HANDOFF 的「官方基准」。
// 关键约束（NRDDescs.h:52-59）：R8+、[0,1]、且必须是"上一帧的量在当前帧算出来"。
//
// 每帧两次 dispatch（同一 pipeline，push.mode 区分）：
//   mode 0：由 IN_DIFF_RADIANCE_HITDIST 的 Y + MV 复投影上一帧亮度 => 梯度
//   mode 1：梯度宽模糊 + 归一化 + 短时域滤波 => confidence（R8）并交给 NRD
// 亮度与 confidence 都是 ping-pong（读上一帧、写本帧），所以描述符集有两套。
//
// 关闭：编译期去掉 -DNRD_LOCAL_DI_CONFIDENCE=1（默认 1）；关掉后
// isHistoryConfidenceAvailable 保持 false，NRD 退回"没有外部提示"的行为。
// =============================================================================
#ifndef NRD_LOCAL_DI_CONFIDENCE
#define NRD_LOCAL_DI_CONFIDENCE 1
#endif

#if NRD_LOCAL_DI_CONFIDENCE

// 本块位于 nrdImageBarrier 的定义之前（它定义在下面解析器之后），先做前置声明。
static void nrdImageBarrier(
    VkCommandBuffer cmd,
    VkImage image,
    VkAccessFlags srcAccess,
    VkAccessFlags dstAccess);

// 官方 Confidence.md 给的量级：几百毫秒级的历史平滑 + "几帧内平滑失效"。
//
// ★ 2026-09-29 13:5x 按第一次实测（13:46 录屏：满幅高频噪点）修正：
//   初版用"当帧 1spp 亮度 vs 上一帧 1spp 亮度"，而本地光是一条二值可见性射线，
//   相对差天然 ≈1 ⇒ 梯度恒 ≈1 ⇒ confidence ≈ exp(-4) ≈ 0.02 ⇒ NRD 每帧重置历史。
//   现在梯度改为 EMA-vs-EMA（beta=0.10 ≈10 帧），并由 threshold 死区吸收残留噪声底：
//     残留噪声 ≈ 0.3 相对量级 ⇒ threshold=0.35 时稳定区域 confidence≈1（正常累积），
//     真实光照变化（相对变化 ≫ 0.35）才压低 confidence。
static constexpr float NRD_DI_CONFIDENCE_SENSITIVITY = 4.0f;
static constexpr float NRD_DI_CONFIDENCE_THRESHOLD = 0.35f;
static constexpr float NRD_DI_CONFIDENCE_EMA_BETA = 0.10f;
static constexpr float NRD_DI_CONFIDENCE_TEMPORAL_ALPHA = 0.25f;
// 与 denoisingRange 同量级：超过即视为天空/无效接收面。
static constexpr float NRD_DI_CONFIDENCE_MAX_VIEWZ = 60000.0f;

struct DiConfidencePushConstants
{
    uint32_t width;
    uint32_t height;
    uint32_t mode;
    float gradientSensitivity;
    float gradientThreshold;
    float temporalAlpha;
    float maxViewZ;
    float lumaEmaBeta;
    float padding0;
};

static VkPipeline g_diConfidencePipeline = VK_NULL_HANDLE;
static VkPipelineLayout g_diConfidencePipelineLayout = VK_NULL_HANDLE;
static VkDescriptorSetLayout g_diConfidenceSetLayout = VK_NULL_HANDLE;
static VkDescriptorPool g_diConfidencePool = VK_NULL_HANDLE;
static VkDescriptorSet g_diConfidenceSets[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };

static VkImage g_diGradientImage = VK_NULL_HANDLE;
static VkDeviceMemory g_diGradientMemory = VK_NULL_HANDLE;
static VkImageView g_diGradientView = VK_NULL_HANDLE;
static VkImageLayout g_diGradientLayout = VK_IMAGE_LAYOUT_UNDEFINED;

static VkImage g_diConfidenceImages[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkDeviceMemory g_diConfidenceMemories[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageView g_diConfidenceViews[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageLayout g_diConfidenceLayouts[2] = {
    VK_IMAGE_LAYOUT_UNDEFINED,
    VK_IMAGE_LAYOUT_UNDEFINED
};

static VkImage g_diLumaImages[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkDeviceMemory g_diLumaMemories[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageView g_diLumaViews[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageLayout g_diLumaLayouts[2] = {
    VK_IMAGE_LAYOUT_UNDEFINED,
    VK_IMAGE_LAYOUT_UNDEFINED
};

static uint32_t g_diConfidenceWidth = 0u;
static uint32_t g_diConfidenceHeight = 0u;
// 读 [p]，写 [p^1]；NRD 绑定"本帧写出"的那一份。帧末翻转。
static uint32_t g_diConfidenceParity = 0u;
static bool g_diConfidenceReady = false;
// 图像是裸内存（NRD 侧图像没有清零路径）：刚建好的前几帧把时域系数压到 1.0，
// 等于"完全采信本帧、不读历史"，避免把未初始化内存混进 confidence。
// 与 NRD 自身的 accumulationMode 语义一致（重建成 CLEAR_AND_RESTART 的那一档）。
static uint32_t g_diConfidenceWarmupFrames = 0u;
// 资源（重）建后描述符需要刷新一次；平时每帧不再重写描述符。
static bool g_diConfidenceDescriptorsDirty = true;

static bool createDiConfidenceResources(uint32_t width, uint32_t height)
{
    // ★ 2026-09-29 修正：这里的早退条件**不能**用 g_diConfidenceReady。
    // recordDiConfidence 每帧开头会把 ready 置 false（沿用 à-trous 链的写法），
    // 于是"ready==false"被误判成"需要重建"→ 每帧销毁重建整条链：
    //   * ping-pong 历史每帧清零 ⇒ confidence 永远是首帧值（时域滤波失效）；
    //   * 未初始化内存被当历史读 ⇒ NRD 收到垃圾置信度 ⇒ 鬼影/闪动。
    // 正确判据：**资源是否齐全 + 尺寸是否一致**。
    if(g_diGradientImage != VK_NULL_HANDLE &&
       g_diConfidenceImages[0] != VK_NULL_HANDLE &&
       g_diConfidenceImages[1] != VK_NULL_HANDLE &&
       g_diLumaImages[0] != VK_NULL_HANDLE &&
       g_diLumaImages[1] != VK_NULL_HANDLE &&
       width == g_diConfidenceWidth &&
       height == g_diConfidenceHeight)
    {
        return true;
    }

    // 尺寸变化：整条链重建（NRD 侧没有 resize，这是官方要求的最小代价做法）。
    if(g_diConfidenceReady ||
       g_diGradientImage != VK_NULL_HANDLE ||
       g_diConfidenceImages[0] != VK_NULL_HANDLE)
    {
        if(g_device != VK_NULL_HANDLE)
        {
            FGDeviceWaitIdle(g_device);
        }

        for(uint32_t i = 0u; i < 2u; ++i)
        {
            if(g_diConfidenceViews[i] != VK_NULL_HANDLE)
            {
                vkDestroyImageView(g_device, g_diConfidenceViews[i], nullptr);
            }
            if(g_diConfidenceImages[i] != VK_NULL_HANDLE)
            {
                vkDestroyImage(g_device, g_diConfidenceImages[i], nullptr);
            }
            if(g_diConfidenceMemories[i] != VK_NULL_HANDLE)
            {
                vkFreeMemory(g_device, g_diConfidenceMemories[i], nullptr);
            }

            if(g_diLumaViews[i] != VK_NULL_HANDLE)
            {
                vkDestroyImageView(g_device, g_diLumaViews[i], nullptr);
            }
            if(g_diLumaImages[i] != VK_NULL_HANDLE)
            {
                vkDestroyImage(g_device, g_diLumaImages[i], nullptr);
            }
            if(g_diLumaMemories[i] != VK_NULL_HANDLE)
            {
                vkFreeMemory(g_device, g_diLumaMemories[i], nullptr);
            }

            g_diConfidenceViews[i] = VK_NULL_HANDLE;
            g_diConfidenceImages[i] = VK_NULL_HANDLE;
            g_diConfidenceMemories[i] = VK_NULL_HANDLE;
            g_diLumaViews[i] = VK_NULL_HANDLE;
            g_diLumaImages[i] = VK_NULL_HANDLE;
            g_diLumaMemories[i] = VK_NULL_HANDLE;
        }

        if(g_diGradientView != VK_NULL_HANDLE)
        {
            vkDestroyImageView(g_device, g_diGradientView, nullptr);
        }
        if(g_diGradientImage != VK_NULL_HANDLE)
        {
            vkDestroyImage(g_device, g_diGradientImage, nullptr);
        }
        if(g_diGradientMemory != VK_NULL_HANDLE)
        {
            vkFreeMemory(g_device, g_diGradientMemory, nullptr);
        }

        g_diGradientView = VK_NULL_HANDLE;
        g_diGradientImage = VK_NULL_HANDLE;
        g_diGradientMemory = VK_NULL_HANDLE;
        g_diConfidenceReady = false;
    }

    // 梯度图：R16f 足够（梯度被 clamp 到 4）。
    if(!nrdCreateImage2D(
           width, height, VK_FORMAT_R16_SFLOAT,
           g_diGradientImage, g_diGradientMemory, g_diGradientView,
           g_diGradientLayout, "DI_CONFIDENCE_GRADIENT"))
    {
        return false;
    }

    for(uint32_t i = 0u; i < 2u; ++i)
    {
        // confidence：NRD 契约 R8+，用 R8_UNORM。
        if(!nrdCreateImage2D(
               width, height, VK_FORMAT_R8_UNORM,
               g_diConfidenceImages[i], g_diConfidenceMemories[i],
               g_diConfidenceViews[i], g_diConfidenceLayouts[i],
               "DI_CONFIDENCE"))
        {
            return false;
        }

        // 上一帧 DI 亮度。
        if(!nrdCreateImage2D(
               width, height, VK_FORMAT_R16_SFLOAT,
               g_diLumaImages[i], g_diLumaMemories[i],
               g_diLumaViews[i], g_diLumaLayouts[i],
               "DI_CONFIDENCE_LUMA"))
        {
            return false;
        }
    }

    g_diConfidenceWidth = width;
    g_diConfidenceHeight = height;
    g_diConfidenceParity = 0u;
    g_diConfidenceReady = true;
    g_diConfidenceWarmupFrames = 2u;
    g_diConfidenceDescriptorsDirty = true;

    RTLog(
        std::string("[DI CONFIDENCE] resources created ") +
        std::to_string(width) + "x" + std::to_string(height)
    );

    return true;
}

static bool createDiConfidencePipeline()
{
    if(g_diConfidencePipeline != VK_NULL_HANDLE &&
       g_diConfidenceSets[0] != VK_NULL_HANDLE &&
       g_diConfidenceSets[1] != VK_NULL_HANDLE)
    {
        return true;
    }

    std::vector<uint8_t> code;

    try
    {
        code = loadSpv("shaders/rt_di_confidence.comp.spv");
    }
    catch(const std::exception& loadError)
    {
        RTLog(
            std::string("[DI CONFIDENCE] shader load failed: ") + loadError.what()
        );
        return false;
    }

    if(code.empty())
    {
        RTLog("[DI CONFIDENCE] shader missing, NRD runs without confidence");
        return false;
    }

    VkDescriptorSetLayoutBinding bindings[9]{};
    for(uint32_t i = 0u; i < 9u; ++i)
    {
        bindings[i].binding = i;
        bindings[i].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
        bindings[i].descriptorCount = 1u;
        bindings[i].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
    }

    VkDescriptorSetLayoutCreateInfo layoutInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO
    };
    layoutInfo.bindingCount = 9u;
    layoutInfo.pBindings = bindings;

    check(
        vkCreateDescriptorSetLayout(
            g_device, &layoutInfo, nullptr, &g_diConfidenceSetLayout
        ),
        "di confidence set layout failed"
    );

    VkDescriptorPoolSize poolSize{};
    poolSize.type = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    poolSize.descriptorCount = 2u * 9u;

    VkDescriptorPoolCreateInfo poolInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO
    };
    poolInfo.maxSets = 2u;
    poolInfo.poolSizeCount = 1u;
    poolInfo.pPoolSizes = &poolSize;

    check(
        vkCreateDescriptorPool(g_device, &poolInfo, nullptr, &g_diConfidencePool),
        "di confidence pool failed"
    );

    VkDescriptorSetLayout layouts[2] = {
        g_diConfidenceSetLayout,
        g_diConfidenceSetLayout
    };

    VkDescriptorSetAllocateInfo allocateInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO
    };
    allocateInfo.descriptorPool = g_diConfidencePool;
    allocateInfo.descriptorSetCount = 2u;
    allocateInfo.pSetLayouts = layouts;

    check(
        vkAllocateDescriptorSets(g_device, &allocateInfo, g_diConfidenceSets),
        "di confidence sets failed"
    );

    VkPushConstantRange pushRange{};
    pushRange.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
    pushRange.offset = 0u;
    pushRange.size = sizeof(DiConfidencePushConstants);

    VkPipelineLayoutCreateInfo pipelineLayoutInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO
    };
    pipelineLayoutInfo.setLayoutCount = 1u;
    pipelineLayoutInfo.pSetLayouts = &g_diConfidenceSetLayout;
    pipelineLayoutInfo.pushConstantRangeCount = 1u;
    pipelineLayoutInfo.pPushConstantRanges = &pushRange;

    check(
        vkCreatePipelineLayout(
            g_device, &pipelineLayoutInfo, nullptr, &g_diConfidencePipelineLayout
        ),
        "di confidence pipeline layout failed"
    );

    VkShaderModule module = createShaderModule(g_device, code);

    VkPipelineShaderStageCreateInfo stage{
        VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO
    };
    stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    stage.module = module;
    stage.pName = "main";

    VkComputePipelineCreateInfo pipelineInfo{
        VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO
    };
    pipelineInfo.stage = stage;
    pipelineInfo.layout = g_diConfidencePipelineLayout;

    check(
        vkCreateComputePipelines(
            g_device, VK_NULL_HANDLE, 1u, &pipelineInfo, nullptr,
            &g_diConfidencePipeline
        ),
        "di confidence pipeline failed"
    );

    vkDestroyShaderModule(g_device, module, nullptr);

    RTLog("[DI CONFIDENCE] pipeline created");
    return true;
}

static void updateDiConfidenceDescriptors()
{
    if(g_diConfidenceSetLayout == VK_NULL_HANDLE ||
       g_diConfidenceSets[0] == VK_NULL_HANDLE ||
       g_diConfidenceSets[1] == VK_NULL_HANDLE ||
       g_diGradientView == VK_NULL_HANDLE ||
       g_diConfidenceViews[0] == VK_NULL_HANDLE ||
       g_diConfidenceViews[1] == VK_NULL_HANDLE ||
       g_diLumaViews[0] == VK_NULL_HANDLE ||
       g_diLumaViews[1] == VK_NULL_HANDLE ||
       g_nrdDiffRadianceHitDistView == VK_NULL_HANDLE ||
       g_nrdMotionView == VK_NULL_HANDLE ||
       g_nrdViewZView == VK_NULL_HANDLE)
    {
        return;
    }

    VkDescriptorImageInfo infos[2][9]{};
    VkWriteDescriptorSet writes[2][9]{};

    for(uint32_t setIndex = 0u; setIndex < 2u; ++setIndex)
    {
        const uint32_t readIndex = setIndex;
        const uint32_t writeIndex = setIndex ^ 1u;

        const VkImageView views[9] = {
            g_nrdDiffRadianceHitDistView,        // 0 IN_DIFF（Y = 亮度）
            g_nrdMotionView,                     // 1 MV
            g_nrdViewZView,                      // 2 viewZ
            g_diLumaViews[readIndex],            // 3 上一帧亮度
            g_diConfidenceViews[readIndex],      // 4 上一帧 confidence
            g_diGradientView,                    // 5 梯度（写）
            g_diGradientView,                    // 6 梯度（读）
            g_diConfidenceViews[writeIndex],     // 7 confidence（写）
            g_diLumaViews[writeIndex]            // 8 本帧亮度（写）
        };

        for(uint32_t slot = 0u; slot < 9u; ++slot)
        {
            infos[setIndex][slot].imageView = views[slot];
            infos[setIndex][slot].imageLayout = VK_IMAGE_LAYOUT_GENERAL;

            writes[setIndex][slot].sType =
                VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
            writes[setIndex][slot].dstSet = g_diConfidenceSets[setIndex];
            writes[setIndex][slot].dstBinding = slot;
            writes[setIndex][slot].dstArrayElement = 0u;
            writes[setIndex][slot].descriptorCount = 1u;
            writes[setIndex][slot].descriptorType =
                VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
            writes[setIndex][slot].pImageInfo = &infos[setIndex][slot];
        }
    }

    vkUpdateDescriptorSets(g_device, 2u * 9u, &writes[0][0], 0u, nullptr);
}

// 返回本帧写出的 confidence 视图（NRD 绑它）；失败返回 VK_NULL_HANDLE。
static VkImageView recordDiConfidence(VkCommandBuffer cmd, uint32_t width, uint32_t height)
{
    if(cmd == VK_NULL_HANDLE || width == 0u || height == 0u)
    {
        return VK_NULL_HANDLE;
    }

    g_diConfidenceReady = false;

    if(!createDiConfidenceResources(width, height))
    {
        return VK_NULL_HANDLE;
    }

    if(!createDiConfidencePipeline())
    {
        return VK_NULL_HANDLE;
    }

    // 描述符只在（重）建后刷新一次；资源没变时视图不变。
    if(g_diConfidenceDescriptorsDirty)
    {
        updateDiConfidenceDescriptors();
        g_diConfidenceDescriptorsDirty = false;
    }

    g_diConfidenceReady = true;

    if(g_diConfidencePipeline == VK_NULL_HANDLE || g_diConfidencePipelineLayout == VK_NULL_HANDLE)
    {
        return VK_NULL_HANDLE;
    }

    // 亮度图/梯度图的上一帧内容必须对 shader 可见。
    nrdImageBarrier(
        cmd, g_diGradientImage,
        VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT
    );

    // 三张输入图（IN_DIFF / MV / IN_VIEWZ）是 rgen 刚写的：显式排序 RT 写 -> compute 读。
    // 本 pass 现在跑在 recordNRDLocalDenoiser **之前**，不能再依赖 NRD 那边的 barrier。
    nrdImageBarrier(
        cmd, g_nrdDiffRadianceHitDistImage,
        VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT
    );
    nrdImageBarrier(
        cmd, g_nrdMotionImage,
        VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT
    );
    nrdImageBarrier(
        cmd, g_nrdViewZImage,
        VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT
    );

    DiConfidencePushConstants push{};
    push.width = width;
    push.height = height;
    push.gradientSensitivity = NRD_DI_CONFIDENCE_SENSITIVITY;
    push.gradientThreshold = NRD_DI_CONFIDENCE_THRESHOLD;
    push.lumaEmaBeta = NRD_DI_CONFIDENCE_EMA_BETA;
    push.padding0 = 0.0f;
    // 预热帧：完全采信本帧（不读未初始化的上一帧 confidence）。
    push.temporalAlpha = g_diConfidenceWarmupFrames > 0u
        ? 1.0f
        : NRD_DI_CONFIDENCE_TEMPORAL_ALPHA;
    push.maxViewZ = NRD_DI_CONFIDENCE_MAX_VIEWZ;

    if(g_diConfidenceWarmupFrames > 0u)
    {
        --g_diConfidenceWarmupFrames;
    }

    const uint32_t groupCountX = (width + 7u) / 8u;
    const uint32_t groupCountY = (height + 7u) / 8u;

    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, g_diConfidencePipeline);
    vkCmdBindDescriptorSets(
        cmd, VK_PIPELINE_BIND_POINT_COMPUTE, g_diConfidencePipelineLayout,
        0u, 1u, &g_diConfidenceSets[g_diConfidenceParity], 0u, nullptr
    );

    // mode 0：梯度
    push.mode = 0u;
    vkCmdPushConstants(
        cmd, g_diConfidencePipelineLayout, VK_SHADER_STAGE_COMPUTE_BIT,
        0u, sizeof(push), &push
    );
    vkCmdDispatch(cmd, groupCountX, groupCountY, 1u);

    // 梯度 -> 模糊 pass 需要一次显式屏障（同一张图先写后读）。
    nrdImageBarrier(
        cmd, g_diGradientImage,
        VK_ACCESS_SHADER_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT
    );

    // mode 1：宽模糊 + 归一化 + 短时域滤波
    push.mode = 1u;
    vkCmdPushConstants(
        cmd, g_diConfidencePipelineLayout, VK_SHADER_STAGE_COMPUTE_BIT,
        0u, sizeof(push), &push
    );
    vkCmdDispatch(cmd, groupCountX, groupCountY, 1u);

    return g_diConfidenceViews[g_diConfidenceParity ^ 1u];
}

// 每帧把本帧写出的 confidence 交给 NRD，并在帧末翻转 ping-pong。
static VkImageView g_nrdConfidenceViewThisFrame = VK_NULL_HANDLE;

#endif // NRD_LOCAL_DI_CONFIDENCE

// Resolves one DispatchDesc resource to the VkImageView it must be bound to.
static VkImageView nrdResolveResourceView(const nrd::ResourceDesc& resource)
{
    if(resource.type == nrd::ResourceType::PERMANENT_POOL)
    {
        if(resource.indexInPool < g_nrdPermanentViews.size())
        {
            return g_nrdPermanentViews[resource.indexInPool];
        }

        return VK_NULL_HANDLE;
    }

    if(resource.type == nrd::ResourceType::TRANSIENT_POOL)
    {
        if(resource.indexInPool < g_nrdTransientViews.size())
        {
            return g_nrdTransientViews[resource.indexInPool];
        }

        return VK_NULL_HANDLE;
    }

    switch(resource.type)
    {
        case nrd::ResourceType::IN_VIEWZ:                    return g_nrdViewZView;
        case nrd::ResourceType::IN_NORMAL_ROUGHNESS:         return g_nrdNormalRoughnessView;
        case nrd::ResourceType::IN_MV:                       return g_nrdMotionView;
        case nrd::ResourceType::IN_DIFF_RADIANCE_HITDIST:    return g_nrdDiffRadianceHitDistView;
#if NRD_LOCAL_DI_CONFIDENCE
        // 2026-09-29 第二步：本帧由 recordDiConfidence 写出的那一份 confidence。
        // 注意：只有 isHistoryConfidenceAvailable 为 true 时 NRD 才会在 dispatch 里
        // 请求这个资源（否则请求的是它自己的 dummy）；而该标志又是按"本帧视图是否
        // 可用"设置的，所以两者不可能不一致——shader 缺失时整体退回无 confidence，
        // 不会出现"NRD 因资源未解析而整帧不跑"。
        case nrd::ResourceType::IN_DIFF_CONFIDENCE:          return g_nrdConfidenceViewThisFrame;
#endif
        case nrd::ResourceType::OUT_DIFF_RADIANCE_HITDIST:   return g_nrdOutDiffRadianceHitDistView;
        // 2026-09-28：只有 enableValidation 打开时 NRD 才会执行 Validation pass
        // 并请求这个输出；关掉时不会有 dispatch 引用它，所以这里返回空也无碍。
        case nrd::ResourceType::OUT_VALIDATION:              return g_nrdValidationView;
        default:                                             break;
    }

    return VK_NULL_HANDLE;
}

// Barrier helper.  NRD reads and writes everything as GENERAL storage images,
// and this backend keeps its RT images in GENERAL for their whole life, so only
// the access masks and the stages need ordering.
//
// The source stage set MUST include the ray tracing stage: the three NRD inputs
// are written by the final ReSTIR RayGen (rt_restir_final.rgen), not by a
// compute pass, and a barrier whose srcStageMask omits RAY_TRACING_SHADER does
// not order those stores against NRD's compute dispatches.  The similar
// hand-offs elsewhere in the frame (reservoir buffer, colour image) already
// name VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR for exactly this reason.
static void nrdImageBarrier(
    VkCommandBuffer cmd,
    VkImage image,
    VkAccessFlags srcAccess,
    VkAccessFlags dstAccess)
{
    VkImageMemoryBarrier barrier{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};
    barrier.srcAccessMask = srcAccess;
    barrier.dstAccessMask = dstAccess;
    barrier.oldLayout = VK_IMAGE_LAYOUT_GENERAL;
    barrier.newLayout = VK_IMAGE_LAYOUT_GENERAL;
    barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    barrier.image = image;
    barrier.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
    barrier.subresourceRange.baseMipLevel = 0u;
    barrier.subresourceRange.levelCount = 1u;
    barrier.subresourceRange.baseArrayLayer = 0u;
    barrier.subresourceRange.layerCount = 1u;

    vkCmdPipelineBarrier(
        cmd,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT |
            VK_PIPELINE_STAGE_TRANSFER_BIT |
            VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
        VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT |
            VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
        0,
        0, nullptr,
        0, nullptr,
        1, &barrier
    );
}

// =============================================================================
// 2026-09-28 P1：直接光（本地光 DI）专用 à-trous 降噪
//
// 定位：与 NRD REBLUR 是**同一个位置的可替换件**（都吃 rt_restir_final.rgen 写出的
// 裸辐照度 IN_DIFF_RADIANCE_HITDIST，都把结果放进 OUT_DIFF_RADIANCE_HITDIST，
// 后面照旧由 rt_nrd_composite.comp 合成）。所以：
//   * 合成 pass 一行都不用改；
//   * 两张图都是 NRD 已经建好的，**不需要新增图像**；
//   * A/B 就是 g_directAtrousEnabled 一个开关（NRD <-> à-trous）。
//
// 为什么要它：本地光这一项每帧是"一个样本的 f·W·V"，V 是二值量，时域平均后仍留
// 细颗粒；MCVR在直接光这一项上放的是**5 级 à-trous、故意放松边缘停止、
// 带萤火虫替换**的空间滤波，而不是靠 NRD 的时域窗口。shader 见
// cpp/shaders/rt_direct_atrous.comp。
// =============================================================================
// 2026-09-28 开启（单变量推进的第一步：只验证"不崩 + 管线真的建起来并每帧跑"）。
//
// 上一课：这次部署曾因为同时改了**共享的 RT 描述符布局**而"进世界就崩"。本轮只动
// 这一个常量，布局/池都保持原值，spv 也已就位（rt_direct_atrous.comp.spv）。
//
// 回退：把这里改回 false 并重建，即回到 NRD（一侧不动，复合 pass 也不动）。
//
// ★★ 2026-09-29：改回 false —— 按 NVIDIA 官方口径收敛为「单一降噪器」。
//
// 依据（NRD v4.18.0 README + RTXDI FullSample 源码，见 HANDOFF 的「官方基准」一节）：
//   * 官方管线是 ReSTIR DI 原始信号 → **一个**降噪器（NRD 或 DLSS-RR，二者互斥）
//     → Resolve。不存在「NRD + 自写 SVGF 链 + DLSS-RR」三层时域叠加。
// * 原参考把 à-trous 放在 NRD **位置**（二选一），我们此前却让自写链
//     在 NRD 之**后**再覆盖 OUT_DIFF_RADIANCE_HITDIST，等于两层滤波串联。
//   * 官方对 RTXDI 类信号的建议是 NRD 吃原始信号 + history confidence（第二步接入）。
// 本开关置 false 后：recordDirectAtrous 整体不跑，recordNRDLocalDenoiser 接管，
// 合成 pass 不变（两者写的是同一张 OUT_DIFF_RADIANCE_HITDIST）。
static bool g_directAtrousEnabled = false;
static bool g_directAtrousReady = false;
static VkPipeline g_directAtrousPipeline = VK_NULL_HANDLE;
static VkPipelineLayout g_directAtrousPipelineLayout = VK_NULL_HANDLE;
static VkDescriptorSetLayout g_directAtrousSetLayout = VK_NULL_HANDLE;
static VkDescriptorPool g_directAtrousPool = VK_NULL_HANDLE;
// 三个集：0/1 是线性域的 ping-pong，2 是链尾（把结果编回 YCoCg 写进 NRD 输出图）。
static VkDescriptorSet g_directAtrousSets[3] = {
    VK_NULL_HANDLE,
    VK_NULL_HANDLE,
    VK_NULL_HANDLE
};
static uint32_t g_directAtrousWidth = 0u;
static uint32_t g_directAtrousHeight = 0u;

struct DirectAtrousPushConstants
{
    uint32_t width;
    uint32_t height;
    uint32_t stepSize;
    float phiColor;
    // 1 = 链尾：结果写回合成端读的 NRD 输出图，需编回 REBLUR 的 YCoCg。
    // 名字改了但**字节布局未变**（仍是 5 个 uint32 大小），与 shader 逐字对应。
    uint32_t encodeToYCoCg;
};

// =============================================================================
// 2026-09-28 空间链的中间图
//
// DI 去噪不是"一个 à-trous"，而是一条链：方差图 + 5 级 à-trous，
// 且整条链工作在线性 radiance 上。本项目能每帧拿到的 DI 项图是 REBLUR 的
// YCoCg 打包图（线性裸项在 reservoir SSBO 里，喂不进滤波器），所以在链首
// 解码、链尾编码（两个变换函数逐字照抄项目已有实现）。
//
//   线性项 ×2：rt_di_prepare 解码后写 L0；5 级 à-trous 在 L0/L1 间 ping-pong
// 方差 ×2：rt_di_prepare 写 V0；与颜色同 parity 逐级传递
//
// 与 NRD 自己的 app 图无关（那是 NRD 的 IN/OUT，我们只把它当输入读）。
// 随分辨率重建：在 recordDirectAtrous 的尺寸变化分支里销毁重建。
// =============================================================================
static VkImage g_diLinearImages[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkDeviceMemory g_diLinearMemories[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageView g_diLinearViews[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageLayout g_diLinearLayouts[2] = {
    VK_IMAGE_LAYOUT_UNDEFINED,
    VK_IMAGE_LAYOUT_UNDEFINED
};

static VkImage g_diVarianceImages[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkDeviceMemory g_diVarianceMemories[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
static VkImageView g_diVarianceViews[2] = { VK_NULL_HANDLE, VK_NULL_HANDLE };
