// =====================================================
// Frame generation base frame-rate cap
// =====================================================
//
// Refresh rate of the display the desktop currently runs on.  This game is
// borderless fullscreen, so the current desktop video mode is the display's
// real refresh rate.
static uint32_t QueryDisplayRefreshHz()
{
    DEVMODEW mode{};

    mode.dmSize =
        sizeof(mode);


    if(
        !EnumDisplaySettingsW(
            nullptr,
            ENUM_CURRENT_SETTINGS,
            &mode
        ) ||
        mode.dmDisplayFrequency <= 1
    )
    {
        return 0;
    }


    return static_cast<uint32_t>(
        mode.dmDisplayFrequency
    );
}


// Resolves the request into the Hz handed to Reflex.  Automatic pairing is
// refresh / multiplier: with N frames presented per rendered one, rendering
// faster than that only produces frames the pacer has to discard, while the
// latency of the extra rendering is kept.
static uint32_t ResolveFgBaseFrameLimitHz()
{
    // With a full-screen menu up, frame generation is off (see the present
    // path), so there is no multiplier to pair with: capping here would only
    // make the menu itself run at the paired rate.
    if(g_fgFullscreenMenuOpen.load())
    {
        return 0;
    }


    const int request =
        g_fgBaseFrameLimitRequest;


    if(request == 0)
    {
        return 0;
    }


    if(request > 0)
    {
        return static_cast<uint32_t>(
            request
        );
    }


    const uint32_t refresh =
        QueryDisplayRefreshHz();


    if(refresh == 0)
    {
        return 0;
    }


    const int requestedMultiplier =
        g_fgMultiplierRequested.load();


    const uint32_t multiplier =
        requestedMultiplier >= 2
            ? static_cast<uint32_t>(
                  requestedMultiplier
              )
            : 1u;


    const uint32_t hz =
        refresh / multiplier;


    return hz == 0
        ? 1u
        : hz;
}


static bool ApplyReflexMode(
    int mode)
{
    std::lock_guard<std::mutex>
        lock(g_reflexMutex);


    if(!g_reflexSupported ||
       !g_slReflexSetOptions)
    {
        return false;
    }


    sl::ReflexMode reflexMode;


    switch(mode)
    {
        case 0:
        {
            reflexMode =
                sl::ReflexMode::eOff;

            break;
        }

        case 1:
        {
            reflexMode =
                sl::ReflexMode::eLowLatency;

            break;
        }

        case 2:
        {
            reflexMode =
                sl::ReflexMode::eLowLatencyWithBoost;

            break;
        }

        default:
        {
            return false;
        }
    }


    sl::ReflexOptions options{};

    options.mode =
        reflexMode;

    // The limiter runs inside the frame-generation path, which is why it is the
    // tool Streamline names for pacing with DLSS-G.  With eOff the value is
    // inert, but it is still computed so the log shows what the pairing wants.
    const uint32_t baseLimitHz =
        ResolveFgBaseFrameLimitHz();

    options.frameLimitUs =
        baseLimitHz == 0
            ? 0u
            : static_cast<uint32_t>(
                  1000000.0 /
                  static_cast<double>(
                      baseLimitHz
                  )
              );

    // 2026-10-22（帧排序 P0）：让驱动利用 PCL marker 重排 CPU 工作与 present。
    // 前提是 marker 六段齐全且区间准确（Sim/RenderSubmit/Present 各一对，本项目已齐全）。
    // 关掉它就等于放弃 Reflex 唯一的"帧排序优化"能力。
    options.useMarkersToOptimize =
        true;

    // PCL 延迟统计热键。0 = 无热键（文档默认值）。
    //
    // 2026-10-22（Reflex 断链根因）：这里原本是 0x78u（VK_F9）。官方头文件
    // cpp/deps/streamline/include/sl_reflex.h:55 把这个字段限死为三个值：
    //     "Possible values: VK_F13, VK_F14, VK_F15"
    // 传 F9 让 slReflexSetOptions 直接返回 eErrorInvalidParameter(25) ⇒
    // Reflex **从未生效** ⇒ DLSS-G 报 status=2（eFailReflexNotDetectedAtRuntime）
    // ⇒ frameLimitUs 从未下发 ⇒ 2x 帧生成完全没有节流。
    // 现场（2026-10-22 21:52 那局）：[REFLEX] SetOptions FAILED mode=1 result=25。
    //
    // 要热键只能填 VK_F13(0x7C) / VK_F14(0x7D) / VK_F15(0x7E)，普通键位非法。
    options.virtualKey =
        0u;

    g_fgBaseFrameLimitHz.store(
        baseLimitHz
    );


    sl::Result result =
        g_slReflexSetOptions(
            options
        );


    if(result != sl::Result::eOk)
    {
        fprintf(
            stderr,
            "[REFLEX] SetOptions FAILED mode=%d result=%d\n",
            mode,
            static_cast<int>(result)
        );
        {
            // 2026-10-22：native stderr 不进 latest.log / rt_debug.log，这条失败
            // 只在控制台可见 ⇒ 补一条落盘 mirror（Reflex 断链时 DLSS-G 会报
            // status=2 = eFailReflexNotDetectedAtRuntime，没有这一行就只能看到
            // 结果、看不到原因）。用 Flushed 变体：失败后进程可能立刻消失。
            std::ostringstream reflexFailLog;

            reflexFailLog
                << "[REFLEX] SetOptions FAILED"
                << " mode=" << mode
                << " result=" << static_cast<int>(result);

            RTLogFlushed(reflexFailLog.str());
        }

        return false;
    }


    g_reflexMode =
        mode;


    fprintf(
        stderr,
        "[REFLEX] mode applied=%d baseLimitHz=%u frameLimitUs=%u\n",
        mode,
        baseLimitHz,
        options.frameLimitUs
    );

    fflush(stderr);


    // Mirrored so the pairing is verifiable from run/rt_debug.log: native
    // stderr never reaches that file.
    {
        std::ostringstream reflexLog;

        reflexLog
            << "[REFLEX]"
            << " mode=" << mode
            << " baseLimitHz=" << baseLimitHz
            << " frameLimitUs=" << options.frameLimitUs
            << " request=" << g_fgBaseFrameLimitRequest;

        RTLog(reflexLog.str());
    }


    return true;
}


// Recomputes and re-pushes the cap.  Called whenever the inputs it depends on
// change - the multiplier, or the request itself - because Reflex only sees the
// value that was sent with the last slReflexSetOptions call.
static void RefreshFgBaseFrameLimit()
{
    const uint32_t hz =
        ResolveFgBaseFrameLimitHz();


    g_fgBaseFrameLimitHz.store(
        hz
    );


    if(g_reflexMode == 0)
    {
        return;
    }


    ApplyReflexMode(
        g_reflexMode
    );
}
static bool SetCurrentPCLMarker(
    sl::PCLMarker marker)
{
    if(!g_pclSupported ||
       !g_slPCLSetMarker ||
       !g_currentSLFrameValid ||
       g_currentSLFrameToken == nullptr)
    {
        return false;
    }


    sl::Result result =
        g_slPCLSetMarker(
            marker,
            *g_currentSLFrameToken
        );


    if(result != sl::Result::eOk)
    {
        fprintf(
            stderr,
            "[PCL MARKER] FAILED"
            " marker=%u"
            " frame=%u"
            " result=%d\n",
            static_cast<unsigned int>(
                marker
            ),
            g_currentSLFrameIndex,
            static_cast<int>(
                result
            )
        );


        return false;
    }


    return true;
}


static bool MarkRenderSubmitStart()
{
    if(!g_currentSLFrameValid ||
       g_currentSLFrameToken == nullptr)
    {
        return false;
    }


    if(g_lastRenderSubmitStartFrame ==
       g_currentSLFrameIndex)
    {
        return true;
    }


    if(!SetCurrentPCLMarker(
        sl::PCLMarker::eRenderSubmitStart
    ))
    {
        return false;
    }


    g_lastRenderSubmitStartFrame =
        g_currentSLFrameIndex;


    static bool printed =
        false;


    if(!printed)
    {
        fprintf(
            stderr,
            "[PCL] RenderSubmitStart ACTIVE frame=%u\n",
            g_currentSLFrameIndex
        );

        printed =
            true;
    }


    return true;
}


static bool MarkRenderSubmitEnd()
{
    if(!g_currentSLFrameValid ||
       g_currentSLFrameToken == nullptr)
    {
        return false;
    }


    // 没有同帧 Start，就不发送孤立的 End。
    if(g_lastRenderSubmitStartFrame !=
       g_currentSLFrameIndex)
    {
        return false;
    }


    if(g_lastRenderSubmitEndFrame ==
       g_currentSLFrameIndex)
    {
        return true;
    }


    if(!SetCurrentPCLMarker(
        sl::PCLMarker::eRenderSubmitEnd
    ))
    {
        return false;
    }


    g_lastRenderSubmitEndFrame =
        g_currentSLFrameIndex;


    static bool printed =
        false;


    if(!printed)
    {
        fprintf(
            stderr,
            "[PCL] RenderSubmitEnd ACTIVE frame=%u\n",
            g_currentSLFrameIndex
        );

        printed =
            true;
    }


    return true;
}
// =====================================================
// 2026-10-22 显存口径采样：三个 feature 的 estimatedVRAMUsageInBytes
// 120 帧一次，零分配，放在 present 路径（DLSS-G 的 GetState 要求呈现线程）。
// =====================================================
static void SampleSlEstimatedVram()
{
    static uint32_t sampleFrameCounter = 0u;

    if((sampleFrameCounter++ % 120u) != 0u)
    {
        return;
    }

    if(g_dlssReady && g_slDLSSGetState)
    {
        sl::DLSSState dlssState{};

        if(g_slDLSSGetState(g_dlssViewport, dlssState) == sl::Result::eOk)
        {
            g_slVramDlssBytes.store(dlssState.estimatedVRAMUsageInBytes);
        }
    }

    if(g_dlssRRReady && g_slDLSSDGetState)
    {
        sl::DLSSDState dlssdState{};

        if(g_slDLSSDGetState(g_dlssViewport, dlssdState) == sl::Result::eOk)
        {
            g_slVramDlssdBytes.store(dlssdState.estimatedVRAMUsageInBytes);
        }
    }

    if(g_dlssGReady && g_slDLSSGGetState)
    {
        sl::DLSSGState dlssgState{};

        if(g_slDLSSGGetState(g_dlssViewport, dlssgState, nullptr) == sl::Result::eOk)
        {
            g_slVramDlssgBytes.store(dlssgState.estimatedVRAMUsageInBytes);
        }
    }
}


static bool MarkPresentStart()
{
    SampleSlEstimatedVram();

    if(!g_currentSLFrameValid ||
       g_currentSLFrameToken == nullptr)
    {
        return false;
    }


    // 正常帧必须已经完成同一帧的 RenderSubmit。
    // 防止 renderFrame(false) 等额外渲染拿旧 token 发 Present。
    if(g_lastRenderSubmitEndFrame !=
       g_currentSLFrameIndex)
    {
        return false;
    }


    if(g_lastPresentStartFrame ==
       g_currentSLFrameIndex)
    {
        return true;
    }


    if(!SetCurrentPCLMarker(
        sl::PCLMarker::ePresentStart
    ))
    {
        return false;
    }


    g_lastPresentStartFrame =
        g_currentSLFrameIndex;


    static bool printed =
        false;


    if(!printed)
    {
        fprintf(
            stderr,
            "[PCL] PresentStart ACTIVE frame=%u\n",
            g_currentSLFrameIndex
        );

        printed =
            true;
    }


    return true;
}


static bool MarkPresentEnd()
{
    if(!g_currentSLFrameValid ||
       g_currentSLFrameToken == nullptr)
    {
        return false;
    }


    // 没有同帧 PresentStart，不发送孤立 End。
    if(g_lastPresentStartFrame !=
       g_currentSLFrameIndex)
    {
        return false;
    }


    if(g_lastPresentEndFrame ==
       g_currentSLFrameIndex)
    {
        return true;
    }


    if(!SetCurrentPCLMarker(
        sl::PCLMarker::ePresentEnd
    ))
    {
        return false;
    }


    g_lastPresentEndFrame =
        g_currentSLFrameIndex;


    static bool printed =
        false;


    if(!printed)
    {
        fprintf(
            stderr,
            "[PCL] PresentEnd ACTIVE frame=%u\n",
            g_currentSLFrameIndex
        );

        printed =
            true;
    }


    return true;
}


static bool BeginStreamlineFrame()
{
    if(!g_slInitialized ||
       !g_reflexSupported ||
       !g_slGetNewFrameToken ||
       !g_slReflexSleep)
    {
        g_currentSLFrameToken =
            nullptr;

        g_currentSLFrameValid =
            false;

        return false;
    }


    const uint32_t frameIndex =
        g_nextSLFrameIndex++;


    sl::FrameToken* frameToken =
        nullptr;


    sl::Result tokenResult =
        g_slGetNewFrameToken(
            frameToken,
            &frameIndex
        );


    if(tokenResult != sl::Result::eOk ||
       frameToken == nullptr)
    {
        g_currentSLFrameToken =
            nullptr;

        g_currentSLFrameValid =
            false;


        fprintf(
            stderr,
            "[REFLEX FRAME] GetFrameToken FAILED"
            " frame=%u result=%d\n",
            frameIndex,
            static_cast<int>(
                tokenResult
            )
        );


        return false;
    }


    g_currentSLFrameToken =
        frameToken;

    g_currentSLFrameIndex =
        frameIndex;

    g_currentSLFrameValid =
        true;


    sl::Result sleepResult =
        g_slReflexSleep(
            *g_currentSLFrameToken
        );


    if(sleepResult != sl::Result::eOk)
    {
        fprintf(
            stderr,
            "[REFLEX SLEEP] FAILED"
            " frame=%u result=%d\n",
            g_currentSLFrameIndex,
            static_cast<int>(
                sleepResult
            )
        );
    }
    else
    {
        static bool printedSleepSuccess =
            false;


        if(!printedSleepSuccess)
        {
            fprintf(
                stderr,
                "[REFLEX SLEEP] ACTIVE"
                " frame=%u result=0\n",
                g_currentSLFrameIndex
            );


            printedSleepSuccess =
                true;
        }
    }


    // 帧起点：FG 若被用户长期关闭（或显存超预算），在这里归还资源。
    MaybeReleaseFgResourcesOnIdle();


    return true;
}
static void initStreamlineInternal()
{
    if(g_device == VK_NULL_HANDLE)
    {
        fprintf(
            stderr,
            "[SL] No Vulkan device yet, skip\n"
        );

        fflush(stderr);
        return;
    }


    if(g_slDeviceConfigured)
    {
        fprintf(
            stderr,
            "[FG-3 EARLY VK]"
            " alreadyConfigured=1\n"
        );

        fflush(stderr);
        return;
    }


    fprintf(
        stderr,
        "[CPP] initStreamlineInternal ENTER\n"
    );
    fprintf(stderr,"[POINT 0] g_device=%p\n",(void*)g_device);
    VkDevice savedDevice = g_device;
    VkInstance savedInstance = g_instance;
    VkPhysicalDevice savedPhysical = g_physicalDevice;
    VkQueue savedQueue = g_queue;
    uint32_t savedQueueFamily = g_queueFamily;

    fprintf(stderr,
    "[SAVE BEFORE DLL] addr=%p value=%p\n",
    (void*)&g_device,
    (void*)g_device);

    fflush(stderr);

    if(!g_slInitialized || !g_slModule)
    {
        fprintf(
            stderr,
            "[SL] ERROR: Streamline was not initialized early before VkDevice creation\n"
        );

        fflush(stderr);
        return;
    }


    fprintf(
        stderr,
        "[SL] Early initialization confirmed, now configuring Vulkan device\n"
    );

    fflush(stderr);


    g_slInit=reinterpret_cast<PFN_slInit>(
        GetProcAddress(g_slModule,"slInit")
    );

    g_slShutdown=reinterpret_cast<PFN_slShutdown>(
        GetProcAddress(g_slModule,"slShutdown")
    );

    g_slSetVulkanInfo=reinterpret_cast<PFN_slSetVulkanInfo>(
        GetProcAddress(g_slModule,"slSetVulkanInfo")
    );

    g_slIsFeatureSupported=reinterpret_cast<PFN_slIsFeatureSupported>(
        GetProcAddress(g_slModule,"slIsFeatureSupported")
    );

    g_slSetFeatureLoaded=reinterpret_cast<PFN_slSetFeatureLoaded>(
        GetProcAddress(g_slModule,"slSetFeatureLoaded")
    );
    g_slGetFeatureFunction =
    reinterpret_cast<PFN_slGetFeatureFunction>(
        GetProcAddress(
            g_slModule,
            "slGetFeatureFunction"
        )
    );


    fprintf(stderr,
    "[SL FUNC CHECK] slGetFeatureFunction=%p\n",
    (void*)g_slGetFeatureFunction);

    fflush(stderr);

    g_slSetConstants =
reinterpret_cast<PFN_slSetConstants>(
    GetProcAddress(
        g_slModule,
        "slSetConstants"
    )
);
    g_slEvaluateFeature =
reinterpret_cast<PFN_slEvaluateFeature>(
    GetProcAddress(
        g_slModule,
        "slEvaluateFeature")
        );
    g_slGetNewFrameToken =
    reinterpret_cast<PFN_slGetNewFrameToken>(
        GetProcAddress(
            g_slModule,
            "slGetNewFrameToken"
        )
    );
    g_slSetTagForFrame =
    reinterpret_cast<PFN_slSetTagForFrame>(
        GetProcAddress(
            g_slModule,
            "slSetTagForFrame"
        )
    );
    g_slFreeResources =
    reinterpret_cast<PFN_slFreeResources>(
        GetProcAddress(
            g_slModule,
            "slFreeResources"
        )
    );



#define CHECK_SL_FUNC(x)\
if(!(x))\
{\
    std::cerr<<"SL MISSING FUNCTION: "<<#x<<std::endl;\
}


    CHECK_SL_FUNC(g_slInit);
    CHECK_SL_FUNC(g_slShutdown);
    CHECK_SL_FUNC(g_slSetVulkanInfo);
    CHECK_SL_FUNC(g_slSetFeatureLoaded);
    CHECK_SL_FUNC(g_slSetConstants);
    CHECK_SL_FUNC(g_slEvaluateFeature);
    CHECK_SL_FUNC(g_slGetNewFrameToken);
    CHECK_SL_FUNC(g_slSetTagForFrame);
    fprintf(
    stderr,
    "[FG-4.2 TAG API]"
    " slSetTagForFrame=%p\n",
    reinterpret_cast<void*>(
        g_slSetTagForFrame
    )
);

    fflush(stderr);

    std::cerr
<< "[SL FUNC]"
<< "\n slInit="
<< g_slInit
<< "\n slShutdown="
<< g_slShutdown
<< "\n slSetVulkanInfo="
<< g_slSetVulkanInfo
<< "\n slIsFeatureSupported="
<< g_slIsFeatureSupported
    << "\n slSetFeatureLoaded="
    << g_slSetFeatureLoaded
    << "\n slSetConstants="
    << g_slSetConstants
    << "\n slDLSSSetOptions="
    << g_slDLSSSetOptions
    << "\n slEvaluateFeature="
<< g_slGetNewFrameToken
<< std::endl;

    fprintf(stderr,
"[AFTER GetProcAddress] g_device=%p\n",
(void*)g_device);

    fflush(stderr);


    if(!g_slInit)
    {


        if(!g_slSetConstants)
        {
            std::cerr
            << "[SL] slSetConstants missing"
            << std::endl;
        }
        std::cerr
        << "[Native C++] Failed to extract slInit."
        << std::endl;
        return;
    }
    if(!g_slEvaluateFeature)
    {
        fprintf(stderr,
        "[SL] slEvaluateFeature missing\n");
        fflush(stderr);
        return;
    }

    sl::Result r =
        sl::Result::eOk;


    std::cout
        << "[SL] slInit already completed during early initialization"
        << std::endl;

// =====================================================
// FG-2.12
// Provide the exact Streamline-reserved Vulkan queues.
//
// Queue plan was calculated before vkCreateDevice()
// and bridged to C++ by FG-2.11.
// =====================================================

if(!g_slQueuePlanReady)
{
    fprintf(
        stderr,
        "[FG-2.12 SL VKINFO]"
        " queuePlanReady=0"
        " ABORT\n"
    );

    fflush(stderr);
    return;
}


sl::VulkanInfo vkInfo{};

vkInfo.device =
    savedDevice;

vkInfo.instance =
    savedInstance;

vkInfo.physicalDevice =
    savedPhysical;


// -----------------------------------------------------
// Streamline Graphics queues
//
// family 0:
//   q0 = Minecraft
//   q1 = first SL queue
// -----------------------------------------------------

vkInfo.graphicsQueueFamily =
    g_slGraphicsQueueFamily;

vkInfo.graphicsQueueIndex =
    g_slGraphicsQueueIndex;


// -----------------------------------------------------
// Streamline Compute queues
//
// family 2:
//   q0    = Minecraft
//   q1-q2 = Streamline
//
// VulkanInfo receives the STARTING index only.
// -----------------------------------------------------

vkInfo.computeQueueFamily =
    g_slComputeQueueFamily;

vkInfo.computeQueueIndex =
    g_slComputeQueueIndex;


// -----------------------------------------------------
// Native NVIDIA Optical Flow
// -----------------------------------------------------

vkInfo.useNativeOpticalFlowMode =
    g_slUseNativeOpticalFlow;


if(g_slUseNativeOpticalFlow)
{
    vkInfo.opticalFlowQueueFamily =
        g_slOpticalFlowQueueFamily;

    vkInfo.opticalFlowQueueIndex =
        g_slOpticalFlowQueueIndex;
}


// All VkDeviceQueueCreateInfo::flags used by the
// current host queue creation path are zero.
vkInfo.graphicsQueueCreateFlags =
    0;

vkInfo.computeQueueCreateFlags =
    0;

vkInfo.opticalFlowQueueCreateFlags =
    0;


fprintf(
    stderr,
    "[FG-2.12 SL VKINFO]"
    " ready=1"
    " G=%u:%u"
    " C=%u:%u"
    " OF=%u:%u"
    " nativeOF=%d"
    " flags=0/0/0\n",

    vkInfo.graphicsQueueFamily,
    vkInfo.graphicsQueueIndex,

    vkInfo.computeQueueFamily,
    vkInfo.computeQueueIndex,

    vkInfo.opticalFlowQueueFamily,
    vkInfo.opticalFlowQueueIndex,

    vkInfo.useNativeOpticalFlowMode
        ? 1
        : 0
);

fflush(stderr);


sl::Result vkResult =
    g_slSetVulkanInfo(
        vkInfo
    );


fprintf(
    stderr,
    "[FG-2.12 SL SET VULKAN INFO]"
    " result=%d\n",
    static_cast<int>(
        vkResult
    )
);

fflush(stderr);



    std::cout << "[SL] slSetVulkanInfo result=" << (int)vkResult << std::endl;
    if (vkResult != sl::Result::eOk)
    {
        return;
    }
    sl::AdapterInfo ai{};

    ai.vkPhysicalDevice =
        g_physicalDevice;


    sl::Result dlssSupport =
        g_slIsFeatureSupported(
            sl::kFeatureDLSS,
            ai
        );


    sl::Result dlssRRSupport =
        g_slIsFeatureSupported(
            sl::kFeatureDLSS_RR,
            ai
        );


    sl::Result reflexSupport =
        g_slIsFeatureSupported(
            sl::kFeatureReflex,
            ai
        );
    sl::Result dlssGSupport =
    g_slIsFeatureSupported(
        sl::kFeatureDLSS_G,
        ai
    );


    sl::Result pclSupport =
        g_slIsFeatureSupported(
            sl::kFeaturePCL,
            ai
        );


    g_dlssRRSupported =
        dlssRRSupport ==
        sl::Result::eOk;
    g_dlssGSupported =
    dlssGSupport ==
    sl::Result::eOk;

    fprintf(
    stderr,
    "[FG-1 SUPPORT]"
    " result=%d"
    " supported=%d\n",

    static_cast<int>(
        dlssGSupport
    ),

    g_dlssGSupported
        ? 1
        : 0
);

    fflush(stderr);

    {
        std::ostringstream fgSupportLog;

        fgSupportLog
            << "[FG-1 SUPPORT]"
            << " result=" << static_cast<int>(dlssGSupport)
            << " supported=" << (g_dlssGSupported ? 1 : 0);

        RTLog(fgSupportLog.str());
    }

    g_reflexSupported =
        reflexSupport == sl::Result::eOk;

    g_pclSupported =
        pclSupport == sl::Result::eOk;

    if(g_reflexSupported)
    {
        void* reflexSetOptionsFn =
            nullptr;

        sl::Result setOptionsFnResult =
            g_slGetFeatureFunction(
                sl::kFeatureReflex,
                "slReflexSetOptions",
                reflexSetOptionsFn
            );


        g_slReflexSetOptions =
            reinterpret_cast<PFN_slReflexSetOptions>(
                reflexSetOptionsFn
            );


        void* reflexGetStateFn =
            nullptr;

        sl::Result getStateFnResult =
            g_slGetFeatureFunction(
                sl::kFeatureReflex,
                "slReflexGetState",
                reflexGetStateFn
            );


        g_slReflexGetState =
            reinterpret_cast<PFN_slReflexGetState>(
                reflexGetStateFn
            );
        void* reflexSleepFn =
    nullptr;

        sl::Result sleepFnResult =
            g_slGetFeatureFunction(
                sl::kFeatureReflex,
                "slReflexSleep",
                reflexSleepFn
            );


        g_slReflexSleep =
            reinterpret_cast<PFN_slReflexSleep>(
                reflexSleepFn
            );


        fprintf(
            stderr,
            "[REFLEX FUNC]"
            " SetOptions result=%d ptr=%p"
            " GetState result=%d ptr=%p"
            " Sleep result=%d ptr=%p\n",

            static_cast<int>(
                setOptionsFnResult
            ),

            reinterpret_cast<void*>(
                g_slReflexSetOptions
            ),

            static_cast<int>(
                getStateFnResult
            ),

            reinterpret_cast<void*>(
                g_slReflexGetState
            ),

            static_cast<int>(
                sleepFnResult
            ),

            reinterpret_cast<void*>(
                g_slReflexSleep
            )
        );;
        {
            // 2026-10-22：同上。这三对 result/ptr 决定 Reflex 到底是
            // "特性不支持"（根本进不了这个 if）还是"插件在但取不到函数"。
            std::ostringstream reflexFuncLog;

            reflexFuncLog
                << "[REFLEX FUNC]"
                << " SetOptions result=" << static_cast<int>(setOptionsFnResult)
                << " ptr=" << reinterpret_cast<void*>(g_slReflexSetOptions)
                << " GetState result=" << static_cast<int>(getStateFnResult)
                << " ptr=" << reinterpret_cast<void*>(g_slReflexGetState)
                << " Sleep result=" << static_cast<int>(sleepFnResult)
                << " ptr=" << reinterpret_cast<void*>(g_slReflexSleep);

            RTLog(reflexFuncLog.str());
        }
    }
    if(g_reflexSupported &&
   g_slReflexGetState)
    {
        sl::ReflexState state{};


        sl::Result stateResult =
            g_slReflexGetState(
                state
            );


        if(stateResult == sl::Result::eOk)
        {
            g_reflexLowLatencyAvailable =
                state.lowLatencyAvailable;


            fprintf(
                stderr,
                "[REFLEX STATE] result=%d lowLatencyAvailable=%d latencyReportAvailable=%d\n",
                static_cast<int>(stateResult),
                state.lowLatencyAvailable ? 1 : 0,
                state.latencyReportAvailable ? 1 : 0
            );
        }
        else
        {
            g_reflexLowLatencyAvailable =
                false;


            fprintf(
                stderr,
                "[REFLEX STATE] FAILED result=%d\n",
                static_cast<int>(stateResult)
            );
        }
    }


    if(g_reflexLowLatencyAvailable)
    {
        ApplyReflexMode(
            1
        );
    }
    else if(g_reflexSupported)
    {
        ApplyReflexMode(
            0
        );
    }


    if(g_pclSupported &&
       g_slGetFeatureFunction)
    {
        void* pclSetMarkerFn =
            nullptr;


        sl::Result pclSetMarkerFnResult =
            g_slGetFeatureFunction(
                sl::kFeaturePCL,
                "slPCLSetMarker",
                pclSetMarkerFn
            );


        g_slPCLSetMarker =
            reinterpret_cast<PFN_slPCLSetMarker>(
                pclSetMarkerFn
            );


        fprintf(
            stderr,
            "[PCL FUNC] SetMarker result=%d ptr=%p\n",
            static_cast<int>(
                pclSetMarkerFnResult
            ),
            reinterpret_cast<void*>(
                g_slPCLSetMarker
            )
        );
    }
    fprintf(
        stderr,
        "[SL SUPPORT]"
        " DLSS=%d"
        " DLSS_RR=%d"
        " Reflex=%d"
        " PCL=%d\n",

        static_cast<int>(
            dlssSupport
        ),

        static_cast<int>(
            dlssRRSupport
        ),

        static_cast<int>(
            reflexSupport
        ),

        static_cast<int>(
            pclSupport
        )
    );
    {
        // 2026-10-22：slIsFeatureSupported 的原始返回值必须落盘。Reflex=%d 非 0
        // 就说明 Reflex 插件在这一版 DLL 下根本没被 Streamline 认出来。
        std::ostringstream slSupportLog;

        slSupportLog
            << "[SL SUPPORT]"
            << " DLSS=" << static_cast<int>(dlssSupport)
            << " DLSS_RR=" << static_cast<int>(dlssRRSupport)
            << " Reflex=" << static_cast<int>(reflexSupport)
            << " PCL=" << static_cast<int>(pclSupport);

        RTLog(slSupportLog.str());
    }

    sl::Result dlssLoad =
        sl::Result::eErrorFeatureNotSupported;


    if(dlssSupport == sl::Result::eOk &&
       kRequestDlssSrFeature)
    {
        dlssLoad =
            g_slSetFeatureLoaded(
                sl::kFeatureDLSS,
                true
            );

        fprintf(
            stderr,
            "[SL] DLSS loaded result=%d\n",
            static_cast<int>(dlssLoad)
        );
    }
    if (dlssLoad == sl::Result::eOk)
    {
        void* dlssSetOptionsFn = nullptr;

        sl::Result featureFnResult =
            g_slGetFeatureFunction(
                sl::kFeatureDLSS,
                "slDLSSSetOptions",
                dlssSetOptionsFn
            );

        g_slDLSSSetOptions =
            reinterpret_cast<PFN_slDLSSSetOptions>(
                dlssSetOptionsFn
            );
        void* dlssOptimalFn = nullptr;

        sl::Result optimalFnResult =
            g_slGetFeatureFunction(
                sl::kFeatureDLSS,
                "slDLSSGetOptimalSettings",
                dlssOptimalFn
            );

        g_slDLSSGetOptimalSettings =
            reinterpret_cast<PFN_slDLSSGetOptimalSettings>(
                dlssOptimalFn
            );

        void* dlssGetStateFn = nullptr;

        g_slGetFeatureFunction(
            sl::kFeatureDLSS,
            "slDLSSGetState",
            dlssGetStateFn
        );

        g_slDLSSGetState =
            reinterpret_cast<PFN_slDLSSGetState>(
                dlssGetStateFn
            );

        std::cerr
            << "[SL] GetFeatureFunction slDLSSGetOptimalSettings result="
            << std::dec
            << (int)optimalFnResult
            << " ptr="
            << g_slDLSSGetOptimalSettings
            << std::endl;

        std::cerr
            << "[SL] GetFeatureFunction slDLSSSetOptions result="
            << (int)featureFnResult
            << " ptr="
            << g_slDLSSSetOptions
            << std::endl;


        if(featureFnResult == sl::Result::eOk &&
           g_slDLSSSetOptions != nullptr)
        {
            g_dlssReady = true;

            std::cout
                << "[DLSS] READY = TRUE"
                << std::endl;
        }
        else
        {
            g_dlssReady = false;

            std::cerr
                << "[DLSS] READY = FALSE - slDLSSSetOptions unavailable"
                << std::endl;
        }
    }
    else
    {
        g_dlssReady = false;

        std::cout
            << "[DLSS] READY = FALSE"
            << std::endl;
    }
    // =====================================================
// DLSS Ray Reconstruction feature load
//
// RR-1:
// 只验证 plugin / support / exported feature functions。
// 此处不调用 SetOptions，不 Evaluate。
// =====================================================

sl::Result dlssRRLoad =
    sl::Result::eErrorFeatureNotSupported;


if(dlssRRSupport == sl::Result::eOk)
{
    dlssRRLoad =
        g_slSetFeatureLoaded(
            sl::kFeatureDLSS_RR,
            true
        );


    fprintf(
        stderr,
        "[SL RR] DLSS_RR loaded result=%d\n",
        static_cast<int>(
            dlssRRLoad
        )
    );
}


if(dlssRRLoad == sl::Result::eOk)
{
    void* dlssdSetOptionsFn =
        nullptr;


    sl::Result rrSetOptionsFnResult =
        g_slGetFeatureFunction(
            sl::kFeatureDLSS_RR,
            "slDLSSDSetOptions",
            dlssdSetOptionsFn
        );


    g_slDLSSDSetOptions =
        reinterpret_cast<
            PFN_slDLSSDSetOptions
        >(
            dlssdSetOptionsFn
        );


    void* dlssdOptimalFn =
        nullptr;


    sl::Result rrOptimalFnResult =
        g_slGetFeatureFunction(
            sl::kFeatureDLSS_RR,
            "slDLSSDGetOptimalSettings",
            dlssdOptimalFn
        );


    g_slDLSSDGetOptimalSettings =
        reinterpret_cast<
            PFN_slDLSSDGetOptimalSettings
        >(
            dlssdOptimalFn
        );


    void* dlssdGetStateFn =
        nullptr;


    g_slGetFeatureFunction(
        sl::kFeatureDLSS_RR,
        "slDLSSDGetState",
        dlssdGetStateFn
    );


    g_slDLSSDGetState =
        reinterpret_cast<
            PFN_slDLSSDGetState
        >(
            dlssdGetStateFn
        );


    fprintf(
        stderr,
        "[SL RR FUNC]"
        " slDLSSDSetOptions"
        " result=%d ptr=%p\n",

        static_cast<int>(
            rrSetOptionsFnResult
        ),

        reinterpret_cast<void*>(
            g_slDLSSDSetOptions
        )
    );


    fprintf(
        stderr,
        "[SL RR FUNC]"
        " slDLSSDGetOptimalSettings"
        " result=%d ptr=%p\n",

        static_cast<int>(
            rrOptimalFnResult
        ),

        reinterpret_cast<void*>(
            g_slDLSSDGetOptimalSettings
        )
    );


    g_dlssRRReady =
        rrSetOptionsFnResult ==
            sl::Result::eOk &&
        rrOptimalFnResult ==
            sl::Result::eOk &&
        g_slDLSSDSetOptions !=
            nullptr &&
        g_slDLSSDGetOptimalSettings !=
            nullptr;


    fprintf(
        stderr,
        "[SL RR] READY=%d\n",
        g_dlssRRReady
            ? 1
            : 0
    );
}
else
{
    g_dlssRRReady =
        false;


    fprintf(
        stderr,
        "[SL RR] READY=0"
        " feature load unavailable\n"
    );
}





    std::cout
    << "[Native C++] slSetVulkanInfo result: "
    << (int)vkResult
    << std::endl;

    // if(g_slReflexSetOptions)
    // {
    //     sl::ReflexOptions options{};
    //
    //     options.mode = sl::eLowLatency;
    //
    //     sl::Result reflexResult =
    //         g_slReflexSetOptions(options);
    //
    //     std::cout
    //     << "[SL] ReflexSetOptions result="
    //     << (int)reflexResult
    //     << std::endl;
    // }


    printf(
    "[SL RESULT] init=%d vulkan=%d\n",
    (int)r,
    (int)vkResult
    );

    {
        std::ostringstream slResultLog;

        slResultLog
            << "[SL RESULT]"
            << " init=" << (int)r
            << " vulkan=" << (int)vkResult;

        RTLog(slResultLog.str());
    }
    g_slDeviceConfigured =
    vkResult ==
    sl::Result::eOk;


    const bool proxyReady =
        g_slDeviceConfigured &&
        ResolveSLVulkanProxies();


    fprintf(
        stderr,
        "[FG-3 EARLY VK]"
        " configured=%d"
        " proxies=%d\n",

        g_slDeviceConfigured
            ? 1
            : 0,

        proxyReady
            ? 1
            : 0
    );

    fflush(stderr);

    }
