// =====================================================
// LOD role table + near-field coverage publication
// =====================================================
//
// Both live here, next to the instance build that fills them, because both need
// the DH spatial-key set (defined with the DH LOD upload path above).

// packSectionKey stores x in bits 0..21 and z in bits 22..43 as masked 22-bit
// two's-complement fields, so both need an explicit sign extension back.
static int32_t sectionKeyColumnX(uint64_t spatialKey)
{
    const uint32_t raw =
        static_cast<uint32_t>(spatialKey & 0x3FFFFFull);

    return static_cast<int32_t>(raw << 10) >> 10;
}

static int32_t sectionKeyColumnZ(uint64_t spatialKey)
{
    const uint32_t raw =
        static_cast<uint32_t>((spatialKey >> 22) & 0x3FFFFFull);

    return static_cast<int32_t>(raw << 10) >> 10;
}

// The single source of truth for "what kind of geometry is this instance".
// The two LOD pseudo-section families share one reserved-Y band, so the band
// only says "LOD"; the DH key set separates DH from Voxy inside it.
//
// DH membership is answered from g_dhLodSpatialSnapshot, not from a single
// "current" key: since 2026-10-01 the far field is uploaded per section and
// therefore owns many keys at once.
static uint32_t sectionRoleOf(const RTSectionAS& section)
{
    const bool lodSpatialKey =
        (section.sectionKey & VOXY_LOD_RESERVED_Y) == VOXY_LOD_RESERVED_Y;

    if(!lodSpatialKey)
    {
        return SECTION_ROLE_TERRAIN;
    }

    const uint64_t instanceSpatialKey =
        section.sectionKey & SPATIAL_SECTION_KEY_MASK;

    return isDhLodSpatialKey(instanceSpatialKey)
        ? SECTION_ROLE_DH_FAR
        : SECTION_ROLE_VOXY_LOD;
}

// Publishes the role of the Section that owns this slot.  Written on every
// rebuild rather than once per slot, because a recycled slot can be handed to a
// Section of a different kind (and because a DH section can be removed and a
// fresh spatial key allocated for a different section in its place).
static void writeSectionRoleSlot(const RTSectionAS& section)
{
    if(g_sectionRoleMapped == nullptr ||
       !section.hasVertexAddressSlot ||
       section.vertexAddressSlot >= SECTION_VERTEX_ADDRESS_SLOT_LIMIT)
    {
        return;
    }

    static_cast<uint32_t*>(
        g_sectionRoleMapped
    )[section.vertexAddressSlot] = sectionRoleOf(section);
}

// Rebuilds the per-column near-field coverage bitmap from this rebuild's
// near-field Sections.  The grid is their column bounding box, padded by one
// column and clamped to LOD_COVERAGE_MAX_SIZE, so "outside the grid" and
// "inside but no Section" both read back as not covered -- the far field stays
// visible there.  An empty near-field set publishes a zero header, which the
// shader reads as "no coverage data, dedup nothing".
static void rebuildLodCoverage(
    const std::vector<RTSectionAS*>& orderedSections
)
{
    if(g_lodCoverageMapped == nullptr || g_lodCoverageWordCount == 0)
    {
        return;
    }

    const size_t coverageBytes =
        sizeof(LodCoverageHeader) +
        static_cast<size_t>(g_lodCoverageWordCount) * sizeof(uint32_t);

    std::memset(g_lodCoverageMapped, 0, coverageBytes);

    LodCoverageHeader* header =
        static_cast<LodCoverageHeader*>(g_lodCoverageMapped);

    uint32_t* words =
        reinterpret_cast<uint32_t*>(header + 1);

    int32_t minX = 0;
    int32_t minZ = 0;
    int32_t maxX = 0;
    int32_t maxZ = 0;

    bool anyNearField = false;

    for(const RTSectionAS* section : orderedSections)
    {
        if(sectionRoleOf(*section) != SECTION_ROLE_TERRAIN)
        {
            continue;
        }

        const uint64_t spatialKey =
            section->sectionKey & SPATIAL_SECTION_KEY_MASK;

        const int32_t columnX = sectionKeyColumnX(spatialKey);
        const int32_t columnZ = sectionKeyColumnZ(spatialKey);

        if(!anyNearField)
        {
            minX = maxX = columnX;
            minZ = maxZ = columnZ;
            anyNearField = true;
            continue;
        }

        minX = std::min(minX, columnX);
        maxX = std::max(maxX, columnX);
        minZ = std::min(minZ, columnZ);
        maxZ = std::max(maxZ, columnZ);
    }

    if(!anyNearField)
    {
        return;
    }

    --minX;
    --minZ;
    ++maxX;
    ++maxZ;

    const int32_t sizeX = std::min(maxX - minX + 1, LOD_COVERAGE_MAX_SIZE);
    const int32_t sizeZ = std::min(maxZ - minZ + 1, LOD_COVERAGE_MAX_SIZE);

    header->originChunkX = minX;
    header->originChunkZ = minZ;
    header->sizeX = sizeX;
    header->sizeZ = sizeZ;

    for(const RTSectionAS* section : orderedSections)
    {
        if(sectionRoleOf(*section) != SECTION_ROLE_TERRAIN)
        {
            continue;
        }

        const uint64_t spatialKey =
            section->sectionKey & SPATIAL_SECTION_KEY_MASK;

        const int32_t relativeX = sectionKeyColumnX(spatialKey) - minX;
        const int32_t relativeZ = sectionKeyColumnZ(spatialKey) - minZ;

        if(relativeX < 0 || relativeX >= sizeX ||
           relativeZ < 0 || relativeZ >= sizeZ)
        {
            continue;
        }

        const uint32_t index =
            static_cast<uint32_t>(relativeZ) *
                static_cast<uint32_t>(sizeX) +
            static_cast<uint32_t>(relativeX);

        words[index / 4u] |=
            LOD_COVERAGE_FLAG_NEAR_READY << ((index % 4u) * 8u);
    }
}

// =====================================================
// 2026-10-09：[RT MEM] 内存记账（诊断行）。
//
// 为什么需要它：用户报"玩久了会直接占满内存"。此前本文件**没有任何**内存口径
// （`[ALLOC FAIL]` 从未出现过 ⇒ 显存分配没失败过 ⇒ 不是显存爆），所以既不能说
// 是哪个结构在涨，也不能说是涨在原生侧还是 Java 堆 / 驱动里。
//
// 判读（这一行给的就是这三种切分）：
//   · rssMB 随时间单调上升，而下列各项之和基本不变
//       ⇒ 涨在**本行没记到的地方**（Java 堆、Vulkan 驱动、或本文件的漏记结构）；
//   · 某一项与 rssMB 同步单调上升（最可能是 meshMB / rawMB / queued）
//       ⇒ 就是它，按持有者去查删除路径；
//   · 全部平稳、只有 sysAvailMB 在掉
//       ⇒ 是别的进程/别的消费者，不是本模组。
//
// 语义说明：
//   · meshMB = g_chunkMeshes 的顶点字节（CPU 侧权威镜像）
//   · rawMB  = g_chunkRawPayloads 的**原始**字节：每层再存一份未打包副本，用于
//              上传前 memcmp 去重 ⇒ 与 meshMB 同量级是**设计如此**，不是泄漏。
//   · 这些量都是世界规模的函数，探索得越远越大属正常；**要看的是它是否收敛**。
//   · 每 600 帧（≈10s）一行，与 [RT GEOMETRY] counters 同频，方便两条时间线对齐。
// =====================================================
static void logNativeMemoryReport()
{
    PROCESS_MEMORY_COUNTERS memCounters{};
    const bool haveProcessMemory =
        GetProcessMemoryInfo(
            GetCurrentProcess(),
            &memCounters,
            sizeof(memCounters)
        ) != FALSE;

    MEMORYSTATUSEX systemMemory{};
    systemMemory.dwLength = sizeof(systemMemory);
    const bool haveSystemMemory =
        GlobalMemoryStatusEx(&systemMemory) != FALSE;

    // 2026-10-09：**显存口径**（VK_EXT_memory_budget）。这是判断"涨在显存还是涨在
    // 主机内存"的唯一直接证据 —— 上一轮的实测把嫌疑指到了记账之外：rssMB 涨 6.8GB、
    // privateMB 比 rssMB 多出约 5GB，而 Java 堆与原生各结构全都平稳。多出来的那部分
    // 正是 WDDM 为 DEVICE_LOCAL 提交的系统内存。驱动不支持该扩展时字段保持 0。
    // 2026-10-13：这段查询抽成了 queryVramBudget()（定义见本文件 slab 池那一节之前），
    // 因为**闸门要用同一份口径** —— 两处各算一次迟早会漂移。上面的说明仍然成立，
    // 这里只留调用；驱动不支持该扩展时两个字段保持 0。
    VramBudgetSample vramSample;
    queryVramBudget(vramSample);

    const double vramUsedMb = vramSample.usedMb;
    const double vramBudgetMb = vramSample.budgetMb;

    size_t meshSectionCount = 0u;
    size_t meshBytes = 0u;
    size_t rawBytes = 0u;
    size_t ommInputCount = 0u;
    size_t ommBytes = 0u;
    size_t dirtyKeyCount = 0u;

    {
        std::lock_guard<std::timed_mutex> lock(g_chunkMutex);

        meshSectionCount = g_chunkMeshes.size();

        for(const auto& entry : g_chunkMeshes)
        {
            meshBytes += entry.second.size() * sizeof(Vertex);
        }

        for(const auto& entry : g_chunkRawPayloads)
        {
            rawBytes += entry.second.size();
        }

        ommInputCount = g_cutoutOmmInputs.size();

        // 2026-10-09：OMM 输入**字节数**。上一版只报了条数 omm=，而每条是
        // 三角形数 × 64B、实测 ~1.1MB ⇒ 约 1000 条就是 1.1GB 的 CPU 侧常驻，
        // 是我自己的记账缺口（RSS 涨了 6.8GB 而我只解释了 1.5GB）。
        // 另外 GPU 侧每个 Section 还会复制一份同尺寸的 ommDataBuffer（见
        // createSectionOpacityMicromap）⇒ 实际是两倍量级。
        for(const auto& entry : g_cutoutOmmInputs)
        {
            ommBytes += entry.second.data.size();
        }

        dirtyKeyCount = g_dirtySectionKeys.size();
    }

    // g_lightMutex 与 g_chunkMutex 之间**没有**全局锁序约定 ⇒ 必须分开取，
    // 绝不嵌套（与任一持有者反向就是死锁）。
    size_t lightSectionCount = 0u;
    size_t lightCount = 0u;
    size_t lightBytes = 0u;

    {
        std::lock_guard<std::mutex> lock(g_lightMutex);

        lightSectionCount = g_lightSections.size();

        for(const auto& entry : g_lightSections)
        {
            lightCount += entry.second.size();
            lightBytes += entry.second.size() * sizeof(LocalLightRecord);
        }
    }

    size_t capturedCount = 0u;

    {
        std::lock_guard<std::mutex> lock(g_capturedSectionsMutex);
        capturedCount = g_capturedSections.size();
    }

    // 以下三项只有渲染线程读写（本函数只从渲染线程调用）⇒ 不需要锁。
    const size_t blasCount = g_sectionBLAS.size();
    const size_t voxySourceCount = g_voxyLodSources.size();

    const auto toMb =
        [](size_t bytes)
        {
            return static_cast<double>(bytes) / 1048576.0;
        };

    // 2026-10-10：Vulkan 分配总账（见 rtxTrackedAllocateMemory 的说明）。
    const RtxMemAccountSnapshot vkMem = rtxMemAccountSnapshot();

    // 2026-10-13（核实 1 / RTXMU 可行性）：Section AS 的"真实需求 vs 实际占用"。
    //
    // 动机：这个 section 的顶点缓冲与 BLAS 共享一块 slab chunk，而 chunk 是 **2 的幂**
    // （sectionMemoryPoolBucketExp）⇒ `slabAllocMB − slabFreeMB` 里既有真 BLAS、也有
    // 取整浪费，读不出来是哪个。所以按**活的** g_sectionBLAS 直接求和：
    //   asBlasMB  = Σ blasBytes                       —— **RTXMU 压缩能作用的上限**
    //   asTrueMB  = Σ(vertexBytes + blasBytes)        —— 真正需要的字节
    //   asChunkMB = Σ sectionMemoryChunkBytes         —— slab 实际切给它的字节
    //   asWasteMB = asChunkMB − asTrueMB              —— 取整浪费
    // 判读：asWasteMB 若与 asBlasMB 同量级 ⇒ 先改桶策略（更便宜、不需要引入 SDK）；
    //       asBlasMB 若 ~1.7GB ⇒ RTXMU 的 52% 大约就是 0.85GB，值得做。
    VkDeviceSize asBlasBytes = 0u;
    VkDeviceSize asTrueBytes = 0u;
    VkDeviceSize asChunkBytes = 0u;

    for(const auto& asEntry : g_sectionBLAS)
    {
        const RTSectionAS& asSection = asEntry.second;

        asBlasBytes += asSection.blasBytes;
        asTrueBytes += asSection.vertexBytes + asSection.blasBytes;
        asChunkBytes += asSection.sectionMemoryChunkBytes;
    }

    // 2026-10-13（乙-4）：Section 构建暂存池明细。这是 churnTop 里那笔
    // "use=0x1 liveN=3 liveMB≈820" 的**直接来源**（纯 TRANSFER_SRC + 主机可见）。
    // 读法：total 是池当前持有的字节（只涨不落 ⇒ "只增不减"在发生）；
    //       inflight 是在飞块数（受 GPU 流水线深度决定、不可释放）；
    //       count - inflight 才是越线时能被 trimIdleKeepingLargest 收回的部分。
    size_t vtxStageCount = 0u;
    VkDeviceSize vtxStageBytes = 0u;
    size_t vtxStageInFlight = 0u;
    g_vertexStagingPool.stats(vtxStageCount, vtxStageBytes, vtxStageInFlight);

    size_t blasScratchCount = 0u;
    VkDeviceSize blasScratchBytes = 0u;
    size_t blasScratchInFlight = 0u;
    g_blasScratchPool.stats(
        blasScratchCount,
        blasScratchBytes,
        blasScratchInFlight
    );

    // 2026-10-10：抖动归因（最热的 4 个 usage），见 rtxBufferChurnTopReport。
    // 2026-10-13（乙-6）：4 → **12**。现场：判"谁是那 820MB 主机可见暂存"时，top4 里
    // 只有一条 use=0x1 liveMB=820.5，其余消费方全被截断 ⇒ 读不出完整构成。
    // 12 条足以覆盖所有实际出现过的 usage，且这一行本来就只有每 ~10s 一条。
    const std::string vkChurn = rtxBufferChurnTopReport(12u);

    std::ostringstream report;
    report << std::fixed << std::setprecision(1)
        << "[RT MEM]"
        << " rssMB="
        << (haveProcessMemory ? toMb(memCounters.WorkingSetSize) : -1.0)
        << " peakRssMB="
        << (haveProcessMemory ? toMb(memCounters.PeakWorkingSetSize) : -1.0)
        << " privateMB="
        << (haveProcessMemory ? toMb(memCounters.PagefileUsage) : -1.0)
        << " sysAvailMB="
        << (haveSystemMemory
                ? static_cast<double>(systemMemory.ullAvailPhys) / 1048576.0
                : -1.0)
        << " sysTotalMB="
        << (haveSystemMemory
                ? static_cast<double>(systemMemory.ullTotalPhys) / 1048576.0
                : -1.0)
        << " vramUsedMB=" << vramUsedMb
        << " vramBudgetMB=" << vramBudgetMb
        // SL/NGX 自管显存（约 2s 采样一次，见 SampleSlEstimatedVram）。
        << " slDlssMB=" << toMb(static_cast<size_t>(g_slVramDlssBytes.load()))
        << " slRrdMB=" << toMb(static_cast<size_t>(g_slVramDlssdBytes.load()))
        << " slFgMB=" << toMb(static_cast<size_t>(g_slVramDlssgBytes.load()))
        << " slNgxMB=" << toMb(static_cast<size_t>(
               g_slVramDlssBytes.load() +
               g_slVramDlssdBytes.load() +
               g_slVramDlssgBytes.load()))
        << " | meshSec=" << meshSectionCount
        << " meshMB=" << toMb(meshBytes)
        << " rawMB=" << toMb(rawBytes)
        << " omm=" << ommInputCount
        << " ommMB=" << toMb(ommBytes)
        << " dirty=" << dirtyKeyCount
        << " lightSec=" << lightSectionCount
        << " lights=" << lightCount
        << " lightMB=" << toMb(lightBytes)
        << " queued=" << capturedCount
        << " blas=" << blasCount
        // 2026-10-13（核实 1）：BLAS 真实字节 / 真实需求 / 实际 chunk / 取整浪费。
        << " asBlasMB=" << toMb(asBlasBytes)
        << " asTrueMB=" << toMb(asTrueBytes)
        << " asChunkMB=" << toMb(asChunkBytes)
        << " asWasteMB="
        << toMb(
               asChunkBytes > asTrueBytes
                   ? asChunkBytes - asTrueBytes
                   : 0u
           )
        << " voxy=" << voxySourceCount
        << " slabKeptMB=" << toMb(g_sectionMemoryPoolKeptBytes)
        // 2026-10-11：slab 的累计分配/释放字节（不随窗口 reset）。
        // slabAllocMB 与 slabFreeMB 若以同速对涨 ⇒ 留用上限仍被顶穿（见其常量的说明）。
        << " slabAllocMB=" << toMb(g_sectionMemoryAllocateBytes)
        << " slabFreeMB=" << toMb(g_sectionMemoryFreeBytes)
        // 2026-10-13（乙-4）：Section 构建暂存池（见本函数里取值处的说明）。
        << " vtxStage=" << vtxStageCount << "/" << toMb(vtxStageBytes)
        << "MB(inflight=" << vtxStageInFlight << ")"
        << " blasScratch=" << blasScratchCount << "/" << toMb(blasScratchBytes)
        << "MB(inflight=" << blasScratchInFlight << ")"
        // 2026-10-10 Vulkan 分配总账：allocMB/freeMB 是累计量（应同步增长），
        // liveMB 才是泄漏指标；liveDeviceMB/liveHostMB 把 liveMB 按堆拆开。
        // vkLiveN / vkAllocN / vkFreeN 用来核对"个数是否也漏"。
        << " | vkAllocMB=" << toMb(vkMem.allocBytes)
        << " vkFreeMB=" << toMb(vkMem.freeBytes)
        << " vkLiveMB=" << toMb(vkMem.liveBytes)
        << " vkLiveDeviceMB=" << toMb(vkMem.liveDeviceLocalBytes)
        << " vkLiveHostMB=" << toMb(vkMem.liveHostBytes)
        << " vkLivePeakMB=" << toMb(vkMem.livePeakBytes)
        << " vkLiveN=" << vkMem.liveCount
        << " vkAllocN=" << vkMem.allocCount
        << " vkFreeN=" << vkMem.freeCount
        << " vkFreeUnknownN=" << vkMem.freeUnknownCount
        // 2026-10-15 对象创建总账（判读见 g_device 声明处的说明）。
        //
        // 为什么单列一组：vkAllocMB/vkFreeMB/vkLiveMB 只覆盖 VkDeviceMemory。实测
        // 出现过"vkAllocMB 95 秒逐字节冻结、NMT 平、JVM 平，而 rssMB 涨 2.7GB
        // （28.6MB/s、0.408MB/帧）"的窗口 ⇒ 增长来自不调 vkAllocateMemory 的对象。
        //
        // 读数：descSet/cmdBuf/pipe 是**对象数**（count 字段求和），其余是调用次数。
        //   · 某一项随会话单调涨 ⇒ 就是它，去那张未池化的表找；
        //   · 九项全平而 rssMB/privateMB 仍涨 ⇒ 不在 Vulkan 层，转去查驱动 /
        //     Streamline（VK_EXT_device_memory_report）。
        // 本组**不含**走 vkGetDeviceProcAddr 的 vkCreateRayTracingPipelinesKHR /
        // vkCreateAccelerationStructureKHR / vkCreateMicromapEXT（宏拦不住）。
        // ORION_MEM_OBJ_TRACK=0 时这九项恒 0（只转发、不计数）。
        << " | obj: descPool="
        << g_rtxMemObj.descPool.load(std::memory_order_relaxed)
        << " descSet="
        << g_rtxMemObj.descSet.load(std::memory_order_relaxed)
        << " cmdPool="
        << g_rtxMemObj.cmdPool.load(std::memory_order_relaxed)
        << " cmdBuf="
        << g_rtxMemObj.cmdBuf.load(std::memory_order_relaxed)
        << " layout="
        << g_rtxMemObj.layout.load(std::memory_order_relaxed)
        << " shader="
        << g_rtxMemObj.shader.load(std::memory_order_relaxed)
        << " pipe="
        << g_rtxMemObj.pipe.load(std::memory_order_relaxed)
        << " view="
        << g_rtxMemObj.view.load(std::memory_order_relaxed)
        << " sampler="
        << g_rtxMemObj.sampler.load(std::memory_order_relaxed)
        // 2026-10-15 对象创建总账②（说明见 g_device 声明处）。
        //
        // 读数要点（这一版才把"真漏"与"churn"分开）：
        //   · cmdBufLive = cmdBuf - cmdBufFree。总账①只有 create，看到"每帧 +1"
        //     无法判断是漏还是 churn；live 恒定 ⇒ churn（本身不该涨内存，但 WDDM
        //     下 free 不立刻还页这条本文件记录过两回，:15619 与 :8279 的 29~33MB/s），
        //     live 单调涨 ⇒ 真漏，直接就是根因。
        //   · asCreate/asDestroy、mmCreate/mmDestroy：加速结构 / 微图的 create 与
        //     destroy 成对 ⇒ churn；只涨不减 ⇒ 漏。这两类的存储来自 slab 子分配，
        //     不调 vkAllocateMemory，所以 vkAllocMB 冻结**挡不住**它们。
        //   · asBuildCmd：每窗口录进命令缓冲的 AS build 次数，用来判断
        //     "0.41~0.44MB 每个命令缓冲"这个量级是否讲得通。
        //   · fence/semaphore/queryPool：一级 API、不需要 VkDeviceMemory 的三类，
        //     属于"冻结窗口里还能产生宿主分配"的最后几个候选。
        // 若上面这些全平（含 as*），而 rssMB/privateMB 仍按 ≥19MB/s 涨 ⇒ 不在
        // Vulkan 层，转去驱动 / Streamline（VK_EXT_device_memory_report）。
        << " cmdBufFree="
        << g_rtxMemObj.cmdBufFree.load(std::memory_order_relaxed)
        << " fence="
        << g_rtxMemObj.fence.load(std::memory_order_relaxed)
        << " semaphore="
        << g_rtxMemObj.semaphore.load(std::memory_order_relaxed)
        << " queryPool="
        << g_rtxMemObj.queryPool.load(std::memory_order_relaxed)
        << " asCreate="
        << g_rtxMemObj.asCreate.load(std::memory_order_relaxed)
        << " asDestroy="
        << g_rtxMemObj.asDestroy.load(std::memory_order_relaxed)
        << " asBuildCmd="
        << g_rtxMemObj.asBuildCmd.load(std::memory_order_relaxed)
        << " mmCreate="
        << g_rtxMemObj.mmCreate.load(std::memory_order_relaxed)
        << " mmDestroy="
        << g_rtxMemObj.mmDestroy.load(std::memory_order_relaxed)
        // 抖动归因：use= 是 VkBufferUsageFlags，n/MB 是累计分配次数/字节，
        // liveN/liveMB 是当前仍存活的部分。高频 + live 小 = 纯抖动（要去池化）；
        // 高频 + live 单调涨 = 真漏。
        << " | churnTop:" << vkChurn;

    RTLog(report.str());
}


// =====================================================
// 2026-10-13（乙·一期）：几何非常驻化的参数与几何工具
//
// 现场（2026-10-13 15:21 那一局 [RT MEM]）：区块一高，meshSec 357 → 1137 → 峰值 2812，
// meshMB 峰值 585MB，blas 与 meshSec 近似 1:1，vkLiveDeviceMB 2106 → 3067（+960MB），
// vramUsedMB 5681 → 6642（ratio 0.809 → 0.971）。
// 一期（slab 清理 + VLI 上限）已经**跑满**——同期 [VRAM GOV] 显示 freedMB=224、
// slabKeptMB=0、vliEvicted=169——仍然压不住，因为涨的是**活的几何**。
//
// 所以二期让几何本身有界：超预算时把"离玩家最远、且不在阴影保留盒/视锥内"的 Section
// 的 GPU 侧释放，CPU 顶点（g_chunkMeshes）保留，玩家靠近时由补传重建。
// =====================================================

// 保护半径（格）：比它近的一律不驱逐。96 格保证"玩家周围一圈"完整，
// 也给补传留出缓冲带（补传阈值 = 本值，驱逐阈值 = 本值 × 1.25，中间那条带子防抖）。
static float vramEvictKeepRadius()
{
    static const float cached = []()
    {
        const char* raw = std::getenv("ORION_VRAM_EVICT_KEEP_RADIUS");

        if(raw == nullptr || raw[0] == '\0')
        {
            return 96.0f;
        }

        const double parsed = std::atof(raw);
        return (parsed >= 16.0 && parsed <= 512.0)
            ? static_cast<float>(parsed)
            : 96.0f;
    }();

    return cached;
}

// 迟滞：驱逐要求 distance > 保护半径 × 1.25，补传要求 distance < 保护半径。
constexpr float VRAM_EVICT_HYSTERESIS = 1.25f;

// 每批（每次重建）驱逐 / 补传的 Section 上限。补传是**重建**，一次塞太多会把这一帧
// 拖长（maxSectionMs 到过 92ms）；驱逐只是 retire + erase，可以多放一些。
static size_t vramEvictPerPass()
{
    static const size_t cached = []() -> size_t
    {
        const char* raw = std::getenv("ORION_VRAM_EVICT_PER_PASS");

        if(raw == nullptr || raw[0] == '\0')
        {
            // 刻意**小**：驱逐只在比率 > 0.85 时发生，而闸门每 30 次重建才重新采样
            // 一次 ⇒ 配额越大越容易过冲（把远超需要的几何也放掉，随后又要补传回来）。
            // 16/批 × ~30 批/秒 ≈ 480 段/秒，足够跟上 1~2GB 的缺口。
            return 16u;
        }

        const long parsed = std::atol(raw);
        return (parsed > 0 && parsed <= 4096)
            ? static_cast<size_t>(parsed)
            : 16u;
    }();

    return cached;
}

static size_t vramRehydratePerPass()
{
    static const size_t cached = []() -> size_t
    {
        const char* raw = std::getenv("ORION_VRAM_REHYDRATE_PER_PASS");

        if(raw == nullptr || raw[0] == '\0')
        {
            // 刻意**大**：补传是"玩家转回来时把地形补上"，恢复慢了就是可见的空缺。
            // 16/批 × ~30 批/秒 ≈ 480 段/秒 ⇒ 转身后不到一秒补回。
            // 代价是每帧多几次 Section 重建（单块 maxSectionMs 到过 92ms，但那是
            // 显存吃紧时的尾巴；这里已经在预算内，且分批摊开）。
            return 16u;
        }

        const long parsed = std::atol(raw);
        return (parsed > 0 && parsed <= 4096)
            ? static_cast<size_t>(parsed)
            : 16u;
    }();

    return cached;
}

// spatial Section 键 → 世界坐标中心（16 格/段 + 半格）。
// 键位布局见 packSectionKey：bits0..21=X、22..43=Z、44..59=Y（各自补码）。
static void vramSectionCenterFromSpatialKey(
    uint64_t spatialKey,
    float& outX,
    float& outY,
    float& outZ
)
{
    auto signExtend = [](uint64_t value, int bits) -> int {
        const uint64_t mask = 1ull << (bits - 1);
        return static_cast<int>((value ^ mask) - mask);
    };

    outX = static_cast<float>(signExtend(spatialKey & 0x3FFFFFull, 22)) * 16.0f + 8.0f;
    outZ = static_cast<float>(signExtend((spatialKey >> 22) & 0x3FFFFFull, 22)) * 16.0f + 8.0f;
    outY = static_cast<float>(signExtend((spatialKey >> 44) & 0xFFFFull, 16)) * 16.0f + 8.0f;
}

// 只处理"真实世界高度"的 Section：voxy LOD / DH LOD 与动态实体聚合共用保留 Y 段，
// 它们的 X/Z **不是世界坐标**（LOD 是哈希分配槽位）⇒ 对它算距离恒为天文数字。
// 与 TLAS 距离 / 视锥剔除用的是同一条判据（见 rebuildWorldGeometry 里的 ⚠⚠ 注释）。
static bool vramWorldHeightSection(uint64_t spatialKey)
{
    const int32_t sectionY =
        static_cast<int32_t>(
            (static_cast<uint32_t>(spatialKey >> 44) & 0xFFFFu) << 16) >> 16;

    return sectionY >= -64 && sectionY <= 512;
}


// 2026-10-21：重建入口取 g_chunkMutex 的等待预算（毫秒，0 = 退回旧的阻塞行为）。
// 见 rebuildWorldGeometry 里"有界取锁"一节的实测依据。
static int64_t geometryPreLoopLockWaitMs()
{
    static const int64_t cached = []() -> int64_t
    {
        const char* raw = std::getenv("ORION_GEOMETRY_LOCK_WAIT_MS");

        if(raw == nullptr || raw[0] == '\0')
        {
            return 3;
        }

        const long parsed = std::strtol(raw, nullptr, 10);

        if(parsed <= 0)
        {
            return 0;
        }

        return std::min<long>(parsed, 50);
    }();

    return cached;
}

// 连续让出次数：达到 5 次就退回阻塞取锁（见同处注释）。
static uint32_t g_geometryPreLoopLockSkips = 0u;

// 2026-10-22（第 3 条）：兜底等待的上限，毫秒。
// 取 12ms —— 略高于捕获线程单次唤醒的时间预算上限（sectionRebuildTimeBudgetMs
// 的 clamp 上界也是 12ms），所以正常情况下"最后一跳"就能等到。
constexpr int64_t SECTION_PRELOOP_LOCK_FALLBACK_MS = 12;

// === 核心逻辑：批量更新 Bindless 纹理描述符集 ===
// === 新增：全局几何体动态重建核心 ===
static bool rebuildWorldGeometry(
    size_t maxSectionUpdates
)
{
    if(
        g_device == VK_NULL_HANDLE ||
        g_rtCommandPool == VK_NULL_HANDLE ||
        g_queue == VK_NULL_HANDLE
    )
    {
        return true;
    }

    // 2026-10-08（BLAS 异步化）：懒启动几何捕获线程（幂等）。放在这里保证它只在
    // 设备/命令池就绪之后起来，且早于任何一次实际捕获。
    // ORION_SYNC_GEOMETRY=1 时它会直接返回 ⇒ 本函数走原来的同步捕获路径。
    ensureGeometryCaptureWorker();

    // 2026-10-08：重建调用计数（配合 counters 行算"每调用搬几块"）。
    g_geometryRebuildCallTotal += 1u;

    // =====================================================
    // 2026-10-10 周期性卡顿修复：入口闸门
    // =====================================================
    // 现场（2026-10-10 23:36~23:43 那一局，dynamicRtasInterval=1）：
    //   · rebuildCalls ≈ 35 次/秒，而 perCall 只有 0.1~0.7 —— 实体层每帧都请求重建，
    //     绕过了静默窗口与最小帧间隔（见 g_entityRebuildRequested 的调用点）；
    //   · 每次重建的尾巴里都要 vkWaitForFences 等**上一批**构建落地，而且是**无限等待**；
    //   · 实测 [PERF L10 STALL] sectionBuildFenceWait=485.01ms、counters 的 tailMs=503.0ms，
    //     [PERF L10 CPU] maxMs 周期性地 94~215ms、[PERF L10 CPUPHASE] maxMs geometry 45~81ms。
    // 也就是说：渲染线程每帧把自己挂在 GPU 的构建进度上，GPU 一落后就是几十~几百毫秒的
    // 硬卡顿 —— 这就是"周期性卡顿"。
    //
    // 修法：上一批的构建还没落地，就**不开新的一批**。这里是最早的安全点：除了上面那两行
    // 计数器，什么都还没碰（没捕获、没摘脏键、没取退役槽、没动 TLAS），所以直接让位是
    // 无副作用的；脏键与捕获队列原样留着，下一帧重新进来。
    //
    // 为什么不去调 dynamicRtasInterval：那会让实体 AS 按帧数掉档（实测视觉直接变 PPT）。
    // 这道闸门不降频率，只把"等"从渲染线程上拿掉 —— 重建节奏自动跟随 GPU 的消化速度：
    // GPU 追得上就照旧每帧一次，追不上就退回上一帧的结果而**不卡帧**。
    {
        // 2026-10-21：删掉了原来的 `!g_forceSectionASReset` 条件。
        //
        // 理由（机制，不是猜测）：该条件让"换世界后的第一批"跳过闸门。而换世界时
        // 上一批（旧世界）的 build 恰恰可能还在飞 —— 跳过闸门不会让它变快，只会把
        // "等它落地"从**这里**（有 2ms 上限、超时就 return false 让位）挪到尾部那次
        // 等待上去扛。让位本身无副作用（此时只动过两个计数器：没捕获、没摘脏键、
        // 没取退役槽、没碰 TLAS），所以世界加载最多晚一帧，比让渲染线程硬等便宜。
        const bool previousBuildPending =
            sectionRebuildFenceGateEnabled() &&
            g_sectionRetirementFencesReady &&
            g_sectionRetirementRing[g_currentRetirementSlot].fencePending;

        if(previousBuildPending)
        {
            const VkFence previousBuildFence =
                g_sectionRetirementFences[g_currentRetirementSlot];

            VkResult fenceStatus =
                vkGetFenceStatus(g_device, previousBuildFence);

            if(
                fenceStatus == VK_NOT_READY &&
                SECTION_REBUILD_FENCE_WAIT_MS > 0u
            )
            {
                // 常见情况是"就差一点点"：给一小段有限时间，能在本帧做完就别拖到下一帧。
                fenceStatus = vkWaitForFences(
                    g_device,
                    1,
                    &previousBuildFence,
                    VK_TRUE,
                    static_cast<uint64_t>(SECTION_REBUILD_FENCE_WAIT_MS) * 1000000ull
                );
            }

            if(
                fenceStatus == VK_NOT_READY ||
                fenceStatus == VK_TIMEOUT
            )
            {
                g_geometryFenceDeferredCount += 1u;
                return false;
            }

            check(
                fenceStatus,
                "poll previous Section build fence failed"
            );

            // 已经信号：顺手把该回收的退役槽收掉（见 reapSignaledRetirements）。
            reapSignaledRetirements();
        }
    }

    const auto perfL10RebuildStart =
        std::chrono::steady_clock::now();

    double perfL10QueueIdleMilliseconds =
        0.0;

    bool forceReset = false;

    std::vector<
        std::pair<
            uint64_t,
            SectionGeometrySplit
        >
    > sectionUpdates;

    // 2026-10-08：这里原来有一个与 geometryAppendSectionVertices() **逐行相同**的
    // 局部 lambda（`appendSectionVertices`）。它随"分类路由的两处手抄副本"一起删掉了
    // —— 现在全函数只有 geometryCaptureSectionLocked() 一个路由实现，追加顶点也只有
    // geometryAppendSectionVertices() 一个入口。


    // =====================================================
    // 2026-10-21 有界取锁（消除 preLoop 上的锁等待尖峰）
    //
    // 实测（10-21 19:56~20:00 同一局）：
    //   [RT GEOMETRY SLOW] total=87.3  pre=86.88  pCap=86.88
    //                      total=94.1  pre=93.51  pCap=93.50
    //                      total=39.9  pre=38.75  pCap=38.75
    // 整帧尖峰**全部**是取 g_chunkMutex 的等待（不是构建、不是上传本身）。
    // 与 Sodium "作业队列只做非阻塞取用"同向：拿不到就本帧不做，下一帧再来。
    //
    // 兜底：连续让出达到 5 次就退回阻塞取锁，保证几何不会因我们自己的守卫而停更。
    // A/B：ORION_GEOMETRY_LOCK_WAIT_MS=0 时退回改动前的阻塞行为（逐位一致）。
    // =====================================================
    const auto geometryLockWaitBudget =
        std::chrono::milliseconds(geometryPreLoopLockWaitMs());
    bool preLoopLockAcquired = geometryLockWaitBudget.count() <= 0;

    if(!preLoopLockAcquired)
    {
        // 2026-10-22（第 3 条）：自旋 try_lock → try_lock_for。
        // 后者把本线程放上互斥量的等待队列，一次交接就能拿到；原来的
        // try_lock + yield 只能在"刚好空出来的那一瞬"抢，十几个持有者轮转时
        // 可能整整 3ms 一次都抢不到（这正是 82.7ms 尖峰的第一步）。
        if(g_chunkMutex.try_lock_for(geometryLockWaitBudget))
        {
            preLoopLockAcquired = true;
            g_geometryPreLoopLockSkips = 0u;
        }
    }

    if(!preLoopLockAcquired)
    {
        ++g_geometryPreLoopLockSkips;

        // 兜底：连续让位 5 次后给一段更长的**有界**等待，而不是无界 lock()。
        // 实测（10-22 10:54 那局）frame=30 pre=82.74 pCap=82.73 —— 整帧尖峰全在
        // 旧兜底那句 g_chunkMutex.lock() 上。有界之后，最坏情况退化成"几何晚几帧
        // 更新"（脏键与捕获队列原样保留），而不是卡住一帧 82ms。
        // skip 计数在真正拿到锁之前不清零 ⇒ 后续每帧一上来就用长预算。
        if(g_geometryPreLoopLockSkips >= 5u)
        {
            preLoopLockAcquired = g_chunkMutex.try_lock_for(
                std::chrono::milliseconds(SECTION_PRELOOP_LOCK_FALLBACK_MS));

            if(preLoopLockAcquired)
            {
                g_geometryPreLoopLockSkips = 0u;
            }
            else
            {
                static bool s_lockFallbackDeferLogged = false;

                if(!s_lockFallbackDeferLogged)
                {
                    s_lockFallbackDeferLogged = true;
                    RTLog(
                        "[GEOMETRY LOCK] deferred after the bounded fallback "
                        "wait (geometry will catch up on a later frame)"
                    );
                }
            }
        }
    }

    if(!preLoopLockAcquired)
    {
        // dirty 集与捕获队列都还没动过 ⇒ 下一帧原样重试，不会丢工作。
        return false;
    }

    {
        std::lock_guard<std::timed_mutex>
            lock(
                g_chunkMutex,
                // 锁已在上面取得（try_lock_for）⇒ 由本 guard 接管、出作用域释放。
                std::adopt_lock
            );


        forceReset =
            g_forceSectionASReset;


        // =====================================================
        // 2026-10-13（乙·一期）：几何非常驻的**补传**入口
        //
        // 被驱逐的 Section 只在 g_sectionBLAS 里消失，g_chunkMeshes 的 CPU 顶点一直
        // 保留 ⇒ 把这个 spatial 键**重新标脏**就够了：下面的脏键路径会走
        // geometryCaptureSectionLocked()（分类路由的**唯一**实现）从 g_chunkMeshes
        // 重捕获并重建。不需要任何新的重建通道。
        //
        // 迟滞：驱逐要求 distance > keepRadius × 1.25，补传要求 distance < keepRadius，
        // 中间那条带子避免"刚放掉就回来"的抖动。
        // 配额：补传是重建（maxSectionMs 到过 92ms），每批只放几个，避免把一帧拖长。
        // A/B：ORION_VRAM_GOVERNOR < 2 时整段不生效（一期行为）。
        // =====================================================
        if(vramGovernorMode() >= 2 && !g_nonResidentSections.empty())
        {
            const CameraUBO* rehydrateUbo =
                g_cameraUboMapped != nullptr
                    ? static_cast<const CameraUBO*>(g_cameraUboMapped)
                    : nullptr;

            const float rehydrateRadius = vramEvictKeepRadius();
            const float rehydrateRadiusSq = rehydrateRadius * rehydrateRadius;

            const size_t rehydrateQuota = vramRehydratePerPass();
            size_t rehydrated = 0u;

            for(auto it = g_nonResidentSections.begin();
                it != g_nonResidentSections.end() &&
                rehydrated < rehydrateQuota;)
            {
                const uint64_t spatialKey =
                    *it & SPATIAL_SECTION_KEY_MASK;

                float centerX = 0.0f;
                float centerY = 0.0f;
                float centerZ = 0.0f;
                vramSectionCenterFromSpatialKey(
                    spatialKey,
                    centerX,
                    centerY,
                    centerZ
                );

                const float dx = centerX - (rehydrateUbo ? rehydrateUbo->playerX : 0.0f);
                const float dy = centerY - (rehydrateUbo ? rehydrateUbo->playerY : 0.0f);
                const float dz = centerZ - (rehydrateUbo ? rehydrateUbo->playerZ : 0.0f);

                if(dx * dx + dy * dy + dz * dz <= rehydrateRadiusSq)
                {
                    g_dirtySectionKeys.insert(spatialKey);
                    it = g_nonResidentSections.erase(it);
                    ++rehydrated;
                    ++g_vramRehydratedSections;
                }
                else
                {
                    ++it;
                }
            }
        }


        if(forceReset)
        {
            // 2026-10-08（BLAS 异步化）：强制重置会从 g_chunkMeshes **全量重建**，
            // 捕获线程队列里那几份（可能是在重置信号之前抓的）由全量结果覆盖 ——
            // 直接丢掉，避免同一个键进来两次。它们对应的键本来就会被下面处理。
            {
                std::lock_guard<std::mutex> capturedLock(g_capturedSectionsMutex);
                g_capturedSections.clear();
            }

            std::unordered_map<
                uint64_t,
                SectionGeometrySplit
            > mergedSections;


            // 2026-10-08：分类路由的**唯一实现**是 geometryCaptureSectionLocked()
            //（捕获线程与增量批次走的也是它）。这里只负责"全量：先收集本帧
            // g_chunkMeshes 里出现过的 spatialKey（去重），再对每个键走一次路由"。
            // 旧实现是直接遍历 g_chunkMeshes（unordered_map ⇒ 顺序本就不确定），
            // 所以"按键分组"不引入任何新的顺序假设。
            // ⚠ 行为变更（本轮的实质修复）：旧的那份手抄副本在**半透明混装层**上漏了
            // marker-1 水分离（整层按 alpha 处理），现在与另外两个消费者一致 ——
            // materialId == 1 的三角形进 water 分区。它只在强制重置那一帧生效，
            // 而强制重置实测只在开局/极少数时刻发生（counters 里的 forceResets）。
            for(const auto& layerEntry : g_chunkMeshes)
            {
                const uint64_t spatialSectionKey =
                    layerEntry.first &
                    SPATIAL_SECTION_KEY_MASK;

                if(mergedSections.find(spatialSectionKey) != mergedSections.end())
                {
                    continue;
                }

                geometryCaptureSectionLocked(
                    spatialSectionKey,
                    mergedSections[spatialSectionKey]
                );
            }


            // 2026-10-08 诊断：强制重置那一帧是**同步全量重建**（捕获线程按设计让路），
            // 它正是 geometry 相位尖峰的来源 —— 打一行带帧号，便于与 CPUPHASE 对齐。
            g_geometryForceResetCount.fetch_add(1u, std::memory_order_relaxed);
            RTLog(
                "[RT GEOMETRY] force reset: synchronous full rebuild of " +
                std::to_string(mergedSections.size()) +
                " section(s), frame=" + std::to_string(g_perfL10FrameSerial)
            );

            sectionUpdates.reserve(
                mergedSections.size()
            );


            for(auto& sectionEntry : mergedSections)
            {
                sectionUpdates.emplace_back(
                    sectionEntry.first,
                    std::move(
                        sectionEntry.second
                    )
                );
            }
        }
        else
        {
            // =====================================================
            // 2026-10-08（BLAS 异步化）：先接手捕获线程的成品
            // =====================================================
            // geometryCaptureWorkerLoop 已用**同一个** geometryCaptureSectionLocked
            // 把 g_dirtySectionKeys 里的非实体键做完"分类拷贝"，并推进
            // g_capturedSections。这里把它们并进本批，渲染线程只做后面的
            // slot 分配 / 录制 / TLAS / 提交。
            //
            // 三条约束（都是正确性，不是优化）：
            //   1. 队列条目**不登记进 updateIndices** —— 下面那套"按空间键枚举 16 层"
            //      会把同一个 split 再追加一次顶点（双重填充）。
            //   2. 队列条目与脏键**共用同一个 batchCap 预算**，所以单批处理量仍与
            //      旧档同级（不会因为多了队列就把一帧的上传/显存抬上去）。
            //   3. 超出预算的部分**放回队列**：键已被捕获线程从脏集合摘走，队列就是
            //      它们的暂存处；函数尾部会因队列非空而保持脏标志 ⇒ 下一帧继续。
            //
            // 实体键不经过捕获线程（逐帧动，必须同步捕获保新鲜），所以下面那段
            // "实体优先"逻辑原样有效。
            std::vector<CapturedSectionUpdate> capturedBatch;
            {
                // 锁序：本函数此刻已持 g_chunkMutex ⇒ 再取 g_capturedSectionsMutex，
                // 与捕获线程的嵌套顺序一致，不会互相等待。
                std::lock_guard<std::mutex> capturedLock(g_capturedSectionsMutex);
                capturedBatch.swap(g_capturedSections);
            }

            // Snapshot only a bounded prefix of the dirty set. Remaining
            // Section keys stay pending for later batches, turning a large
            // streaming burst into several bounded BLAS/TLAS rebuilds.
            const bool entityDirty =
                g_dirtySectionKeys.find(ENTITY_RT_SPATIAL_KEY) !=
                g_dirtySectionKeys.end();

            const size_t batchCap =
                std::min(maxSectionUpdates, effectiveSectionRebuildBatchCap());
            const size_t adoptedCount =
                std::min(capturedBatch.size(), batchCap);
            if(adoptedCount < capturedBatch.size())
            {
                std::lock_guard<std::mutex> capturedLock(g_capturedSectionsMutex);
                g_capturedSections.insert(
                    g_capturedSections.end(),
                    std::make_move_iterator(capturedBatch.begin() + adoptedCount),
                    std::make_move_iterator(capturedBatch.end())
                );
            }

            const size_t selectedCount = std::min(
                g_dirtySectionKeys.size(),
                batchCap - adoptedCount
            );
            sectionUpdates.reserve(adoptedCount + selectedCount);

            std::unordered_map<uint64_t, size_t> updateIndices;
            updateIndices.reserve(selectedCount + 1u);

            // Entity animation is the only non-streaming producer.  Keep its
            // reserved Section first so bounded world updates cannot defer it
            // behind a chunk upload burst.
            if(entityDirty && (adoptedCount + selectedCount) > 0u)
            {
                sectionUpdates.emplace_back(
                    ENTITY_RT_SPATIAL_KEY,
                    SectionGeometrySplit{}
                );
                updateIndices.emplace(
                    ENTITY_RT_SPATIAL_KEY,
                    0u
                );
            }

            // 捕获线程的成品：直接进列表，**不**登记 updateIndices（见上面第 1 条）。
            // 顺手做两道"内容新鲜度"去重：
            //   · 同一个键在队列里可能出现多次（捕获之后又被上传、又被捕获）⇒ 只留
            //     **最后**一份（队列 FIFO ⇒ 后者更新）。所以倒序遍历、每个键只留首个
            //     见过的（即最新的）。
            //   · 键如果此刻又出现在脏集合里，说明队列那份之后还有更新的上传 ⇒ 整份
            //     丢掉，交给下面的同步路径去拿最新内容。
            std::unordered_set<uint64_t> adoptedKeys;
            adoptedKeys.reserve(adoptedCount);
            for(size_t adopted = adoptedCount; adopted-- > 0u;)
            {
                const uint64_t adoptedKey = capturedBatch[adopted].spatialKey;
                if(g_dirtySectionKeys.find(adoptedKey) !=
                   g_dirtySectionKeys.end())
                {
                    continue;
                }
                if(!adoptedKeys.insert(adoptedKey).second)
                {
                    continue;
                }
                sectionUpdates.emplace_back(
                    adoptedKey,
                    std::move(capturedBatch[adopted].split)
                );
                g_geometryAdoptedSectionTotal += 1u;
            }

            // 一次性诊断（渲染线程打，worker 线程不碰日志流）：看到这一行就说明
            // "分类拷贝"确实已经在渲染线程之外完成了。ORION_SYNC_GEOMETRY=1 时永不出现。
            if(!sectionUpdates.empty() && adoptedCount > 0u)
            {
                static bool loggedFirstAdoption = false;
                if(!loggedFirstAdoption)
                {
                    loggedFirstAdoption = true;
                    RTLog(
                        "[RT GEOMETRY] async capture active: adopted " +
                        std::to_string(adoptedCount) +
                        " pre-split section(s) from the capture worker"
                    );
                }
            }

            // =====================================================
            // 2026-10-21 就近优先（对齐 Sodium ChunkJobQueue 的 importance 排序）
            //
            // 旧实现按 unordered_set 的**哈希序**取前 N 个 ⇒ 大范围流式加载时，
            // 玩家脚下的段可能排在上百个无关段之后，观感是"眼前缺块、远处先补"。
            // 现在先收集候选、按到相机的距离选最近的 N 个，再写回 sectionUpdates。
            //
            // 正确性前提不变：下标即捕获顺序、且未捕获的永远是**尾部连续区间**
            // （见下面 captureOrder 升序 + resize 裁剪的说明）。
            // 候选数上限 512：限制单帧的排序代价（Sodium 的作业队列同样是限量取用）。
            // =====================================================
            if(selectedCount > 0u)
            {
                constexpr size_t DIRTY_CANDIDATE_LIMIT = 512u;

                std::vector<std::pair<float, uint64_t>> nearest;
                nearest.reserve(
                    std::min(selectedCount * 4u + 16u, DIRTY_CANDIDATE_LIMIT));

                for(uint64_t sectionKey : g_dirtySectionKeys)
                {
                    if(sectionKey == ENTITY_RT_SPATIAL_KEY)
                    {
                        continue;
                    }

                    float centerX = 0.0f;
                    float centerY = 0.0f;
                    float centerZ = 0.0f;
                    vramSectionCenterFromSpatialKey(
                        sectionKey,
                        centerX,
                        centerY,
                        centerZ);

                    const float dx = centerX - g_dynamicCaptureCameraX;
                    const float dy = centerY - g_dynamicCaptureCameraY;
                    const float dz = centerZ - g_dynamicCaptureCameraZ;

                    nearest.emplace_back(
                        dx * dx + dy * dy + dz * dz,
                        sectionKey);

                    if(nearest.size() >= DIRTY_CANDIDATE_LIMIT)
                    {
                        break;
                    }
                }

                if(nearest.size() > selectedCount)
                {
                    std::nth_element(
                        nearest.begin(),
                        nearest.begin() + static_cast<std::ptrdiff_t>(selectedCount),
                        nearest.end());
                    nearest.resize(selectedCount);
                }

                std::sort(
                    nearest.begin(),
                    nearest.end(),
                    [](const std::pair<float, uint64_t>& a,
                       const std::pair<float, uint64_t>& b)
                    {
                        return a.first < b.first;
                    });

                for(const auto& nearestEntry : nearest)
                {
                    const size_t updateIndex = sectionUpdates.size();
                    sectionUpdates.emplace_back(
                        nearestEntry.second,
                        SectionGeometrySplit{});
                    updateIndices.emplace(nearestEntry.second, updateIndex);
                }
            }


            const bool onlyDynamicSection =
                sectionUpdates.size() == 1u &&
                sectionUpdates.front().first == ENTITY_RT_SPATIAL_KEY;
            if(onlyDynamicSection)
            {
                // 走**同一个**分类路由（见 geometryCaptureSectionLocked）。
                // 等价性：实体聚合键的三个有效 layer 分别是
                //   ENTITY_RT_LAYER_KEY(5)        -> split.entity
                //   LOCAL_PLAYER_RT_LAYER_KEY(6)  -> split.localPlayer
                //   PARTICLE_RT_LAYER_KEY(7)      -> split.particle
                // 与原来那次显式三连调用进的是**三个不同的桶**，所以桶内顶点顺序
                // 不受枚举顺序影响；键是保留段，layer 0..4/8..15 不可能存在。
                geometryCaptureSectionLocked(
                    ENTITY_RT_SPATIAL_KEY,
                    sectionUpdates.front().second
                );
            }
            else
            {
                // 分类路由的**唯一实现**是 geometryCaptureSectionLocked()（捕获线程
                // 与 forceReset 全量重建走的也是它）—— 这里只负责"按脏 spatialKey
                // 枚举"这一层。
                //
                // ⭐ 2026-09-26 性能：遍历 updateIndices（条数 = selectedCount，有界），
                // 对每个 dirty 的 spatialKey 走一次分类路由。原来这里扫整张
                // g_chunkMeshes（世界里所有 section × 所有 layer，实测上万条）只为挑出
                // ≤24 个脏键，而且跑在 g_chunkMutex 里挡着 Java 侧的几何上传（同一个
                // 互斥量）。
                //
                // 等价性可证明，不是估计：键的布局固定为 `layerId<<60 | spatialKey`
                //（layerId 取自 key>>60，4 bit ⇒ 只可能 0..15），而路由内部正是枚举这
                // 16 个 layer；特殊全局键（LOCAL_PLAYER/ENTITY/PARTICLE）的
                // spatialKey = 低 60 位、layerId = 5/6/7，正是枚举范围内的一项。
                // =====================================================
                // 2026-10-08 时间预算进"捕获段"（根治最后一条"越玩越卡"）。
                //
                // 现场：preLoopMs（本段耗时）在同一会话里单调增长
                //   10.6ms → 22.3 → 36.5 → **52.7ms**（约 4 分钟），
                // 而 maxSectionMs 只有 0.7~7.6ms、allocCalls=0（slab 已根治分配）。
                // 也就是说帧尖峰（geometry 相位 43~55ms）**全部**来自这一段：
                // g_chunkMutex 内的分类拷贝。原来的时间预算只装在逐块构建循环里
                // （下面 `if(sectionUpdateIndex != 0u && g_asBuilt && !forceReset)`），
                // 锁内这段完全不受约束 —— 2026-10-07 的注释自己也点明了这点。
                //
                // 为什么必须按**下标升序**捕获：unordere_map 的遍历序是哈希序，
                // 一旦中途 break，"未捕获"的就不是尾部连续区间，没法安全裁剪。
                // 升序后未捕获的一定是尾部区间 ⇒ 直接 resize 即可。语义等价：
                // 分类路由与枚举顺序无关（见上面 ⭐ 注释）。
                //
                // 为什么中断时必须**把未捕获的条目裁掉**（这一步不做就是画面缺块）：
                //   下面的 `for(const auto& update : sectionUpdates) g_dirtySectionKeys.erase(...)`
                //   会把 sectionUpdates 里**每个**键从脏集摘掉。未捕获的条目若留在里面，
                //   就等于"处理完毕"，而它带着**空 split** 进构建循环又会被判成
                //   "该 Section 没几何" ⇒ 退役/删除 ⇒ 那一片几何直接消失。
                //   裁掉之后：脏键原样保留 ⇒ 下一次重建接着做（updateIndices 在这之后
                //   不再被使用，所以裁剪是安全的）。
                //
                // 实体 Section 不受影响：它在 sectionUpdates 里排下标 0，升序捕获必然
                // 第一个做，裁剪不会碰到它（与"实体固定排第一批"的约定一致）。
                // 回退：把本段的 break 条件去掉即回到旧行为。
                // =====================================================
                std::vector<size_t> captureOrder;
                captureOrder.reserve(updateIndices.size());
                for(const auto& updateEntry : updateIndices)
                {
                    captureOrder.push_back(updateEntry.second);
                }
                std::sort(captureOrder.begin(), captureOrder.end());

                size_t capturedCount = 0u;
                for(size_t orderIndex = 0u; orderIndex < captureOrder.size(); ++orderIndex)
                {
                    if(orderIndex != 0u)
                    {
                        const double captureElapsedMs =
                            std::chrono::duration<double, std::milli>(
                                std::chrono::steady_clock::now() - perfL10RebuildStart
                            ).count();
                        // 直接调用而不是复用逐块构建循环里那份缓存 —— 那个变量声明在
                        // 本段之后（它服务后面的构建循环），此处不可见。同一个函数，
                        // 同一个语义（自适应预算，见 sectionRebuildTimeBudgetMs）。
                        if(captureElapsedMs >= sectionRebuildTimeBudgetMs())
                        {
                            break;
                        }
                    }

                    const size_t captureIndex = captureOrder[orderIndex];
                    geometryCaptureSectionLocked(
                        sectionUpdates[captureIndex].first,
                        sectionUpdates[captureIndex].second
                    );
                    ++capturedCount;
                }

                if(capturedCount < captureOrder.size())
                {
                    // 裁掉未捕获的尾部条目（见上面"为什么必须裁"）。
                    sectionUpdates.resize(captureOrder[capturedCount]);

                    g_sectionRebuildInterrupted = true;
                    g_sectionRebuildContinueFrame =
                        g_perfL10FrameSerial + SECTION_REBUILD_CONTINUE_FRAMES;

                    // 脏集此刻还没被摘（摘在下面的 erase 循环里），所以未捕获的键
                    // 一定还在 ⇒ 置 true，让提交侧知道还有活。
                    g_worldGeometryDirty.store(
                        !g_dirtySectionKeys.empty(),
                        std::memory_order_release
                    );
                }
            }
            }


        if(forceReset)
        {
            g_dirtySectionKeys.clear();
        }
        else
        {
            // Remove only the bounded batch captured above. Uploads that
            // arrived after this snapshot remain dirty and will be processed
            // by the following rebuild rather than being silently discarded.
            for(const auto& update : sectionUpdates)
            {
                g_dirtySectionKeys.erase(update.first);
            }
        }

        // The role table and the instance loop below run outside this lock, so
        // they cannot read g_dhLodSections directly.  Publish a sorted snapshot
        // of the live DH spatial keys here, while the lock still protects it.
        refreshDhLodSpatialSnapshotLocked();

        g_forceSectionASReset = false;
        // 2026-10-08（BLAS 异步化）：队列里还有捕获线程的成品时也必须保持脏标志 ——
        // 那些键早已被捕获线程从脏集合里摘走，只看脏集合就会漏掉它们，队列会一直等到
        // 下一次无关的脏事件才被消费。
        bool capturedPending = false;
        {
            std::lock_guard<std::mutex> capturedLock(g_capturedSectionsMutex);
            capturedPending = !g_capturedSections.empty();
        }
        g_worldGeometryDirty.store(
            !g_dirtySectionKeys.empty() || capturedPending,
            std::memory_order_release
        );
    }

    // =====================================================
    // 2026-10-08：捕获线程计数器 —— **周期性**输出（每 600 帧一次）
    // =====================================================
    // 教训：原来只把它挂在 stopGeometryCaptureWorker()（关停钩子）上，而实测
    // **正常退出根本不走 native cleanup** —— rt_debug.log 在退出前约 7 秒就停止
    // 写入，2026-10-07 23:08 那次跑完一行 summary 都没有，等于观测不到。
    //
    // 改挂在这里的理由：本函数只在"有脏活"时被调用 ⇒ 空闲时不刷屏，而空闲时
    // 计数器本来也不变；每 600 帧（≈10s）一行，A/B 时两条时间线可直接对齐比较。
    //
    // 2026-10-13：显存预算闸门 tick 挂在这里 —— 闸门只在**我们要分配**的时候才需要
    // 动作，而"有脏活"正是那个时刻。它内部自带降频（见 VRAM_GOVERNOR_SAMPLE_TICKS），
    // 所以放在这里不会变成每帧的驱动查询。
    updateVramGovernor();

    // 2026-10-13 preLoop 内切（见 [RT GEOMETRY SLOW] 的 pCap/pLog/pRsv）：
    // 本局的 600 次窗口最大值显示 preLoop=7.9 → 23.8 → 17.3 → **46.0ms**，
    // 而同期 maxSectionMs 只有 3.6~7.7ms ⇒ 尖峰不在"某一块"，在循环之前那段。
    // preLoop = 函数入口 → 构建循环起点，里面按顺序是：捕获/分类拷贝 + 脏集快照
    // （锁内）→ 本日志块 → 空批检查 → 退役槽获取 + 三次 reserve。
    // 这里按自然边界插两个时刻点，把它切成三段。
    const std::chrono::steady_clock::time_point rtxPreLoopMarkLog =
        std::chrono::steady_clock::now();

    if(g_perfL10FrameSerial % 600u == 0u)
    {
        // 2026-10-08：加 rebuildCalls / perCall 与"当前批次上限 cap、当前预算 budgetMs"
        // —— 这三个数字用来区分限速的是**批次上限**还是**时间预算**：
        //   · perCall 贴近 cap   ⇒ 上限卡住（该抬 cap）
        //   · perCall 明显小于 cap ⇒ 预算卡住（该抬预算，这正是本次要验的）
        const uint64_t capturedNow = g_geometryCapturedSectionTotal.load();
        const uint64_t callsNow = g_geometryRebuildCallTotal;
        const uint64_t capturedDelta = capturedNow - g_geometryCountersLastCaptured;
        const uint64_t callsDelta = callsNow - g_geometryCountersLastCalls;
        g_geometryCountersLastCaptured = capturedNow;
        g_geometryCountersLastCalls = callsNow;

        std::ostringstream countersLog;
        countersLog
            << std::fixed << std::setprecision(1)
            << "[RT GEOMETRY] counters: captured=" << capturedNow
            << " adopted=" << g_geometryAdoptedSectionTotal
            << " forceResets=" << g_geometryForceResetCount.load()
            << " rebuildCalls=" << callsNow
            // 2026-10-10：入口闸门让位的累计次数（见 rebuildWorldGeometry 的闸门）。
            // 稳态应当很小；若它随帧数线性增长，说明几何构建长期追不上请求，
            // 那时该看的是 tailMs / maxSectionMs，而不是继续加闸门。
            << " fenceDeferred=" << g_geometryFenceDeferredCount
            << " perCall="
            << (callsDelta > 0u
                    ? static_cast<double>(capturedDelta) /
                          static_cast<double>(callsDelta)
                    : 0.0)
            << " cap=" << effectiveSectionRebuildBatchCap()
            << " budgetMs=" << sectionRebuildTimeBudgetMs()
            // 2026-10-08：窗口内**单块**最大构建耗时（见 g_geometryMaxSectionMs）。
            // 拿它和 CPUPHASE 的 geometry 尖峰对比即可一眼定性：
            //   maxSectionMs ≈ 尖峰 ⇒ 某一块特别贵（下一步给单块做可续/降级）
            //   maxSectionMs ≪ 尖峰 ⇒ 贵在构建循环之外（锁内捕获/staging/TLAS/队列）
            << " maxSectionMs=" << g_geometryMaxSectionMs
            // 2026-10-08：逐块循环**之前**那段（锁内捕获/分类 + 脏集快照）的最大耗时。
            // 与 maxSectionMs 一起读：两者之和才是 geometry 相位的尖峰来源。
            << " preLoopMs=" << g_geometryMaxPreLoopMs
            // 2026-10-09（B）：三分之后的另外两段（见 g_geometryMaxBuildLoopMs 说明）。
            // 判读：preLoop + buildLoop + tail 应 ≈ CPUPHASE 的 geometry 尖峰；
            // 哪一项吃掉差额，就改哪一项。
            << " buildLoopMs=" << g_geometryMaxBuildLoopMs
            << " tailMs=" << g_geometryMaxTailMs
            // 2026-10-08 Section 内存 **slab 分配器**（见其说明）：
            //   poolHit/poolMiss = chunk 复用命中/未命中（未命中才真 vkAllocateMemory）
            //   allocCalls/allocMs = 真分配次数与**累计耗时**（尾巴的直接量化）
            //   poolKeptMB = 空 slab 留用量
            // 判据（与池化版同一臂对比）：
            //   · allocCalls 应从"每块一次"掉到"每几十~几百块一次"（slab 生效）；
            //   · maxSectionMs 的尖峰应随 allocMs 一起消失；若 allocMs 仍高，说明显存
            //     **总量**被别的消费者顶满（下一步查 VLI 页池 / Section 距离释放）。
            << " poolHit=" << g_sectionMemoryPoolHits
            << " poolMiss=" << g_sectionMemoryPoolMisses
            << " allocCalls=" << g_sectionMemoryAllocateCalls
            << std::fixed << std::setprecision(1)
            << " allocMs=" << g_sectionMemoryAllocateMs
            << " poolKeptMB="
            << (static_cast<double>(g_sectionMemoryPoolKeptBytes) /
                1048576.0)
            // 2026-10-11 Section 重建缓冲池（顶点 staging / BLAS scratch，多槽）：
            //   buildPoolReuse = 命中池的次数，buildPoolAlloc = 真 vkAllocateMemory 次数。
            // 判据：稳态下 alloc 应**不再增长**（预热后恒为个位数），reuse 随重建数线性涨；
            //   若 alloc 仍随 rebuildCalls 线性涨 ⇒ 池没生效（回到单槽 churn）。
            << " buildPoolReuse=" << g_sectionBuildPoolReuseCount
            << " buildPoolAlloc=" << g_sectionBuildPoolAllocCount
            // 2026-10-20 Section BLAS 重建归因（见 g_sectionASCreateCalls 的说明）：
            //   asCreateN/asRetireN = 窗口内 BLAS 创建/退役次数（与 [RT MEM] 的
            //     asCreate/asDestroy 同源但只统计 Section 段，不含 TLAS）；
            //   asCreateMs/asRetireMs = 对应的**真实毫秒**；
            //   asRefitCand / asCreateN = 可 refit（同 primitiveCount 且无 OMM）的比例。
            << " asCreateN=" << g_sectionASCreateCalls
            << " asRetireN=" << g_sectionASRetireCalls
            << std::fixed << std::setprecision(2)
            << " asCreateMs=" << g_sectionASCreateMs
            << " asRetireMs=" << g_sectionASRetireMs
            << " asSameTris=" << g_sectionASRebuildSameTris
            << " asRefitCand=" << g_sectionASRefitCandidateHits
            << " asRefitHits=" << g_sectionASRefitHits
            << std::fixed << std::setprecision(1)
            // 2026-10-15 g_chunkMutex 争用仪表（窗口最大值，见 g_chunkMutex 声明处
            // 的说明与判读表）。与 Java 侧 [SECTION COMPILE] jniMs 对着读：
            // jniMs 大而 upWaitMs 小 ⇒ 瓶颈不在锁；upWaitMs ≈ capHoldMs ⇒ 捕获线程；
            // upWaitMs ≈ upHoldMs ⇒ uploadChunk 自身。
            << std::fixed << std::setprecision(1)
            << " upWaitMs="
            << (g_chunkLockMaxWaitNanos.load(std::memory_order_relaxed) / 1.0e6)
            << " upHoldMs="
            << (g_chunkLockMaxHoldNanos.load(std::memory_order_relaxed) / 1.0e6)
            << " capHoldMs="
            << (g_captureLockMaxHoldNanos.load(std::memory_order_relaxed) / 1.0e6)
            << " capWaitMs="
            << (g_captureLockMaxWaitNanos.load(std::memory_order_relaxed) / 1.0e6);

        {
            std::lock_guard<std::mutex> capturedLock(g_capturedSectionsMutex);
            countersLog << " queued=" << g_capturedSections.size();
        }

        RTLog(countersLog.str());

        // 2026-10-09：[RT MEM] 与 counters 同频（每 600 帧）打一行内存记账。
        // 内存问题是"单调劣化"型，必须和 counters 放在同一时间轴上才能对齐看。
        logNativeMemoryReport();

        // 2026-10-13：闸门状态与 [RT MEM] 同频同轴，便于直接对照
        // vramUsedMB / slabKeptMB 的变化与 keepCapMB 的动作是否一致。
        logVramGovernor();

        // 窗口最大值/累计量 → 打完清零，下一行对应下一个窗口。
        g_geometryMaxSectionMs = 0.0;
        g_geometryMaxPreLoopMs = 0.0;
        // 2026-10-09（B）三分里的另两段（必须一起清，否则会退化成会话累计值）。
        g_geometryMaxBuildLoopMs = 0.0;
        g_geometryMaxTailMs = 0.0;
        g_sectionMemoryPoolHits = 0u;
        g_sectionMemoryPoolMisses = 0u;
        g_sectionMemoryAllocateCalls = 0u;
        g_sectionMemoryAllocateMs = 0.0;
        // 2026-10-20 Section BLAS 重建归因（同一窗口口径）。
        g_sectionASCreateCalls = 0u;
        g_sectionASRetireCalls = 0u;
        g_sectionASCreateMs = 0.0;
        g_sectionASRetireMs = 0.0;
        g_sectionASRebuildSameTris = 0u;
        g_sectionASRefitCandidateHits = 0u;
        g_sectionASRefitHits = 0u;
        // 2026-10-15 争用仪表的窗口最大值（与上面同一窗口口径）。
        g_chunkLockMaxWaitNanos.store(0u, std::memory_order_relaxed);
        g_chunkLockMaxHoldNanos.store(0u, std::memory_order_relaxed);
        g_captureLockMaxHoldNanos.store(0u, std::memory_order_relaxed);
        g_captureLockMaxWaitNanos.store(0u, std::memory_order_relaxed);
    }


    // 2026-10-13 preLoop 内切：本日志块到此结束（见 rtxPreLoopMarkLog 的说明）。
    const std::chrono::steady_clock::time_point rtxPreLoopMarkMid =
        std::chrono::steady_clock::now();

    if(
        !forceReset &&
        sectionUpdates.empty()
    )
    {
        // 本批确实没活可干（脏集与捕获队列都空）⇒ 正常收工，不是让位。
        // 2026-10-11 慢帧归因：这一条提前 return 会绕开 tail 段，所以三段计时在这里
        // 一个数都不留。整体耗时单独打一行 —— 若慢帧全是 empty=1，说明那 60+ms 花在
        // "进锁之前/之内但没活"的路径上（锁等待是头号嫌疑）。
        const double rtxEmptyTotalMs =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() -
                perfL10RebuildStart
            ).count();

        if(rtxEmptyTotalMs >= 15.0)
        {
            RTLog(
                "[RT GEOMETRY SLOW] frame=" +
                std::to_string(g_perfL10FrameSerial) +
                " total=" + std::to_string(rtxEmptyTotalMs) +
                " sections=0 empty=1");
        }

        return true;
    }

    if(!getDestroyAccelerationStructure())
    {
        throw std::runtime_error(
            "vkDestroyAccelerationStructureKHR unavailable"
        );
    }

    // Perf-SR.1 / SR.2: the existing TLAS references the current Section BLAS
    // objects and the GPU may still be tracing them, so the whole generation is
    // parked rather than destroyed.  It is released later by fence rather than
    // by draining the queue here: the fence is attached to the build submit
    // below, and the queue being FIFO means a signaled fence covers every
    // submission made before it - including the frames that still referenced
    // this generation.  acquireRetirementSlot() picks the ring slot and only
    // falls back to a drain when every slot is still in flight.
    //
    // The slot holding the previous rebuild's build fence.  Captured before the
    // acquire below overwrites the current index; the instance table rewrite
    // further down waits on it because that build reads the same buffer.
    const uint32_t previousRetirementSlot =
        g_currentRetirementSlot;

    g_currentRetirementSlot =
        acquireRetirementSlot();

    g_sectionRetirement =
        &g_sectionRetirementRing[g_currentRetirementSlot];

    g_sectionRetirement->fencePending =
        false;

    g_sectionRetirement->deferredBuild =
        std::move(g_deferredSectionBuild);

    g_deferredSectionBuild = {};

    // The TLAS storage, scratch and instance table stay resident across
    // rebuilds.  Each is parked individually further down, and only when the
    // build really outgrows it, so this rebuild does not touch them here.
    g_sectionRetirement->occupied =
        true;


    if(forceReset)
    {
        for(auto& entry : g_sectionBLAS)
        {
            retireSectionAS(
                entry.second
            );
        }


        g_sectionBLAS.clear();
    }


    uint32_t removedSectionCount = 0;
    uint32_t rebuiltSectionCount = 0;
    uint64_t rebuiltOpaqueTriangleCount = 0;
    uint64_t rebuiltOmmTriangleCount = 0;
    uint64_t rebuiltAlphaTriangleCount = 0;
    uint64_t rebuiltWaterTriangleCount = 0;
    uint64_t rebuiltParticleTriangleCount = 0;

    std::vector<RTSectionAS*>
        sectionsNeedingBuild;

    sectionsNeedingBuild.reserve(
        sectionUpdates.size() * 7u
    );

    // Each Section can contribute seven independent geometry classes. Keep
    // the hash table and upload list sized for the batch to avoid rehashing
    // and vector growth while the rebuild is assembling resources.
    g_sectionBLAS.reserve(
        g_sectionBLAS.size() + sectionUpdates.size() * 7u
    );


    struct PendingSectionUpload
    {
        RTSectionAS* section = nullptr;
        const std::vector<Vertex>* vertices = nullptr;
        VkDeviceSize stagingOffset = 0;
        // 2026-10-09 运动矢量：该 class 的位移来源（nullptr = 无位移段）。
        // 它写进 staging 里顶点之后的那一段，长度由 section->vertexBytes 决定。
        const std::vector<float>* motion = nullptr;
        // 2026-10-21：捕获阶段预打包好的 32B 顶点（可为 nullptr = 没有快路）。
        // 消费端会再校验 size() 与 vertices 一致，不一致就退回逐顶点打包。
        const std::vector<SectionVertex>* packed = nullptr;
    };


    std::vector<PendingSectionUpload>
        pendingUploads;

    pendingUploads.reserve(
        sectionUpdates.size() * 7u
    );


    VkDeviceSize totalStagingBytes = 0;


    VkDeviceSize maxBLASScratchSize = 0;


    // 2026-10-08：本批的时间预算取**一次**（批内所有 Section 共用）。默认跟着实测
    // GPU 帧时间自适应（GPU 受限时把本来空转的 CPU 用来搬区块），可用环境变量
    // ORION_GEOMETRY_BUDGET_MS 覆盖（=5 即回到改动前的行为）。
    const double sectionRebuildBudgetMs = sectionRebuildTimeBudgetMs();


    // 单块计时（见 g_geometryMaxSectionMs 的说明）：用"上一次迭代开头 → 这一次
    // 迭代开头"的间隔当作上一块的耗时。只取最大值，所以不必在循环体结尾挂钩子，
    // 中途 continue（把剩余块回填脏集）也不影响。
    std::chrono::steady_clock::time_point previousSectionStart{};
    bool previousSectionTimingArmed = false;

    // 2026-10-09（B）：buildLoop 段的起点/终点，供"三分"用（见 g_geometryMaxBuildLoopMs）。
    const std::chrono::steady_clock::time_point perfL10BuildLoopStart =
        std::chrono::steady_clock::now();
    std::chrono::steady_clock::time_point perfL10AfterBuildLoop =
        perfL10BuildLoopStart;

    // =====================================================
    // 2026-10-10：把"时间预算"下沉到**类粒度**（中断点见下面 class 循环内）。
    //
    // 【病灶】原预算闸只在**块与块之间**（上面那个 `sectionUpdateIndex != 0u …`
    // 的 if 块）：一块内部不可中断 ⇒ 只要某一块本身贵，它的全部耗时必然落在
    // 同一帧里。现场（2026-10-10 一局，纯原版区块）：
    //     perCall 均值只有 1.3~3.8ms（多数块很便宜），
    //     而窗口最大值 maxSectionMs=47.1ms、buildLoopMs=47.2ms
    // ⇒ 就是"偶尔某一两块特别贵"，于是约每秒出现一次 35~48ms 的帧
    // （[LOD PERF] 的 p1=35~48ms）。工程自己在 10-09 的注释里已把这条标成
    // 下一步：maxSectionMs ≈ 尖峰 ⇒ 给单块做可续/降级。
    //
    // 【做法】一个 Section 在下面被拆成 7 个 class 依次重建，而每个 class 都是
    // **独立的 BLAS** ⇒ class 之间是天然的、语义完整的中断点。于是在每个 class
    // 之前查一次预算，超了就把该 Section（连同本批剩下的）重新标脏并整批跳出：
    //   · 结果正确：已重建完的 class 自身完整可用，未做的 class 保持旧版；下一帧
    //     整块重做，最终收敛到与不分段完全相同的结果；
    //   · 代价：本帧已做的 class 下一帧会重做一遍（少量重复劳动换帧时间上限）；
    //   · 与既有闸门的语义严格对齐：共用同一个 `sectionRebuildBudgetMs`、
    //     同样是"回填脏集 + 打断标志 + 批上限减半"、同样**首节不设预算**
    //     （实体 Section 固定排第一批，动画延迟不受影响）。
    // =====================================================
    const auto rebuildElapsedMsNow =
        [&]() -> double
        {
            return std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - perfL10RebuildStart
            ).count();
        };

    // 把 [fromIndex, end) 的 Section 回填脏集，并置位"重建被打断"。
    // 与上面既有闸门里那段收工动作**逐句相同**（抽出来只为两处不会各自漂移）。
    const auto requeueSectionsFrom =
        [&](size_t fromIndex)
        {
            {
                std::lock_guard<std::timed_mutex> lock(g_chunkMutex);
                for(size_t pending = fromIndex;
                    pending < sectionUpdates.size();
                    ++pending)
                {
                    g_dirtySectionKeys.insert(sectionUpdates[pending].first);
                }
                g_worldGeometryDirty.store(
                    !g_dirtySectionKeys.empty(),
                    std::memory_order_release
                );
            }
            g_sectionRebuildInterrupted = true;
            g_sectionRebuildContinueFrame =
                g_perfL10FrameSerial + SECTION_REBUILD_CONTINUE_FRAMES;
            g_sectionRebuildBatchCap = std::max<size_t>(
                1u,
                g_sectionRebuildBatchCap / 2u
            );
        };

    for(size_t sectionUpdateIndex = 0u;
        sectionUpdateIndex < sectionUpdates.size();
        ++sectionUpdateIndex)
    {
        {
            const std::chrono::steady_clock::time_point sectionNow =
                std::chrono::steady_clock::now();

            if(sectionUpdateIndex == 0u)
            {
                // 循环之前那段 = 从函数入口到这里的耗时（perfL10RebuildStart 在
                // :51151 入口就取了）。见 g_geometryMaxPreLoopMs 的说明。
                const double preLoopMs =
                    std::chrono::duration<double, std::milli>(
                        sectionNow - perfL10RebuildStart
                    ).count();

                if(preLoopMs > g_geometryMaxPreLoopMs)
                {
                    g_geometryMaxPreLoopMs = preLoopMs;
                }
            }

            if(previousSectionTimingArmed)
            {
                const double previousSectionMs =
                    std::chrono::duration<double, std::milli>(
                        sectionNow - previousSectionStart
                    ).count();

                if(previousSectionMs > g_geometryMaxSectionMs)
                {
                    g_geometryMaxSectionMs = previousSectionMs;
                }
            }

            previousSectionStart = sectionNow;
            previousSectionTimingArmed = true;
        }

        auto& update = sectionUpdates[sectionUpdateIndex];

        // 2026-10-07 时间预算：首节无条件构建（实体 Section 固定排第一批，
        // 动画延迟不受影响），之后超出墙钟预算就把本批剩余 Section 回填脏集
        // 并提前收工。回填必须同时恢复 g_worldGeometryDirty —— 脏键在锁内
        // 捕获时已被摘除，否则预算中断会让这批 Section 悬在
        // g_dirtySectionKeys 里等不到下一次重建。首次全局构建与 forceReset
        // 不设预算（都发生在加载期/罕见重置，吞吐优先）。
        if(sectionUpdateIndex != 0u && g_asBuilt && !forceReset)
        {
            const double rebuildElapsedMs =
                std::chrono::duration<double, std::milli>(
                    std::chrono::steady_clock::now() - perfL10RebuildStart
                ).count();
            // 2026-10-08：改用自适应预算（sectionRebuildBudgetMs，见其说明）。
            // GPU 受限的机器上它比旧的 5ms 大 ⇒ 每帧多搬几块；CPU 受限或
            // ORION_GEOMETRY_BUDGET_MS=5 时与改动前逐位相同。
            if(rebuildElapsedMs >= sectionRebuildBudgetMs)
            {
                {
                    std::lock_guard<std::timed_mutex> lock(g_chunkMutex);
                    for(size_t pending = sectionUpdateIndex;
                        pending < sectionUpdates.size();
                        ++pending)
                    {
                        g_dirtySectionKeys.insert(sectionUpdates[pending].first);
                    }
                    g_worldGeometryDirty.store(
                        !g_dirtySectionKeys.empty(),
                        std::memory_order_release
                    );
                }
                g_sectionRebuildInterrupted = true;
                g_sectionRebuildContinueFrame =
                    g_perfL10FrameSerial + SECTION_REBUILD_CONTINUE_FRAMES;
                g_sectionRebuildBatchCap = std::max<size_t>(
                    1u,
                    g_sectionRebuildBatchCap / 2u
                );
                break;
            }
        }

        const uint64_t spatialSectionKey =
            update.first;

        auto rebuildGeometryClass =
            [&]
            (
                uint64_t classKey,
                const std::vector<Vertex>& vertices,
                bool opaqueGeometry,
                const OmmCutoutInput* ommInput,
                // 2026-10-09 运动矢量：该 class 的"上一帧位移"（**相机相对**，
                // nullptr = 无；地形四个 class 一律传 nullptr ⇒ 不产生尾段、零额外内存）。
                const std::vector<float>* vertexMotion,
                // 2026-10-21：捕获阶段预打包的 32B 顶点（nullptr = 无快路，
                // 由 staging 段退回逐顶点 makeSectionVertex）。只影响 CPU 侧
                // 搬运方式，不影响 section.vertexStride 的判定（那仍由
                // createSectionBLAS 内部算）。
                const std::vector<SectionVertex>* packedVertices
            )
            {
                // =====================================================
                // 2026-10-13（乙·修正 3）：非常驻段不再被脏键重建立刻重建回来。
                //
                // 现场：`[VRAM GOV]` 打出 `secEvicted=15` 的同时 `nonResident=0
                // secRehydrated=0` —— 这两个数不可能同时成立。查下来是本闭包末尾那句
                // `g_nonResidentSections.erase(...)`：驱逐刚把段写进非常驻表，紧接着一次
                // 普通脏键重建就把它摘掉并重建 ⇒ **驱逐被撤销，白做功**（而只有补传路径
                // 才计 `secRehydrated`，所以账目看起来自相矛盾）。
                //
                // 判据与驱逐同源、并复用同一份超线状态：**仍在越线中 + 该段在非常驻表里**
                // ⇒ 跳过重建，保持非常驻。玩家靠近时由补传路径重新标脏并把它从表里摘掉，
                // 那条路径不受本守卫影响。
                //
                // 省下的是这个闭包内部的内存：顶点捕获在**调用点**已经完成（闭包拿到的是
                // `const std::vector<Vertex>&`），而 slot 分配 + mesh/raw payload + BLAS
                // 都在下面 ⇒ 跳过它才是真正把显存省住的那一步。
                // A/B：ORION_VRAM_GOVERNOR < 2，或回到低水位以下（over=0）时整段不生效。
                // =====================================================
                if(vramGovernorMode() >= 2 &&
                   g_vramGovernor.over &&
                   g_nonResidentSections.count(
                       classKey & SPATIAL_SECTION_KEY_MASK) != 0u)
                {
                    return;
                }

                // 2026-10-20 仪表 + 2026-10-21 refit：先取旧段身份，**不**立刻退役 ——
                // refit 判定必须在 retire 之前完成（源 AS 一旦退役就不能再作为 UPDATE 源）。
                uint32_t previousTriangleCount = 0u;
                uint32_t previousMotionFloats = 0u;
                VkDeviceSize previousVertexBytes = 0u;
                VkDeviceSize previousUpdateScratchSize = 0u;
                bool previousHadOpacityMicromap = false;
                bool previousRefitCapable = false;
                bool hadPreviousSection = false;

                if(auto old = g_sectionBLAS.find(classKey);
                   old != g_sectionBLAS.end())
                {
                    previousTriangleCount = old->second.triangleCount;
                    previousMotionFloats = old->second.vertexMotionFloats;
                    previousVertexBytes = old->second.vertexBytes;
                    previousUpdateScratchSize = old->second.updateScratchSize;
                    previousHadOpacityMicromap = old->second.hasOpacityMicromap;
                    previousRefitCapable = old->second.refitCapable;
                    hadPreviousSection = true;
                }

                // 真正退役（释放 slab chunk + AS）。只在"确定要重建 / 删除"时调用。
                const auto retirePreviousSection =
                    [&]()
                    {
                        if(!hadPreviousSection)
                        {
                            return;
                        }

                        auto old = g_sectionBLAS.find(classKey);

                        if(old == g_sectionBLAS.end())
                        {
                            return;
                        }

                        const std::chrono::steady_clock::time_point retireStart =
                            std::chrono::steady_clock::now();

                        retireSectionAS(old->second);

                        g_sectionASRetireMs +=
                            std::chrono::duration<double, std::milli>(
                                std::chrono::steady_clock::now() - retireStart
                            ).count();
                        ++g_sectionASRetireCalls;

                        g_sectionBLAS.erase(old);
                        hadPreviousSection = false;
                    };

                // 2026-10-13（乙）：这一段几何刚被（重新）接管 —— 无论是补传回来的、
                // 还是 Java 重新上传的 —— 都要从"非常驻表"里摘掉，否则：
                //   · 常驻的段会一直被补传段重复标脏（多余的整块重建）；
                //   · 而"重捕获后其实没有几何"的段会永远留在表里 ⇒ 每个补传批次
                //     都把它重新标脏一次，形成永不收敛的抖动。
                // 放在 vertices.empty() **之前**：空几何也说明"这一轮已经处理过它了"，
                // 该段此时既不常驻也不需要补传；日后 Java 真的补上几何会照旧走脏键。
                g_nonResidentSections.erase(
                    classKey & SPATIAL_SECTION_KEY_MASK
                );

                if(vertices.empty())
                {
                    retirePreviousSection();
                    return;
                }

                if(hadPreviousSection)
                {
                    const uint32_t newTriangleCount =
                        static_cast<uint32_t>(vertices.size() / 3u);

                    if(newTriangleCount == previousTriangleCount)
                    {
                        ++g_sectionASRebuildSameTris;

                        if(!previousHadOpacityMicromap)
                        {
                            ++g_sectionASRefitCandidateHits;
                        }
                    }
                }

                // =====================================================
                // 2026-10-21 refit 快路（ORION_AS_REFIT=1 才进）
                //
                // 条件全部满足才走，否则原样重建：
                //   · 旧 AS 建时带 ALLOW_UPDATE（previousRefitCapable）
                //   · 无 OMM（micromap 没有 update 模式）
                //   · primitiveCount 相同、顶点字节布局完全相同（含运动位移尾段）
                //   · 有 update 口径的 scratch 需求
                // 动作：不 retire、不换 chunk、不改 AS 句柄；把新顶点经 staging 拷回
                // **原** vertex buffer，再以 UPDATE 模式重录 BLAS。
                // =====================================================
                if(hadPreviousSection &&
                   previousRefitCapable &&
                   previousUpdateScratchSize != 0u &&
                   sectionBLASRefitEnabled())
                {
                    const uint32_t newTriangleCount =
                        static_cast<uint32_t>(vertices.size() / 3u);

                    // 与 createSectionBLAS 完全同口径地算新布局（顶点 + 可选位移尾段）。
                    const uint32_t newMotionFloats =
                        (vertexMotion != nullptr && !vertexMotion->empty())
                            ? static_cast<uint32_t>(vertices.size() * 3u)
                            : 0u;

                    // 2026-10-21 地形 32B：步长必须与 createSectionBLAS 用同一个判据，
                    // 否则 newVertexBytes 与 section.vertexBytes 永远不等 ⇒ refit 静默失效
                    // （只是退回重建，不会算错）。索引化 SOLID 当前恒 false；若将来打开，
                    // 这里要补 indexedSolidQuads 的等价判据。
                    const VkDeviceSize newVertexStride =
                        static_cast<VkDeviceSize>(
                            sectionUsesPackedVertices(
                                classKey,
                                false,
                                vertices.size())
                                ? sizeof(SectionVertex)
                                : sizeof(Vertex));

                    VkDeviceSize newVertexBytes =
                        static_cast<VkDeviceSize>(vertices.size()) *
                        newVertexStride;

                    if(newMotionFloats != 0u)
                    {
                        newVertexBytes +=
                            static_cast<VkDeviceSize>(newMotionFloats) *
                            sizeof(float);
                    }

                    if(newTriangleCount == previousTriangleCount &&
                       newVertexBytes == previousVertexBytes &&
                       newMotionFloats == previousMotionFloats &&
                       !previousHadOpacityMicromap)
                    {
                        auto refitEntry = g_sectionBLAS.find(classKey);

                        if(refitEntry != g_sectionBLAS.end())
                        {
                            RTSectionAS& refitSection = refitEntry->second;

                            refitSection.pendingRefit = true;
                            sectionsNeedingBuild.push_back(&refitSection);

                            constexpr VkDeviceSize STAGING_ALIGNMENT = 16;

                            if(totalStagingBytes >
                               std::numeric_limits<VkDeviceSize>::max() -
                                   (STAGING_ALIGNMENT - 1))
                            {
                                throw std::runtime_error(
                                    "Section refit staging offset overflow");
                            }

                            const VkDeviceSize stagingOffset =
                                (totalStagingBytes + STAGING_ALIGNMENT - 1) &
                                ~(STAGING_ALIGNMENT - 1);

                            if(stagingOffset >
                               std::numeric_limits<VkDeviceSize>::max() -
                                   refitSection.vertexBytes)
                            {
                                throw std::runtime_error(
                                    "Section refit staging size overflow");
                            }

                            pendingUploads.push_back(
                                { &refitSection, &vertices, stagingOffset,
                                  vertexMotion, packedVertices }
                            );
                            totalStagingBytes =
                                stagingOffset + refitSection.vertexBytes;
                            maxBLASScratchSize = std::max(
                                maxBLASScratchSize,
                                refitSection.updateScratchSize
                            );

                            if(opaqueGeometry)
                            {
                                rebuiltOpaqueTriangleCount +=
                                    refitSection.triangleCount;
                            }
                            else if(
                                (classKey & ~SPATIAL_SECTION_KEY_MASK) ==
                                SECTION_AS_CLASS_WATER
                            )
                            {
                                rebuiltWaterTriangleCount +=
                                    refitSection.triangleCount;
                            }

                            ++g_sectionASRefitHits;
                            return;
                        }
                    }
                }

                retirePreviousSection();

                RTSectionAS newSection{};
                try
                {
                    const std::chrono::steady_clock::time_point createStart =
                        std::chrono::steady_clock::now();

                    const VkDeviceSize scratchSize =
                        createSectionBLAS(
                            newSection,
                            classKey,
                            vertices,
                            opaqueGeometry,
                            ommInput,
                            vertexMotion,
                            // 2026-10-21：闸门打开时新段一律带 ALLOW_UPDATE，
                            // 这样它下一次同拓扑重建就能走 refit。
                            sectionBLASRefitEnabled()
                        );

                    g_sectionASCreateMs +=
                        std::chrono::duration<double, std::milli>(
                            std::chrono::steady_clock::now() - createStart
                        ).count();
                    ++g_sectionASCreateCalls;

                    auto insertResult =
                        g_sectionBLAS.emplace(
                            classKey,
                            std::move(newSection)
                        );
                    if(!insertResult.second)
                    {
                        throw std::runtime_error("duplicate Section BLAS key");
                    }

                    RTSectionAS& insertedSection =
                        insertResult.first->second;
                    newSection = {};
                    sectionsNeedingBuild.push_back(&insertedSection);

                    constexpr VkDeviceSize STAGING_ALIGNMENT = 16;
                    if(totalStagingBytes >
                       std::numeric_limits<VkDeviceSize>::max() -
                           (STAGING_ALIGNMENT - 1))
                    {
                        throw std::runtime_error("Section staging offset overflow");
                    }

                    const VkDeviceSize stagingOffset =
                        (totalStagingBytes + STAGING_ALIGNMENT - 1) &
                        ~(STAGING_ALIGNMENT - 1);
                    if(stagingOffset >
                       std::numeric_limits<VkDeviceSize>::max() -
                           insertedSection.vertexBytes)
                    {
                        throw std::runtime_error("Section staging size overflow");
                    }

                    pendingUploads.push_back(
                        { &insertedSection, &vertices, stagingOffset,
                          vertexMotion, packedVertices }
                    );
                    totalStagingBytes =
                        stagingOffset + insertedSection.vertexBytes;
                    maxBLASScratchSize = std::max(
                        maxBLASScratchSize,
                        scratchSize
                    );
                    if(opaqueGeometry)
                    {
                        rebuiltOpaqueTriangleCount +=
                            insertedSection.triangleCount;
                    }
                    else if(insertedSection.hasOpacityMicromap)
                    {
                        rebuiltOmmTriangleCount +=
                            insertedSection.triangleCount;
                    }
                    else if(
                        (classKey & ~SPATIAL_SECTION_KEY_MASK) ==
                        SECTION_AS_CLASS_WATER
                    )
                    {
                        rebuiltWaterTriangleCount +=
                            insertedSection.triangleCount;
                    }
                    else if(
                        (classKey & ~SPATIAL_SECTION_KEY_MASK) ==
                        SECTION_AS_CLASS_PARTICLE
                    )
                    {
                        rebuiltParticleTriangleCount +=
                            insertedSection.triangleCount;
                    }
                    else
                    {
                        rebuiltAlphaTriangleCount +=
                            insertedSection.triangleCount;
                    }
                    ++rebuiltSectionCount;
                }
                catch(const SectionMemoryUnavailableError&)
                {
                    // 2026-10-15（OOM 崩溃修复）：显存耗尽 ⇒ 跳过本块，不再终止进程。
                    // 旧 BLAS 已在上面 retire+erase，本块此刻的观感与"被闸门驱逐"
                    // 完全一致；进非常驻表后由 mode>=2 的补传配额在预算允许时重建，
                    // Java 重新上传也会重新标脏（见 :58956 摘除非驻表的同一约定）。
                    destroySectionAS(newSection);
                    g_sectionMemoryOomSkipCount += 1u;
                    g_nonResidentSections.insert(
                        classKey & SPATIAL_SECTION_KEY_MASK
                    );
                    RTLogFlushed(
                        "[SECTION OOM] build skipped (out of device memory), key=" +
                        std::to_string(classKey) +
                        " totalSkips=" +
                        std::to_string(g_sectionMemoryOomSkipCount)
                    );
                    return;
                }
                catch(...)
                {
                    destroySectionAS(newSection);
                    throw;
                }
            };

        if(update.second.opaque.empty() &&
           update.second.ommCutout.empty() &&
           update.second.alpha.empty() &&
           update.second.water.empty() &&
           update.second.entity.empty() &&
           update.second.localPlayer.empty() &&
           update.second.particle.empty())
        {
            ++removedSectionCount;
        }

        // 2026-10-09 运动矢量：只有三个动态 class 传位移（最后一个参数）。
        // 地形四个 class 一律 nullptr ⇒ 顶点缓冲不产生尾段、零额外内存，
        // 表项里 motionOffset=0 ⇒ shader 读到"该面不动"。
        //
        // 2026-10-10：改成"数据表 + 循环"，唯一目的是能在**两个 class 之间**插入
        // 预算检查（见上面 requeueSectionsFrom 与"预算下沉到类粒度"的说明）。
        // 类的顺序、每个 class 的 key 与全部参数都与改动前**逐项一致**：没有增删、
        // 没有换序，空 class 也照旧会被调用（lambda 内部仍要先丢掉旧的 BLAS）。
        struct RtGeometryClassPlan
        {
            uint64_t classKey;
            const std::vector<Vertex>* vertices;
            bool opaqueGeometry;
            const OmmCutoutInput* ommInput;
            const std::vector<float>* vertexMotion;
            // 2026-10-21：捕获阶段预打包的 32B 顶点（地形四桶有值，动态三桶为
            // nullptr —— 它们仍在渲染线程同步捕获，预打包只会多走一遍）。
            const std::vector<SectionVertex>* packed;
        };

        constexpr size_t RT_GEOMETRY_CLASS_COUNT = 7u;

        const RtGeometryClassPlan geometryClassPlan[RT_GEOMETRY_CLASS_COUNT] =
        {
            { spatialSectionKey | SECTION_AS_CLASS_OPAQUE,
              &update.second.opaque, true, nullptr, nullptr,
              &update.second.opaquePacked },
            { spatialSectionKey | SECTION_AS_CLASS_OMM,
              &update.second.ommCutout, false,
              update.second.hasOmmInput ? &update.second.ommInput : nullptr,
              nullptr, &update.second.ommCutoutPacked },
            { spatialSectionKey | SECTION_AS_CLASS_ALPHA,
              &update.second.alpha, false, nullptr, nullptr,
              &update.second.alphaPacked },
            { spatialSectionKey | SECTION_AS_CLASS_WATER,
              &update.second.water, false, nullptr, nullptr,
              &update.second.waterPacked },
            { spatialSectionKey | SECTION_AS_CLASS_ENTITY,
              &update.second.entity, false, nullptr,
              &update.second.entityMotion, nullptr },
            { spatialSectionKey | SECTION_AS_CLASS_LOCAL_PLAYER,
              &update.second.localPlayer, false, nullptr,
              &update.second.localPlayerMotion, nullptr },
            { spatialSectionKey | SECTION_AS_CLASS_PARTICLE,
              &update.second.particle, false, nullptr,
              &update.second.particleMotion, nullptr }
        };

        bool sectionAbortedMidway = false;

        for(size_t classIndex = 0u;
            classIndex < RT_GEOMETRY_CLASS_COUNT;
            ++classIndex)
        {
            // =================================================
            // ★ 中断点：只在 class 与 class 之间。
            //
            // 条件与上面那道既有闸门严格同源（同一个 sectionRebuildBudgetMs、
            // 同样受 g_asBuilt / forceReset 约束、同样**首节不设预算**）：
            // 唯一新增的是 classIndex != 0 —— 已经做完的 class 不白扔，
            // 本 Section 中途停下时 fromIndex 取**它自己**，下一帧整块重做。
            // =================================================
            if(classIndex != 0u &&
               sectionUpdateIndex != 0u &&
               g_asBuilt &&
               !forceReset &&
               rebuildElapsedMsNow() >= sectionRebuildBudgetMs)
            {
                requeueSectionsFrom(sectionUpdateIndex);
                sectionAbortedMidway = true;
                break;
            }

            const RtGeometryClassPlan& plan =
                geometryClassPlan[classIndex];

            rebuildGeometryClass(
                plan.classKey,
                *plan.vertices,
                plan.opaqueGeometry,
                plan.ommInput,
                plan.vertexMotion,
                plan.packed
            );
        }

        if(sectionAbortedMidway)
        {
            // 本批至此收工，交给循环后面的 staging / BLAS scratch / TLAS 段
            // 处理**本帧已经建好的那些 class**（它们都是完整可用的）。
            break;
        }
    }

    // 2026-10-09（B）构建循环收工 → 记下边界时间，并更新 buildLoop 段的最大值。
    // 判读见 g_geometryMaxBuildLoopMs 的说明。
    perfL10AfterBuildLoop =
        std::chrono::steady_clock::now();

    // 2026-10-11 慢帧归因（tail 内切）：2026-10-11 15:32~15:35 那一局实测
    // [RT GEOMETRY SLOW] 的四次慢调用里 tail 占 14.4/36.9/20.3/56.0ms（总 15.9/
    // 37.7/21.1/56.8）⇒ 尖峰**全在 tail**，而 tail 里被 STALL 计时的两个等待
    // （worldGeometryQueueIdle / sectionBuildFenceWait，阈值 3ms、开关已确认为 true）
    // 在这几帧一条都没打 ⇒ 不是那两个等待。
    // tail 里剩下的东西此前一个数都没有：staging 拷贝、BLAS scratch、命令缓冲
    // 分配+录制、实例表重写、vkQueueSubmit、4 次 vkUpdateDescriptorSets、停泊与日志。
    // 这里把它们切成五段，尾部同一行打出（见 [RT GEOMETRY SLOW] 的尾巴）。
    std::chrono::steady_clock::time_point rtxTailAfterStaging =
        perfL10AfterBuildLoop;
    // 2026-10-13 慢帧归因（preCmd 内切，见 [RT GEOMETRY SLOW] 的 ord/evict/inst/tlas 字段）：
    // 2026-10-13 22:57:24 那一秒出现一串 78ms 级的 geometry 慢帧，而 sections 只有 1 个、
    // tail 里别的段都是零点几 —— 整段时间全落在 preCmd（staging 就绪 → 开始录命令，
    // 源码 58366..59788，约 1400 行）。该窗口内**没有** vkAllocateMemory / vkWaitFences /
    // vkMapMemory，同帧也没有 [PERF L10 ALLOC]（它只打 >=1ms 的分配），而 [TLAS SKIP]
    // 的 instances 恒为 1099 ⇒ 不是分配抖动、也不是 TLAS 容量重建。
    // 所以把 preCmd 按地标再切五段，下一次慢帧就能直接指名。
    std::chrono::steady_clock::time_point rtxPreCmdAfterOrdered =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxPreCmdAfterEvict =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxPreCmdAfterInstances =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxPreCmdAfterTlas =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxTailBeforeCommandRecord =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxTailAfterCommandRecord =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxTailAfterFenceWait =
        perfL10AfterBuildLoop;
    std::chrono::steady_clock::time_point rtxTailAfterSubmit =
        perfL10AfterBuildLoop;

    {
        const double buildLoopMs =
            std::chrono::duration<double, std::milli>(
                perfL10AfterBuildLoop - perfL10BuildLoopStart
            ).count();

        if(buildLoopMs > g_geometryMaxBuildLoopMs)
        {
            g_geometryMaxBuildLoopMs = buildLoopMs;
        }
    }

    // 2026-10-07: the whole batch was captured and built inside the time
    // budget -> grow the cap back so a quiet burst still drains in one pass,
    // and retire the continue flag (both live on the render thread only).
    if(!sectionUpdates.empty())
    {
        g_sectionRebuildBatchCap = std::min<size_t>(
            SECTION_REBUILD_MAX_SECTIONS_PER_BATCH,
            g_sectionRebuildBatchCap + 2u
        );
    }
    g_sectionRebuildInterrupted = false;
    g_sectionRebuildContinueFrame = 0u;


    VkBuffer vertexStagingBuffer =
        VK_NULL_HANDLE;

    VkDeviceMemory vertexStagingMemory =
        VK_NULL_HANDLE;


    if(!pendingUploads.empty())
    {
        RtxSectionBuildBufferSlot vertexStagingSlot;

        if(g_vertexStagingPool.tryAcquire(totalStagingBytes, vertexStagingSlot))
        {
            // 2026-10-11 多槽池命中：稳态走这里，零 vkAllocateMemory / vkFreeMemory。
            vertexStagingBuffer = vertexStagingSlot.buffer;
            vertexStagingMemory = vertexStagingSlot.memory;

            g_sectionBuildPoolReuseCount += 1u;
        }
        else
        {

            // 2026-10-10：补上 10-09 那次"上传缓冲内存类型"修复**漏掉的一处**。
            //
            // 这是 Section 批量重建的顶点暂存：usage 只有 TRANSFER_SRC，用途是
            // 主机写入 → vkCmdCopyBuffer 拷进设备本地的网格缓冲，也就是 10-09 那条
            // 规则里的教科书案例（"主机写、设备读一次"）⇒ 应当在系统内存，没有理由
            // 占那块小 BAR 堆（DEVICE_LOCAL|HOST_VISIBLE，没开 ReBAR 只有 256MB）。
            //
            // 为什么这一处特别要紧（比纹理 staging 更要紧）：
            //   · 尺寸是世界规模 —— totalStagingBytes 是一次重建里**全部**待建 Section
            //     的顶点字节之和，探索越远越大；
            //   · 而且是**池化且只增不减**（见上面的 RtxSectionBuildBufferPool），
            //     历史峰值会长期常驻；
            //   · BAR 堆同时也是"每帧被光追反复读"那些缓冲（本地光 / 动态光 / 地址表 /
            //     TLAS 实例表）的家，被它挤占后驱动只能驱逐 → 溢出到系统内存，
            //     正是 [RT MEM] 里"rssMB/privateMB 涨而原生各结构全都有界"的形状。
            // 2026-10-14：容量按 2 的幂向上取整（见 sectionBuildPoolSlotBytes 说明）。
            // 分配与登记都用取整后的尺寸，这样 tryAcquire 的 "slot.bytes >= 需要"
            // 比的仍是真实容量，只是档位变粗 ⇒ 池命中率从"看运气"变成"几乎恒命中"。
            const VkDeviceSize vertexStagingSlotBytes =
                sectionBuildPoolSlotBytes(totalStagingBytes);

            createBuffer(
                g_device,
                g_physicalDevice,
                vertexStagingSlotBytes,
                VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
                VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                    VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                vertexStagingBuffer,
                vertexStagingMemory,
                true
            );

            // 登记进池（只增不减；下一批重建即可命中）。
            g_vertexStagingPool.adopt(
                vertexStagingBuffer,
                vertexStagingMemory,
                vertexStagingSlotBytes
            );

            g_sectionBuildPoolAllocCount += 1u;
        }


        void* mappedStaging = nullptr;

        check(
            vkMapMemory(
                g_device,
                vertexStagingMemory,
                0,
                totalStagingBytes,
                0,
                &mappedStaging
            ),
            "map batched Section staging buffer failed"
        );


        uint8_t* stagingBytes =
            static_cast<uint8_t*>(
                mappedStaging
            );


        for(const PendingSectionUpload& upload : pendingUploads)
        {
            // ⚠ 2026-10-09 运动矢量：`section->vertexBytes` 现在**含位移尾段**，
            // 不能再拿它当顶点那一段的长度 —— 顶点向量里没有那么多元素，直接
            // memcpy 会读到界外。
            const VkDeviceSize vertexOnlyBytes =
                static_cast<VkDeviceSize>(
                    upload.vertices->size()
                ) *
                static_cast<VkDeviceSize>(
                    upload.section->vertexStride);

            if(upload.section->packedSectionVertices &&
               upload.packed != nullptr &&
               upload.packed->size() == upload.vertices->size())
            {
                // 2026-10-21（第 2 条）快路：捕获线程已经打包完，这里只剩搬运。
                // 判据（是否 32B）仍由 createSectionBLAS 写入 section，本分支只
                // 决定"搬哪一份"；size 校验保证预打包与最终顶点数一致。
                std::memcpy(
                    stagingBytes +
                        static_cast<size_t>(upload.stagingOffset),
                    upload.packed->data(),
                    static_cast<size_t>(upload.vertices->size()) *
                        sizeof(SectionVertex)
                );
            }
            else if(upload.section->packedSectionVertices)
            {
                // 2026-10-21 地形 32B：CPU 侧仍是 48B Vertex，这里逐顶点打包
                // （颜色 → RGBA8、pad1 折进 pad2）。见 makeSectionVertex()。
                SectionVertex* const packed =
                    reinterpret_cast<SectionVertex*>(
                        stagingBytes +
                        static_cast<size_t>(upload.stagingOffset));

                const std::vector<Vertex>& source = *upload.vertices;

                for(size_t vertexIndex = 0u;
                    vertexIndex < source.size();
                    ++vertexIndex)
                {
                    packed[vertexIndex] = makeSectionVertex(source[vertexIndex]);
                }
            }
            else
            {
                std::memcpy(
                    stagingBytes +
                        static_cast<size_t>(
                            upload.stagingOffset
                        ),
                    upload.vertices->data(),
                    static_cast<size_t>(
                        vertexOnlyBytes
                    )
                );
            }

            const VkDeviceSize motionTailBytes =
                upload.section->vertexBytes -
                vertexOnlyBytes;

            if(motionTailBytes > 0u)
            {
                uint8_t* const tail =
                    stagingBytes +
                    static_cast<size_t>(upload.stagingOffset) +
                    static_cast<size_t>(vertexOnlyBytes);

                // 先整段清零：来源短于尾段时，剩下的必须是 0 而不是 staging 的
                // 残留垃圾（垃圾会变成任意位移 ⇒ 画面上一片乱拖）。
                std::memset(
                    tail,
                    0,
                    static_cast<size_t>(motionTailBytes)
                );

                if(
                    upload.motion != nullptr &&
                    !upload.motion->empty()
                )
                {
                    std::memcpy(
                        tail,
                        upload.motion->data(),
                        std::min(
                            static_cast<size_t>(motionTailBytes),
                            upload.motion->size() * sizeof(float)
                        )
                    );
                }
            }
        }


        vkUnmapMemory(
            g_device,
            vertexStagingMemory
        );
    }


    // 2026-10-11 慢帧归因（tail 内切）：staging 段到此结束（见 perfL10AfterBuildLoop 后的说明）。
    rtxTailAfterStaging = std::chrono::steady_clock::now();

    std::vector<RTSectionAS*>
        orderedSections;

    orderedSections.reserve(
        g_sectionBLAS.size()
    );


    for(auto& entry : g_sectionBLAS)
    {
        if(
            entry.second.blas == VK_NULL_HANDLE ||
            entry.second.blasAddress == 0 ||
            entry.second.vertexAddress == 0
        )
        {
            throw std::runtime_error(
                "Section AS map contains an incomplete entry"
            );
        }


        orderedSections.push_back(
            &entry.second
        );
    }


    std::sort(
        orderedSections.begin(),
        orderedSections.end(),
        [](
            const RTSectionAS* a,
            const RTSectionAS* b
        )
        {
            return
                a->sectionKey <
                b->sectionKey;
        }
    );


    // Hand every Section its stable vertex address table slot before the
    // instance list is built, because instanceCustomIndex carries that slot
    // into the hit shaders.  Only newly acquired slots are written, so this
    // replaces the per-rebuild full-table rewrite.
    //
    // 2026-10-13：ensureSectionVertexAddressSlot 现在返回 bool。拿不到槽的 Section
    // 从本轮 orderedSections 里**摘掉** —— 它既没有角色位，也不会在下游的实例循环里
    // 被建成 instance（否则 instanceCustomIndex 会指向占位槽 0，那是测试三角形，
    // 绝不能进 TLAS）。表现是本轮不出现，与距离剔除同形，符合"允许视距外缺失"。
    for(auto it = orderedSections.begin(); it != orderedSections.end(); )
    {
        RTSectionAS* section = *it;

        if(!ensureSectionVertexAddressSlot(*section))
        {
            it = orderedSections.erase(it);
            continue;
        }

        writeSectionRoleSlot(
            *section
        );

        ++it;
    }


    // Published right after the roles, from the same Section list, so the two
    // can never describe different frames.
    rebuildLodCoverage(
        orderedSections
    );


    constexpr size_t MAX_TLAS_CUSTOM_INDEX_COUNT =
        static_cast<size_t>(1u << 24u);


    if(
        orderedSections.size() >
        MAX_TLAS_CUSTOM_INDEX_COUNT
    )
    {
        throw std::runtime_error(
            "Section count exceeds instanceCustomIndex 24-bit capacity"
        );
    }


    // 2026-10-04 TLAS 视锥剔除（「后处理」页"TLAS视锥剔除边距"，0 = 关）：
    // 由当帧 viewProj = inv(projInverse)·inv(viewInverse) 提取 5 个视锥面
    // （Gribb-Hartmann；远面归距离剔除）。每帧构建只算一次；下面循环里的
    // AABB 半径 = 8√3（16 格 Section 半对角）+ 外扩边距。
    // ⚠ 相机矩阵取 g_cameraUboHost（updateCamera 在 renderLevel HEAD 先行
    //   写入，与距离剔除诊断同一数据源、同一时效假设）。
    static float s_tlasFrustumPlanes[5][4] = {};
    static bool s_tlasFrustumPlanesValid = false;
    s_tlasFrustumPlanesValid = false;
    {
        const CameraUBO* frustumUbo =
            g_cameraUboMapped != nullptr
                ? static_cast<const CameraUBO*>(g_cameraUboMapped)
                : nullptr;

        if(frustumUbo != nullptr)
        {
            float view[16];
            float proj[16];
            float viewProj[16];

            if(mat4Invert(frustumUbo->viewInverse, view) &&
               mat4Invert(frustumUbo->projInverse, proj))
            {
                mat4Mul(proj, view, viewProj);

                // Gribb-Hartmann 行组合（列主序 M，行 i 取 M[j*4+i]）
                const float (*m)[4] =
                    reinterpret_cast<const float (*)[4]>(viewProj);
                float planes[5][4] = {
                    // left:   row3 + row0
                    { m[0][3] + m[0][0], m[1][3] + m[1][0], m[2][3] + m[2][0], m[3][3] + m[3][0] },
                    // right:  row3 - row0
                    { m[0][3] - m[0][0], m[1][3] - m[1][0], m[2][3] - m[2][0], m[3][3] - m[3][0] },
                    // bottom: row3 + row1
                    { m[0][3] + m[0][1], m[1][3] + m[1][1], m[2][3] + m[2][1], m[3][3] + m[3][1] },
                    // top:    row3 - row1
                    { m[0][3] - m[0][1], m[1][3] - m[1][1], m[2][3] - m[2][1], m[3][3] - m[3][1] },
                    // near:   row3 + row2
                    { m[0][3] + m[0][2], m[1][3] + m[1][2], m[2][3] + m[2][2], m[3][3] + m[3][2] },
                };

                bool allFinite = true;
                for(int p = 0; p < 5; ++p)
                {
                    const float len = std::sqrt(
                        planes[p][0] * planes[p][0] +
                        planes[p][1] * planes[p][1] +
                        planes[p][2] * planes[p][2]);

                    if(len > 1.0e-8f)
                    {
                        for(int k = 0; k < 4; ++k)
                        {
                            s_tlasFrustumPlanes[p][k] = planes[p][k] / len;
                            if(!std::isfinite(s_tlasFrustumPlanes[p][k]))
                            {
                                allFinite = false;
                            }
                        }
                    }
                    else
                    {
                        allFinite = false;
                    }
                }

                s_tlasFrustumPlanesValid = allFinite;
            }
        }
    }

    // =====================================================
    // 2026-10-11「体积光穿墙」修复：太阳阴影图的**保留盒**
    //
    // 太阳阴影图（cpp/shaders/sun_shadow.glsl，生产者 rt_sun_shadow.comp）是在
    // **光空间**里、以相机为中心、三轴各 ±160 格的盒子里打射线的；它需要的遮挡体
    // 就是这个盒里的 Section。
    //
    // 而下面循环里的两个剔除都是按**相机**的视锥/距离剔实例，与光空间方向无关：
    //   · 距离剔除（「TLAS剔除距离」，0 = 自适应 = clamp(视距×1.25, 64, 512)）把
    //     100 格外的 Section 拿掉；
    //   · 视锥剔除（「TLAS视锥剔除边距」）把相机身后/侧方的 Section 拿掉。
    // 两者都会把"本应挡住太阳、给空气投下影子的地形"从 TLAS 里拿掉 ⇒ 太阳阴影图
    // 查不到遮挡 ⇒ 该处空气被判受光 ⇒ **光柱穿墙**。
    //
    // 2026-10-10 修的阴影图射线端镜像是一个**另一个**独立 bug；它不改这里的观感，
    // 所以"数学修好了、用户仍看到穿墙"是必然的 —— 真正的漏点在这里：实测日志
    // [CULL DIAG] 一次剔除 frustumCulled≈6321 / culled≈4453（合计约 13% 实例），
    // 被剔的正是阴影图要用、而相机看不见的那些地形。
    //
    // 所以：落在保留盒里的 Section 一律不参与这两个剔除；盒外照旧剔 —— 远景剔除的
    // 收益保留，而阴影图要的遮挡体不再被误杀。改动方向是"只多留、不少留"，所以
    // 最坏情况只是白留一点实例（变慢），不可能把画面里该有的几何剔没。
    //
    // 盒中心取相机眼位（与 sunShadowCenter 同源，量化误差 <1 格，忽略）；正交基与
    // sun_shadow.glsl 的 sunShadowBasis 逐字同式，避免"写盒"和"读盒"两套基。
    // =====================================================
    static float s_sunShadowKeepBasis[3][3] = {};
    static float s_sunShadowKeepCenter[3] = {};
    static bool s_sunShadowKeepValid = false;
    s_sunShadowKeepValid = false;
    {
        const CameraUBO* keepUbo =
            g_cameraUboMapped != nullptr
                ? static_cast<const CameraUBO*>(g_cameraUboMapped)
                : nullptr;

        if(keepUbo != nullptr)
        {
            // sunShadowLightDirection()：相位 = historyParams.w，方向翻到 y ≥ 0。
            const float phase = keepUbo->historyParamsPadding1;
            const float angle =
                (phase - std::floor(phase)) * 6.28318530718f;
            float sunX = std::cos(angle);
            float sunY = 0.81915204429f * std::sin(angle);
            float sunZ = 0.57357643635f * std::sin(angle);
            const float sunLen =
                std::sqrt(sunX * sunX + sunY * sunY + sunZ * sunZ);

            if(sunLen > 1.0e-8f)
            {
                sunX /= sunLen;
                sunY /= sunLen;
                sunZ /= sunLen;
                if(sunY < 0.0f)
                {
                    sunX = -sunX;
                    sunY = -sunY;
                    sunZ = -sunZ;
                }

                // sunShadowBasis()：reference = |s.y| > 0.99 ? (1,0,0) : (0,1,0)
                float rightX;
                float rightY;
                float rightZ;
                if(std::fabs(sunY) > 0.99f)
                {
                    rightX = 0.0f;
                    rightY = -sunZ;
                    rightZ = sunY;
                }
                else
                {
                    rightX = sunZ;
                    rightY = 0.0f;
                    rightZ = -sunX;
                }

                const float rightLen = std::sqrt(
                    rightX * rightX + rightY * rightY + rightZ * rightZ);

                if(rightLen > 1.0e-8f)
                {
                    rightX /= rightLen;
                    rightY /= rightLen;
                    rightZ /= rightLen;

                    // up = cross(sunDirection, basisRight)
                    float upX = sunY * rightZ - sunZ * rightY;
                    float upY = sunZ * rightX - sunX * rightZ;
                    float upZ = sunX * rightY - sunY * rightX;
                    const float upLen =
                        std::sqrt(upX * upX + upY * upY + upZ * upZ);

                    if(upLen > 1.0e-8f)
                    {
                        upX /= upLen;
                        upY /= upLen;
                        upZ /= upLen;

                        for(int axis = 0; axis < 3; ++axis)
                        {
                            s_sunShadowKeepCenter[axis] =
                                keepUbo->viewInverse[12 + axis];
                        }

                        s_sunShadowKeepBasis[0][0] = rightX;
                        s_sunShadowKeepBasis[0][1] = rightY;
                        s_sunShadowKeepBasis[0][2] = rightZ;
                        s_sunShadowKeepBasis[1][0] = upX;
                        s_sunShadowKeepBasis[1][1] = upY;
                        s_sunShadowKeepBasis[1][2] = upZ;
                        s_sunShadowKeepBasis[2][0] = sunX;
                        s_sunShadowKeepBasis[2][1] = sunY;
                        s_sunShadowKeepBasis[2][2] = sunZ;
                        s_sunShadowKeepValid = true;
                    }
                }
            }
        }
    }

    // =====================================================
    // 2026-10-13（乙·一期）：Section 几何非常驻化 —— 预算驱动的距离驱逐
    //
    // 放在这里的原因：两套守卫（视锥面 + 太阳阴影保留盒）刚好都在上面算完了，
    // 而实例列表还没开始构建 ⇒ **本帧就能生效**（不必等到下一次重建）。
    //
    // 选择粒度 = spatial Section（一个 Section 在 g_sectionBLAS 里可能有多条，
    // 每个 class 一条 ⇒ 必须整段一起走，否则会留下半张几何）。
    //
    // 守卫（全部与 TLAS 剔除同一套判据，避免"放掉了本该保留的东西"）：
    //   · 保护半径内     —— 不驱逐（给补传留缓冲带，见 vramEvictKeepRadius）
    //   · 阴影保留盒内   —— 不驱逐（否则"体积光穿墙"会回来）
    //   · 视锥内         —— 不驱逐（否则玩家正看着的地形缺块）
    //   · 非真实世界高度 —— 不驱逐（voxy/DH/实体的 X/Z 不是世界坐标）
    //
    // 视锥测试刻意**不读** g_tlasFrustumCullMargin：那是用户对"实例剔除"的设置，
    // 不该影响"会不会把可见几何放掉"。这里半径只取 Section 半对角（更保守）。
    //
    // 释放走既有原语 retireSectionAS()（停进退休环，fence 信号后才真释放），
    // 不做裸 vkFreeMemory ⇒ 不引入新的时序约定。
    //
    // A/B：ORION_VRAM_GOVERNOR < 2 时整段不生效（一期行为）。
    //
    // 2026-10-13（乙·修正）：越线时按**超线程度**收缩上面两道保护壳。
    //
    // 现场（19:15-19:17 那一局，单客户端、8 区块）：`over=1` 连续 44 秒，而
    // `nonResident` 恒为 0 —— 一个候选都没选出来，最后只驱逐了 15 个。读到原因是
    // 上面那条注释自己写的东西：**太阳阴影保留盒以相机为中心、XY 各 ±160 格**，
    // 而本局 cullDist=160 ⇒ 已加载几何**整个落在盒内** ⇒ `insideKeepBox` 把每一个
    // Section 都 continue 掉。距离守卫（96×1.25=120 格）叠加后候选带更窄。
    //
    // 所以越线时把两道壳按超线比例收缩（overageT：刚过 85% 为 0，到 100% 为 1）：
    //   · 保护半径最多收到 (1 - VRAM_EVICT_SHRINK_RADIUS) = 0.75×  ⇒ 96 → 72 格
    //   · 阴影保留盒最多收到 (1 - VRAM_EVICT_SHRINK_SHADOW) = 0.60× ⇒ 160 → 96 格
    //
    // 代价：阴影图边缘的遮挡体可能被放掉 ⇒ 远处可能出现"体积光穿墙"。这是显存告急时
    // 刻意接受的取舍（比整帧放弃、画面退回原版好得多）。防抖仍然保留：evictRadius
    // 里 25% 的迟滞、keepRadius 72 格的硬地板，以及下面的补传半径不参与收缩。
    // =====================================================
    if(vramGovernorMode() >= 2 &&
       g_vramGovernor.over &&
       !orderedSections.empty())
    {
        // 2026-10-13：保护壳收缩系数（见上面说明）。
        constexpr float VRAM_EVICT_SHRINK_RADIUS = 0.25f;
        constexpr float VRAM_EVICT_SHRINK_SHADOW = 0.40f;

        const double overRatio =
            g_vramGovernor.budgetMb > 0.0
                ? g_vramGovernor.usedMb / g_vramGovernor.budgetMb
                : 0.0;

        // 2026-10-13（修正 2）：**一旦 over 就用满收缩量**，不再按"逼近 1.0"的比例。
        //
        // 现场（19:39 那一局）：over=1、ratio=0.849 ⇒ 旧公式 overageT=(0.849-0.85)/0.15
        // 为负、归零 ⇒ 保护壳原样 ⇒ nonResident 与 secEvicted 恒为 0，二期一次都没动作。
        // 而同一局 DLSS 在 **ratio=0.849 就报 eWarnOutOfVRAM**（37 次）⇒ 等不到"逼近 1.0"
        // 那一刻。所以越线即用满；越线越早，收缩越早生效、越安全。
        const float overageT = 1.0f;

        // 只用于日志：把实际比例带出来，便于按局对比。
        (void)overRatio;

        const float keepRadius =
            vramEvictKeepRadius() *
            (1.0f - VRAM_EVICT_SHRINK_RADIUS * overageT);
        const float evictRadius = keepRadius * VRAM_EVICT_HYSTERESIS;
        const float evictRadiusSq = evictRadius * evictRadius;

        // 阴影保留盒的收缩系数（下面 insideKeepBox 用它缩放三个半轴）。
        const float shadowKeepScale =
            1.0f - VRAM_EVICT_SHRINK_SHADOW * overageT;

        const CameraUBO* evictUbo =
            g_cameraUboMapped != nullptr
                ? static_cast<const CameraUBO*>(g_cameraUboMapped)
                : nullptr;

        const float playerX = evictUbo ? evictUbo->playerX : 0.0f;
        const float playerY = evictUbo ? evictUbo->playerY : 0.0f;
        const float playerZ = evictUbo ? evictUbo->playerZ : 0.0f;

        struct VramEvictCandidate
        {
            uint64_t spatialKey = 0u;
            float distanceSq = 0.0f;
        };

        // 2026-10-13 preCmd 内切①：orderedSections 构建到此结束。
        rtxPreCmdAfterOrdered = std::chrono::steady_clock::now();

        std::vector<VramEvictCandidate> candidates;
        candidates.reserve(g_sectionBLAS.size());

        {
            std::unordered_set<uint64_t> seen;

            for(const auto& entry : g_sectionBLAS)
            {
                const uint64_t spatialKey =
                    entry.second.sectionKey & SPATIAL_SECTION_KEY_MASK;

                if(!seen.insert(spatialKey).second)
                {
                    continue;
                }

                if(!vramWorldHeightSection(spatialKey))
                {
                    continue;
                }

                float centerX = 0.0f;
                float centerY = 0.0f;
                float centerZ = 0.0f;
                vramSectionCenterFromSpatialKey(
                    spatialKey,
                    centerX,
                    centerY,
                    centerZ
                );

                const float dx = centerX - playerX;
                const float dy = centerY - playerY;
                const float dz = centerZ - playerZ;
                const float distanceSq = dx * dx + dy * dy + dz * dz;

                if(distanceSq <= evictRadiusSq)
                {
                    continue;
                }

                // 太阳阴影保留盒（与 TLAS 剔除同一套式，含半对角余量）。
                if(s_sunShadowKeepValid)
                {
                    constexpr float SECTION_HALF_DIAGONAL = 13.8564f;

                    const float keepX = centerX - s_sunShadowKeepCenter[0];
                    const float keepY = centerY - s_sunShadowKeepCenter[1];
                    const float keepZ = centerZ - s_sunShadowKeepCenter[2];

                    // 2026-10-13（乙·修正）：半轴乘 shadowKeepScale —— 越线时保留盒
                    // 收缩（见驱逐段说明），否则"±160 格的盒 + cullDist=160"会让每个
                    // Section 都判为盒内 ⇒ 永远选不出候选。不越线时该系数恒为 1.0，
                    // 判定与本改动前逐位相同。
                    const bool insideKeepBox =
                        std::fabs(keepX * s_sunShadowKeepBasis[0][0] +
                            keepY * s_sunShadowKeepBasis[0][1] +
                            keepZ * s_sunShadowKeepBasis[0][2]) <=
                                SUN_SHADOW_EXTENT_XY * shadowKeepScale +
                                    SECTION_HALF_DIAGONAL &&
                        std::fabs(keepX * s_sunShadowKeepBasis[1][0] +
                            keepY * s_sunShadowKeepBasis[1][1] +
                            keepZ * s_sunShadowKeepBasis[1][2]) <=
                                SUN_SHADOW_EXTENT_XY * shadowKeepScale +
                                    SECTION_HALF_DIAGONAL &&
                        std::fabs(keepX * s_sunShadowKeepBasis[2][0] +
                            keepY * s_sunShadowKeepBasis[2][1] +
                            keepZ * s_sunShadowKeepBasis[2][2]) <=
                                SUN_SHADOW_EXTENT_Z * shadowKeepScale +
                                    SECTION_HALF_DIAGONAL;

                    if(insideKeepBox)
                    {
                        continue;
                    }
                }

                // 视锥面还没就绪 ⇒ 这一批不驱逐，宁可不动。
                if(!s_tlasFrustumPlanesValid)
                {
                    continue;
                }

                {
                    constexpr float SECTION_HALF_DIAGONAL = 13.8564f;
                    bool frustumOutside = false;

                    for(int plane = 0; plane < 5; ++plane)
                    {
                        const float planeDist =
                            s_tlasFrustumPlanes[plane][0] * centerX +
                            s_tlasFrustumPlanes[plane][1] * centerY +
                            s_tlasFrustumPlanes[plane][2] * centerZ +
                            s_tlasFrustumPlanes[plane][3];

                        if(planeDist < -SECTION_HALF_DIAGONAL)
                        {
                            frustumOutside = true;
                            break;
                        }
                    }

                    if(!frustumOutside)
                    {
                        continue;
                    }
                }

                VramEvictCandidate candidate;
                candidate.spatialKey = spatialKey;
                candidate.distanceSq = distanceSq;
                candidates.push_back(candidate);
            }
        }

        if(!candidates.empty())
        {
            std::sort(
                candidates.begin(),
                candidates.end(),
                [](const VramEvictCandidate& a, const VramEvictCandidate& b)
                {
                    return a.distanceSq > b.distanceSq;
                }
            );

            const size_t evictQuota =
                std::min(candidates.size(), vramEvictPerPass());

            std::unordered_set<uint64_t> victims;
            victims.reserve(evictQuota);

            for(size_t index = 0u; index < evictQuota; ++index)
            {
                victims.insert(candidates[index].spatialKey);
            }

            // =====================================================
            // 2026-10-13 崩溃修复：本轮刚入队的 Section 不得被本轮的驱逐选中。
            //
            // 现场（2026-10-13 共 7 次硬崩，hs_err 同族）：渲染线程在 nvoglv64.dll
            // 里 AV（siginfo: reading address 0x110，RBX=RSI=0），栈为
            //   recordFrameCommand → rebuildWorldGeometry →（某次 vk 调用）→ 驱动。
            // 用 map + dumpbin 解出两处具体调用点，都在本段 ② 之后：
            //   · vkCmdCopyBuffer(cmd, staging, upload.section->vertexBuffer, …)
            //   · recordSectionBLASBuild(cmd, *section, …)
            // （两处驱动的 pc 偏移不同 ⇒ 同一根因、不同调用点。）
            //
            // 而这两个队列（pendingUploads / sectionsNeedingBuild）里存的是指向
            // g_sectionBLAS **条目**的裸指针（57944 / 57964）。② 会
            // retireSectionAS + erase 条目 ⇒ 那些指针立刻悬垂 ⇒ 队列把垃圾句柄
            // 喂给驱动。这也解释了为什么空值护栏没命中：内存里是垃圾，不是 VK_NULL。
            //
            // 为什么会被选中：candidates 取自**全部** g_sectionBLAS，本轮刚插入的
            // Section 也在其中；流式期"刚补进来但还在远处/视锥外"非常常见 ⇒ 进 victims。
            //
            // 修法：把"本轮即将拷贝 / 即将建 BLAS"的段从 victims 里摘掉。语义上也
            // 更对 —— 正在上传的段本来就不该在这几毫秒里被驱逐。摘掉后 ① 的
            // orderedSections 剔除、③ 的非常驻记账、g_vramEvictedSections 计数
            // 三处自动保持一致（它们都用同一个 victims）。
            // =====================================================
            for(const PendingSectionUpload& upload : pendingUploads)
            {
                if(upload.section != nullptr)
                {
                    victims.erase(
                        upload.section->sectionKey & SPATIAL_SECTION_KEY_MASK
                    );
                }
            }

            for(const RTSectionAS* queuedSection : sectionsNeedingBuild)
            {
                if(queuedSection != nullptr)
                {
                    victims.erase(
                        queuedSection->sectionKey & SPATIAL_SECTION_KEY_MASK
                    );
                }
            }

            // ① 先从 orderedSections 摘掉（此刻指针仍有效）。
            orderedSections.erase(
                std::remove_if(
                    orderedSections.begin(),
                    orderedSections.end(),
                    [&victims](const RTSectionAS* section)
                    {
                        return victims.count(
                            section->sectionKey & SPATIAL_SECTION_KEY_MASK) != 0u;
                    }
                ),
                orderedSections.end()
            );

            // ② 再 retire + erase g_sectionBLAS 的**所有** class 条目。
            for(auto it = g_sectionBLAS.begin(); it != g_sectionBLAS.end();)
            {
                if(victims.count(
                       it->second.sectionKey & SPATIAL_SECTION_KEY_MASK) != 0u)
                {
                    retireSectionAS(it->second);
                    it = g_sectionBLAS.erase(it);
                }
                else
                {
                    ++it;
                }
            }

            // ③ 记账：这些 Section 的 CPU 顶点仍在 g_chunkMeshes 里，靠近时由补传重建。
            for(const uint64_t spatialKey : victims)
            {
                g_nonResidentSections.insert(spatialKey);
            }

            g_vramEvictedSections += victims.size();
        }
    }


    // 2026-10-13 preCmd 内切②：驱逐段（候选扫描 + 排序 + retireSectionAS + erase）到此结束。
    rtxPreCmdAfterEvict = std::chrono::steady_clock::now();

    std::vector<VkAccelerationStructureInstanceKHR>
        instances;


    if(orderedSections.empty())
    {
        // Keep Binding 0 valid while no world Section is loaded.
        // A zero BLAS reference makes this instance inactive.
        VkAccelerationStructureInstanceKHR inactive{};

        inactive.transform.matrix[0][0] = 1.0f;
        inactive.transform.matrix[1][1] = 1.0f;
        inactive.transform.matrix[2][2] = 1.0f;

        inactive.instanceCustomIndex = 0u;
        inactive.mask = 0u;

        inactive.instanceShaderBindingTableRecordOffset =
            0u;

        inactive.flags =
            VK_GEOMETRY_INSTANCE_TRIANGLE_FACING_CULL_DISABLE_BIT_KHR |
            VK_GEOMETRY_INSTANCE_FORCE_NO_OPAQUE_BIT_KHR;

        inactive.accelerationStructureReference =
            0;


        instances.push_back(
            inactive
        );
    }
    else
    {
        instances.reserve(
            orderedSections.size()
        );


        for(
            uint32_t instanceIndex = 0;
            instanceIndex <
                static_cast<uint32_t>(
                    orderedSections.size()
                );
            ++instanceIndex
        )
        {
            const RTSectionAS& section =
                *orderedSections[instanceIndex];

            float diagDistance = 0.0f;

            // =====================================================
            // 2026-10-03 剔除可行性诊断（零行为变化，只统计）：
            // 按"Section 中心到玩家的距离"分桶，回答"视锥/距离剔除有没有肉"。
            // 键位布局见 packSectionKey()：bits0..21=X、22..43=Z、44..59=Y
            //（16 格/Section，各自 22/22/16 位补码）；位置用玩家近似相机
            //（剔除增益估计对这个差别不敏感）。
            // =====================================================
            {
                auto signExtend = [](uint64_t value, int bits) -> int {
                    const uint64_t mask = 1ull << (bits - 1);
                    return static_cast<int>((value ^ mask) - mask);
                };

                const uint64_t spatialKey =
                    section.sectionKey & SPATIAL_SECTION_KEY_MASK;

                const float sectionWorldX = static_cast<float>(
                    signExtend(spatialKey & 0x3FFFFFull, 22)) * 16.0f + 8.0f;
                const float sectionWorldZ = static_cast<float>(
                    signExtend((spatialKey >> 22) & 0x3FFFFFull, 22)) * 16.0f + 8.0f;
                const float sectionWorldY = static_cast<float>(
                    signExtend((spatialKey >> 44) & 0xFFFFull, 16)) * 16.0f + 8.0f;

                const CameraUBO* diagUbo =
                    g_cameraUboMapped != nullptr
                        ? static_cast<const CameraUBO*>(g_cameraUboMapped)
                        : nullptr;
                const float diagCenterX = diagUbo ? diagUbo->playerX : 0.0f;
                const float diagCenterZ = diagUbo ? diagUbo->playerZ : 0.0f;
                const float diagCenterY = diagUbo ? diagUbo->playerY : 0.0f;

                const float diagDx = sectionWorldX - diagCenterX;
                const float diagDy = sectionWorldY - diagCenterY;
                const float diagDz = sectionWorldZ - diagCenterZ;
                diagDistance = std::sqrt(
                    diagDx * diagDx + diagDy * diagDy + diagDz * diagDz);

                static int diagBandCount[7] = {};
                static uint64_t diagBandTriangles[7] = {};
                static uint64_t diagTotalTriangles = 0;
                static int diagCulledCount = 0;
                static int diagFrustumCulled = 0;
                static int diagCullLimit = 0;
                static std::chrono::steady_clock::time_point diagLastPrint{};
                static bool diagLastPrintValid = false;
                diagCullLimit = g_tlasCullDistance.load();

                int diagBand =
                    diagDistance < 32.0f ? 0 :
                    diagDistance < 64.0f ? 1 :
                    diagDistance < 96.0f ? 2 :
                    diagDistance < 128.0f ? 3 :
                    diagDistance < 192.0f ? 4 :
                    diagDistance < 256.0f ? 5 : 6;

                diagBandCount[diagBand] += 1;
                diagBandTriangles[diagBand] += section.triangleCount;
                diagTotalTriangles += section.triangleCount;

                const auto diagNow = std::chrono::steady_clock::now();
                if(!diagLastPrintValid ||
                   std::chrono::duration<float>(diagNow - diagLastPrint).count() > 5.0f)
                {
                    if(diagLastPrintValid)
                    {
                        RTLogFlushed(std::string("[CULL DIAG]") +
                            " total=" + std::to_string(
                                diagBandCount[0] + diagBandCount[1] + diagBandCount[2] +
                                diagBandCount[3] + diagBandCount[4] + diagBandCount[5] +
                                diagBandCount[6]) +
                            " d<32=" + std::to_string(diagBandCount[0]) +
                            " 32-64=" + std::to_string(diagBandCount[1]) +
                            " 64-96=" + std::to_string(diagBandCount[2]) +
                            " 96-128=" + std::to_string(diagBandCount[3]) +
                            " 128-192=" + std::to_string(diagBandCount[4]) +
                            " 192-256=" + std::to_string(diagBandCount[5]) +
                            " >=256=" + std::to_string(diagBandCount[6]) +
                            " tris=" + std::to_string(diagTotalTriangles) +
                            " culled=" + std::to_string(diagCulledCount) +
                            " frustumCulled=" + std::to_string(diagFrustumCulled) +
                            " cullDist=" + std::to_string(diagCullLimit));
                    }
                    diagLastPrint = diagNow;
                    diagLastPrintValid = true;
                    std::fill(std::begin(diagBandCount), std::end(diagBandCount), 0);
                    std::fill(std::begin(diagBandTriangles), std::end(diagBandTriangles), 0);
                    diagTotalTriangles = 0;
                    diagCulledCount = 0;
                    diagFrustumCulled = 0;
                }

                // =================================================
                // 2026-10-03 TLAS 实例距离剔除（「后处理」页「TLAS剔除距离」，
                // 0 = 关 = 现状）。超距实例不进 TLAS：重建与遍历成本同步下降。
                // ⚠ 远场几何被剔除后，主画面由 DH 合成块负责（本来就不靠 TLAS）；
                //   次级射线（阴影/GI/反射）会失去超距遮挡 —— 默认关闭，由你 A/B。
                //
                // ⚠⚠ 只有"真实世界高度"的 Section 才允许参与距离剔除。
                //   voxy LOD / DH LOD（VOXY_LOD_RESERVED_Y = 0x7ffe）与动态实体
                //   聚合（ENTITY_RT_SPATIAL_KEY = 0x7fff，含 entity/localPlayer/
                //   particle 三个 layer）共用保留 Y 段，且它们的 X/Z **不是世界
                //   坐标**（LOD 是哈希分配槽位）。上面按世界坐标解出来的距离对这
                //   三类 Section 恒为 ~52 万格 ⇒ 只要 cullLimit > 0 就把它们全部
                //   静默剔光：实机表现为"实体、玩家自身代理、雨滴（走粒子路径）
                //   全部不可见"，而地形正常。这不是它们的距离太远，是判据用错了。
                // =================================================
                const int32_t diagSectionY =
                    static_cast<int32_t>(
                        (static_cast<uint32_t>(spatialKey >> 44) & 0xFFFFu) << 16) >> 16;
                const bool diagWorldHeightSection =
                    diagSectionY >= -64 && diagSectionY <= 512;

                // 太阳阴影保留盒（初始化见 instances 声明之前）：三轴投影都落在
                // 光空间盒（含一个 Section 半对角的余量）内 ⇒ 这个 Section 可能是
                // 太阳阴影图射线的遮挡体，两个剔除都放过它。
                bool sunShadowKeepsSection = false;
                if(s_sunShadowKeepValid)
                {
                    const float keepX =
                        sectionWorldX - s_sunShadowKeepCenter[0];
                    const float keepY =
                        sectionWorldY - s_sunShadowKeepCenter[1];
                    const float keepZ =
                        sectionWorldZ - s_sunShadowKeepCenter[2];
                    // 16³ Section 的半对角 = 8√3；余量让"中心在盒外、几何探进盒内"
                    // 的 Section 也保留（探进来的那部分照样挡光）。
                    constexpr float SECTION_HALF_DIAGONAL = 13.8564f;

                    sunShadowKeepsSection =
                        std::fabs(keepX * s_sunShadowKeepBasis[0][0] +
                            keepY * s_sunShadowKeepBasis[0][1] +
                            keepZ * s_sunShadowKeepBasis[0][2]) <=
                                SUN_SHADOW_EXTENT_XY + SECTION_HALF_DIAGONAL &&
                        std::fabs(keepX * s_sunShadowKeepBasis[1][0] +
                            keepY * s_sunShadowKeepBasis[1][1] +
                            keepZ * s_sunShadowKeepBasis[1][2]) <=
                                SUN_SHADOW_EXTENT_XY + SECTION_HALF_DIAGONAL &&
                        std::fabs(keepX * s_sunShadowKeepBasis[2][0] +
                            keepY * s_sunShadowKeepBasis[2][1] +
                            keepZ * s_sunShadowKeepBasis[2][2]) <=
                                SUN_SHADOW_EXTENT_Z + SECTION_HALF_DIAGONAL;
                }

                if(diagWorldHeightSection && !sunShadowKeepsSection &&
                   diagCullLimit > 0 &&
                   diagDistance > static_cast<float>(diagCullLimit))
                {
                    diagCulledCount += 1;
                    continue;
                }

                // 2026-10-04 TLAS 实例视锥剔除：5 面测试（left/right/bottom/top/near，
                // 远面归距离剔除）。AABB 半径 = 16 格 Section 半对角 8√3 + 外扩边距；
                // 面距 = plane·center + d，< -radius 即整体落在该面外侧 ⇒ 剔除。
                // ⚠ 与距离剔除共用同一保留 Y 段守卫（diagWorldHeightSection）：
                //   voxy LOD / 动态实体聚合不参与（X/Z 非世界坐标，见上方 ⚠⚠ 注释）。
                if(diagWorldHeightSection && !sunShadowKeepsSection &&
                   s_tlasFrustumPlanesValid)
                {
                    const int frustumMargin = g_tlasFrustumCullMargin.load();
                    if(frustumMargin > 0)
                    {
                        const float cullRadius =
                            13.8564f + static_cast<float>(frustumMargin);

                        bool frustumOutside = false;
                        for(int plane = 0; plane < 5; ++plane)
                        {
                            const float planeDist =
                                s_tlasFrustumPlanes[plane][0] * sectionWorldX +
                                s_tlasFrustumPlanes[plane][1] * sectionWorldY +
                                s_tlasFrustumPlanes[plane][2] * sectionWorldZ +
                                s_tlasFrustumPlanes[plane][3];

                            if(planeDist < -cullRadius)
                            {
                                frustumOutside = true;
                                break;
                            }
                        }

                        if(frustumOutside)
                        {
                            diagFrustumCulled += 1;
                            continue;
                        }
                    }
                }
            }


            VkAccelerationStructureInstanceKHR instance{};

            instance.transform.matrix[0][0] = 1.0f;
            instance.transform.matrix[1][1] = 1.0f;
            instance.transform.matrix[2][2] = 1.0f;

            // The hit shaders index the Section vertex address table with this
            // value, so it must be the Section's stable slot rather than its
            // position in this frame's instance list: the table is no longer
            // reordered to match the instance order.
            instance.instanceCustomIndex =
                section.vertexAddressSlot;

            // 位 0x04 = "遮挡体积光"。太阳阴影图的射线是**用这一位去 cull** 的
            // （见 cpp/shaders/sun_shadow.glsl 的 SUN_SHADOW_CULL_MASK），
            // 所以只有 `(instance.mask & 0x04) != 0` 的实例才挡得住光柱。
            // 反过来写是静默失效：把 cull mask 设成和某个桶一样的值，
            // 那个桶照样会被打到。
            instance.mask =
                0xff;

            // ⭐⭐ 09-25 方案 c（远场外观取 DH 自己渲染的画面）：
            //    DH 远场几何<b>不对主相机射线可见</b> ⇒ mask 清掉位 0x01，其余全保留
            //    （0x04 = 挡体积光/太阳阴影，必须留；0xff = 阴影/GI/反射/水面的次级射线）。
            //    主射线因此会在远场 miss ⇒ rgen 的合成块用 DH 的 color/depth 填上那片像素。
            //    ⚠ 只在合成块真的开着时才隐藏（g_dhFarFieldMode > 0.5，由 Java 的 farLight.mode 决定）。
            //      判据必须是"明确开启"（12/13），不能是 ">= 0"：
            //      g_dhFarFieldMode 的初值曾是 0.0f，而这条 JNI 推送只在 MATRICES 打开时才发生
            //      （Java 的 DhFarFieldGeometry），于是 mode 未被推送时读到的就是初值 ——
            //      ">= 0" 恒成立 ⇒ 远场几何被静默设成相机不可见 ⇒ 实机表现为"远景没出现"
            //      （日志却一切正常：数据/上传/FFG provider=dh 全齐）。现初值已改为 -1.0f，
            //      判据改为 > 0.5，两道都只在真正开启时才隐藏。
            //    ⚠ 不要写成 0x02（局部玩家代理的取值）：它没有 0x04 位，DH 远场就再也
            //      挡不住太阳光柱了。只针对 DH 的伪 section：voxy LOD 对相机仍然可见。
            //
            // ★ 2026-09-30：这个 mask 特判<b>只是合成块特性</b>，不再承担任何远场
            //   识别/去重职责。识别看每实例角色表（binding 19），去重看每柱覆盖位图
            //   （binding 20）——见 cpp/shaders/lod_coverage.glsl 与 sectionRoleOf()。
            const uint64_t instanceSpatialKey =
                section.sectionKey &
                SPATIAL_SECTION_KEY_MASK;

            if(g_dhFarFieldMode > 0.5f &&
               isDhLodSpatialKey(instanceSpatialKey))
            {
                instance.mask = 0xfe;
            }

            const uint64_t geometryClass =
                section.sectionKey & ~SPATIAL_SECTION_KEY_MASK;

            // ALPHA 桶（玻璃 / 树叶 / 植物）是半透明的，不该把光柱挡成一条
            // 硬边 —— "透过窗户看见光柱"正是靠这一条才成立的。
            //
            // 陷阱：`LOD_AS_CLASS_WATER == SECTION_AS_CLASS_ALPHA`（都是
            // `3ull << 60ull`），所以判 ALPHA 之前必须先排除 voxy LOD 键，
            // 否则 LOD 水面会被当成玻璃一起放行。
            const bool lodSpatialKey =
                (section.sectionKey & VOXY_LOD_RESERVED_Y) == VOXY_LOD_RESERVED_Y;
            if(!lodSpatialKey && geometryClass == SECTION_AS_CLASS_ALPHA)
            {
                instance.mask = 0xfb;
            }

            // Main camera rays use mask 0x01.  The local player's RT proxy
            // uses 0x02, so reflections/shadows/GI (0xff) can still hit it
            // without making first-person camera rays hit the player's own
            // body.  0x02 里没有 0x04，于是本地玩家代理也不投体积阴影 ——
            // 它只是个为了让相机看到自己身体而插进来的代理，挡出来的影子
            // 只会变成视野正中心的一块黑斑。
            if(geometryClass == SECTION_AS_CLASS_LOCAL_PLAYER)
            {
                instance.mask = 0x02;
            }

            // 2026-10-23：粒子/天气层（雨丝、雪片、普通粒子）**不参与"雨水可见度"
            // 探针**。那根探针（rt_test.rgen 的 rainExposure*）用 bit 0x08 单独寻址，
            // 这里把粒子层清掉这一位即可；其余射线仍是 0xff（含 0x08）⇒ 粒子的
            // 阴影 / GI / 反射 / 水面行为逐位不变。
            //
            // 为什么必须排除：
            //   · 物理上雨滴不该挡住"这片天空有没有雨落下来"的判定 —— 雨丝挡雨是错的；
            //   · 代价上那根探针是每像素一根直达 10000 格的 TerminateOnFirstHit 射线，
            //     而粒子层是一整块相机周围 7k 三角形的 BLAS，正好铺在视线正中。
            if(geometryClass == SECTION_AS_CLASS_PARTICLE)
            {
                instance.mask = 0xf7;
            }

            if(geometryClass == SECTION_AS_CLASS_OPAQUE)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_OPAQUE;
            }
            else if(geometryClass == SECTION_AS_CLASS_OMM)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_OMM;
            }
            else if(geometryClass == SECTION_AS_CLASS_WATER)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_WATER;
            }
            else if(geometryClass == SECTION_AS_CLASS_ENTITY)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_ENTITY;
            }
            else if(geometryClass == SECTION_AS_CLASS_LOCAL_PLAYER)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_ENTITY;
            }
            else if(geometryClass == SECTION_AS_CLASS_PARTICLE)
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_ENTITY;
            }
            else
            {
                instance.instanceShaderBindingTableRecordOffset =
                    SBT_RECORD_ALPHA;
            }

            const bool opaqueGeometry =
                geometryClass ==
                    SECTION_AS_CLASS_OPAQUE;

            const bool ommGeometry = section.hasOpacityMicromap;

            // =====================================================
            // 2026-10-05 OMM 桶改为"可被背面剔除"（其余桶保持双面）
            //
            // 原版 cutout 层是单面 authored：cross 草丛的正反两份共面 quad
            // 靠背面剔除各显示一面，透过镂空看到的是后面的世界。此前所有
            // 实例都带 FACING_CULL_DISABLE（永久双面），于是：
            //   • 主相机射线透过草丛正面副本的镂空，还会撞上背面副本的
            //     镜像纹素（整株草显得比原版"密"）；
            //   • 正反两份共面副本的提交完全由遍历顺序决定。
            // 把 OMM 实例的 DISABLE 摘掉后，它只对**显式带剔除标志**的射线
            // 变成单面 —— 目前只有主相机射线带 CullBackFacingTriangles
            // （见 rt_test.rgen 的 Primary Ray）。其余射线（AO/GI/反射/
            // 水体分类/玻璃可见性/直射阴影）不带标志，OMM 实例对它们仍然
            // 双面，行为与改动前一致。直射阴影射线刻意**不**带剔除：
            // 太阳方向的可见性取正反两份的并集，能自然填补点采样在草丛
            // 底部影子里的漏光缝隙（用户报告"草的底部阴影有缝隙"）。
            // 水体/玻璃（ALPHA 桶）、不透明地形、实体、粒子依旧双面。
            // =====================================================
            instance.flags =
                (geometryClass == SECTION_AS_CLASS_OMM
                    ? 0u
                    : VK_GEOMETRY_INSTANCE_TRIANGLE_FACING_CULL_DISABLE_BIT_KHR) |
                (
                    // OMM needs its opaque/transparent/unknown states to be
                    // visible to traversal. FORCE_NO_OPAQUE would make every
                    // micro-triangle invoke .rahit and remove the benefit.
                    (opaqueGeometry || ommGeometry)
                        ? 0u
                        : VK_GEOMETRY_INSTANCE_FORCE_NO_OPAQUE_BIT_KHR
                );

            instance.accelerationStructureReference =
                section.blasAddress;


            instances.push_back(
                instance
            );
        }
    }

    // 2026-10-03 剔除边界修复：距离剔除可能把**全部**实例剔光 —— 进世界第 0 帧
    // 玩家位置尚未写入 UBO（读到 0,0,0）时尤其如此 ⇒ instances 为空 ⇒ TLAS 实例
    // 缓冲 0 字节 ⇒ vkAllocateMemory(0) 报 OUT_OF_DEVICE_MEMORY（实机崩溃，日志
    // [ALLOC FAIL] request=0）。补一个 mask=0 的非激活哑实例：TLAS 合法、遍历
    // 零命中，与上面 orderedSections 为空的分支同一先例。
    if(instances.empty())
    {
        VkAccelerationStructureInstanceKHR inactive{};
        inactive.transform.matrix[0][0] = 1.0f;
        inactive.transform.matrix[1][1] = 1.0f;
        inactive.transform.matrix[2][2] = 1.0f;
        inactive.instanceCustomIndex = 0u;
        inactive.mask = 0u;
        inactive.instanceShaderBindingTableRecordOffset = 0u;
        inactive.flags =
            VK_GEOMETRY_INSTANCE_TRIANGLE_FACING_CULL_DISABLE_BIT_KHR |
            VK_GEOMETRY_INSTANCE_FORCE_NO_OPAQUE_BIT_KHR;
        inactive.accelerationStructureReference = 0;
        instances.push_back(inactive);
        RTLogFlushed("[TLAS CULL] all instances culled; inactive placeholder in use");
    }

    // =====================================================
    // 2026-10-03 优化②：TLAS **跳过重建**。实例表与上一帧逐位一致 ⇒ TLAS 内容
    // 不变 ⇒ 跳过实例表写入与 build 命令（顶点上传/BLAS 构建/提交流程不受影响，
    // 画面逐位一致）。玩家静止时每帧都命中跳过路径。强制构建条件在下方随流程
    // 收紧（TLAS 存储/实例缓冲刚重建时，新对象内容不继承）。
    // =====================================================
    // 2026-10-13 preCmd 内切③：实例表构建（含 memcmp 影子比较 / 空表哑实例）到此结束。
    rtxPreCmdAfterInstances = std::chrono::steady_clock::now();

    const VkAccelerationStructureKHR tlasHandleAtEntry = g_tlas;
    static std::vector<VkAccelerationStructureInstanceKHR> s_tlasInstancesShadow;

    // 2026-10-17：把实例列表排成**规范顺序**，让下面的 memcmp 变成"集合比较"。
    //
    // 依据（`ORION_TLAS_DELTA=1` 实测 1881 条差量）：63% 的"变化"是**尺寸不变、内容变了**，
    // posDiff 中位 3 但 p90=1025、最大 1518 —— 即同一批实例被重排。memcmp 对顺序敏感，
    // 于是每帧都判"变了" ⇒ TLAS 每帧重建 ⇒ 阴影/间接光反复微调，表现为"光源时不时闪一下"。
    // 排序后：集合不变 ⇒ tlasInstancesUnchanged=true ⇒ 跳过重建（既治闪，也省下每帧 AS 重建）。
    // 排序键按"每个实例自身携带的字段"，所以 SBT offset/mask 仍跟着各自实例，映射关系不变。
    std::sort(
        instances.begin(),
        instances.end(),
        [](const VkAccelerationStructureInstanceKHR& a,
           const VkAccelerationStructureInstanceKHR& b)
        {
            if(a.accelerationStructureReference != b.accelerationStructureReference)
            {
                return a.accelerationStructureReference < b.accelerationStructureReference;
            }

            if(a.instanceCustomIndex != b.instanceCustomIndex)
            {
                return a.instanceCustomIndex < b.instanceCustomIndex;
            }

            if(a.mask != b.mask)
            {
                return a.mask < b.mask;
            }

            return a.instanceShaderBindingTableRecordOffset <
                   b.instanceShaderBindingTableRecordOffset;
        }
    );

    bool tlasInstancesUnchanged =
        tlasHandleAtEntry != VK_NULL_HANDLE &&
        s_tlasInstancesShadow.size() == instances.size() &&
        (instances.empty() ||
         std::memcmp(
             s_tlasInstancesShadow.data(),
             instances.data(),
             instances.size() * sizeof(VkAccelerationStructureInstanceKHR)
         ) == 0);
    bool tlasInstancesBufferRecreated = false;
    bool tlasStorageRecreated = false;


    auto destroyAS =
        getDestroyAccelerationStructure();

    auto createAS =
        getCreateAccelerationStructure();

    auto getBuildSizes =
        getGetAccelerationStructureBuildSizes();

    auto getASAddress =
        getGetAccelerationStructureDeviceAddress();

    auto cmdBuild =
        getCmdBuildAccelerationStructures();


    if(
        !destroyAS ||
        !createAS ||
        !getBuildSizes ||
        !getASAddress ||
        !cmdBuild
    )
    {
        throw std::runtime_error(
            "multi-Section TLAS Vulkan functions unavailable"
        );
    }

    // The driver can hang if a TLAS UPDATE reads a source TLAS whose dynamic
    // BLAS references were just replaced. Keep the proven full-build path.
    constexpr bool updateTlas = false;

    // Nothing is released here: the TLAS resources that have to be replaced are
    // parked individually below, so these globals still hold the resident ones
    // and the build simply reuses them.  Whatever is parked is destroyed right
    // after the queue drain.


    // =====================================================
    // 2026-10-03 hitch 修复：容量带余量。
    //
    // 此前实例表与 TLAS 本体都按**精确需求**分配（createBuffer 用的就是
    // instanceBytes / accelerationStructureSize），于是 Section 数一旦刷新高水位
    // 就要重建实例缓冲 + 重建 TLAS 本体 ⇒ g_tlas 换句柄 ⇒ 描述符必须重发 ⇒ 走到
    // 本函数里唯一还保留的 vkQueueWaitIdle（排空整条 RT 队列）并整棵重建 TLAS。
    // 日志里 geometry 相 17~24 ms 的尖峰走的正是这条路径；而流送/探索时实例数会
    // 在平台期上下抖动，旧策略下"刷新高水位即重建"会被反复触发。
    //
    // 现在容量 = 需求 + 25% + 256（向上取到 64 的倍数），且只增不减：
    //   · 实例表按容量分配（表里只写前 instances.size() 项）；
    //   · getBuildSizes 按**容量**问，于是 accelerationStructureSize 与
    //     buildScratchSize 都是容量口径 ⇒ 小幅增长不再换句柄、不再排空队列。
    // =====================================================
    constexpr VkDeviceSize TLAS_INSTANCE_STRIDE =
        sizeof(VkAccelerationStructureInstanceKHR);

    const size_t requiredInstanceCount =
        instances.size();

    const size_t previousCapacityInstances =
        static_cast<size_t>(
            g_tlasInstancesCapacity / TLAS_INSTANCE_STRIDE);

    size_t capacityInstances =
        previousCapacityInstances;

    if(requiredInstanceCount > previousCapacityInstances)
    {
        // 2026-10-21：增长步长改成"比例余量 + 绝对地板 + 几何级翻倍"。
        //
        // 原来每次只留 25% + 256 个实例余量 ⇒ 实测实例数在 730~772 之间来回波动
        // （[TLAS SKIP] instances= 行）时也会反复越过容量，而**每次越界都会重建
        // TLAS 句柄**；句柄一变，尾部就必须 vkQueueWaitIdle 才能重写 4 个描述符
        // 里的 AS 绑定（见 rebuildPublishesTlasDescriptor 判据），而那条排空正是
        // [PERF L10 STALL] tag=worldGeometryQueueIdle 的唯一来源（实测 5~55ms）。
        //
        // 现在：目标容量 = max(需求 ×1.5 + 4096, 上一次容量 ×2)，向上取 64。
        // 地板档在几千实例时只有几百 KB（实例 64B/个 + BVH 存储），且 build 的
        // primitiveCount 仍是实际实例数（见 tlasPrimitiveCount），所以 GPU 侧
        // 构建/遍历成本不变，换来的只是"不再频繁换句柄"。
        constexpr size_t TLAS_CAPACITY_SLACK_MIN = 4096u;

        size_t targetCapacity =
            requiredInstanceCount +
            requiredInstanceCount / 2u +
            TLAS_CAPACITY_SLACK_MIN;

        const size_t doublePreviousCapacity =
            previousCapacityInstances >
                std::numeric_limits<size_t>::max() / 2u
                ? std::numeric_limits<size_t>::max()
                : previousCapacityInstances * 2u;

        if(doublePreviousCapacity > targetCapacity)
        {
            targetCapacity = doublePreviousCapacity;
        }

        capacityInstances =
            (targetCapacity +
             63u) &
            ~static_cast<size_t>(63u);
    }

    const VkDeviceSize instanceBytes =
        static_cast<VkDeviceSize>(
            capacityInstances
        ) *
        TLAS_INSTANCE_STRIDE;


    // Host-visible build input, rewritten on every rebuild.  Keep it at its
    // high-water mark and only replace it when the table outgrows the buffer.
    if(
        g_tlasInstancesBuffer == VK_NULL_HANDLE ||
        g_tlasInstancesCapacity < instanceBytes
    )
    {
        if(g_tlasInstancesBuffer != VK_NULL_HANDLE)
        {
            parkTlasInstances();
        }

        createBuffer(
            g_device,
            g_physicalDevice,
            instanceBytes,
            VK_BUFFER_USAGE_ACCELERATION_STRUCTURE_BUILD_INPUT_READ_ONLY_BIT_KHR |
                VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT,
            VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
            g_tlasInstancesBuffer,
            g_tlasInstancesMemory
        );

        g_tlasInstancesCapacity =
            instanceBytes;

        g_tlasInstancesAddress =
            getBufferDeviceAddress(
                g_device,
                g_tlasInstancesBuffer
            );
    }


    // The table is written after the drain below: until then a build submitted
    // by the previous rebuild may still be reading this buffer.


    VkAccelerationStructureGeometryInstancesDataKHR
        instanceData{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_INSTANCES_DATA_KHR
        };

    instanceData.arrayOfPointers =
        VK_FALSE;

    instanceData.data.deviceAddress =
        g_tlasInstancesAddress;


    VkAccelerationStructureGeometryKHR
        tlasGeometry{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_GEOMETRY_KHR
        };

    tlasGeometry.geometryType =
        VK_GEOMETRY_TYPE_INSTANCES_KHR;

    tlasGeometry.geometry.instances =
        instanceData;


    VkAccelerationStructureBuildGeometryInfoKHR
        tlasBuildInfo{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_BUILD_GEOMETRY_INFO_KHR
        };

    tlasBuildInfo.type =
        VK_ACCELERATION_STRUCTURE_TYPE_TOP_LEVEL_KHR;

    // No ALLOW_UPDATE: the TLAS is always fully rebuilt (see updateTlas
    // below), and the flag lets the driver pick a refit-friendly BVH that is
    // potentially slower to traverse.
    tlasBuildInfo.flags =
        VK_BUILD_ACCELERATION_STRUCTURE_PREFER_FAST_TRACE_BIT_KHR;

    tlasBuildInfo.mode =
        VK_BUILD_ACCELERATION_STRUCTURE_MODE_BUILD_KHR;

    tlasBuildInfo.geometryCount = 1;
    tlasBuildInfo.pGeometries =
        &tlasGeometry;


    // 真正写入并交给 build 的实例数（范围用这个）。
    const uint32_t tlasPrimitiveCount =
        static_cast<uint32_t>(
            instances.size()
        );


    // 分配口径：按**容量**问 sizes（见上方容量余量的说明）。这样
    // accelerationStructureSize 与 buildScratchSize 都按容量算，本体的重建判据
    // （g_tlasAsSize < accelerationStructureSize）才跟容量挂钩，而不是跟"这一帧
    // 的精确需求"挂钩 —— 容量 >= 需求，多出来的部分对本体的 build 无害。
    const uint32_t tlasCapacityPrimitiveCount =
        static_cast<uint32_t>(
            capacityInstances
        );


    VkAccelerationStructureBuildSizesInfoKHR
        tlasSizes{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_BUILD_SIZES_INFO_KHR
        };


    getBuildSizes(
        g_device,
        VK_ACCELERATION_STRUCTURE_BUILD_TYPE_DEVICE_KHR,
        &tlasBuildInfo,
        &tlasCapacityPrimitiveCount,
        &tlasSizes
    );


    // Storage + acceleration structure are resident across rebuilds.  A full
    // BUILD into an existing TLAS is legal and the queue is drained before this
    // build is submitted, so nothing is reading the old contents while they are
    // overwritten; only a size increase needs a new allocation.
    //
    // 2026-10-03：这里比较的是**容量口径**的 accelerationStructureSize（见上方
    // 容量余量），所以只有"容量不够了"才会换句柄，而不是"这一帧的实例数比上一帧
    // 多一个"。
    if(
        g_tlas == VK_NULL_HANDLE ||
        g_tlasBuffer == VK_NULL_HANDLE ||
        g_tlasAsSize < tlasSizes.accelerationStructureSize
    )
    {
        if(
            g_tlas != VK_NULL_HANDLE ||
            g_tlasBuffer != VK_NULL_HANDLE
        )
        {
            parkTlasStorage();
        }

        createBuffer(
            g_device,
            g_physicalDevice,
            tlasSizes.accelerationStructureSize,
            VK_BUFFER_USAGE_ACCELERATION_STRUCTURE_STORAGE_BIT_KHR |
                VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT,
            VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
            g_tlasBuffer,
            g_tlasMemory
        );


    VkAccelerationStructureCreateInfoKHR
        tlasCreateInfo{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_CREATE_INFO_KHR
        };

    tlasCreateInfo.buffer =
        g_tlasBuffer;

    tlasCreateInfo.size =
        tlasSizes.accelerationStructureSize;

    tlasCreateInfo.type =
        VK_ACCELERATION_STRUCTURE_TYPE_TOP_LEVEL_KHR;


        check(
            createAS(
                g_device,
                &tlasCreateInfo,
                nullptr,
                &g_tlas
            ),
            "create multi-Section TLAS failed"
        );

        g_tlasAsSize =
            tlasSizes.accelerationStructureSize;

        tlasStorageRecreated = true;
    }


    // The scratch is grow-only too.  updateScratchSize is only meaningful with
    // ALLOW_UPDATE, which this TLAS no longer requests, so the build size alone
    // sizes it, and a build that needs less than the buffer holds reuses it.
    if(
        tlasSizes.buildScratchSize > 0 &&
        (
            g_tlasScratchBuffer == VK_NULL_HANDLE ||
            g_tlasScratchCapacity < tlasSizes.buildScratchSize
        )
    )
    {
        if(g_tlasScratchBuffer != VK_NULL_HANDLE)
        {
            parkTlasScratch();
        }

        g_tlasScratchCapacity =
            tlasSizes.buildScratchSize;

        createBuffer(
            g_device,
            g_physicalDevice,
            g_tlasScratchCapacity,
            VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
                VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT,
            VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
            g_tlasScratchBuffer,
            g_tlasScratchMemory
        );


        g_tlasScratchAddress =
            getBufferDeviceAddress(
                g_device,
                g_tlasScratchBuffer
            );
    }


    VkBuffer blasScratchBuffer =
        VK_NULL_HANDLE;

    VkDeviceMemory blasScratchMemory =
        VK_NULL_HANDLE;

    VkDeviceAddress blasScratchAddress =
        0;


    if(
        !sectionsNeedingBuild.empty() &&
        maxBLASScratchSize > 0
    )
    {
        RtxSectionBuildBufferSlot blasScratchSlot;

        if(g_blasScratchPool.tryAcquire(maxBLASScratchSize, blasScratchSlot))
        {
            // 2026-10-11 多槽池命中。
            blasScratchBuffer = blasScratchSlot.buffer;
            blasScratchMemory = blasScratchSlot.memory;

            g_sectionBuildPoolReuseCount += 1u;
        }
        else
        {

            // 2026-10-14：同顶点 staging —— 容量按 2 的幂取整（见
            // sectionBuildPoolSlotBytes），让池档位变粗、命中率接近恒命中。
            const VkDeviceSize blasScratchSlotBytes =
                sectionBuildPoolSlotBytes(maxBLASScratchSize);

            createBuffer(
                g_device,
                g_physicalDevice,
                blasScratchSlotBytes,
                VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
                    VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT,
                VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT,
                blasScratchBuffer,
                blasScratchMemory
            );

            g_blasScratchPool.adopt(
                blasScratchBuffer,
                blasScratchMemory,
                blasScratchSlotBytes
            );

            g_sectionBuildPoolAllocCount += 1u;
        }


        blasScratchAddress =
            getBufferDeviceAddress(
                g_device,
                blasScratchBuffer
            );
    }


    // 2026-10-13 preCmd 内切④：TLAS build-size 查询 + 存储/scratch/BLAS scratch 池到此结束。
    rtxPreCmdAfterTlas = std::chrono::steady_clock::now();

    VkCommandBufferAllocateInfo allocateInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO
    };

    allocateInfo.commandPool =
        g_rtCommandPool;

    allocateInfo.level =
        VK_COMMAND_BUFFER_LEVEL_PRIMARY;

    allocateInfo.commandBufferCount =
        1;


    VkCommandBuffer cmd =
        VK_NULL_HANDLE;

    // 2026-10-11 慢帧归因（tail 内切）：命令缓冲录制段起点。
    rtxTailBeforeCommandRecord = std::chrono::steady_clock::now();

    check(
        vkAllocateCommandBuffers(
            g_device,
            &allocateInfo,
            &cmd
        ),
        "allocate Section AS command buffer failed"
    );

    // 强制构建：TLAS 存储刚重建（新 AS 是空的）或实例缓冲刚重建（新缓冲内容
    // 不继承）⇒ 即便实例表逐位一致也必须构建/写入。
    if(tlasStorageRecreated || tlasInstancesBufferRecreated)
    {
        tlasInstancesUnchanged = false;
    }


    VkCommandBufferBeginInfo beginInfo{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO
    };

    beginInfo.flags =
        VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;


    check(
        vkBeginCommandBuffer(
            cmd,
            &beginInfo
        ),
        "begin Section AS command buffer failed"
    );


    if(!pendingUploads.empty())
    {
        for(const PendingSectionUpload& upload : pendingUploads)
        {
            // =====================================================
            // 2026-10-13 崩溃护栏（临时仪器，兼修复）
            //
            // 现场：2026-10-13 共 6 次硬崩（19:30 / 19:34 / 19:39 / 19:43 /
            // 21:09 / 21:11），hs_err 全部同签名：
            //   EXCEPTION_ACCESS_VIOLATION，problematic frame = nvoglv64.dll+0xe75372
            //   （NVIDIA 驱动），reading address 0x0000000000000110，RBX=RSI=0；
            //   原生栈 nvoglv64 ← nvoglv64 ← vulkan-1.dll ← rtx_backend.dll
            //   ← rtx_backend.dll ← Java 的 recordFrameCommand
            //   ← createRenderPass（混入方法 handler$…$injectRtBeforeGui）。
            //   崩溃前日志一切正常（[VRAM GOV] ratio=0.816、workAvgMs=6.7）。
            //
            // 用 map + dumpbin 把两个 rtx_backend 偏移解析到函数：
            //   0x7b165 → Java_…_recordFrameCommand +0x17e5
            //   0x5b8dd → ?rebuildWorldGeometry@@YA_N_K@Z +0x3d8d
            // 该处反汇编是"循环体里 call [IAT 槽 0x1800B6828]"，而 map 的数据符号
            // 显示 0x1800B6828 = __imp_vkCmdCopyBuffer；参数装载 r9d=1、
            // [rsp+20h]=&24 字节局部，正是 (cmd, src, dst, 1, &VkBufferCopy)。
            // 与源码逐字段对上（尾注：PendingSectionUpload 是 32 字节，故 rbx+=0x20；
            //   [rbx+0x10]=stagingOffset、[rbx]=section、section+8=vertexBuffer、
            //   section+0x48=vertexBytes）：
            //       本行的 vkCmdCopyBuffer(...)
            // ⇒ 驱动是对**无效的 VkBuffer 句柄**解引用（空基址 + 0x110）才崩的。
            //
            // 所以这里在录制之前先筛一遍：句柄为空/长度为零就跳过这一次拷贝并记一行。
            // 判据：打出来的 key / vertexBytes / stagingOffset 直接指出是哪一类 Section
            // 出了问题（新插入？复水？退役后仍被引用？），据此再找根因。
            // 只在真出问题时才打印，稳态零开销、零行为变化。
            // =====================================================
            // 2026-10-13 追加：还要查一次"身份"。队列里是裸指针，若条目已被 erase
            // （悬垂）则句柄是垃圾值 —— 空值护栏拦不住（实测护栏 0 命中却照样崩）。
            // 该 Section 必须仍是 g_sectionBLAS 里**同一个**对象，否则跳过并记账。
            const auto liveEntry =
                (upload.section != nullptr)
                    ? g_sectionBLAS.find(upload.section->sectionKey)
                    : g_sectionBLAS.end();

            const bool staleEntry =
                upload.section == nullptr ||
                liveEntry == g_sectionBLAS.end() ||
                &liveEntry->second != upload.section;

            if(
                vertexStagingBuffer == VK_NULL_HANDLE ||
                upload.section == nullptr ||
                upload.section->vertexBuffer == VK_NULL_HANDLE ||
                upload.section->vertexBytes == 0u ||
                staleEntry
            )
            {
                static uint64_t guardSkips = 0u;

                ++guardSkips;

                if(
                    guardSkips <= 5u ||
                    (guardSkips % 100u) == 0u
                )
                {
                    std::stringstream guardLog;
                    guardLog
                        << "[SECTION UPLOAD GUARD] skip#" << guardSkips
                        << " stagingNull="
                        << (vertexStagingBuffer == VK_NULL_HANDLE ? 1 : 0)
                        << " sectionNull=" << (upload.section == nullptr ? 1 : 0)
                        << " vbNull="
                        << ((upload.section == nullptr ||
                             upload.section->vertexBuffer == VK_NULL_HANDLE) ? 1 : 0)
                        << " key="
                        << (upload.section != nullptr ? upload.section->sectionKey : 0ull)
                        << " vertexBytes="
                        << (upload.section != nullptr
                                ? static_cast<unsigned long long>(
                                      upload.section->vertexBytes)
                                : 0ull)
                        << " stale=" << (staleEntry ? 1 : 0)
                        << " stagingOffset="
                        << static_cast<unsigned long long>(upload.stagingOffset);

                    RTLog(guardLog.str());
                }

                continue;
            }

            VkBufferCopy copy{};

            copy.srcOffset =
                upload.stagingOffset;

            copy.dstOffset = 0;

            copy.size =
                upload.section->vertexBytes;


            vkCmdCopyBuffer(
                cmd,
                vertexStagingBuffer,
                upload.section->vertexBuffer,
                1,
                &copy
            );
        }


        VkMemoryBarrier uploadBarrier{
            VK_STRUCTURE_TYPE_MEMORY_BARRIER
        };

        uploadBarrier.srcAccessMask =
            VK_ACCESS_TRANSFER_WRITE_BIT;

        uploadBarrier.dstAccessMask =
            VK_ACCESS_ACCELERATION_STRUCTURE_READ_BIT_KHR |
            VK_ACCESS_SHADER_READ_BIT;


        vkCmdPipelineBarrier(
            cmd,
            VK_PIPELINE_STAGE_TRANSFER_BIT,
            VK_PIPELINE_STAGE_ACCELERATION_STRUCTURE_BUILD_BIT_KHR |
                VK_PIPELINE_STAGE_RAY_TRACING_SHADER_BIT_KHR,
            0,
            1,
            &uploadBarrier,
            0,
            nullptr,
            0,
            nullptr
        );
    }


    VkMemoryBarrier asBuildBarrier{
        VK_STRUCTURE_TYPE_MEMORY_BARRIER
    };

    asBuildBarrier.srcAccessMask =
        VK_ACCESS_ACCELERATION_STRUCTURE_WRITE_BIT_KHR;

    asBuildBarrier.dstAccessMask =
        VK_ACCESS_ACCELERATION_STRUCTURE_READ_BIT_KHR |
        VK_ACCESS_ACCELERATION_STRUCTURE_WRITE_BIT_KHR;


    // 2026-10-21 refit：recordSectionBLASBuild 现在要清除 pendingRefit ⇒ 去掉 const。
    for(RTSectionAS* section : sectionsNeedingBuild)
    {
        // 2026-10-13 同一处崩溃的第二个调用点（hs_err: nvoglv64 AV，无 vulkan-1 帧
        // ⇒ 直连驱动函数指针）。队列里是裸指针，条目若已被 erase 就会把垃圾
        // VkAccelerationStructureKHR / VkBuffer 喂给驱动。身份校验见驱逐段说明；
        // 主修在那里（把本轮入队的段摘出 victims），这里是第二道保险。
        if(section == nullptr)
        {
            continue;
        }

        {
            const auto liveEntry = g_sectionBLAS.find(section->sectionKey);

            if(liveEntry == g_sectionBLAS.end() ||
               &liveEntry->second != section)
            {
                static uint64_t blasStaleSkips = 0u;

                ++blasStaleSkips;

                if(blasStaleSkips <= 5u || (blasStaleSkips % 100u) == 0u)
                {
                    std::stringstream staleLog;
                    staleLog
                        << "[SECTION BLAS GUARD] skip#" << blasStaleSkips
                        << " key=" << section->sectionKey
                        << " (entry erased while queued)";
                    RTLog(staleLog.str());
                }

                continue;
            }
        }

        recordSectionBLASBuild(
            cmd,
            *section,
            blasScratchAddress
        );


        // The next BLAS reuses the same scratch allocation. This also
        // makes every newly built BLAS visible to the following TLAS build.
        vkCmdPipelineBarrier(
            cmd,
            VK_PIPELINE_STAGE_ACCELERATION_STRUCTURE_BUILD_BIT_KHR,
            VK_PIPELINE_STAGE_ACCELERATION_STRUCTURE_BUILD_BIT_KHR,
            0,
            1,
            &asBuildBarrier,
            0,
            nullptr,
            0,
            nullptr
        );
    }


    tlasBuildInfo.dstAccelerationStructure =
        g_tlas;

    tlasBuildInfo.mode =
        updateTlas
            ? VK_BUILD_ACCELERATION_STRUCTURE_MODE_UPDATE_KHR
            : VK_BUILD_ACCELERATION_STRUCTURE_MODE_BUILD_KHR;

    tlasBuildInfo.srcAccelerationStructure =
        updateTlas
            ? g_tlas
            : VK_NULL_HANDLE;

    tlasBuildInfo.scratchData.deviceAddress =
        g_tlasScratchAddress;


    VkAccelerationStructureBuildRangeInfoKHR
        tlasRange{};

    tlasRange.primitiveCount =
        tlasPrimitiveCount;


    const VkAccelerationStructureBuildRangeInfoKHR*
        tlasRanges[] =
        {
            &tlasRange
        };


    // 优化②：实例表未变化 ⇒ 跳过 build 命令（TLAS 保持上一帧内容 = 内容一致）
    if(!tlasInstancesUnchanged)
    {
        cmdBuild(
            cmd,
            1,
            &tlasBuildInfo,
            tlasRanges
        );
    }


    check(
        vkEndCommandBuffer(cmd),
        "end Section AS command buffer failed"
    );

    // 2026-10-11 慢帧归因（tail 内切）：录制段到此结束。
    rtxTailAfterCommandRecord = std::chrono::steady_clock::now();


    VkSubmitInfo submitInfo{
        VK_STRUCTURE_TYPE_SUBMIT_INFO
    };

    submitInfo.commandBufferCount =
        1;

    submitInfo.pCommandBuffers =
        &cmd;


    // SR.2: the drain that used to be unconditional here is gone.  Everything it
    // protected has moved elsewhere: the parked generation is released by its
    // fence (attached to the submit below), the Section vertex address table is
    // append-only, and the TLAS descriptor is only republished when its handle
    // actually changed.  That last case is the one remaining reason a
    // descriptor write could race a frame in flight, so only it still drains.
    const bool rebuildPublishesTlasDescriptor =
        g_tlasDescriptorHandle != g_tlas;

    const auto perfL10QueueIdleStart =
        std::chrono::steady_clock::now();

    if(rebuildPublishesTlasDescriptor)
    {
        PERF_L10_TIME_STALL("worldGeometryQueueIdle", check(
            vkQueueWaitIdle(g_queue),
            "wait RT queue before Section AS rebuild failed"
        ));

        // The drain just made every outstanding fence signal, so the remaining
        // generations are reclaimed by the next rebuild's reap.  They are not
        // released here on purpose: this rebuild's own slot is one of them and
        // its generation must stay parked until the build below has run.
    }

    perfL10QueueIdleMilliseconds =
        std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() -
            perfL10QueueIdleStart
        ).count();


    // The resident instance table is rewritten before the submit.  The build it
    // feeds is submitted below, so the coherent host write becomes visible with
    // that submission; what must not overlap is the *previous* rebuild's build,
    // which reads the same buffer.  Its fence covers exactly that build and
    // everything submitted before it, so waiting on it - rather than on the
    // whole queue, which would also pull in the last frame's ray tracing - is
    // both necessary and sufficient.  It is normally already signaled, and when
    // the previous generation has already been reaped the fence is signaled by
    // definition, so this costs nothing on the steady-state path.
    if(
        g_sectionRetirementFencesReady &&
        g_sectionRetirementRing[previousRetirementSlot].fencePending
    )
    {
        VkFence previousBuildFence =
            g_sectionRetirementFences[previousRetirementSlot];

        // 2026-10-21：把这条**无限等待**改成"默认零等待"。
        //
        // 依据（本文件内可自查，不依赖注释）：入口闸门轮询的是*同一个槽位、同一条
        // fence* —— 闸门里的 g_currentRetirementSlot 与这里的 previousRetirementSlot
        // 是同一值（见 64576 附近的捕获），而 VkFence 只会单向"未信号 → 已信号"。
        // 因此闸门放行之后，本处正常情况下必然早已信号。
        //
        // 于是这里只做一次零超时查询（vkGetFenceStatus），不再进驱动的等待路径。
        // 若真查到未信号，说明闸门没生效（ORION_REBUILD_FENCE_GATE=0 的 A/B 路径，
        // 或将来有第二处提交插进来）：先给 2ms 有界预算，仍不行才退回旧的无限等待。
        // 正确性优先，但该路径会打一行诊断，不会再无声地卡住渲染线程。
        VkResult previousBuildStatus =
            VK_NOT_READY;

        PERF_L10_TIME_STALL(
            "sectionBuildFenceWait",
            previousBuildStatus = vkGetFenceStatus(
                g_device,
                previousBuildFence
            )
        );

        if(previousBuildStatus == VK_NOT_READY)
        {
            static bool s_tailFenceWaitFallbackLogged = false;

            if(!s_tailFenceWaitFallbackLogged)
            {
                s_tailFenceWaitFallbackLogged = true;

                RTLog(
                    "[SECTION BUILD FENCE] tail poll found the previous batch "
                    "still in flight (entry gate bypassed?)"
                );
            }

            previousBuildStatus = vkWaitForFences(
                g_device,
                1,
                &previousBuildFence,
                VK_TRUE,
                static_cast<uint64_t>(
                    SECTION_REBUILD_FENCE_WAIT_MS > 0u
                        ? SECTION_REBUILD_FENCE_WAIT_MS
                        : 2u
                ) * 1000000ull
            );

            if(previousBuildStatus == VK_TIMEOUT)
            {
                // 最后保底：宁可等，也不要把实例表写进一条正在读它的 build。
                previousBuildStatus = vkWaitForFences(
                    g_device,
                    1,
                    &previousBuildFence,
                    VK_TRUE,
                    std::numeric_limits<uint64_t>::max()
                );
            }
        }

        check(
            previousBuildStatus,
            "wait previous Section build fence failed"
        );

        reapSignaledRetirements();
    }

    // 2026-10-11 慢帧归因（tail 内切）：两个等待（queueIdle / 上一批 fence）到此结束。
    rtxTailAfterFenceWait = std::chrono::steady_clock::now();

    // 优化②：跳过重建时实例缓冲内容与要写的数据逐位一致 ⇒ 不重写
    if(!tlasInstancesUnchanged)
    {
        void* mappedInstances = nullptr;

        check(
            vkMapMemory(
                g_device,
                g_tlasInstancesMemory,
                0,
                instanceBytes,
                0,
                &mappedInstances
            ),
            "map multi-Section TLAS instance buffer failed"
        );


        // 2026-10-04 修复（玩家端 EXCEPTION_ACCESS_VIOLATION）：
        //   instanceBytes 是**容量**口径（需求 + 25% + 256，见上方"容量带余量"），
        //   拿它当 memcpy 长度就会从 instances 尾部多读 (capacity - size) 项。
        //   多数情况下这块落在堆的同页内 —— 读出垃圾、写进只读前 size 项的 TLAS
        //   输入缓冲，对 build 无害，所以开发机长期没暴露；一旦这次多读越过分配
        //   末尾的页边界，就是进程级 AV（现场：rtx_backend+0x4AD5D 就位后直接崩在
        //   VCRUNTIME140 的 memcpy 循环，读地址恰在源缓冲尾后）。
        //   真正交给 build 的范围是 tlasPrimitiveCount = instances.size()（见下方
        //   "范围用这个"），所以这里按同一口径写：只写前 size 项。
        std::memcpy(
            mappedInstances,
            instances.data(),
            static_cast<size_t>(tlasPrimitiveCount) * TLAS_INSTANCE_STRIDE
        );


        vkUnmapMemory(
            g_device,
            g_tlasInstancesMemory
        );
    }


    VkFence buildFence =
        VK_NULL_HANDLE;

    if(g_sectionRetirementFencesReady)
    {
        buildFence =
            g_sectionRetirementFences[g_currentRetirementSlot];

        check(
            vkResetFences(
                g_device,
                1,
                &buildFence
            ),
            "reset Section retirement fence failed"
        );
    }

    check(
        vkQueueSubmit(
            g_queue,
            1,
            &submitInfo,
            buildFence
        ),
        "submit Section BLAS/TLAS build failed"
    );

    // 2026-10-11 慢帧归因（tail 内切）：vkResetFences + vkQueueSubmit 到此结束。
    // 这一段是 tail 里最后一个**会阻塞**的调用（队列饱和时驱动会在 submit 里等），
    // 也是此前唯一完全没有计时的地方 —— 若 slow 行的 submit= 大，元凶就是它。
    rtxTailAfterSubmit = std::chrono::steady_clock::now();

    // 优化②读数：每 5 秒一行。稳态（玩家静止）应看到 skipped=true。
    if(!tlasInstancesUnchanged)
    {
        // 2026-10-17 诊断（`ORION_TLAS_DELTA=1` 才打，**默认关**）：实例集合一变就记账，
        // 用来判定"是谁在变"——
        //   · 粒子 episode（[RT PARTICLES] 每 1~2 秒 start/end）⇒ 尺寸只差几个、posDiff 很小；
        //   · section 剔除轮换（[CULL DIAG] culled 0..300）⇒ 尺寸差几十上百、posDiff 很大。
        // 不引入容器/额外头文件：只比"尺寸 + 逐位置差 + FNV 指纹"（顺序变化也会体现在指纹上）。
        if(std::getenv("ORION_TLAS_DELTA") != nullptr)
        {
            const size_t prevSize = s_tlasInstancesShadow.size();
            const size_t nowSize = instances.size();
            const size_t shorter = prevSize < nowSize ? prevSize : nowSize;
            size_t posDiff = 0u;

            for(size_t i = 0u; i < shorter; ++i)
            {
                if(s_tlasInstancesShadow[i].accelerationStructureReference !=
                   instances[i].accelerationStructureReference)
                {
                    ++posDiff;
                }
            }

            uint64_t hashPrev = 1469598103934665603ull;
            uint64_t hashNow = 1469598103934665603ull;

            for(size_t i = 0u; i < prevSize; ++i)
            {
                hashPrev =
                    (hashPrev ^ s_tlasInstancesShadow[i].accelerationStructureReference) *
                    1099511628211ull;
            }

            for(size_t i = 0u; i < nowSize; ++i)
            {
                hashNow =
                    (hashNow ^ instances[i].accelerationStructureReference) *
                    1099511628211ull;
            }

            std::fprintf(
                stderr,
                "[TLAS DELTA] prev=%zu now=%zu posDiff=%zu hashPrev=%016llx hashNow=%016llx\n",
                prevSize,
                nowSize,
                posDiff,
                static_cast<unsigned long long>(hashPrev),
                static_cast<unsigned long long>(hashNow)
            );

            std::fflush(stderr);
        }

        s_tlasInstancesShadow = instances;
    }

    {
        static std::chrono::steady_clock::time_point s_tlasSkipLastPrint{};
        static bool s_tlasSkipLastValid = false;

        const auto skipNow = std::chrono::steady_clock::now();
        if(!s_tlasSkipLastValid ||
           std::chrono::duration<float>(skipNow - s_tlasSkipLastPrint).count() > 5.0f)
        {
            RTLogFlushed(std::string("[TLAS SKIP]") +
                (tlasInstancesUnchanged ? " skipped=true" : " skipped=false") +
                " instances=" + std::to_string(instances.size()));
            s_tlasSkipLastPrint = skipNow;
            s_tlasSkipLastValid = true;
        }
    }

    if(g_sectionRetirementFencesReady)
    {
        // From here the slot is only released once this fence signals.
        g_sectionRetirement->fencePending =
            true;
    }


    g_tlasInstanceCount =
        instances.size();

    for(RTSectionAS* section : sectionsNeedingBuild)
    {
        deferSectionOpacityMicromapBuildInputs(*section);
    }


    // Queue ordering guarantees that this build completes before the frame's
    // later RT submission.  Keep only the temporary inputs alive; do not
    // stall this CPU frame waiting for the build command to finish.
    g_deferredSectionBuild.commandBuffer =
        cmd;

    g_deferredSectionBuild.blasScratchBuffer =
        blasScratchBuffer;

    g_deferredSectionBuild.blasScratchMemory =
        blasScratchMemory;

    g_deferredSectionBuild.blasScratchSize =
        maxBLASScratchSize;

    g_deferredSectionBuild.vertexStagingBuffer =
        vertexStagingBuffer;

    g_deferredSectionBuild.vertexStagingMemory =
        vertexStagingMemory;

    g_deferredSectionBuild.vertexStagingSize =
        totalStagingBytes;

    cmd = VK_NULL_HANDLE;
    blasScratchBuffer = VK_NULL_HANDLE;
    blasScratchMemory = VK_NULL_HANDLE;
    vertexStagingBuffer = VK_NULL_HANDLE;
    vertexStagingMemory = VK_NULL_HANDLE;


    VkAccelerationStructureDeviceAddressInfoKHR
        tlasAddressInfo{
            VK_STRUCTURE_TYPE_ACCELERATION_STRUCTURE_DEVICE_ADDRESS_INFO_KHR
        };

    tlasAddressInfo.accelerationStructure =
        g_tlas;


    g_tlasDeviceAddress =
        getASAddress(
            g_device,
            &tlasAddressInfo
        );


    // The Section vertex address table needs nothing here any more: every live
    // Section already owns a stable slot and its single entry was written when
    // the slot was acquired, before the instance list was assembled.  Rewriting
    // the table (and, when it grew, its descriptor) after the submit was the
    // reason this point had to sit behind a queue drain.


    VkWriteDescriptorSetAccelerationStructureKHR
        tlasDescriptorInfo{
            VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET_ACCELERATION_STRUCTURE_KHR
        };

    tlasDescriptorInfo.accelerationStructureCount =
        1;

    tlasDescriptorInfo.pAccelerationStructures =
        &g_tlas;


    VkWriteDescriptorSet tlasWrite{
        VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET
    };

    tlasWrite.pNext =
        &tlasDescriptorInfo;

    tlasWrite.dstSet =
        g_rayTracingDescriptorSet;

    tlasWrite.dstBinding = 0;
    tlasWrite.descriptorCount = 1;

    tlasWrite.descriptorType =
        VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR;


    // Republishing the handle is what used to force this rebuild to drain the
    // queue before touching the descriptor.  The TLAS storage is resident now,
    // so the handle only changes when the acceleration structure itself had to
    // be recreated; in the steady state the descriptor already holds it and the
    // write - the last thing here that could race a frame in flight - is
    // skipped.  When the handle does change the queue is still drained, because
    // a descriptor set must not be updated while a submission is using it.
    if(g_tlasDescriptorHandle != g_tlas)
    {
        vkUpdateDescriptorSets(
            g_device,
            1,
            &tlasWrite,
            0,
            nullptr
        );

        // 太阳阴影图用同一个 TLAS，但它有自己的描述符集（还要带相机 UBO 与
        // 阴影图本身），所以在这里一并重写。`g_sunShadowTlasHandle` 是"已发布"
        // 标记：recordSunShadowMap 靠它确认描述符与当前 TLAS 一致才派发，
        // 否则宁可少写一帧也不拿旧句柄去派发。
        if(g_sunShadowSet != VK_NULL_HANDLE)
        {
            VkWriteDescriptorSet sunShadowTlasWrite{
                VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET
            };

            sunShadowTlasWrite.pNext =
                &tlasDescriptorInfo;

            sunShadowTlasWrite.dstSet =
                g_sunShadowSet;

            sunShadowTlasWrite.dstBinding = 1u;
            sunShadowTlasWrite.descriptorCount = 1u;

            sunShadowTlasWrite.descriptorType =
                VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR;

            vkUpdateDescriptorSets(
                g_device,
                1,
                &sunShadowTlasWrite,
                0,
                nullptr
            );

            g_sunShadowTlasHandle =
                g_tlas;
        }

        // 地形高度场同样用这个 TLAS，同样有自己的描述符集（相机 UBO + 高度图）。
        // 与阴影图一样的"已发布"标记语义：recordTerrainHeightMap 靠它确认描述符
        // 与当前 TLAS 一致才派发。
        if(g_terrainHeightSet != VK_NULL_HANDLE)
        {
            VkWriteDescriptorSet terrainHeightTlasWrite{
                VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET
            };

            terrainHeightTlasWrite.pNext =
                &tlasDescriptorInfo;

            terrainHeightTlasWrite.dstSet =
                g_terrainHeightSet;

            terrainHeightTlasWrite.dstBinding = 1u;
            terrainHeightTlasWrite.descriptorCount = 1u;

            terrainHeightTlasWrite.descriptorType =
                VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR;

            vkUpdateDescriptorSets(
                g_device,
                1,
                &terrainHeightTlasWrite,
                0,
                nullptr
            );

            g_terrainHeightTlasHandle =
                g_tlas;
        }

        // 远场太阳阴影图（2026-10-01）同样用这个 TLAS，同样有自己的描述符集。
        // 没有这一块，`g_sunShadowFarTlasHandle != g_tlas` 会在**第一次 TLAS
        // 重建之后永久成立** —— recordSunShadowFarMap 一路早退，远场阴影图
        // 静默停摆（画面退回"远处没有大尺度阴影"，且没有任何报错）。
        if(g_sunShadowFarSet != VK_NULL_HANDLE)
        {
            VkWriteDescriptorSet sunShadowFarTlasWrite{
                VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET
            };

            sunShadowFarTlasWrite.pNext =
                &tlasDescriptorInfo;

            sunShadowFarTlasWrite.dstSet =
                g_sunShadowFarSet;

            sunShadowFarTlasWrite.dstBinding = 1u;
            sunShadowFarTlasWrite.descriptorCount = 1u;

            sunShadowFarTlasWrite.descriptorType =
                VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR;

            vkUpdateDescriptorSets(
                g_device,
                1,
                &sunShadowFarTlasWrite,
                0,
                nullptr
            );

            g_sunShadowFarTlasHandle =
                g_tlas;
        }

        g_tlasDescriptorHandle =
            g_tlas;
    }


    g_asBuilt =
        true;


    uint64_t totalTriangleCount = 0;


    for(const RTSectionAS* section : orderedSections)
    {
        totalTriangleCount +=
            section->triangleCount;
    }


    if constexpr(PERF_L10_ENABLE_SECTION_REBUILD_LOGS)
    {
        std::stringstream log;

        log
            << "[RT SECTION AS]"
            << " rebuilt=" << rebuiltSectionCount
            << " removed=" << removedSectionCount
            << " instances=" << orderedSections.size()
            << " triangles=" << totalTriangleCount
            << " rebuiltOpaqueTriangles=" << rebuiltOpaqueTriangleCount
            << " rebuiltOmmTriangles=" << rebuiltOmmTriangleCount
            << " rebuiltAlphaTriangles=" << rebuiltAlphaTriangleCount
            << " rebuiltWaterTriangles=" << rebuiltWaterTriangleCount
            << " rebuiltParticleTriangles=" << rebuiltParticleTriangleCount
            << " queued=1"
            << " tlasAddr=0x"
            << std::hex
            << static_cast<unsigned long long>(
                g_tlasDeviceAddress
            );

        RTLog(
            log.str()
        );

        const double perfL10TotalMilliseconds =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() -
                perfL10RebuildStart
            ).count();

        std::stringstream perfL10Log;
        perfL10Log
            << "[PERF L10 SECTION REBUILD]"
            << " frame=" << g_perfL10FrameSerial
            << " totalCpuMs=" << std::fixed << std::setprecision(3)
            << perfL10TotalMilliseconds
            << " queueIdleMs=" << perfL10QueueIdleMilliseconds
            << " rebuilt=" << rebuiltSectionCount
            << " removed=" << removedSectionCount
            << " instances=" << orderedSections.size()
            << " triangles=" << totalTriangleCount
            << " rebuiltOpaqueTriangles=" << rebuiltOpaqueTriangleCount
            << " rebuiltOmmTriangles=" << rebuiltOmmTriangleCount
            << " rebuiltAlphaTriangles=" << rebuiltAlphaTriangleCount
            << " rebuiltWaterTriangles=" << rebuiltWaterTriangleCount
            << " rebuiltParticleTriangles=" << rebuiltParticleTriangleCount;

        RTLog(
            perfL10Log.str()
        );
    }

    // 2026-10-09（B）tail 段：构建循环收工 → 函数返回。判读见 g_geometryMaxTailMs。
    // 这一段的已知内容：staging 拷贝与 createBuffer、BLAS scratch、TLAS 本体与
    // scratch 的 createBuffer、录制 BLAS/TLAS build、提交、**上一批 build 的
    // fence 等待**（vkWaitForFences，此前完全没计时）、停泊与日志。
    {
        const double tailMs =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() -
                perfL10AfterBuildLoop
            ).count();

        if(tailMs > g_geometryMaxTailMs)
        {
            g_geometryMaxTailMs = tailMs;
        }

        // 2026-10-11 慢帧归因：本函数**整体**超过阈值就打一行。
        //
        // 为什么要单独记整体：counters 的三段都有盲区 ——
        //   · preLoopMs 只在构建循环跑到 sectionUpdateIndex==0 时记（空批不记）；
        //   · 空批会走上面的提前 return，tail 段根本不执行；
        // ⇒ 一次"卡了 60ms 但批是空的"的调用在三段里**一个数都不留**，这正是
        //   2026-10-11 15:23:58 那帧（geometry=67.73ms 而三段落和只有 31.8ms）
        //   最可能的形态。本行与 [RT PHASE SLOW] 同阈值、同帧号，成对读。
        const double rtxRebuildTotalMs =
            std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() -
                perfL10RebuildStart
            ).count();

        if(rtxRebuildTotalMs >= 15.0)
        {
            const auto rtxSegMs =
                [](const std::chrono::steady_clock::time_point& from,
                   const std::chrono::steady_clock::time_point& to)
                {
                    return std::chrono::duration<double, std::milli>(
                        to - from
                    ).count();
                };

            RTLog(
                "[RT GEOMETRY SLOW] frame=" +
                std::to_string(g_perfL10FrameSerial) +
                " total=" + std::to_string(rtxRebuildTotalMs) +
                " sections=" + std::to_string(sectionUpdates.size()) +
                // 2026-10-13：把"循环之前那段"和"构建循环"也打出来（此前只有 600 次
                // 窗口最大值，看不到单帧）。对账关系：
                //   pCap + pLog + pRsv == pre      （循环前三分）
                //   pre + bld + tail   == total    （整函数三分，tail 是嵌套的）
                " pre=" + std::to_string(
                    rtxSegMs(perfL10RebuildStart, perfL10BuildLoopStart)) +
                " pCap=" + std::to_string(
                    rtxSegMs(perfL10RebuildStart, rtxPreLoopMarkLog)) +
                " pLog=" + std::to_string(
                    rtxSegMs(rtxPreLoopMarkLog, rtxPreLoopMarkMid)) +
                " pRsv=" + std::to_string(
                    rtxSegMs(rtxPreLoopMarkMid, perfL10BuildLoopStart)) +
                " bld=" + std::to_string(
                    rtxSegMs(perfL10BuildLoopStart, perfL10AfterBuildLoop)) +
                " tail=" + std::to_string(tailMs) +
                " staging=" + std::to_string(
                    rtxSegMs(perfL10AfterBuildLoop, rtxTailAfterStaging)) +
                // 2026-10-15：补 staging 字节数（HANDOFF-2026-10-15 §A 的 OPEN 项
                // ——staging 字节数未单独记录）。用它对账"staging 毫秒 ↔ 字节"，
                // 验证 :59186 的 vkMapMemory+memcpy（写合并带宽 ~1-2GB/s）是否就是
                // tail 的 47-59ms 大头。MB 口径与 counters 的 poolKeptMB 同（/1048576）。
                " stagingMB=" + std::to_string(
                    static_cast<double>(totalStagingBytes) / 1048576.0) +
                " preCmd=" + std::to_string(
                    rtxSegMs(rtxTailAfterStaging, rtxTailBeforeCommandRecord)) +
                // 2026-10-13 preCmd 内切（五段之和 == 上面的 preCmd=，可直接对账）：
                //   ord     = orderedSections 构建 + 驱逐前的余量数学
                //   evict   = 驱逐候选扫描（遍历全部 g_sectionBLAS）+ 排序 + retire/erase
                //   inst    = 实例表构建 + memcmp 影子比较 + 空表哑实例
                //   tlas    = build-size 查询 + TLAS 存储/scratch/BLAS scratch 池
                //   preMisc = 剩下的（allocateInfo 组装等）
                " ord=" + std::to_string(
                    rtxSegMs(rtxTailAfterStaging, rtxPreCmdAfterOrdered)) +
                " evict=" + std::to_string(
                    rtxSegMs(rtxPreCmdAfterOrdered, rtxPreCmdAfterEvict)) +
                " inst=" + std::to_string(
                    rtxSegMs(rtxPreCmdAfterEvict, rtxPreCmdAfterInstances)) +
                " tlas=" + std::to_string(
                    rtxSegMs(rtxPreCmdAfterInstances, rtxPreCmdAfterTlas)) +
                " preMisc=" + std::to_string(
                    rtxSegMs(rtxPreCmdAfterTlas, rtxTailBeforeCommandRecord)) +
                " record=" + std::to_string(
                    rtxSegMs(rtxTailBeforeCommandRecord, rtxTailAfterCommandRecord)) +
                " waits=" + std::to_string(
                    rtxSegMs(rtxTailAfterCommandRecord, rtxTailAfterFenceWait)) +
                " submit=" + std::to_string(
                    rtxSegMs(rtxTailAfterFenceWait, rtxTailAfterSubmit)) +
                " park=" + std::to_string(
                    rtxSegMs(rtxTailAfterSubmit, std::chrono::steady_clock::now())) +
                " qIdle=" + std::to_string(perfL10QueueIdleMilliseconds));
        }
    }

    return true;
}
// DLSS frame-level Halton(2,3)
// 必须与 rt_test.rgen 完全一致
// =====================================================

static float DLSSHaltonValue(
    uint32_t index,
    uint32_t base
)
{
    float f = 1.0f;
    float result = 0.0f;

    uint32_t i = index;

    while(i > 0u)
    {
        f /= static_cast<float>(base);

        result +=
            f *
            static_cast<float>(
                i % base
            );

        i /= base;
    }

    return result;
}


static void GetDLSSFrameJitter(
    uint32_t frameIndex,
    float& outX,
    float& outY
)
{
    // =====================================================================
    // 2026-09-28 诊断开关：把相机抖动整条关掉。
    //
    // 注意这里**同时**影响两个消费者，且必须同时：
    //   * 主射线用的像素中心（相机 UBO 的抖动）
    //   * 传给 DLSS 的 jitterOffset
    // 只关一边会让 DLSS 的复投影与渲染的像素中心错位，噪声与糊都不可判读。
    //
    // 目的：分辨本地光残余噪声的两种来源：
    //   (a) 硬边信号（阴影/发光体边界）在**亚像素抖动**下的合法逐帧变化
    //       ⇒ 噪声会明显塌下去；那说明改估计量没用，唯一出路是让时域累积真正收下它
    //         （即修历史接受判据 / 复用，而不是加采样）；
    //   (b) 采样与可见性自身的随机性（与抖动无关）
    //       ⇒ 噪声基本不变，那才轮到动估计量。
    //
    // 已知混淆项（判读时必须记住）：抖动为 0 后 **DLSS-RR 自己的时域累积也停了**
    //   （它靠亚像素抖动累积细节），画面会出现阶梯/锯齿、移动时更糊。
    //   所以只看"本地光那片噪声的强度与形态"，不要评价整体抗锯齿。
    //
    // 打开方式（二选一）：
    //   1) 编译期：-DRESTIR_TEST_NO_JITTER=1
    //   2) 运行期：环境变量 RESTIR_NO_JITTER=1（同一个 exe 内生效，免重编）
    // =====================================================================
#ifndef RESTIR_TEST_NO_JITTER
#define RESTIR_TEST_NO_JITTER 0
#endif

    static const bool runtimeNoJitter = []
    {
        const char* value = std::getenv("RESTIR_NO_JITTER");

        if(value != nullptr && value[0] != '\0' && value[0] != '0')
        {
            RTLog("[JITTER] no-jitter test ACTIVE (env RESTIR_NO_JITTER)");
            return true;
        }

        // 第三种、最省事的开法：在运行目录放一个标记文件，存在即关抖动。
        // 这样 A/B 只需要"删文件 + 重启"，不必重编。
        std::ifstream marker(
            ResolveRTXRuntimePath("restir_no_jitter.flag"),
            std::ios::binary
        );

        if(marker.good())
        {
            RTLog(
                std::string("[JITTER] no-jitter test ACTIVE (flag file: ") +
                ResolveRTXRuntimePath("restir_no_jitter.flag") + ")"
            );
            return true;
        }

        RTLog("[JITTER] no-jitter test inactive (jitter on)");
        return false;
    }();

#if RESTIR_TEST_NO_JITTER
    const bool noJitter = true;
#else
    const bool noJitter = runtimeNoJitter;
#endif

    if(noJitter)
    {
        outX = 0.0f;
        outY = 0.0f;
        return;
    }

    constexpr uint32_t PHASE_COUNT =
        32u;

    const uint32_t sequenceIndex =
        (frameIndex % PHASE_COUNT) +
        1u;


    outX =
        DLSSHaltonValue(
            sequenceIndex,
            2u
        ) -
        0.5f;


    outY =
        DLSSHaltonValue(
            sequenceIndex,
            3u
        ) -
        0.5f;
}
